module a311o_2(
    output X,
    input A1,
    input A2,
    input A3,
    input B1,
    input C1
);

    // Intermediate wires for internal logic
    wire A_out;
    wire BC_out;

    // Logical OR for A inputs
    assign A_out = A1 | A2 | A3;

