    // Y equals NAND of ((A1|A2), D1, (B1 XNOR C1)) on A1 edge.
    check_Y_function_equivalence_on_A1: assert property (
        @(posedge A1) Y == ~((A1 | A2) & D1 & (B1 ~^ C1))
