module magnitude_comparator(
  input [3:0] A,
  input [3:0] B,
  output EQ,
  output GT
);

  assign EQ = (A == B);
  assign GT = (A > B);

endmodule

sva_code:
module magnitude_comparator_sva (
    input logic clk,          // sampling clock for assertions (DUT is combinational)
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT
);
    // EQ must equal (A == B).
    check_eq_definition: assert property (
        @(posedge clk) (EQ === (A == B))
    );

    // GT must equal (A > B).
    check_gt_definition: assert property (
        @(posedge clk) (GT === (A > B))
    );

    // EQ and GT cannot both be HIGH.
    check_eq_gt_mutex: assert property (
        @(posedge clk) !(EQ && GT)
    );

    // If inputs are equal, then EQ=1 and GT=0.
    check_outputs_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT)
    );

    // If A is greater than B, then GT=1 and EQ=0.
    check_outputs_when_greater: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ)
    );

    // If A is less than B, then both EQ and GT are 0.
    check_outputs_when_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT)
    );

    // EQ high implies inputs are equal.
    check_eq_implies_inputs_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

    // GT high implies A is greater than B.
    check_gt_implies_inputs_ordered: assert property (
        @(posedge clk) GT |-> (A > B)
    );

    // EQ high implies GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

    // GT high implies EQ low.
    check_gt_implies_not_eq: assert property (
        @(posedge clk) GT |-> !EQ
    );
endmodule

verilog_code:
module fsm_consecutive_ones_detection (
  input clk,
  input reset,
  input [15:0] data,
  output reg [3:0] count
);

  parameter S0 = 2'b00;
  parameter S1 = 2'b01;

  reg [1:0] state;
  reg [3:0] count_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S0;
      count_reg <= 0;
    end else begin
      case (state)
        S0: begin
          if (data == 16'hFFFF) begin
            state <= S1;
            count_reg <= 1;
          end else begin
            state <= S0;
            count_reg <= 0;
          end
        end
        S1: begin
          if (data == 16'hFFFF) begin
            state <= S1;
            count_reg <= count_reg + 1;
          end else begin
            state <= S0;
            count_reg <= 0;
          end
        end
      endcase
    end
  end

  always @(*) begin
    if (state == S0) begin
      count = 0;
    end else begin
      count = count_reg;
    end
  end

endmodule

sva_code:
module fsm_consecutive_ones_detection_sva (
  input logic clk,
  input logic reset,
  input logic [15:0] data,
  input logic [3:0] count,
  input logic [1:0] state,
  input logic [3:0] count_reg
);
  localparam logic [1:0] S0 = 2'b00;
  localparam logic [1:0] S1 = 2'b01;

  // Reset forces state=S0, count_reg=0, and output count=0.
  check_reset_initialization: assert property (
    @(posedge clk) reset |-> (state == S0) && (count_reg == 4'd0) && (count == 4'd0)
  );

  // When in S0, output count must be 0.
  check_output_zero_in_S0: assert property (
    @(posedge clk) disable iff (reset) (state == S0) |-> (count == 4'd0)
  );

  // When in S1, output count equals count_reg.
  check_output_matches_reg_in_S1: assert property (
    @(posedge clk) disable iff (reset) (state == S1) |-> (count == count_reg)
  );

  // From S0 with data==FFFF, next state is S1 with count_reg=1 and output count=1.
  check_S0_to_S1_on_all_ones: assert property (
    @(posedge clk) disable iff (reset) (state == S0 && data == 16'hFFFF) |=> (state == S1 && count_reg == 4'd1 && count == 4'd1)
  );

  // From S0 with data!=FFFF, stay in S0 and clear count_reg and output.
  check_S0_stay_on_not_all_ones: assert property (
    @(posedge clk) disable iff (reset) (state == S0 && data != 16'hFFFF) |=> (state == S0 && count_reg == 4'd0 && count == 4'd0)
  );

  // From S1 with data==FFFF, stay in S1 and increment count_reg and output by 1.
  check_S1_stay_and_increment_on_all_ones: assert property (
    @(posedge clk) disable iff (reset || $initstate) (state == S1 && data == 16'hFFFF) |=> (state == S1 && (count_reg == $past(count_reg) + 4'd1) && (count == $past(count) + 4'd1))
  );

