module my_module_sva (
    input logic in,
    input logic clk,
    input logic fr_a,
    input logic fr_b,
    input logic fr_chk
);
    ///// Sequential sampling /////
    // fr_a samples 'in' on each rising clock (1-cycle latency).
    check_fr_a_samples_in: assert property (
        @(posedge clk) fr_a == $past(in)
    );
    // fr_b samples 'in' on each rising clock (1-cycle latency).
    check_fr_b_samples_in: assert property (
        @(posedge clk) fr_b == $past(in)
    );
    // fr_chk captures LSB of (in + 1), i.e., complement of previous 'in'.
    check_fr_chk_complements_in: assert property (
        @(posedge clk) fr_chk == ~ $past(in)
    );

    ///// Edge propagation /////
    // A rise on 'in' causes a rise on fr_a one cycle later.
    in_rise_to_fr_a_rise: assert property (
        @(posedge clk) $rose(in) |=> $rose(fr_a)
    );
    // A fall on 'in' causes a fall on fr_a one cycle later.
    in_fall_to_fr_a_fall: assert property (
        @(posedge clk) $fell(in) |=> $fell(fr_a)
    );
    // A rise on 'in' causes a rise on fr_b one cycle later.
    in_rise_to_fr_b_rise: assert property (
        @(posedge clk) $rose(in) |=> $rose(fr_b)
    );
    // A fall on 'in' causes a fall on fr_b one cycle later.
    in_fall_to_fr_b_fall: assert property (
        @(posedge clk) $fell(in) |=> $fell(fr_b)
    );
    // A rise on 'in' causes a fall on fr_chk one cycle later.
    in_rise_to_fr_chk_fall: assert property (
        @(posedge clk) $rose(in) |=> $fell(fr_chk)
    );
    // A fall on 'in' causes a rise on fr_chk one cycle later.
    in_fall_to_fr_chk_rise: assert property (
        @(posedge clk) $fell(in) |=> $rose(fr_chk)
    );
endmodule

verilog_code:
module soc_design_SystemID (
  // inputs:
  address,
  clock,
  reset_n,

  // outputs:
  readdata
);

  output [31:0] readdata;
  input [31:0] address;
  input clock;
  input reset_n;

  reg [31:0] readdata_reg;

  always @(posedge clock or negedge reset_n) begin
    if (!reset_n) begin
      readdata_reg <= 32'h0;
    end else begin
      readdata_reg <= (address == 32'h0) ? 32'hff : 32'h590d8d31;
    end
  end

  assign readdata = readdata_reg;

endmodule

sva_code:
module soc_design_SystemID_sva (
    input logic clock,
    input logic reset_n,
    input logic [31:0] address,
    input logic [31:0] readdata
);
    // During reset, readdata is 0.
    check_reset_forces_zero: assert property (
        @(posedge clock) (!reset_n) |-> (readdata == 32'h00000000)
    );

    // On falling edge of reset_n, readdata is 0 at this sample.
    check_reset_fall_clears_output: assert property (
        @(posedge clock) $fell(reset_n) |-> (readdata == 32'h00000000)
    );

    // On rising edge of reset_n, readdata remains 0 in this cycle.
    check_reset_rise_zero_this_cycle: assert property (
        @(posedge clock) $rose(reset_n) |-> (readdata == 32'h00000000)
    );

    // Out of reset, readdata equals function of previous-cycle address.
    check_prev_addr_mapping: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata == (($past(address) == 32'h00000000) ? 32'h000000FF : 32'h590D8D31))
    );

    // When operational, readdata is one of the two allowed constants.
    check_operational_value_domain: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata inside {32'h000000FF, 32'h590D8D31})
    );

    // When operational, readdata is never zero.
    check_operational_nonzero: assert property (
        @(posedge clock) disable iff (!reset_n)
            $past(reset_n) |-> (readdata != 32'h00000000)
    );

    // If address==0 and remain out of reset, next-cycle readdata is 0xFF.
    check_forward_pipeline_zero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address == 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h000000FF))
    );

    // If address!=0 and remain out of reset, next-cycle readdata is 0x590D8D31.
    check_forward_pipeline_nonzero: assert property (
        @(posedge clock) disable iff (!reset_n)
            (address != 32'h00000000) |-> ##1 (reset_n && (readdata == 32'h590D8D31))
    );

    // With two-cycle stable address and out of reset, readdata stays stable.
    check_stable_address_two_cycles_keeps_output_stable: assert property (
        @(posedge clock) disable iff (!reset_n)
            ($past(reset_n) && $past(reset_n,2) && ($past(address) == $past(address,2))) |-> (readdata == $past(readdata))
    );

    // With two cycles out of reset, both current and previous outputs match their respective address mappings.
    check_two_cycle_correlation: assert property (
        @(posedge clock) disable iff (!reset_n)
            ($past(reset_n) && $past(reset_n,2)) |-> 
            (($past(readdata) == (($past(address,2) == 32'h00000000) ? 32'h000000FF : 32'h590D8D31)) &&
             (readdata       == (($past(address)    == 32'h00000000) ? 32'h000000FF : 32'h590D8D31)))
    );
endmodule

module compm4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B0,
    input logic B1,
    input logic B2,
    input logic B3,
    input logic GT,
    input logic LT
);
    // GT matches unsigned compare A>B
    check_gt_definition: assert property (
        @(posedge clk) GT == ({A3,A2,A1,A0} > {B3,B2,B1,B0})
    );

    // LT matches unsigned compare A<B
    check_lt_definition: assert property (
        @(posedge clk) LT == ({A3,A2,A1,A0} < {B3,B2,B1,B0})
    );

    // GT and LT are never both 1
    check_mutual_exclusion: assert property (
        @(posedge clk) !(GT && LT)
    );

    // When A==B, both outputs are 0
    check_equal_outputs_zero: assert property (
        @(posedge clk) ({A3,A2,A1,A0} == {B3,B2,B1,B0}) |=> (GT == 1'b0 && LT == 1'b0)
    );

    // When A!=B, exactly one of GT or LT is 1
    check_inequal_outputs_xor: assert property (
        @(posedge clk) ({A3,A2,A1,A0} != {B3,B2,B1,B0}) |=> (GT ^ LT)
    );

    // If GT is 1 then LT is 0
    check_gt_implies_not_lt: assert property (
        @(posedge clk) GT |=> (LT == 1'b0)
    );

    // If LT is 1 then GT is 0
    check_lt_implies_not_gt: assert property (
        @(posedge clk) LT |=> (GT == 1'b0)
    );

    // When A>B, GT=1 and LT=0
    check_outputs_when_A_gt_B: assert property (
        @(posedge clk) ({A3,A2,A1,A0} > {B3,B2,B1,B0}) |=> (GT == 1'b1 && LT == 1'b0)
    );

    // When A<B, LT=1 and GT=0
    check_outputs_when_A_lt_B: assert property (
        @(posedge clk) ({A3,A2,A1,A0} < {B3,B2,B1,B0}) |=> (LT == 1'b1 && GT == 1'b0)
    );
endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] count
);
    ///// Reset behavior /////
    // When rst is HIGH at a clock edge, count must be zero.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

    // During reset, count is known and zero (no X/Z while rst is HIGH).
    check_known_zero_during_reset: assert property (
        @(posedge clk) rst |-> (!$isunknown(count) && count == 4'd0)
    );

    ///// Enable-driven counting (gated to cycles where rst is LOW at both ends) /////
    // With rst LOW in both cycles and en LOW in the previous cycle, count holds its value.
    check_hold_when_en_low: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(!en,1,1'b0)) |-> (count == $past(count,1,4'h0))
    );

    // With rst LOW in both cycles and en HIGH in the previous cycle, count increments by 1 (mod 16).
    check_increment_when_en_high: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(en,1,1'b0)) |-> (count == (($past(count,1,4'h0) + 4'd1) & 4'hF))
    );

    // With rst LOW in both cycles, if prior count was 4'hF and en was HIGH, next count wraps to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (rst)
            ($past(!rst,1,1'b0) && !rst && $past(en,1,1'b0) && ($past(count,1,4'h0) == 4'hF)) |-> (count == 4'h0)
    );
endmodule

verilog_code:
module fb_rxcounters (
   input MRxClk, Reset, MRxDV, RxValid,
   input StateIdle, StateFFS, StatePreamble,
   input [1:0] StateData,
   input StateFrmCrc,
   input MRxDEqDataSoC,
   output TotalRecvNibCntEq0,
   output [15:0] TotalRecvNibCnt,
   output [7:0] RxRamAddr,
   output [3:0] FrmCrcNibCnt,
   output FrmCrcStateEnd
);
   reg [15:0] TotalRecvNibCnt;
   reg [7:0] RxRamAddr;
   reg [3:0] FrmCrcNibCnt;
   wire ResetTotalRecvNibCnt, IncrementTotalRecvNibCnt;
   wire ResetRxRamAddr, IncrementRxRamAddr;
   wire IncrementFrmCrcNibCnt, ResetFrmCrcNibCnt;

   assign ResetTotalRecvNibCnt = StateIdle & ~MRxDV;
   assign IncrementTotalRecvNibCnt = MRxDV;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) TotalRecvNibCnt <= 16'd0;
      else if (ResetTotalRecvNibCnt) TotalRecvNibCnt <= 16'd0;
      else if (IncrementTotalRecvNibCnt) TotalRecvNibCnt <= TotalRecvNibCnt + 16'd1;
   end

   assign TotalRecvNibCntEq0 = (TotalRecvNibCnt == 16'd0);

   assign ResetRxRamAddr = StateIdle | StateFFS | StatePreamble;
   assign IncrementRxRamAddr = RxValid;
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) RxRamAddr <= 8'd0;
      else if (ResetRxRamAddr) RxRamAddr <= 8'd0;
      else if (IncrementRxRamAddr) RxRamAddr <= RxRamAddr + 8'd1;
   end

   assign IncrementFrmCrcNibCnt = StateFrmCrc;
   assign ResetFrmCrcNibCnt = StateIdle;
   assign FrmCrcStateEnd = FrmCrcNibCnt[0];
   always @(posedge MRxClk or posedge Reset) begin
      if (Reset) FrmCrcNibCnt <= 4'd0;
      else if (ResetFrmCrcNibCnt) FrmCrcNibCnt <= 4'd0;
      else if (IncrementFrmCrcNibCnt) FrmCrcNibCnt <= FrmCrcNibCnt + 4'd1;
   end
endmodule

sva_code:
module fb_rxcounters_sva (
   input logic MRxClk,
   input logic Reset,
   input logic MRxDV,
   input logic RxValid,
   input logic StateIdle,
   input logic StateFFS,
   input logic StatePreamble,
   input logic [1:0] StateData,
   input logic StateFrmCrc,
   input logic MRxDEqDataSoC,
   input logic TotalRecvNibCntEq0,
   input logic [15:0] TotalRecvNibCnt,
   input logic [7:0] RxRamAddr,
   input logic [3:0] FrmCrcNibCnt,
   input logic FrmCrcStateEnd
);
   ///// Global reset effects (active-high, async) /////
   // On Reset, TotalRecvNibCnt must be 0.
   totalcnt_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (TotalRecvNibCnt == 16'd0)
   );
   // On Reset, RxRamAddr must be 0.
   rxaddr_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (RxRamAddr == 8'd0)
   );
   // On Reset, FrmCrcNibCnt must be 0.
   frmcrc_zero_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (FrmCrcNibCnt == 4'd0)
   );
   // On Reset, TotalRecvNibCntEq0 must be 1.
   eq0_high_on_reset: assert property (
      @(posedge MRxClk) Reset |-> (TotalRecvNibCntEq0 == 1'b1)
   );

   ///// Combinational outputs reflect registered values /////
   // TotalRecvNibCntEq0 equals (TotalRecvNibCnt == 0).
   eq0_matches_counter: assert property (
      @(posedge MRxClk) disable iff (Reset) (TotalRecvNibCntEq0 == (TotalRecvNibCnt == 16'd0))
   );
   // FrmCrcStateEnd equals LSB of FrmCrcNibCnt.
   frmcrcstateend_matches_lsb: assert property (
      @(posedge MRxClk) disable iff (Reset) (FrmCrcStateEnd == FrmCrcNibCnt[0])
   );

   ///// TotalRecvNibCnt behavior /////
   // When StateIdle && !MRxDV, counter resets to 0 on next cycle.
   totalcnt_reset_on_idle_no_dv: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateIdle && !MRxDV) |-> ##1 (TotalRecvNibCnt == 16'd0)
   );
   // When MRxDV, counter increments by 1 on next cycle.
   totalcnt_increments_on_mrxdv: assert property (
      @(posedge MRxClk) disable iff (Reset) MRxDV |-> ##1 (TotalRecvNibCnt == $past(TotalRecvNibCnt) + 16'd1)
   );
   // When !MRxDV and not idle, counter holds its value.
   totalcnt_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!MRxDV && !StateIdle) |-> ##1 (TotalRecvNibCnt == $past(TotalRecvNibCnt))
   );

   ///// RxRamAddr behavior /////
   // When StateIdle/StateFFS/StatePreamble, address resets to 0 on next cycle.
   rxaddr_reset_on_state_reset: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateIdle || StateFFS || StatePreamble) |-> ##1 (RxRamAddr == 8'd0)
   );
   // When RxValid and not in reset states, address increments by 1 on next cycle.
   rxaddr_increments_on_rxvalid: assert property (
      @(posedge MRxClk) disable iff (Reset) (RxValid && !(StateIdle || StateFFS || StatePreamble)) |-> ##1 (RxRamAddr == $past(RxRamAddr) + 8'd1)
   );
   // When not incrementing and not resetting, address holds its value.
   rxaddr_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!RxValid && !(StateIdle || StateFFS || StatePreamble)) |-> ##1 (RxRamAddr == $past(RxRamAddr))
   );

   ///// FrmCrcNibCnt behavior /////
   // When StateIdle, CRC nibble counter resets to 0 on next cycle.
   frmcrc_reset_on_idle: assert property (
      @(posedge MRxClk) disable iff (Reset) StateIdle |-> ##1 (FrmCrcNibCnt == 4'd0)
   );
   // When StateFrmCrc and not idle, CRC nibble counter increments by 1 on next cycle.
   frmcrc_increments_in_crc_state: assert property (
      @(posedge MRxClk) disable iff (Reset) (StateFrmCrc && !StateIdle) |-> ##1 (FrmCrcNibCnt == $past(FrmCrcNibCnt) + 4'd1)
   );
   // When not in CRC state and not idle, CRC nibble counter holds its value.
   frmcrc_holds_without_inc_or_rst: assert property (
      @(posedge MRxClk) disable iff (Reset) (!StateFrmCrc && !StateIdle) |-> ##1 (FrmCrcNibCnt == $past(FrmCrcNibCnt))
   );
endmodule

