module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    ///// Functional correctness /////
    // X equals the defined boolean function of inputs.
    check_functional_equivalence: assert property (
        @(posedge VPWR) X == (A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );

    ///// Gating: any required-true input low forces X low /////
    // A1 low forces X low.
    gate_A1_low_forces_X0: assert property (
        @(posedge VPWR) (!A1) |-> (X == 1'b0)
    );
    // A2 low forces X low.
    gate_A2_low_forces_X0: assert property (
        @(posedge VPWR) (!A2) |-> (X == 1'b0)
    );
    // A3 low forces X low.
    gate_A3_low_forces_X0: assert property (
        @(posedge VPWR) (!A3) |-> (X == 1'b0)
    );

    ///// Gating: any required-false input high forces X low /////
    // B1 high forces X low.
    gate_B1_high_forces_X0: assert property (
        @(posedge VPWR) (B1) |-> (X == 1'b0)
    );
    // B2 high forces X low.
    gate_B2_high_forces_X0: assert property (
        @(posedge VPWR) (B2) |-> (X == 1'b0)
    );

    ///// Power/body rails gating /////
    // VPWR low forces X low.
    gate_VPWR_low_forces_X0: assert property (
        @(posedge VPWR) (!VPWR) |-> (X == 1'b0)
    );
    // VGND high forces X low.
    gate_VGND_high_forces_X0: assert property (
        @(posedge VPWR) (VGND) |-> (X == 1'b0)
    );
    // VPB low forces X low.
    gate_VPB_low_forces_X0: assert property (
        @(posedge VPWR) (!VPB) |-> (X == 1'b0)
    );
    // VNB high forces X low.
    gate_VNB_high_forces_X0: assert property (
        @(posedge VPWR) (VNB) |-> (X == 1'b0)
    );

    ///// Transition sanity /////
    // X can only rise when all required conditions are met.
    check_X_rise_requires_minterm: assert property (
        @(posedge VPWR) $rose(X) |-> (A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );
    // X can only fall when the minterm is not satisfied.
    check_X_fall_requires_not_minterm: assert property (
        @(posedge VPWR) $fell(X) |-> !(A1 & A2 & A3 & ~B1 & ~B2 & VPWR & ~VGND & VPB & ~VNB)
    );

endmodule

module up_counter_sva (
    input logic clk,
    input logic reset,       // Active-low asynchronous reset
    input logic [2:0] count
);
    ///// Reset behavior /////
    // When reset is LOW at a clock edge, count must be 0.
    check_reset_low_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'd0)
    );

    // On a falling edge of reset between clock edges, count must be 0 at this clock.
    check_reset_fall_clears_count: assert property (
        @(posedge clk) $fell(reset) |-> (count == 3'd0)
    );

    // While reset is held LOW across consecutive clocks, count remains 0.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (reset == 1'b0) && ($past(reset) == 1'b0) |-> (count == 3'd0)
    );

    ///// Normal counting rules (enabled when reset is HIGH) /////
    // When reset is HIGH for two consecutive clocks and prior count < 7, increment by 1.
    check_increment_when_below_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset && ($past(count) != 3'd7)) |-> (count == ($past(count) + 3'd1))
    );

    // When reset is HIGH for two consecutive clocks and prior count == 7, wrap to 0.
    check_wrap_to_zero_from_max: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // With reset HIGH for two consecutive clocks, count must change every cycle (no stalls).
    check_change_each_cycle_when_enabled: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && reset) |-> (count != $past(count))
    );

    // With reset HIGH for 8 consecutive clocks, count returns to its value 8 cycles earlier.
    sequence reset_high_8;
        (reset == 1'b1) [*8];
    endsequence
    check_period_8_when_enabled: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            reset_high_8 |-> (count == $past(count, 8))
    );
endmodule

