    input logic Y
);
    // Y must be 1 when A > B.
    check_y_high_when_a_gt_b: assert property (
        @(posedge CLK) (A > B) |-> (Y == 1'b1)
    );

    // Y must be 0 when A <= B.
    check_y_low_when_a_le_b: assert property (
        @(posedge CLK) (A <= B) |-> (Y == 1'b0)
    );

    // If Y is 1 then A must be greater than B.
    check_y1_implies_a_gt_b: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A > B)
    );

    // If MSBs differ and A[1]=1,B[1]=0 then Y must be 1.
    check_msb_diff_a1_b0: assert property (
        @(posedge CLK) (A[1] && !B[1]) |-> (Y == 1'b1)
    );

    // If MSBs differ and A[1]=0,B[1]=1 then Y must be 0.
    check_msb_diff_a0_b1: assert property (
        @(posedge CLK) (!A[1] && B[1]) |-> (Y == 1'b0)
    );

    // If MSBs equal, comparison reduces to LSB: Y == (A[0] & ~B[0]).
    check_msb_equal_lsb_decides: assert property (
        @(posedge CLK) (A[1] == B[1]) |-> (Y == (A[0] & ~B[0]))
    );

    // If A equals B then Y must be 0.
    check_equal_inputs_y0: assert property (
        @(posedge CLK) (A == B) |-> (Y == 1'b0)
    );

    // If A is 0 then Y must be 0.
    check_a_zero_y0: assert property (
        @(posedge CLK) (A == 2'b00) |-> (Y == 1'b0)
    );

    // If B is 3 then Y must be 0.
    check_b_three_y0: assert property (
        @(posedge CLK) (B == 2'b11) |-> (Y == 1'b0)
    );

    // If A is 3 and B is not 3 then Y must be 1.
    check_a_three_gt_non_three: assert property (
        @(posedge CLK) (A == 2'b11 && B != 2'b11) |-> (Y == 1'b1)
    );
endmodule

verilog_code:
module bin2gray(
  input [3:0] binary,
  output reg [3:0] gray
);

  always @ (binary) begin
    gray[3] = binary[3];
    gray[2] = binary[3] ^ binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
  end

endmodule

sva_code:
module bin2gray_sva (
    input  logic        clk,
    input  logic [3:0]  binary,
    input  logic [3:0]  gray
);
    ///// Functional mapping /////
    // MSB mapping: gray[3] equals binary[3].
    check_gray_bit3_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] === binary[3]
    );

    // gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] === (binary[3] ^ binary[2])
    );

    // gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] === (binary[2] ^ binary[1])
    );

    // gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] === (binary[1] ^ binary[0])
    );

    // Full vector mapping matches {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_full_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray === {binary[3], (binary[3]^binary[2]), (binary[2]^binary[1]), (binary[1]^binary[0])}
    );

    ///// Stability /////
    // If binary is stable between cycles, gray must be stable.
    check_gray_stability: assert property (
        @(posedge clk) disable iff (1'b0) $stable(binary) |-> $stable(gray)
    );

    ///// Single-bit input toggle effects /////
    // Only b3 toggles: g3 and g2 toggle; g1 and g0 stay stable.
    check_only_b3_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[3]) && $stable(binary[2]) && $stable(binary[1]) && $stable(binary[0]))
            |-> ($changed(gray[3]) && $changed(gray[2]) && $stable(gray[1]) && $stable(gray[0]))
    );

    // Only b2 toggles: g2 and g1 toggle; g3 and g0 stay stable.
    check_only_b2_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[2]) && $stable(binary[3]) && $stable(binary[1]) && $stable(binary[0]))
            |-> ($changed(gray[2]) && $changed(gray[1]) && $stable(gray[3]) && $stable(gray[0]))
    );

    // Only b1 toggles: g1 and g0 toggle; g3 and g2 stay stable.
    check_only_b1_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[1]) && $stable(binary[3]) && $stable(binary[2]) && $stable(binary[0]))
            |-> ($changed(gray[1]) && $changed(gray[0]) && $stable(gray[3]) && $stable(gray[2]))
    );

    // Only b0 toggles: only g0 toggles; g3,g2,g1 stay stable.
    check_only_b0_toggles: assert property (
        @(posedge clk) disable iff (1'b0)
            ($changed(binary[0]) && $stable(binary[3]) && $stable(binary[2]) && $stable(binary[1]))
            |-> ($changed(gray[0]) && $stable(gray[3]) && $stable(gray[2]) && $stable(gray[1]))
    );
endmodule

module updown_counter_sva (
    input logic clk,
    input logic reset,      // active-low asynchronous reset
    input logic control,    // 0: up, 1: down
    input logic [2:0] count // 3-bit counter
);
    // Reset low forces count to zero at each clock.
    reset_low_clears_count: assert property (
        @(posedge clk) (reset == 1'b0) |-> (count == 3'd0)
    );

    // Out of reset, next count matches prev control: +1 when 0, -1 when 1.
    count_update_matches_prev_control: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            $past(reset) |-> (count == ($past(control) ? ($past(count) - 3'd1) : ($past(count) + 3'd1)))
    );

    // Up-count wraps from 7 to 0 when previous control was 0.
    wrap_up_on_7_to_0: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    // Down-count wraps from 0 to 7 when previous control was 1.
    wrap_down_on_0_to_7: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) == 3'd0)) |-> (count == 3'd7)
    );

    // Up-count increments by exactly one when not wrapping.
    increment_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b0) && ($past(count) != 3'd7)) |-> (count == $past(count) + 3'd1)
    );

    // Down-count decrements by exactly one when not wrapping.
    decrement_no_wrap: assert property (
        @(posedge clk) disable iff (reset == 1'b0)
            ($past(reset) && ($past(control) == 1'b1) && ($past(count) != 3'd0)) |-> (count == $past(count) - 3'd1)
    );

    // While reset remains asserted across cycles, count stays at zero.
    hold_zero_during_reset: assert property (
        @(posedge clk) (!$past(reset) && !reset) |-> (count == 3'd0)
    );
endmodule

