sva_code:
module sky130_fd_sc_lp__ha_sva (
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B
);
    // COUT equals logical AND of A and B.
    check_cout_definition: assert property (
        @(posedge $global_clock) COUT == (A & B)
    );

    // SUM equals logical XOR of A and B.
    check_sum_definition: assert property (
        @(posedge $global_clock) SUM == (A ^ B)
    );

    // When A=0 and B=0 then SUM=0 and COUT=0.
    check_tt_00: assert property (
        @(posedge $global_clock) (A==1'b0 && B==1'b0) |-> (SUM==1'b0 && COUT==1'b0)
    );

    // When A=0 and B=1 then SUM=1 and COUT=0.
    check_tt_01: assert property (
        @(posedge $global_clock) (A==1'b0 && B==1'b1) |-> (SUM==1'b1 && COUT==1'b0)
    );

    // When A=1 and B=0 then SUM=1 and COUT=0.
    check_tt_10: assert property (
        @(posedge $global_clock) (A==1'b1 && B==1'b0) |-> (SUM==1'b1 && COUT==1'b0)
    );

    // When A=1 and B=1 then SUM=0 and COUT=1.
    check_tt_11: assert property (
        @(posedge $global_clock) (A==1'b1 && B==1'b1) |-> (SUM==1'b0 && COUT==1'b1)
    );

    // SUM and COUT are never both HIGH.
    check_outputs_not_both_high: assert property (
        @(posedge $global_clock) !(SUM && COUT)
    );

    // SUM=1 implies inputs differ.
    check_sum_high_inputs_differ: assert property (
        @(posedge $global_clock) SUM |-> (A != B)
    );

    // COUT=1 implies both inputs are 1.
    check_cout_high_inputs_one: assert property (
        @(posedge $global_clock) COUT |-> (A && B)
    );

    // Inputs equal implies SUM=0.
    check_inputs_equal_sum_low: assert property (
        @(posedge $global_clock) (A == B) |-> (SUM == 1'b0)
    );
endmodule

verilog_code:
module shift_register (
    input clk,
    input [3:0] in,
    input load,
    output [3:0] out,
    output reg valid
);

reg [3:0] reg1, reg2, reg3, reg4;

always @(posedge clk) begin
    if (load) begin
        reg1 <= in;
        reg2 <= reg1;
        reg3 <= reg2;
        reg4 <= reg3;
        valid <= 1;
    end else begin
        reg1 <= reg2;
        reg2 <= reg3;
        reg3 <= reg4;
        reg4 <= 0;
        valid <= 0;
    end
end

assign out = reg4;

endmodule

sva_code:
module shift_register_sva (
    input logic clk,
    input logic [3:0] in,
    input logic load,
    input logic [3:0] out,
    input logic valid
);
    // Next cycle valid reflects load HIGH this cycle.
    valid_next_high_when_load_high: assert property (
        @(posedge clk) load |=> (valid == 1'b1)
    );

    // Next cycle valid reflects load LOW this cycle.
    valid_next_low_when_load_low: assert property (
        @(posedge clk) !load |=> (valid == 1'b0)
    );

    // A rise on load causes a rise on valid in the next cycle.
    valid_rise_follows_load_rise: assert property (
        @(posedge clk) $rose(load) |=> $rose(valid)
    );

    // A fall on load causes a fall on valid in the next cycle.
    valid_fall_follows_load_fall: assert property (
        @(posedge clk) $fell(load) |=> $fell(valid)
    );

    // When load is LOW, out is cleared to zero in the next cycle.
    out_cleared_next_on_no_load: assert property (
        @(posedge clk) !load |=> (out == 4'b0000)
    );

    // A falling load clears both valid and out in the next cycle.
    clear_valid_and_out_on_load_fall: assert property (
        @(posedge clk) $fell(load) |=> (!valid && (out == 4'b0000))
    );

    // Whenever valid is LOW, out must be zero in the same cycle.
    valid_low_implies_out_zero: assert property (
        @(posedge clk) (!valid) |-> (out == 4'b0000)
    );

    // Four consecutive cycles of load HIGH pipeline in to out with 4-cycle latency.
    four_cycle_load_delays_input_to_out: assert property (
        @(posedge clk) load[*4] |=> (out == $past(in,4))
    );

    // A fall on valid implies out is zero in the same cycle.
    out_zero_on_valid_fall: assert property (
        @(posedge clk) $fell(valid) |-> (out == 4'b0000)
    );

    // After four consecutive load HIGH cycles, valid is HIGH in the next cycle.
    valid_high_after_four_loads: assert property (
        @(posedge clk) load[*4] |=> (valid == 1'b1)
    );
endmodule

