sva_code:
module sky130_fd_sc_hd__nand2b_sva (
    input logic Y,
    input logic A_N,
    input logic B
);
    // No clock/reset in DUT; pure combinational; function: Y = A_N | ~B.

    // Y equals A_N | ~B on A_N rising edge.
    check_function_equiv_posA: assert property (
        @(posedge A_N) (Y === (A_N | ~B))
    );

    // Y equals A_N | ~B on A_N falling edge.
    check_function_equiv_negA: assert property (
        @(negedge A_N) (Y === (A_N | ~B))
    );

    // Y equals A_N | ~B on B rising edge.
    check_function_equiv_posB: assert property (
        @(posedge B) (Y === (A_N | ~B))
    );

    // Y equals A_N | ~B on B falling edge.
    check_function_equiv_negB: assert property (
        @(negedge B) (Y === (A_N | ~B))
    );

    // A_N=1 forces Y=1 on A_N rising edge.
    check_A_N_one_forces_Y_one_posA: assert property (
        @(posedge A_N) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // A_N=1 forces Y=1 on A_N falling edge.
    check_A_N_one_forces_Y_one_negA: assert property (
        @(negedge A_N) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B=0 forces Y=1 on B rising edge.
    check_B_zero_forces_Y_one_posB: assert property (
        @(posedge B) (B == 1'b0) |-> (Y == 1'b1)
    );

    // B=0 forces Y=1 on B falling edge.
    check_B_zero_forces_Y_one_negB: assert property (
        @(negedge B) (B == 1'b0) |-> (Y == 1'b1)
    );

    // Y==0 iff (A_N==0 && B==1) on A_N rising edge.
    check_only_zero_case_posA: assert property (
        @(posedge A_N) ((Y === 1'b0) == ((A_N === 1'b0) && (B === 1'b1)))
    );

    // Y==0 iff (A_N==0 && B==1) on B rising edge.
    check_only_zero_case_posB: assert property (
        @(posedge B) ((Y === 1'b0) == ((A_N === 1'b0) && (B === 1'b1)))
    );
endmodule

verilog_code:
module write_axi_9bit(
		 input clock_recovery,
		 input clock_50,
		 input reset_n,
		 input [8:0] data_rec,
		 output reg [8:0] data_stand	
		);


always@(posedge clock_50 or negedge reset_n )
begin

	if(!reset_n)
	begin
		data_stand <= 9'd0;
	end
	else
	begin
		if(clock_recovery)
			data_stand <= data_rec;
		else
			data_stand <= data_stand;
	end
end

endmodule

sva_code:
module write_axi_9bit_sva (
    input  logic        clock_recovery,
    input  logic        clock_50,
    input  logic        reset_n,
    input  logic [8:0]  data_rec,
    input  logic [8:0]  data_stand
);

    ///// Reset behavior /////
    // While reset_n is LOW, data_stand must be 0.
    reset_forces_zero: assert property (
        @(posedge clock_50) !reset_n |-> (data_stand == 9'd0)
    );

    ///// Sequential load/hold behavior /////
    // If not in reset last cycle and enable was 1, load previous data_rec.
    load_on_enable_prev_cycle: assert property (
        @(posedge clock_50) disable iff (!reset_n)
            ($past(reset_n) && $past(clock_recovery)) |-> (data_stand == $past(data_rec))
    );

    // If not in reset last cycle and enable was 0, hold previous value.
    hold_on_disable_prev_cycle: assert property (
        @(posedge clock_50) disable iff (!reset_n)
            ($past(reset_n) && !$past(clock_recovery)) |-> (data_stand == $past(data_stand))
    );

    // Next value is the mux of previous values based on previous enable.
    next_value_matches_prev_mux: assert property (
        @(posedge clock_50) disable iff (!reset_n)
            $past(reset_n) |-> (data_stand == ($past(clock_recovery) ? $past(data_rec) : $past(data_stand)))
    );

    // With enable LOW for two consecutive prior cycles (and not in reset two cycles ago), value matches from two cycles ago.
    hold_across_two_disable_cycles: assert property (
        @(posedge clock_50) disable iff (!reset_n)
            ($past(reset_n,2) && !$past(clock_recovery,1) && !$past(clock_recovery,2)) |-> (data_stand == $past(data_stand,2))
    );

endmodule

module adder_subtractor_4bit_sva (
    input  logic CLK,
    input  logic [3:0] a,
    input  logic [3:0] b,
    input  logic       sub,
    input  logic [3:0] sum
);
    ///// Functional checks /////
    // When sub==0, sum equals a + b (mod 16).
    check_add_when_sub0: assert property (
        @(posedge CLK) (!sub) |-> (sum == (a + b))
    );

    // When sub==1, sum equals a - b (mod 16).
    check_sub_when_sub1: assert property (
        @(posedge CLK) (sub) |-> (sum == (a - b))
    );

    // Output remains stable if a, b, and sub are stable across a cycle.
    check_stable_output_when_inputs_stable: assert property (
        @(posedge CLK) $stable({a,b,sub}) |-> $stable(sum)
    );

    // Switching from add to sub with same inputs yields a - b.
    check_toggle_to_sub: assert property (
        @(posedge CLK) ($past(sub)==1'b0 && sub==1'b1 && $stable(a) && $stable(b)) |-> (sum == (a - b))
    );

    // Switching from sub to add with same inputs yields a + b.
    check_toggle_to_add: assert property (
        @(posedge CLK) ($past(sub)==1'b1 && sub==1'b0 && $stable(a) && $stable(b)) |-> (sum == (a + b))
    );

    // Addition identity: adding zero on b returns a.
    check_add_zero_b: assert property (
        @(posedge CLK) (!sub && (b == 4'd0)) |-> (sum == a)
    );

    // Subtraction identity: subtracting zero returns a.
    check_sub_zero_b: assert property (
        @(posedge CLK) (sub && (b == 4'd0)) |-> (sum == a)
    );

    // Subtraction of equal operands yields zero.
