module RegisterMult_W32 (clk, rst, load, D, Q);
  input clk, rst, load;
  input [31:0] D;
  output reg [31:0] Q;

  always @(posedge clk) begin
    if (rst) begin
      Q <= 32'h0;
    end else if (load) begin
      Q <= D;
    end
  end
endmodule

module CLKBUFX2TS (A, Y);
