    check_out1_when_sel1_b1: assert property (
        @(posedge clk) (sel & b) |-> (out == 1'b1)
    );

    // If sel=1 and b=0 then out must be 0.
    check_out0_when_sel1_b0: assert property (
        @(posedge clk) (sel & (~b)) |-> (out == 1'b0)
    );

