    check_out1_when_sel0_a1: assert property (
        @(posedge clk) ((~sel) & a) |-> (out == 1'b1)
    );

    // If sel=0 and a=0 then out must be 0.
    check_out0_when_sel0_a0: assert property (
        @(posedge clk) ((~sel) & (~a)) |-> (out == 1'b0)
    );
endmodule

verilog_code:
module Ramifier
#(
    parameter BRANCH_CONDITION_WIDTH = 4
)(
  input [(BRANCH_CONDITION_WIDTH - 1):0] condition,
  input negative_flag, zero_flag, carry_flag, overflow_flag,
  output reg take
);


    always @ ( * ) begin
        case (condition)
            0:begin take = zero_flag;
            end
            1:begin take = !zero_flag;
            end
            2:begin take = carry_flag;
            end
            3:begin take = !carry_flag;
            end
            4:begin   take = negative_flag;
            end
            5:begin   take = !(negative_flag);
            end
            6:begin   take = overflow_flag;
            end
            7:begin   take = !(overflow_flag);
            end
            8:begin   take = (carry_flag) && (!zero_flag);
            end
            9:begin   take = (!carry_flag) || (zero_flag);
            end
            10:begin    take =  (negative_flag ^~ overflow_flag) ;
            end
            11:begin    take = (negative_flag ^ overflow_flag);
            end
            12:begin    take = (!zero_flag) && (negative_flag ^~ overflow_flag);
            end
            13:begin     take = (zero_flag) || (negative_flag ^ overflow_flag);
            end
            14:begin  take = 1;
            end
            default: begin
                take = 0; end
        endcase
    end

endmodule

sva_code:
module Ramifier_sva #(
    parameter BRANCH_CONDITION_WIDTH = 4
)(
    input logic clk,
    input logic [(BRANCH_CONDITION_WIDTH - 1):0] condition,
    input logic negative_flag,
    input logic zero_flag,
    input logic carry_flag,
    input logic overflow_flag,
    input logic take
);
    // When condition==0, take equals zero_flag.
    check_take_cond0_zero: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd0) |-> (take === zero_flag)
    );
    // When condition==1, take equals !zero_flag.
    check_take_cond1_not_zero: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd1) |-> (take === !zero_flag)
    );
    // When condition==2, take equals carry_flag.
    check_take_cond2_carry: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd2) |-> (take === carry_flag)
    );
    // When condition==3, take equals !carry_flag.
    check_take_cond3_not_carry: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd3) |-> (take === !carry_flag)
    );
    // When condition==4, take equals negative_flag.
    check_take_cond4_negative: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd4) |-> (take === negative_flag)
    );
    // When condition==5, take equals !negative_flag.
    check_take_cond5_not_negative: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd5) |-> (take === !negative_flag)
    );
    // When condition==6, take equals overflow_flag.
    check_take_cond6_overflow: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd6) |-> (take === overflow_flag)
    );
    // When condition==7, take equals !overflow_flag.
    check_take_cond7_not_overflow: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd7) |-> (take === !overflow_flag)
    );
    // When condition==8, take equals carry_flag && !zero_flag.
    check_take_cond8_carry_and_not_zero: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd8) |-> (take === (carry_flag && !zero_flag))
    );
    // When condition==9, take equals !carry_flag || zero_flag.
    check_take_cond9_notcarry_or_zero: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd9) |-> (take === (!carry_flag || zero_flag))
    );
    // When condition==10, take equals negative_flag XNOR overflow_flag.
    check_take_cond10_neg_xnor_ovf: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd10) |-> (take === (negative_flag ^~ overflow_flag))
    );
    // When condition==11, take equals negative_flag XOR overflow_flag.
    check_take_cond11_neg_xor_ovf: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd11) |-> (take === (negative_flag ^ overflow_flag))
    );
    // When condition==12, take equals !zero_flag && (negative_flag XNOR overflow_flag).
    check_take_cond12_notzero_and_xnor: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd12) |-> (take === (!zero_flag && (negative_flag ^~ overflow_flag)))
    );
    // When condition==13, take equals zero_flag || (negative_flag XOR overflow_flag).
    check_take_cond13_zero_or_xor: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd13) |-> (take === (zero_flag || (negative_flag ^ overflow_flag)))
    );
    // When condition==14, take must be 1.
    check_take_cond14_one: assert property (
        @(posedge clk) disable iff (1'b0) (condition == 'd14) |-> (take === 1'b1)
    );
    // For any other condition, take must be 0 (default case).
    check_take_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (!(condition inside { 'd0, 'd1, 'd2, 'd3, 'd4, 'd5, 'd6, 'd7, 'd8, 'd9, 'd10, 'd11, 'd12, 'd13, 'd14 })) |-> (take === 1'b0)
    );
endmodule

verilog_code:
module BlackKeyRoom(clk_vga, CurrentX, CurrentY, mapData, wall);

	input clk_vga;
	input [9:0]CurrentX;
	input [8:0]CurrentY;
	input [7:0]wall;

	output [7:0]mapData;

	reg [7:0]mColor;

	always @(posedge clk_vga) begin

		if(((CurrentY < 40) && (CurrentX < 260)) || ((CurrentY < 40) && ~(CurrentX < 380))) begin
			mColor[7:0] <= wall;
		end
		else if(CurrentX < 40) begin
			mColor[7:0] <= wall;
		end
		else if(~(CurrentX < 600)) begin
			mColor[7:0] <= wall;
		end
		else if(~(CurrentY < 440)) begin
			mColor[7:0] <= wall;
		end else
			mColor[7:0] <= 8'b10110110;	
		end


	assign mapData = mColor;


endmodule

sva_code:
module BlackKeyRoom_sva (
    input logic clk_vga,
    input logic [9:0] CurrentX,
    input logic [8:0] CurrentY,
    input logic [7:0] wall,
    input logic [7:0] mapData
);
    ///// Design uses clk_vga, no reset present /////
    // Next cycle mapData follows the priority if-else chain driven by prior-cycle inputs.
    check_map_priority_function: assert property (
        @(posedge clk_vga)
            1'b1 |=> mapData == (
                ( (( $past(CurrentY) < 9'd40) && ( $past(CurrentX) < 10'd260)) ||
                  (( $past(CurrentY) < 9'd40) && ~( $past(CurrentX) < 10'd380)) ) ? $past(wall) :
                (  $past(CurrentX) < 10'd40 )                                 ? $past(wall) :
                ( ~($past(CurrentX) < 10'd600) )                               ? $past(wall) :
                ( ~($past(CurrentY) < 9'd440) )                                ? $past(wall) :
                                                                                 8'b10110110
            )
    );

    // For Y<40 and X<260, next cycle mapData equals prior wall.
    check_wall_region_top_left: assert property (
        @(posedge clk_vga)
            ((CurrentY < 9'd40) && (CurrentX < 10'd260)) |=> (mapData == $past(wall))
    );

    // For Y<40 and not(X<380), next cycle mapData equals prior wall.
    check_wall_region_top_right: assert property (
        @(posedge clk_vga)
            ((CurrentY < 9'd40) && ~(CurrentX < 10'd380)) |=> (mapData == $past(wall))
    );

    // For X<40, next cycle mapData equals prior wall.
    check_wall_region_left_edge: assert property (
        @(posedge clk_vga)
            (CurrentX < 10'd40) |=> (mapData == $past(wall))
    );

    // For not(X<600) i.e., X>=600, next cycle mapData equals prior wall.
    check_wall_region_right_edge: assert property (
        @(posedge clk_vga)
            (~(CurrentX < 10'd600)) |=> (mapData == $past(wall))
    );

    // For not(Y<440) i.e., Y>=440, next cycle mapData equals prior wall.
    check_wall_region_bottom_edge: assert property (
        @(posedge clk_vga)
            (~(CurrentY < 9'd440)) |=> (mapData == $past(wall))
    );

    // For Y<40 and 260<=X<380, next cycle mapData equals the constant 8'b10110110.
    check_constant_region_top_gap: assert property (
        @(posedge clk_vga)
            ((CurrentY < 9'd40) && !(CurrentX < 10'd260) && (CurrentX < 10'd380)) |=> (mapData == 8'b10110110)
    );

    // When no wall conditions hold, next cycle mapData equals the constant 8'b10110110.
    check_constant_when_no_wall_conds: assert property (
        @(posedge clk_vga)
            ( !(((CurrentY < 9'd40) && (CurrentX < 10'd260)) || ((CurrentY < 9'd40) && ~(CurrentX < 10'd380)))) &&
              !(CurrentX < 10'd40) &&
              !(~(CurrentX < 10'd600)) &&
              !(~(CurrentY < 9'd440))
            |=> (mapData == 8'b10110110)
    );

    // Next cycle mapData is always either prior wall or the constant.
    check_only_wall_or_const: assert property (
        @(posedge clk_vga)
            1'b1 |=> ((mapData == $past(wall)) || (mapData == 8'b10110110))
    );

    // If next cycle mapData equals the constant, then no wall conditions held in the prior cycle.
    check_const_implies_no_wall_conds: assert property (
        @(posedge clk_vga)
            (mapData == 8'b10110110) |-> (
                !((($past(CurrentY) < 9'd40) && ($past(CurrentX) < 10'd260)) || (($past(CurrentY) < 9'd40) && ~($past(CurrentX) < 10'd380)))) &&
                !($past(CurrentX) < 10'd40) &&
                !(~($past(CurrentX) < 10'd600)) &&
                !(~($past(CurrentY) < 9'd440))
            )
    );

    // If next cycle mapData equals prior wall, then at least one wall condition held in the prior cycle.
    check_wall_implies_some_condition: assert property (
        @(posedge clk_vga)
            (mapData == $past(wall)) |-> (
                (( $past(CurrentY) < 9'd40) && ( $past(CurrentX) < 10'd260)) ||
                (( $past(CurrentY) < 9'd40) && ~( $past(CurrentX) < 10'd380)) ||
                (  $past(CurrentX) < 10'd40) ||
                ( ~($past(CurrentX) < 10'd600)) ||
                ( ~($past(CurrentY) < 9'd440))
            )
    );

endmodule

module up_down_counter_sva (
    input logic [2:0] D,
    input logic UD,
    input logic LD,
    input logic CLK,
    input logic [2:0] Q
);

    // When LD=1, Q loads D on that clock.
    check_load_on_LD: assert property (
        @(posedge CLK) LD |-> (Q == D)
    );

    // When LD=0 and UD=1, Q decrements by 1 (mod-8).
    check_decrement_when_UD_no_LD: assert property (
        @(posedge CLK) (!LD && UD) |-> (Q == $past(Q) - 3'd1)
    );

    // When LD=0 and UD=0, Q increments by 1 (mod-8).
    check_increment_when_no_LD_no_UD: assert property (
        @(posedge CLK) (!LD && !UD) |-> (Q == $past(Q) + 3'd1)
    );

    // LD has priority over UD when both are 1.
    check_ld_overrides_ud: assert property (
        @(posedge CLK) (LD && UD) |-> (Q == D)
    );

    // With no load, the counter never holds its value.
    check_no_hold_when_no_LD: assert property (
        @(posedge CLK) (!LD) |-> (Q != $past(Q))
    );

    // Decrement wraps from 0 to 7.
    check_wrap_on_decrement_from_zero: assert property (
        @(posedge CLK) (!LD && UD && ($past(Q) == 3'd0)) |-> (Q == 3'd7)
    );

    // Increment wraps from 7 to 0.
    check_wrap_on_increment_from_seven: assert property (
        @(posedge CLK) (!LD && !UD && ($past(Q) == 3'd7)) |-> (Q == 3'd0)
    );

    // Two consecutive cycles of UD=1 and LD=0 subtract 2.
    check_two_cycle_decrement: assert property (
        @(posedge CLK) ((!LD && UD) ##1 (!LD && UD)) |-> (Q == $past(Q,2) - 3'd2)
    );

    // Two consecutive cycles of UD=0 and LD=0 add 2.
    check_two_cycle_increment: assert property (
        @(posedge CLK) ((!LD && !UD) ##1 (!LD && !UD)) |-> (Q == $past(Q,2) + 3'd2)
    );

endmodule

