module sky130_fd_sc_hd__or4b_sva (
    input logic CLK,   // Sampling clock for assertions (RTL has no clock/reset)
    input logic A,
    input logic B,
    input logic C,
    input logic D_N,
    input logic X
);
    ///// Functional equivalence /////
    // X implements a 4-input NAND of {A,B,C,D_N}.
    check_functional_equation: assert property (
        @(posedge CLK) X == ~(A & B & C & D_N)
    );

    ///// Basic implications /////
    // When all inputs are 1, X must be 0.
    check_all_ones_implies_X0: assert property (
        @(posedge CLK) (A && B && C && D_N) |-> (X == 1'b0)
    );
    // If A is 0, X must be 1.
    check_A_zero_implies_X1: assert property (
        @(posedge CLK) (!A) |-> (X == 1'b1)
    );
    // If B is 0, X must be 1.
    check_B_zero_implies_X1: assert property (
        @(posedge CLK) (!B) |-> (X == 1'b1)
    );
    // If C is 0, X must be 1.
    check_C_zero_implies_X1: assert property (
        @(posedge CLK) (!C) |-> (X == 1'b1)
    );
    // If D_N is 0, X must be 1.
    check_DN_zero_implies_X1: assert property (
        @(posedge CLK) (!D_N) |-> (X == 1'b1)
    );

    ///// Output transition constraints /////
    // X can only fall when all inputs are 1 in the same cycle.
    check_X_fall_implies_all_ones: assert property (
        @(posedge CLK) $fell(X) |-> (A && B && C && D_N)
    );
    // X can only rise when at least one input is 0 in the same cycle.
    check_X_rise_implies_any_zero: assert property (
        @(posedge CLK) $rose(X) |-> (!A || !B || !C || !D_N)
    );

    ///// Input transition effects under enabling conditions /////
    // If A rises while B,C,D_N are 1, X must fall.
    check_rise_A_others1_causes_X_fall: assert property (
        @(posedge CLK) (B && C && D_N && $rose(A)) |-> $fell(X)
    );
    // If B rises while A,C,D_N are 1, X must fall.
    check_rise_B_others1_causes_X_fall: assert property (
        @(posedge CLK) (A && C && D_N && $rose(B)) |-> $fell(X)
    );
    // If C rises while A,B,D_N are 1, X must fall.
    check_rise_C_others1_causes_X_fall: assert property (
        @(posedge CLK) (A && B && D_N && $rose(C)) |-> $fell(X)
    );
    // If D_N rises while A,B,C are 1, X must fall.
    check_rise_DN_others1_causes_X_fall: assert property (
        @(posedge CLK) (A && B && C && $rose(D_N)) |-> $fell(X)
    );
endmodule

verilog_code:
module priority_encoder (
    input [7:0] I,
    output reg EN,
    output reg V,
    output reg [2:0] Q
);

    parameter WIDTH = 8;
    integer i;

    always @(*) begin
        if (|I) begin
            EN = 1;
            V = (|I) & (~&I);
            for (i = 0; i < WIDTH; i = i + 1) begin
                if (I[i]) begin
                    Q = i + 1'b1;
                end
            end
        end
        else begin
            EN = 0;
            V = 0;
            Q = 0;
        end
    end

endmodule

sva_code:
module priority_encoder_sva (
    input logic clk,
    input logic [7:0] I,
    input logic EN,
    input logic V,
    input logic [2:0] Q
);
    // EN equals reduction-OR of I.
    check_en_matches_or: assert property (
        @(posedge clk) EN == (|I)
    );

    // V is 1 when some but not all bits of I are 1.
    check_v_matches_some_but_not_all: assert property (
        @(posedge clk) V == ((|I) & (~&I))
    );

    // When I is zero, outputs are all zero.
    check_outputs_when_I_zero: assert property (
        @(posedge clk) (I == 8'b0) |-> (EN == 1'b0 && V == 1'b0 && Q == 3'b000)
    );

    // If bit 7 is set, Q wraps to 0 due to i+1 truncation to 3 bits.
    check_q_zero_when_bit7_set: assert property (
        @(posedge clk) I[7] |-> (Q == 3'b000)
    );

    // If highest set bit is 6 (and 7 is 0), Q is 7.
    check_q_when_highest_6: assert property (
        @(posedge clk) (I[7] == 1'b0 && I[6] == 1'b1) |-> (Q == 3'b111)
    );

    // If highest set bit is 5 (and 7:6 are 0), Q is 6.
    check_q_when_highest_5: assert property (
        @(posedge clk) (I[7:6] == 2'b00 && I[5]) |-> (Q == 3'b110)
    );

    // If highest set bit is 4 (and 7:5 are 0), Q is 5.
    check_q_when_highest_4: assert property (
        @(posedge clk) (I[7:5] == 3'b000 && I[4]) |-> (Q == 3'b101)
    );

    // If highest set bit is 3 (and 7:4 are 0), Q is 4.
    check_q_when_highest_3: assert property (
        @(posedge clk) (I[7:4] == 4'b0000 && I[3]) |-> (Q == 3'b100)
    );

    // If highest set bit is 2 (and 7:3 are 0), Q is 3.
    check_q_when_highest_2: assert property (
        @(posedge clk) (I[7:3] == 5'b00000 && I[2]) |-> (Q == 3'b011)
    );

    // If highest set bit is 1 (and 7:2 are 0), Q is 2.
    check_q_when_highest_1: assert property (
        @(posedge clk) (I[7:2] == 6'b000000 && I[1]) |-> (Q == 3'b010)
    );

    // If highest set bit is 0 (and 7:1 are 0), Q is 1.
    check_q_when_highest_0: assert property (
        @(posedge clk) (I[7:1] == 7'b0000000 && I[0]) |-> (Q == 3'b001)
    );
endmodule

