module NAND4X0 (input IN1, IN2, IN3, IN4, output QN, input VDD, VSS);
  wire nand1, nand2, nand3;

  assign nand1 = ~(IN1 & IN2);
  assign nand2 = ~(IN3 & IN4);
  assign nand3 = ~(nand1 & nand2);

  assign QN = nand3;
endmodule

sva_code:
module NAND4X0_sva (
    input logic clk,
    input logic IN1,
    input logic IN2,
    input logic IN3,
    input logic IN4,
    input logic QN,
    input logic VDD,
    input logic VSS
);
    // QN equals (IN1&IN2) OR (IN3&IN4).
    check_qn_function: assert property (
        @(posedge clk) QN == ((IN1 & IN2) | (IN3 & IN4))
    );

    // If IN1 and IN2 are HIGH, QN must be HIGH.
    check_pair12_implies_high: assert property (
        @(posedge clk) (IN1 && IN2) |-> QN
    );

    // If IN3 and IN4 are HIGH, QN must be HIGH.
    check_pair34_implies_high: assert property (
        @(posedge clk) (IN3 && IN4) |-> QN
    );

    // If neither pair is both HIGH, QN must be LOW.
    check_both_pairs_not_high_implies_low: assert property (
        @(posedge clk) (!(IN1 && IN2) && !(IN3 && IN4)) |-> !QN
    );

    // If QN is LOW, neither pair can be both HIGH.
    check_low_implies_no_pair_high: assert property (
        @(posedge clk) !QN |-> (!(IN1 && IN2) && !(IN3 && IN4))
    );

    // If QN is HIGH, at least one pair is both HIGH.
    check_high_implies_some_pair_high: assert property (
        @(posedge clk) QN |-> ((IN1 && IN2) || (IN3 && IN4))
    );

    // If all four inputs are stable, QN must be stable (pure combinational).
    check_stability_with_stable_inputs: assert property (
        @(posedge clk) $stable({IN1,IN2,IN3,IN4}) |-> $stable(QN)
    );

    // QN changes only if at least one of the four inputs changes.
    check_output_change_requires_input_change: assert property (
        @(posedge clk) $changed(QN) |-> !$stable({IN1,IN2,IN3,IN4})
    );

    // Changes on VDD/VSS do not affect QN when data inputs are stable.
    check_power_pins_no_effect: assert property (
        @(posedge clk) ($changed(VDD) || $changed(VSS)) && $stable({IN1,IN2,IN3,IN4}) |-> $stable(QN)
    );

    // If all inputs are LOW, QN must be LOW.
    check_all_zero_implies_low: assert property (
        @(posedge clk) (!IN1 && !IN2 && !IN3 && !IN4) |-> !QN
    );
endmodule

module xor_32_sva (
    input logic CLK,
    input logic [31:0] X,
    input logic [31:0] Y,
    input logic [31:0] Dout
);
    // Clock: CLK (posedge). No reset in RTL; mask first cycle with $initstate.
    // Sequential: Dout is a 1-cycle-registered XOR of X and Y.

    // Dout equals previous cycle's bitwise XOR of X and Y.
    check_dout_pipeline_xor: assert property (
        @(posedge CLK) disable iff ($initstate) (Dout == $past(X ^ Y))
    );

    // If X equals Y in this cycle, Dout is zero next cycle.
    check_zero_when_inputs_equal: assert property (
        @(posedge CLK) disable iff ($initstate) (X == Y) |=> (Dout == 32'b0)
    );

    // If X is bitwise complement of Y in this cycle, Dout is all ones next cycle.
    check_allones_when_inputs_complementary: assert property (
        @(posedge CLK) disable iff ($initstate) (X == ~Y) |=> (Dout == 32'hFFFF_FFFF)
    );

    // If Y is zero in this cycle, Dout equals prior X next cycle.
    check_prevY_zero_passes_prevX: assert property (
        @(posedge CLK) disable iff ($initstate) (Y == 32'b0) |=> (Dout == $past(X))
    );

    // If X is zero in this cycle, Dout equals prior Y next cycle.
    check_prevX_zero_passes_prevY: assert property (
        @(posedge CLK) disable iff ($initstate) (X == 32'b0) |=> (Dout == $past(Y))
    );

    // If Y is all ones in this cycle, Dout equals bitwise NOT of prior X next cycle.
    check_prevY_ones_inverts_prevX: assert property (
        @(posedge CLK) disable iff ($initstate) (Y == 32'hFFFF_FFFF) |=> (Dout == ~ $past(X))
    );

    // If X is all ones in this cycle, Dout equals bitwise NOT of prior Y next cycle.
    check_prevX_ones_inverts_prevY: assert property (
        @(posedge CLK) disable iff ($initstate) (X == 32'hFFFF_FFFF) |=> (Dout == ~ $past(Y))
    );

endmodule

verilog_code:
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] SUM
);

    wire [3:0] B_comp;
    assign B_comp = ~B + 1;

    assign SUM = (SUB) ? A + B_comp : A + B;

endmodule

sva_code:
module adder_subtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] SUM
);
    // SUM matches the RTL expression for both add and subtract paths (modulo 16).
    functional_equivalence_to_rtl: assert property (
        @(posedge clk) SUM == ( SUB
            ? (({1'b0, A} + ({1'b0, ~B} + 5'd1)) [3:0])
            : (({1'b0, A} + {1'b0, B}) [3:0]) )
    );

    // When SUB=0, SUM is low 4 bits of A+B.
    add_path_correct: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (SUM == (({1'b0, A} + {1'b0, B}) [3:0]))
    );

    // When SUB=1, SUM is low 4 bits of A+(~B+1).
    sub_path_correct: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (SUM == (({1'b0, A} + ({1'b0, ~B} + 5'd1)) [3:0]))
    );

    // If B is zero, SUM equals A regardless of SUB.
    identity_when_B_is_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (SUM == A)
    );

    // If A is zero and SUB=0, SUM equals B.
    add_identity_when_A_zero: assert property (
        @(posedge clk) (SUB == 1'b0 && A == 4'd0) |-> (SUM == B)
    );

    // If SUB=1 and A==B, SUM is zero (A - A = 0 modulo 16).
    subtract_equal_operands_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && (A == B)) |-> (SUM == 4'd0)
    );

    // If SUB=1 and B=15, SUM equals A+1 modulo 16.
    sub_with_B_15_increments_A: assert property (
        @(posedge clk) (SUB == 1'b1 && B == 4'd15) |-> (SUM == (({1'b0, A} + 5'd1) [3:0]))
    );

    // If SUB=1 and B=8, SUM equals A+8 modulo 16 (since ~8+1 == 8 in 4-bit).
    sub_with_B_8_equals_add_8: assert property (
        @(posedge clk) (SUB == 1'b1 && B == 4'd8) |-> (SUM == (({1'b0, A} + 5'd8) [3:0]))
    );

    // If A, B, and SUB hold their values, SUM must hold as well (combinational behavior).
    stable_output_when_inputs_stable: assert property (
        @(posedge clk) $stable(A) && $stable(B) && $stable(SUB) |-> $stable(SUM)
    );
endmodule

