module RegisterAdd_4 (
  input clk,
  input rst,
  input load,
  input [3:0] D,
  output [3:0] Q
);

  reg [3:0] reg_out;
  wire [3:0] add_out;

  always @(posedge clk, posedge rst) begin
    if (rst) begin
      reg_out <= 4'b0;
    end else if (load) begin
      reg_out <= D;
    end else begin
      reg_out <= reg_out + D;
    end
  end

  assign Q = reg_out;

endmodule

sva_code:
module RegisterAdd_4_sva (
  input logic clk,
  input logic rst,
  input logic load,
  input logic [3:0] D,
  input logic [3:0] Q
);

  ///// Environment assumptions /////
  // Assume reset does not glitch between clock edges.
  assume_stable_reset: assume property (
    @(posedge clk) $stable(rst)
  );

  ///// Reset behavior /////
  // While reset is asserted, Q must be 0.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (Q == 4'b0000)
  );

  ///// Load and accumulate behaviors /////
  // If load is HIGH, next Q equals current D.
  load_writes_D_to_Q: assert property (
    @(posedge clk) disable iff (rst) load |=> (Q == $past(D))
  );

  // If load is LOW, next Q equals current Q + D modulo 16.
  add_when_not_load: assert property (
    @(posedge clk) disable iff (rst) !load |=> (Q == (($past(Q) + $past(D))[3:0]))
  );

  // If load is LOW and D is 0, Q holds its value.
  hold_when_addend_zero: assert property (
    @(posedge clk) disable iff (rst) (!load && (D == 4'b0000)) |=> (Q == $past(Q))
  );

  // If load is HIGH and D is 0, Q becomes 0.
  load_zero_clears: assert property (
    @(posedge clk) disable iff (rst) (load && (D == 4'b0000)) |=> (Q == 4'b0000)
  );

  // If load is LOW and D is nonzero, Q must change (modulo 16).
  add_nonzero_changes_Q: assert property (
    @(posedge clk) disable iff (rst) (!load && (D != 4'b0000)) |=> (Q != $past(Q))
  );

  ///// Useful arithmetic corner checks (mod-16 wrap) /////
  // When Q=15 and D=1 with load LOW, next Q wraps to 0.
  wrap_15_plus_1_to_0: assert property (
    @(posedge clk) disable iff (rst) ($past(!load) && ($past(Q) == 4'hF) && ($past(D) == 4'h1)) |-> (Q == 4'h0)
  );

  // When Q=8 and D=8 with load LOW, next Q wraps to 0.
  wrap_8_plus_8_to_0: assert property (
    @(posedge clk) disable iff (rst) ($past(!load) && ($past(Q) == 4'h8) && ($past(D) == 4'h8)) |-> (Q == 4'h0)
  );

endmodule

module synchronous_counter_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] count
);
    ///// Reset behavior /////
    // While reset is HIGH at a clock edge, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

    ///// Normal counting behavior (when not in reset) /////
    // If last cycle was not reset and count <= 8, increment by 1.
    check_increment_when_below_9: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) <= 4'd8)) |-> (count == $past(count) + 4'd1)
    );

    // If last cycle was not reset and count was 9, wrap to 0.
    check_wrap_from_9_to_0: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) == 4'd9)) |-> (count == 4'd0)
    );

    // After at least one non-reset cycle, count must be within 0..9.
    check_range_after_nonreset: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset)) |-> (count <= 4'd9)
    );

    // If not in reset now and previously not in reset, a zero must come from a wrap from 9.
    check_zero_only_from_wrap_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && !reset && $past(!reset) && (count == 4'd0)) |-> ($past(count) == 4'd9)
    );

    // If last cycle was not reset and count <= 8, the value must change (no hold).
    check_no_hold_when_below_9: assert property (
        @(posedge clk) disable iff (reset)
            (!$initstate && $past(!reset) && ($past(count) <= 4'd8)) |-> (count != $past(count))
    );

    ///// Reset release behavior /////
    // On reset falling edge, count is 0 this cycle and 1 on the next (if reset stays low).
    check_post_reset_first_increment: assert property (
        @(posedge clk) disable iff (reset)
            $fell(reset) |-> (count == 4'd0) ##1 (count == 4'd1)
    );

    ///// Periodicity /////
    // With no reset for 10 cycles, count repeats every 10 cycles.
    check_period_10_no_reset: assert property (
        @(posedge clk) disable iff (reset)
            1'b1 |-> ##10 (count == $past(count, 10))
    );
endmodule

