    // gray[0] equals prior bin[1] XOR bin[0].
    check_gray0_maps_bin10: assert property (
        @(posedge clk) disable iff (reset)
            $past(!reset) |-> (gray[0] == ($past(bin[1]) ^ $past(bin[0])))
    );
