    check_reg3_samples_reg2: assert property (
        @(posedge clk) 1'b1 |=> (reg3 === $past(reg2))
    );

    // reg4 samples reg3 every cycle.
    check_reg4_samples_reg3: assert property (
        @(posedge clk) 1'b1 |=> (reg4 === $past(reg3))
    );

