module updown_counter_sva (
    input logic clk,
    input logic U_D,
    input logic [3:0] Q
);
    ///// Counter update behavior /////
    // Q updates by +1 when U_D=1, else -1 (mod 16), on each clock after the first.
    check_update_rule: assert property (
        @(posedge clk) 1'b1 |=> (U_D ? (Q == $past(Q) + 4'd1) : (Q == $past(Q) - 4'd1))
    );

    // Q must change every cycle (never holds its value).
    check_q_always_changes: assert property (
        @(posedge clk) 1'b1 |=> $changed(Q)
    );

    // If counting up and previous Q was 15, wrap to 0.
    check_inc_wrap: assert property (
        @(posedge clk) 1'b1 |=> ( !(U_D && ($past(Q) == 4'hF)) || (Q == 4'h0) )
    );

    // If counting down and previous Q was 0, wrap to 15.
    check_dec_wrap: assert property (
        @(posedge clk) 1'b1 |=> ( !((!U_D) && ($past(Q) == 4'h0)) || (Q == 4'hF) )
    );

    // If counting up and previous Q != 15, increment by 1.
    check_inc_nonwrap: assert property (
        @(posedge clk) 1'b1 |=> ( !(U_D && ($past(Q) != 4'hF)) || (Q == $past(Q) + 4'd1) )
    );

    // If counting down and previous Q != 0, decrement by 1.
    check_dec_nonwrap: assert property (
        @(posedge clk) 1'b1 |=> ( !((!U_D) && ($past(Q) != 4'h0)) || (Q == $past(Q) - 4'd1) )
    );

    // The magnitude of the step each cycle is exactly 1 (mod 16).
    check_delta_one: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) || (Q == $past(Q) - 4'd1) )
    );

    // Exactly one of +1 or -1 delta holds each cycle.
    check_delta_exclusive: assert property (
        @(posedge clk) 1'b1 |=> ( (Q == $past(Q) + 4'd1) != (Q == $past(Q) - 4'd1) )
    );

    // U_D reflects the direction of change (increment iff U_D==1).
    check_direction_matches_delta: assert property (
        @(posedge clk) 1'b1 |=> ( U_D == (Q == $past(Q) + 4'd1) )
    );

    // LSB toggles every cycle due to +/-1 operation.
    check_lsb_toggle: assert property (
        @(posedge clk) 1'b1 |=> ( Q[0] != $past(Q[0]) )
    );
endmodule

module adder_sva (
    // Analysis: no clock/reset in RTL; purely combinational; S = (C ? A - B : A + B) with 4-bit wrap.
    // Key signals: A[3:0], B[3:0], C (mode select), S[3:0] (result).
    // Assertions sample on an external clock 'clk'.
    input  logic        clk,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        C,
    input  logic [3:0]  S
);
    // Add mode: S equals low 4 bits of A+B when C==0.
    check_add_mode_result: assert property (
        @(posedge clk) (C == 1'b0) |-> (S == (A + B)[3:0])
    );

    // Sub mode: S equals low 4 bits of A-B when C==1.
    check_sub_mode_result: assert property (
        @(posedge clk) (C == 1'b1) |-> (S == (A - B)[3:0])
    );

    // Combinational determinism: if {A,B,C} are stable, S is stable.
    stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,C}) |-> $stable(S)
    );

    // Identity for zero B: adding or subtracting zero yields A.
    identity_when_B_zero: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A)
    );

    // Add identity: when A is zero in add mode, S equals B.
    add_identity_A_zero: assert property (
        @(posedge clk) (C == 1'b0 && A == 4'h0) |-> (S == B)
    );

    // Sub equality: when A==B in sub mode, S is zero (mod-16).
    sub_zero_when_A_eq_B: assert property (
        @(posedge clk) (C == 1'b1 && A == B) |-> (S == 4'h0)
    );

    // Add invertibility (mod-16): in add mode, (S - A) mod 16 equals B.
    add_mode_invertibility: assert property (
        @(posedge clk) (C == 1'b0) |-> ((S - A)[3:0] == B)
    );

    // Sub invertibility (mod-16): in sub mode, (S + B) mod 16 equals A.
    sub_mode_invertibility: assert property (
        @(posedge clk) (C == 1'b1) |-> ((S + B)[3:0] == A)
    );
endmodule

