        @(posedge clk) (en && (sel == 2'b10)) |-> (out == in2)
    );
    // When en and sel==11, out equals in3.
    check_out_matches_in3_when_en_sel11: assert property (
        @(posedge clk) (en && (sel == 2'b11)) |-> (out == in3)
    );
