verilog_code:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  output C
);

  wire [3:0] sum;
  wire C1, C2, C3; // Intermediate carry signals

  // Full adder for least significant bit
  full_adder fa0(
    .a(A[0]),
    .b(B[0]),
    .c_in(1'b0),
    .sum(sum[0]),
    .c_out(C1)
  );

  // Full adder for second least significant bit
  full_adder fa1(
    .a(A[1]),
    .b(B[1]),
    .c_in(C1),
    .sum(sum[1]),
    .c_out(C2)
  );

  // Full adder for third least significant bit
  full_adder fa2(
    .a(A[2]),
    .b(B[2]),
    .c_in(C2),
    .sum(sum[2]),
    .c_out(C3)
  );

  // Full adder for most significant bit
  full_adder fa3(
    .a(A[3]),
    .b(B[3]),
    .c_in(C3),
    .sum(sum[3]),
    .c_out(C)
  );

  assign S = sum;

endmodule
module full_adder(
  input a,
  input b,
  input c_in,
  output sum,
  output c_out
);

  assign sum = a ^ b ^ c_in;
  assign c_out = (a & b) | (a & c_in) | (b & c_in);

endmodule

sva_code:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C
);
    // Local recompute of ripple-carry chain from A and B
    logic c1, c2, c3;
    logic [4:0] exp_sum5;

    assign c1 = A[0] & B[0];
    assign c2 = (A[1] & B[1]) | (A[1] & c1) | (B[1] & c1);
    assign c3 = (A[2] & B[2]) | (A[2] & c2) | (B[2] & c2);
    assign exp_sum5 = {1'b0, A} + {1'b0, B};

    // The 5-bit result {C,S} equals A+B with zero carry-in.
    check_vector_sum_matches_add: assert property (
        @(posedge clk) disable iff (1'b0) ({C, S} == exp_sum5)
    );

    // LSB sum is XOR of A[0] and B[0] (c_in=0).
    check_sum_bit0_xor: assert property (
        @(posedge clk) disable iff (1'b0) (S[0] == (A[0] ^ B[0]))
    );

    // Bit1 sum equals XOR of A[1], B[1], and c1.
    check_sum_bit1_xor_with_c1: assert property (
        @(posedge clk) disable iff (1'b0) (S[1] == (A[1] ^ B[1] ^ c1))
    );

    // Bit2 sum equals XOR of A[2], B[2], and c2.
    check_sum_bit2_xor_with_c2: assert property (
        @(posedge clk) disable iff (1'b0) (S[2] == (A[2] ^ B[2] ^ c2))
    );

    // Bit3 sum equals XOR of A[3], B[3], and c3.
    check_sum_bit3_xor_with_c3: assert property (
        @(posedge clk) disable iff (1'b0) (S[3] == (A[3] ^ B[3] ^ c3))
    );

    // Final carry-out equals majority of A[3], B[3], and c3.
    check_carryout_majority: assert property (
        @(posedge clk) disable iff (1'b0) (C == ((A[3] & B[3]) | (A[3] & c3) | (B[3] & c3)))
    );

    // Carry-out equals MSB of the 5-bit sum.
    check_carryout_equals_sum_msb: assert property (
        @(posedge clk) disable iff (1'b0) (C == exp_sum5[4])
    );

    // Sum lower 4 bits equal lower 4 bits of A+B.
    check_sum_lower4_equals_add: assert property (
        @(posedge clk) disable iff (1'b0) (S == exp_sum5[3:0])
    );

    // Adding zero on A yields S=B and C=0.
    check_add_zero_on_A: assert property (
        @(posedge clk) disable iff (1'b0) ((A == 4'b0000) |-> (S == B) && (C == 1'b0))
    );

    // Adding zero on B yields S=A and C=0.
    check_add_zero_on_B: assert property (
        @(posedge clk) disable iff (1'b0) ((B == 4'b0000) |-> (S == A) && (C == 1'b0))
    );

    // If no bit position has both A and B set, result is XOR and no carry.
    check_no_overlap_bits_implies_xor: assert property (
        @(posedge clk) disable iff (1'b0) (((A & B) == 4'b0000) |-> (S == (A ^ B)) && (C == 1'b0))
    );

endmodule

verilog_code:
module strobe_gen 
  ( input clock,
    input reset,
    input enable,
    input [7:0] rate, input strobe_in,
    output wire strobe );

reg [7:0] counter;
   assign strobe = ~|counter && enable && strobe_in;

   always @(posedge clock)
     if(reset | ~enable)
       counter <= #1 8'd0;
     else if(strobe_in)
       if(counter == 0)
	 counter <= #1 rate;
       else 
	 counter <= #1 counter - 8'd1;

endmodule

sva_code:
module strobe_gen_sva (
    input logic clock,
    input logic reset,
    input logic enable,
    input logic [7:0] rate,
    input logic strobe_in,
    input logic strobe,
    input logic [7:0] counter
);
    ///// Combinational strobe definition /////
    // strobe equals (counter==0) && enable && strobe_in.
    check_strobe_definition: assert property (
        @(posedge clock) (strobe == ((counter == 8'd0) && enable && strobe_in))
    );

    // strobe HIGH requires enable and strobe_in HIGH.
    strobe_requires_inputs: assert property (
        @(posedge clock) strobe |-> (enable && strobe_in)
    );

    // enable LOW forces strobe LOW.
    enable_low_forces_strobe_low: assert property (
        @(posedge clock) (!enable) |-> (strobe == 1'b0)
    );

    // strobe_in LOW forces strobe LOW.
    strobe_in_low_forces_strobe_low: assert property (
        @(posedge clock) (!strobe_in) |-> (strobe == 1'b0)
    );

    // strobe HIGH implies counter is zero.
    strobe_implies_counter_zero: assert property (
        @(posedge clock) strobe |-> (counter == 8'd0)
    );

    // When counter is zero and inputs are HIGH, strobe is HIGH.
    zero_counter_inputs_high_implies_strobe: assert property (
        @(posedge clock) (enable && strobe_in && (counter == 8'd0)) |-> strobe
    );

    ///// Counter update behavior /////
    // On reset, counter clears to zero on next cycle.
    counter_clears_on_reset: assert property (
        @(posedge clock) reset |=> (counter == 8'd0)
    );

    // When enable is LOW, counter clears to zero on next cycle.
    counter_clears_when_disabled: assert property (
        @(posedge clock) (!reset && !enable) |=> (counter == 8'd0)
    );

    // With enable HIGH and strobe_in LOW, counter holds its value.
    counter_holds_when_strobe_in_low: assert property (
        @(posedge clock) disable iff (reset) (enable && !strobe_in) |=> (counter == $past(counter))
    );

    // With enable and strobe_in HIGH and counter non-zero, counter decrements by one.
    counter_decrements_when_nonzero: assert property (
        @(posedge clock) disable iff (reset) (enable && strobe_in && (counter != 8'd0)) |=> (counter == $past(counter) - 8'd1)
    );

    // With enable and strobe_in HIGH and counter zero, counter loads rate.
    counter_loads_rate_when_zero: assert property (
        @(posedge clock) disable iff (reset) (enable && strobe_in && (counter == 8'd0)) |=> (counter == rate)
    );

    // When strobe is HIGH, counter loads rate on next cycle.
    strobe_implies_load_rate_next: assert property (
        @(posedge clock) disable iff (reset) strobe |=> (counter == rate)
    );
endmodule

verilog_code:
module magnitude_comparator (
    input valid,
    input [3:0] A,
    input [3:0] B,
    input [1:0] sel,
    output [1:0] out_mode0,
    output less_than,
    output equal_to,
    output greater_than
);

    reg [1:0] magnitude;
    reg less_than_reg, equal_to_reg, greater_than_reg;

    always @(*) begin
        if (A == B) begin
            magnitude = 2'b00;
            less_than_reg = 1'b0;
            equal_to_reg = 1'b1;
            greater_than_reg = 1'b0;
        end else if (A > B) begin
            magnitude = 2'b01;
            less_than_reg = 1'b0;
            equal_to_reg = 1'b0;
            greater_than_reg = 1'b1;
        end else begin
            magnitude = 2'b10;
            less_than_reg = 1'b1;
            equal_to_reg = 1'b0;
            greater_than_reg = 1'b0;
        end
    end

    assign out_mode0 = (sel == 2'b00) ? magnitude : 2'b00;
    assign less_than = (sel == 2'b01) ? less_than_reg : 1'b0;
    assign equal_to = (sel == 2'b01) ? equal_to_reg : 1'b0;
    assign greater_than = (sel == 2'b01) ? greater_than_reg : 1'b0;

endmodule

sva_code:
module magnitude_comparator_sva (
    input logic        valid,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [1:0]  sel,
    input logic [1:0]  out_mode0,
    input logic        less_than,
    input logic        equal_to,
    input logic        greater_than
);
    ///// Mode-0 (magnitude code) behavior /////
    // When sel==00, out_mode0 encodes compare result: 00 if A==B, 01 if A>B, 10 if A<B.
    check_sel00_magnitude_encoding: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0 == ((A == B) ? 2'b00 : ((A > B) ? 2'b01 : 2'b10)))
    );
    // When sel!=00, out_mode0 must be 00.
    check_sel_not00_out_zero: assert property (
        @(posedge valid) (sel != 2'b00) |-> (out_mode0 == 2'b00)
    );
    // For sel==00, out_mode0[1] reflects (A<B).
    check_sel00_out_msb_is_less: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[1] == (A < B))
    );
    // For sel==00, out_mode0[0] reflects (A>B).
    check_sel00_out_lsb_is_greater: assert property (
        @(posedge valid) (sel == 2'b00) |-> (out_mode0[0] == (A > B))
    );

    ///// Mode-1 (flag outputs) behavior /////
    // When sel==01, less_than reflects (A<B).
    check_sel01_less_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (less_than == (A < B))
    );
    // When sel==01, equal_to reflects (A==B).
    check_sel01_equal_to_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (equal_to == (A == B))
    );
    // When sel==01, greater_than reflects (A>B).
    check_sel01_greater_than_matches: assert property (
        @(posedge valid) (sel == 2'b01) |-> (greater_than == (A > B))
    );
    // When sel==01, exactly one of the three flags is HIGH.
    check_sel01_onehot_result: assert property (
        @(posedge valid) (sel == 2'b01) |-> $onehot({less_than, equal_to, greater_than})
    );

    ///// Output gating when not in mode-1 /////
    // When sel!=01, less_than must be 0.
    check_sel_not01_less_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (less_than == 1'b0)
    );
    // When sel!=01, equal_to must be 0.
    check_sel_not01_equal_zero: assert property (
        @(posedge valid) (sel != 2'b01) |-> (equal_to == 1'b0)
    );
