    check_allA_high_forces_Y0: assert property (
        @(posedge A1) (A1 & A2 & A3) |-> (Y == 1'b0)
    );

    // If the OR of (A1&A2&A3), B1, or C1 is high, Y must be low.
    check_or_inputs_high_implies_Y0: assert property (
        @(posedge A1) ((A1 & A2 & A3) | B1 | C1) |-> (Y == 1'b0)
