module shift_mux_adder_sva (
    input logic clk,
    input logic [7:0] data_in_0,
    input logic [7:0] data_in_1,
    input logic [7:0] data_in_2,
    input logic [7:0] data_in_3,
    input logic [3:0] B,
    input logic sel1,
    input logic sel2,
    input logic [7:0] out
);
    // When B>3, out is forced to zero.
    check_B_gt3_zero: assert property (
        @(posedge clk) (B > 4'd3) |-> (out == 8'b0)
    );

    // For B<=3, out equals selected input left-shifted by B.
    check_B_le3_selected_shift: assert property (
        @(posedge clk) (B <= 4'd3) |-> (out == (((sel2 == 1'b0) ? ((sel1 == 1'b0) ? data_in_0 : data_in_1)
                                                                 : ((sel1 == 1'b0) ? data_in_2 : data_in_3)) << B))
    );

    // For B<=3 and sel=00, out equals data_in_0 << B.
    check_sel00_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b0) && (sel1 == 1'b0)) |-> (out == (data_in_0 << B))
    );

    // For B<=3 and sel=01, out equals data_in_1 << B.
    check_sel01_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b0) && (sel1 == 1'b1)) |-> (out == (data_in_1 << B))
    );

    // For B<=3 and sel=10, out equals data_in_2 << B.
    check_sel10_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b1) && (sel1 == 1'b0)) |-> (out == (data_in_2 << B))
    );

    // For B<=3 and sel=11, out equals data_in_3 << B.
    check_sel11_shift: assert property (
        @(posedge clk) ((B <= 4'd3) && (sel2 == 1'b1) && (sel1 == 1'b1)) |-> (out == (data_in_3 << B))
    );

    // For B==0, out passes through the selected input.
    check_B0_passthrough: assert property (
        @(posedge clk) (B == 4'd0) |-> (out == ((sel2 == 1'b0) ? ((sel1 == 1'b0) ? data_in_0 : data_in_1)
                                                              : ((sel1 == 1'b0) ? data_in_2 : data_in_3)))
    );

    // For B==1, LSB of out is zero due to left shift.
    check_B1_zero_fill: assert property (
        @(posedge clk) (B == 4'd1) |-> (out[0] == 1'b0)
    );

    // For B==2, two LSBs of out are zero due to left shift.
    check_B2_zero_fill: assert property (
        @(posedge clk) (B == 4'd2) |-> (out[1:0] == 2'b00)
    );

    // For B==3, three LSBs of out are zero due to left shift.
    check_B3_zero_fill: assert property (
        @(posedge clk) (B == 4'd3) |-> (out[2:0] == 3'b000)
    );
endmodule

module up_down_counter_4bit_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic en,
    input logic [3:0] data_in,
    input logic [3:0] out
);

    // If en was 0 last cycle, out holds its value.
    hold_when_en_low: assert property (
        @(posedge clk) ($past(en) == 1'b0) |-> (out == $past(out))
    );

    // If en and load were 1 last cycle, out captures data_in.
    load_captures_data: assert property (
        @(posedge clk) ($past(en) && $past(load)) |-> (out == $past(data_in))
    );

    // If en=1, load=0, up_down=1 last cycle, out increments by 1 (mod 16).
    count_up_next_value: assert property (
        @(posedge clk) ($past(en) && !$past(load) && $past(up_down)) |-> (out == ($past(out) + 4'd1))
    );

    // If en=1, load=0, up_down=0 last cycle, out decrements by 1 (mod 16).
    count_down_next_value: assert property (
        @(posedge clk) ($past(en) && !$past(load) && !$past(up_down)) |-> (out == ($past(out) - 4'd1))
    );

    // When enabled last cycle, next out equals load data or +/-1 as selected.
    functional_update_when_enabled: assert property (
        @(posedge clk) $past(en) |-> (
            out == ( $past(load)
                     ? $past(data_in)
                     : ( $past(up_down) ? ($past(out) + 4'd1) : ($past(out) - 4'd1) )
                   )
        )
    );

    // Any change in out implies en was 1 in the prior cycle.
    change_implies_enabled: assert property (
        @(posedge clk) (out != $past(out)) |-> $past(en)
    );

    // When counting (enabled, no load), out always changes from prior value.
    counting_changes_value: assert property (
        @(posedge clk) ($past(en) && !$past(load)) |-> (out != $past(out))
    );

    // If out did not change, reason is en=0 or a load of the same value.
    stable_out_has_reason: assert property (
        @(posedge clk) (out == $past(out)) |-> (
            ($past(en) == 1'b0) ||
            ($past(en) && $past(load) && ($past(data_in) == $past(out)))
        )
    );

    // Count up from 4'hF wraps to 4'h0.
    wrap_on_increment_from_max: assert property (
        @(posedge clk) ($past(en) && !$past(load) && $past(up_down) && ($past(out) == 4'hF)) |-> (out == 4'h0)
    );

    // Count down from 4'h0 wraps to 4'hF.
    wrap_on_decrement_from_min: assert property (
        @(posedge clk) ($past(en) && !$past(load) && !$past(up_down) && ($past(out) == 4'h0)) |-> (out == 4'hF)
    );

endmodule

module synchronous_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic control,
    input logic [3:0] count
);
    // Synchronous reset clears count to zero on the next cycle.
    reset_clears_next: assert property (
        @(posedge clk) reset |-> ##1 (count == 4'b0)
    );

    // While reset is held across cycles, count is zero.
    reset_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'b0)
    );

    // When enable is LOW, count holds its value on the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> ##1 (count == $past(count))
    );

    // When enable and control are HIGH, count increments by 1 on the next cycle.
    inc_on_enable_control: assert property (
        @(posedge clk) disable iff (reset) (enable && control) |-> ##1 (count == $past(count) + 4'd1)
    );

    // When enable is HIGH and control is LOW, count decrements by 1 on the next cycle.
    dec_on_enable_ncontrol: assert property (
        @(posedge clk) disable iff (reset) (enable && !control) |-> ##1 (count == $past(count) - 4'd1)
    );

    // With enable HIGH, count must change on the next cycle.
    change_when_enable: assert property (
        @(posedge clk) disable iff (reset) enable |-> ##1 (count != $past(count))
    );

    // Any change (excluding prior reset) implies previous enable was HIGH.
    change_implies_prev_enable: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count != $past(count))) |-> $past(enable)
    );

    // If count increased by 1 (excluding prior reset), previous enable && control were HIGH.
    inc_cause_requires_en_ctrl: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count == $past(count) + 4'd1)) |-> ($past(enable) && $past(control))
    );

    // If count decreased by 1 (excluding prior reset), previous enable was HIGH and control LOW.
    dec_cause_requires_en_nctrl: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (count == $past(count) - 4'd1)) |-> ($past(enable) && !$past(control))
    );

    // Wrap-around on increment: 0xF + 1 -> 0x0 when enabled and control HIGH.
    wrap_inc_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && control && (count == 4'hF)) |-> ##1 (count == 4'h0)
    );

    // Wrap-around on decrement: 0x0 - 1 -> 0xF when enabled and control LOW.
    wrap_dec_from_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && !control && (count == 4'h0)) |-> ##1 (count == 4'hF)
    );

    // LSB toggles whenever an update occurs (enable HIGH).
    lsb_toggles_when_enable: assert property (
        @(posedge clk) disable iff (reset) enable |-> ##1 (count[0] != $past(count[0]))
    );
endmodule

