    check_g_out_bar_low_implies_all_high: assert property (
        @(posedge CLK) disable iff (!RESETn) !g_out_BAR |-> (g_prec && p && g)
    );

    // When g_prec, p, and g are all HIGH, g_out_BAR must be LOW.
