module barrel_shifter (
    input [7:0] DATA,
    input [2:0] SHIFT_AMOUNT,
    input SHIFT_DIRECTION,
    output [7:0] SHIFTED_DATA
);

    reg [7:0] shifted_data;

    always @(*) begin
        if (SHIFT_DIRECTION == 0) begin
            shifted_data = DATA << SHIFT_AMOUNT;
        end else begin
            shifted_data = DATA >> SHIFT_AMOUNT;
        end
    end

    assign SHIFTED_DATA = shifted_data;

endmodule

sva_code:
module barrel_shifter_sva (
    input  logic        CLK,
    input  logic [7:0]  DATA,
    input  logic [2:0]  SHIFT_AMOUNT,
    input  logic        SHIFT_DIRECTION,
    input  logic [7:0]  SHIFTED_DATA
);

    // For SHIFT_DIRECTION=0, output equals DATA << SHIFT_AMOUNT.
    check_left_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

    // For SHIFT_DIRECTION=1, output equals DATA >> SHIFT_AMOUNT.
    check_right_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

    // Shift amount 0 leaves data unchanged.
    check_shift_by_zero_identity: assert property (
        @(posedge CLK) (SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

    // Left shift zero-fills lower bits.
    check_left_zero_fill_lsb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> ((SHIFTED_DATA & ((8'h1 << SHIFT_AMOUNT) - 8'h1)) == 8'h00)
    );

    // Right shift zero-fills upper bits.
    check_right_zero_fill_msb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> ((SHIFTED_DATA & ~(8'hFF >> SHIFT_AMOUNT)) == 8'h00)
    );

    // Output stable if all inputs stable.
    check_stable_with_stable_inputs: assert property (
        @(posedge CLK) $stable({DATA, SHIFT_AMOUNT, SHIFT_DIRECTION}) |-> $stable(SHIFTED_DATA)
    );

    // Zero input yields zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (DATA == 8'h00) |-> (SHIFTED_DATA == 8'h00)
    );

    // Left shift by 7 moves bit0 to MSB and clears others.
    check_left_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {DATA[0], 7'b0})
    );

    // Right shift by 7 moves MSB to LSB and clears others.
    check_right_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {7'b0, DATA[7]})
    );

    // Output equals selected shift function for all cases.
    check_functional_equation: assert property (
        @(posedge CLK) SHIFTED_DATA == ((SHIFT_DIRECTION == 1'b0) ? (DATA << SHIFT_AMOUNT) : (DATA >> SHIFT_AMOUNT))
    );

endmodule

module simple_counter_sva (
  input logic clk,
  input logic rst_n,
  input logic en,
  input logic [3:0] count
);
  // Clock: clk; Reset: rst_n active-low, synchronous
  // Sequential counter: increments on clk when en=1; holds when en=0; wraps 15->0

  // During reset, count is 0.
  reset_value: assert property (
    @(posedge clk) !rst_n |-> (count == 4'b0000)
  );

  // When en=0 (no reset), count holds its value.
  hold_when_en_low: assert property (
    @(posedge clk) disable iff (!rst_n) (!en) |-> $stable(count)
  );

  // When en=1 (no reset), count updates by +1 with wrap at 15->0.
  update_on_en_high: assert property (
    @(posedge clk) disable iff (!rst_n)
      en |-> (count == (($past(count) == 4'hf) ? 4'h0 : ($past(count) + 1'b1)))
  );

  // Any change to count (no reset) requires en=1.
  change_requires_en: assert property (
    @(posedge clk) disable iff (!rst_n) (!$stable(count)) |-> en
  );

  // When en=1 (no reset), the value must change.
  update_changes_value: assert property (
    @(posedge clk) disable iff (!rst_n) en |-> (count != $past(count))
  );

  // If en=1 and the new value is 0 (no reset), the previous value was 15.
  wrap_from_15_only: assert property (
    @(posedge clk) disable iff (!rst_n) (en && (count == 4'h0)) |-> ($past(count) == 4'hf)
  );

  // On the cycle reset is asserted, count is driven to 0.
  sync_reset_effect: assert property (
    @(posedge clk) $fell(rst_n) |-> (count == 4'h0)
  );
endmodule

module nova_io_pio_dummy_sva (
    input logic        pclk,
    input logic        bs_rst,     // Active-low async reset
    input logic        bs_stb,
    input logic        bs_we,
    input logic [7:0]  bs_adr,
    input logic [15:0] bs_din,
    input logic [15:0] bs_dout,
    input logic        r_DONE,
    input logic        r_BUSY
);
    parameter logic [5:0] device_addr = 6'b000000;

    // During reset, flags and bs_dout drive known values.
    reset_known_values: assert property (
        @(posedge pclk) !bs_rst |-> (r_DONE == 1'b1) && (r_BUSY == 1'b0) && (bs_dout == {1'b0, 1'b1, 14'h0000})
    );

    // bs_dout must reflect r_BUSY and r_DONE with lower 14 bits zero.
    dout_reflects_flags: assert property (
        @(posedge pclk) disable iff (!bs_rst) (bs_dout == {r_BUSY, r_DONE, 14'h0000})
    );

    // Write to group 00 with cmd 01 drives DONE=0, BUSY=1 on next cycle.
    write_cmd01_sets_busy: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b01))
            |=> (r_DONE == 1'b0) && (r_BUSY == 1'b1)
    );

    // Write to group 00 with cmd 10 drives DONE=0, BUSY=0 on next cycle.
    write_cmd10_clears_busy_and_done: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b10))
            |=> (r_DONE == 1'b0) && (r_BUSY == 1'b0)
    );

    // Write to group 00 with cmd 11 does not change flags.
    write_cmd11_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b11))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Write to group 00 with cmd 00 does not change flags.
    write_cmd00_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] == 2'b00) && (bs_din[15:14] == 2'b00))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Writes to groups 01/10/11 do not change flags.
    write_group_non00_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && bs_we && (bs_adr[7:6] != 2'b00))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Reads (any group) do not change flags.
    read_access_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] == device_addr) && !bs_we)
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // Non-targeted accesses do not change flags.
    non_target_access_no_change: assert property (
        @(posedge pclk) disable iff (!bs_rst)
            (bs_stb && (bs_adr[5:0] != device_addr))
            |=> (r_DONE == $past(r_DONE)) && (r_BUSY == $past(r_BUSY))
    );

    // BUSY implies DONE is low.
    busy_implies_done_low: assert property (
        @(posedge pclk) disable iff (!bs_rst) r_BUSY |-> (r_DONE == 1'b0)
    );

endmodule

module counter_sva (
  input logic clk,
  input logic rst,
  input logic dir,
  input logic [7:0] count
);

  // While reset is asserted, count must be 0.
  check_reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 8'd0)
  );

  // When dir=1 and count is not 255, next count increments by 1.
  check_up_increments_when_not_max: assert property (
    @(posedge clk) disable iff (rst) (dir && (count != 8'd255)) |=> (count == $past(count) + 8'd1)
  );

  // When dir=1 and count is 255, next count wraps to 0.
  check_up_wraps_at_255: assert property (
    @(posedge clk) disable iff (rst) (dir && (count == 8'd255)) |=> (count == 8'd0)
  );

  // When dir=0 and count is not 0, next count decrements by 1.
  check_down_decrements_when_not_min: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count != 8'd0)) |=> (count == $past(count) - 8'd1)
  );

  // When dir=0 and count is 0, next count wraps to 255.
  check_down_wraps_at_0: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count == 8'd0)) |=> (count == 8'd255)
  );

  // Out of reset, count changes every cycle.
  check_count_changes_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count != $past(count))
  );

  // Out of reset, LSB toggles every cycle (±1 update).
  check_lsb_toggles_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count[0] != $past(count[0]))
  );

  // Full next-state equation for dir=1 (increment with wrap at 255).
  check_up_next_state_equation: assert property (
    @(posedge clk) disable iff (rst) dir |-> (count == (($past(count) == 8'd255) ? 8'd0 : ($past(count) + 8'd1)))
  );

  // Full next-state equation for dir=0 (decrement with wrap at 0).
  check_down_next_state_equation: assert property (
    @(posedge clk) disable iff (rst) !dir |-> (count == (($past(count) == 8'd0) ? 8'd255 : ($past(count) - 8'd1)))
  );

  // Step size is always ±1 modulo 256 out of reset.
  check_step_is_plus_or_minus_one: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> ((count == $past(count) + 8'd1) || (count == $past(count) - 8'd1))
  );

endmodule

