    // Note: Assertions are sampled on posedge of ctrl[0] as a proxy clock.

    ///// Decode mapping /////
    // ctrl[7:5]==000 -> td_mode=0000
    decode_000: assert property (
        @(posedge ctrl[0]) (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );
