sva_code:
module six_input_module_sva (
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic Y
);
    // Y equals the RTL boolean function when A1 toggles.
    check_func_eq_on_A1: assert property (
        @(posedge A1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when A2 toggles.
    check_func_eq_on_A2: assert property (
        @(posedge A2) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when B1 toggles.
    check_func_eq_on_B1: assert property (
        @(posedge B1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when B2 toggles.
    check_func_eq_on_B2: assert property (
        @(posedge B2) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // Y equals the RTL boolean function when C1 toggles.
    check_func_eq_on_C1: assert property (
        @(posedge C1) Y == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );

    // C1 high forces Y high.
    check_c1_dominates_y: assert property (
        @(posedge C1) C1 |-> (Y == 1'b1)
    );

    // A1&A2&~B1&~B2 implies Y high.
    check_aa11_bb00_implies_y1: assert property (
        @(posedge A1) (A1 & A2 & ~B1 & ~B2) |-> (Y == 1'b1)
    );

    // ~A1&~A2&B1&B2 implies Y high.
    check_aa00_bb11_implies_y1: assert property (
        @(posedge B1) (~A1 & ~A2 & B1 & B2) |-> (Y == 1'b1)
    );

    // If no term true and C1 low, Y must be low.
    check_else_case_y0: assert property (
        @(posedge A2) (!C1 && !((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))) |-> (Y == 1'b0)
    );

    // Any rising edge of Y must be due to the function being true.
    check_y_rise_consistent_with_function: assert property (
        @(posedge Y) ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2) | C1)
    );
endmodule

verilog_code:
module freq_synthesizer (
  input clk_ref,
  input [31:0] ctrl_word,
  output reg out_clk
);

parameter N = 10;
parameter M = 5;

reg [31:0] counter;
reg [31:0] divider = 0;

always @(posedge clk_ref) begin
  counter <= counter + 1;
  if (counter == N-1) begin
    counter <= 0;
    if (divider == M-1) begin
      divider <= 0;
      out_clk <= ~out_clk;
    end
    else begin
      divider <= divider + 1;
    end
  end
end

endmodule

sva_code:
module freq_synthesizer_sva #(
    parameter int unsigned N = 10,
    parameter int unsigned M = 5
) (
    input  logic         clk_ref,
    input  logic [31:0]  ctrl_word,
    input  logic         out_clk,
    input  logic [31:0]  counter,
    input  logic [31:0]  divider
);
    // Local copies of thresholds for comparisons
    localparam logic [31:0] N_MINUS_1 = N - 1;
    localparam logic [31:0] M_MINUS_1 = M - 1;

    // Gate assertions for the first cycle
    logic past_valid;
    initial past_valid = 1'b0;
    always @(posedge clk_ref) past_valid <= 1'b1;

    // Counter increments by 1 when not at N-1.
    check_counter_increment_when_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (counter == $past(counter) + 32'd1)
    );

    // Counter wraps to 0 when at N-1.
    check_counter_wrap_to_zero: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1) |-> (counter == 32'd0)
    );

    // Divider holds when counter does not wrap.
    check_divider_stable_when_counter_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (divider == $past(divider))
    );

    // out_clk holds when counter does not wrap.
    check_outclk_stable_when_counter_not_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) != N_MINUS_1) |-> (out_clk == $past(out_clk))
    );

    // On counter wrap without divider wrap, divider increments and out_clk holds.
    check_divider_inc_on_counter_wrap_not_div_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1 && $past(divider) != M_MINUS_1)
            |-> (divider == $past(divider) + 32'd1) && (out_clk == $past(out_clk))
    );

    // On both counter and divider wrap, divider resets and out_clk toggles.
    check_both_wrap_resets_divider_and_toggles_outclk: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1 && $past(divider) == M_MINUS_1)
            |-> (divider == 32'd0) && (out_clk == ~$past(out_clk))
    );

    // On any counter wrap, only valid divider/out_clk updates occur (increment+hold or reset+toggle).
    check_counter_wrap_results_in_valid_update: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            ($past(counter) == N_MINUS_1)
            |-> (
                    ((divider == $past(divider) + 32'd1) && (out_clk == $past(out_clk))) ||
                    ((divider == 32'd0) && (out_clk == ~$past(out_clk)))
                )
    );

    // out_clk can only change when both counter and divider were at their terminal values.
    check_outclk_toggle_only_on_both_wraps: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> ($past(counter) == N_MINUS_1) && ($past(divider) == M_MINUS_1)
    );

    // Any change of divider implies counter wrapped the previous cycle.
    check_divider_change_implies_counter_wrap: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            (divider != $past(divider)) |-> ($past(counter) == N_MINUS_1)
    );

    // out_clk cannot toggle in back-to-back cycles.
    check_no_back_to_back_outclk_toggle: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> ##1 !$changed(out_clk)
    );

    // Any change of out_clk must be a logical inversion.
    check_outclk_change_is_invert: assert property (
        @(posedge clk_ref) disable iff (!past_valid)
            $changed(out_clk) |-> (out_clk == ~$past(out_clk))
    );

endmodule

verilog_code:
module nor_gate(
    input A,
    input B,
    output Z
);

    assign Z = ~(A | B);

endmodule

sva_code:
module nor_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Z
);
    // Z implements NOR of A and B.
    check_nor_function: assert property (
        @(posedge clk) Z === ~(A | B)
    );

    // Z equals (~A & ~B) (De Morgan consistency).
    check_demorgan_equivalence: assert property (
        @(posedge clk) Z === ((~A) & (~B))
    );

    // Z can be HIGH only when both inputs are LOW.
    check_Z_high_only_if_inputs_low: assert property (
        @(posedge clk) (Z === 1'b1) |-> ((A === 1'b0) && (B === 1'b0))
    );

    // When both inputs are LOW, Z must be HIGH.
    check_inputs_low_imply_Z_high: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Z === 1'b1)
    );

    // If A is HIGH, Z must be LOW.
    check_A_high_implies_Z_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Z === 1'b0)
    );

    // If B is HIGH, Z must be LOW.
    check_B_high_implies_Z_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Z === 1'b0)
    );

    // If both inputs are HIGH, Z must be LOW.
    check_both_inputs_high_implies_Z_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (Z === 1'b0)
    );

    // If Z is LOW, at least one input must be HIGH.
    check_Z_low_implies_any_input_high: assert property (
        @(posedge clk) (Z === 1'b0) |-> ((A === 1'b1) || (B === 1'b1))
    );

    // If inputs are stable across cycles, Z must be stable.
    check_output_stable_if_inputs_stable: assert property (
        @(posedge clk) $stable({A,B}) |-> $stable(Z)
    );

    // If Z changes, at least one input must have changed.
    check_output_change_implies_input_change: assert property (
        @(posedge clk) $changed(Z) |-> $changed({A,B})
    );
endmodule

