sva_code:
module sky130_fd_sc_lp__nand4_sva (
    input logic CLK,   // Sampling clock (DUT has no clock/reset; purely combinational)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);
    ///// Functional equivalence /////
    // Y equals the 4-input NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge CLK) Y == ~(A & B & C & D)
    );

    ///// Truth table implications /////
    // If all inputs are 1, Y must be 0.
    check_all_ones_implies_y0: assert property (
        @(posedge CLK) (A && B && C && D) |-> (Y == 1'b0)
    );
    // If A is 0, Y must be 1.
    check_a0_implies_y1: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y == 1'b1)
    );
    // If B is 0, Y must be 1.
    check_b0_implies_y1: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );
    // If C is 0, Y must be 1.
    check_c0_implies_y1: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );
    // If D is 0, Y must be 1.
    check_d0_implies_y1: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );
    // Y can be 0 only when all inputs are 1.
    check_y0_implies_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A && B && C && D)
    );

    ///// Edge-driven behavior when last input goes HIGH /////
    // When A rises and B,C,D are stably 1, Y must be 0.
    check_y_fall_when_A_rises_last: assert property (
        @(posedge CLK) $rose(A) && B && C && D && $past(B) && $past(C) && $past(D) |-> (Y == 1'b0)
    );
    // When B rises and A,C,D are stably 1, Y must be 0.
    check_y_fall_when_B_rises_last: assert property (
        @(posedge CLK) $rose(B) && A && C && D && $past(A) && $past(C) && $past(D) |-> (Y == 1'b0)
    );
    // When C rises and A,B,D are stably 1, Y must be 0.
    check_y_fall_when_C_rises_last: assert property (
        @(posedge CLK) $rose(C) && A && B && D && $past(A) && $past(B) && $past(D) |-> (Y == 1'b0)
    );
    // When D rises and A,B,C are stably 1, Y must be 0.
    check_y_fall_when_D_rises_last: assert property (
        @(posedge CLK) $rose(D) && A && B && C && $past(A) && $past(B) && $past(C) |-> (Y == 1'b0)
    );
endmodule

verilog_code:
module four_to_one (
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y
);

    assign Y = ~(A1_N & A2_N & B1 & ~B2) & ~(A1_N & ~A2_N & ~B1 & B2) & ~(~A1_N & A2_N & ~B1 & B2) & ~(~A1_N & ~A2_N & B1 & B2);

endmodule

sva_code:
module four_to_one_sva (
    input logic CLK,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y
);
    // Y implements the exact combinational equation from RTL.
    func_equivalence: assert property (
        @(posedge CLK)
        Y == ( !(A1_N && A2_N && B1 && !B2)
             && !(A1_N && !A2_N && !B1 && B2)
             && !(!A1_N && A2_N && !B1 && B2)
             && !(!A1_N && !A2_N && B1 && B2) )
    );

    // Minterm A1_N&A2_N&B1&~B2 forces Y LOW.
    minterm1_forces_low: assert property (
        @(posedge CLK) (A1_N && A2_N && B1 && !B2) |-> (Y == 1'b0)
    );

    // Minterm A1_N&~A2_N&~B1&B2 forces Y LOW.
    minterm2_forces_low: assert property (
        @(posedge CLK) (A1_N && !A2_N && !B1 && B2) |-> (Y == 1'b0)
    );

    // Minterm ~A1_N&A2_N&~B1&B2 forces Y LOW.
    minterm3_forces_low: assert property (
        @(posedge CLK) (!A1_N && A2_N && !B1 && B2) |-> (Y == 1'b0)
    );

    // Minterm ~A1_N&~A2_N&B1&B2 forces Y LOW.
    minterm4_forces_low: assert property (
        @(posedge CLK) (!A1_N && !A2_N && B1 && B2) |-> (Y == 1'b0)
    );

    // If none of the minterms hold, Y must be HIGH.
    none_minterm_forces_high: assert property (
        @(posedge CLK)
        !( (A1_N && A2_N && B1 && !B2)
         || (A1_N && !A2_N && !B1 && B2)
         || (!A1_N && A2_N && !B1 && B2)
         || (!A1_N && !A2_N && B1 && B2) ) |-> (Y == 1'b1)
    );

    // Y LOW implies at least one minterm is true.
    y_low_implies_some_minterm: assert property (
        @(posedge CLK)
        (Y == 1'b0) |-> ( (A1_N && A2_N && B1 && !B2)
                       || (A1_N && !A2_N && !B1 && B2)
                       || (!A1_N && A2_N && !B1 && B2)
                       || (!A1_N && !A2_N && B1 && B2) )
    );

    // With stable inputs, Y must remain stable (purely combinational).
    stable_output_when_inputs_stable: assert property (
        @(posedge CLK)
        ($stable(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> $stable(Y)
    );

    // When B1=0 and B2=0, Y must be HIGH.
    b00_forces_high: assert property (
        @(posedge CLK) (!B1 && !B2) |-> (Y == 1'b1)
    );

    // When B1=1 and B2=0 and not(A1_N&A2_N), Y must be HIGH.
    b10_nonbothA_high_forces_high: assert property (
        @(posedge CLK) (B1 && !B2 && !(A1_N && A2_N)) |-> (Y == 1'b1)
    );

    // When B1=0 and B2=1 and A1_N^A2_N, Y must be LOW.
    b01_xor_forces_low: assert property (
        @(posedge CLK) (!B1 && B2 && (A1_N ^ A2_N)) |-> (Y == 1'b0)
    );

    // When B1=0 and B2=1 and A1_N==A2_N, Y must be HIGH.
    b01_xnor_forces_high: assert property (
        @(posedge CLK) (!B1 && B2 && !(A1_N ^ A2_N)) |-> (Y == 1'b1)
    );

    // When B1=1 and B2=1 and any A is HIGH, Y must be HIGH.
    b11_anyA_high_forces_high: assert property (
        @(posedge CLK) (B1 && B2 && (A1_N || A2_N)) |-> (Y == 1'b1)
    );
endmodule

verilog_code:
module ripple_carry_adder (
	input [3:0] A,
	input [3:0] B,
	input C_in,
	input clk,
	output [3:0] S,
	output C_out
);

	reg [3:0] S_reg;
	reg C_out_reg;

	always @(posedge clk) begin
		// calculate the sum of A, B, and C_in
		S_reg = A + B + C_in;

		// calculate the carry-out bit
		C_out_reg = ((A[3] & B[3]) | (A[3] & C_in) | (B[3] & C_in));
	end

	// assign outputs
	assign S = S_reg;
	assign C_out = C_out_reg;

endmodule

sva_code:
module ripple_carry_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        C_in,
    input logic [3:0]  S,
    input logic        C_out
);
    // 3-input majority function
    function automatic logic maj3 (input logic x, input logic y, input logic z);
        maj3 = (x & y) | (x & z) | (y & z);
    endfunction

    ///// Functional correctness of registered outputs /////
    // S equals previous-cycle A+B+C_in (low 4 bits).
    check_sum_matches_prev_inputs: assert property (
        @(posedge clk) S == (($past(A) + $past(B) + $past(C_in)) & 4'hF)
    );

    // C_out equals previous-cycle majority of A[3], B[3], and C_in.
    check_cout_matches_prev_inputs: assert property (
        @(posedge clk) C_out == maj3($past(A[3]), $past(B[3]), $past(C_in))
    );

    ///// Bit-level sum correctness /////
    // Bit 0 is XOR of previous-cycle A[0], B[0], and C_in.
    check_s0_xor: assert property (
        @(posedge clk) S[0] == ($past(A[0]) ^ $past(B[0]) ^ $past(C_in))
    );

    // Bit 1 is XOR of A[1], B[1], and carry from bit 0 (all from previous cycle).
    check_s1_xor_with_c1: assert property (
        @(posedge clk) S[1] == ($past(A[1]) ^ $past(B[1]) ^ maj3($past(A[0]), $past(B[0]), $past(C_in)))
    );

    // Bit 2 is XOR of A[2], B[2], and carry from bit 1 (prev cycle).
    check_s2_xor_with_c2: assert property (
        @(posedge clk) S[2] == ($past(A[2]) ^ $past(B[2]) ^ maj3($past(A[1]), $past(B[1]), maj3($past(A[0]), $past(B[0]), $past(C_in))))
    );

    // Bit 3 is XOR of A[3], B[3], and carry from bit 2 (prev cycle).
    check_s3_xor_with_c3: assert property (
        @(posedge clk) S[3] == ($past(A[3]) ^ $past(B[3]) ^ maj3($past(A[2]), $past(B[2]), maj3($past(A[1]), $past(B[1]), maj3($past(A[0]), $past(B[0]), $past(C_in)))))
    );

    ///// Carry-out corner cases derived from implemented logic /////
    // If previous-cycle A[3]=0 and B[3]=0, C_out must be 0.
    check_cout_zero_when_msbs_zero: assert property (
        @(posedge clk) ($past(A[3]) == 1'b0 && $past(B[3]) == 1'b0) |-> (C_out == 1'b0)
    );

    // If previous-cycle A[3]=1 and B[3]=1, C_out must be 1.
    check_cout_one_when_msbs_one: assert property (
        @(posedge clk) ($past(A[3]) == 1'b1 && $past(B[3]) == 1'b1) |-> (C_out == 1'b1)
    );

    // If previous-cycle A[3] != B[3], C_out equals previous-cycle C_in.
    check_cout_equals_cin_when_msbs_differ: assert property (
        @(posedge clk) ($past(A[3]) ^ $past(B[3])) |-> (C_out == $past(C_in))
    );

    ///// Simple identity cases for the sum /////
    // When previous-cycle B==0 and C_in==0, S equals previous-cycle A.
    check_sum_identity_B_zero: assert property (
        @(posedge clk) ($past(B) == 4'b0000 && $past(C_in) == 1'b0) |-> (S == $past(A))
    );

    // When previous-cycle A==0 and C_in==0, S equals previous-cycle B.
    check_sum_identity_A_zero: assert property (
        @(posedge clk) ($past(A) == 4'b0000 && $past(C_in) == 1'b0) |-> (S == $past(B))
    );

    // When previous-cycle B==0 and C_in==1, S equals previous-cycle A+1 (mod 16).
    check_sum_increment_B_zero_Cin1: assert property (
        @(posedge clk) ($past(B) == 4'b0000 && $past(C_in) == 1'b1) |-> (S == (($past(A) + 4'd1) & 4'hF))
    );

endmodule

