module my_module (
    X   ,
    A1  ,
    A2  ,
    A3  ,
    B1  ,
    B2  ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  A3  ;
    input  B1  ;
    input  B2  ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire a2_and_a3;
    wire b2_or_vpwr;
    wire vpb_xor_vnb;

    assign a2_and_a3 = A2 & A3;
    assign b2_or_vpwr = B2 | VPWR;
    assign vpb_xor_vnb = VPB ^ VNB;

    assign X = (A1 & a2_and_a3) | (~A1 & B1 & b2_or_vpwr) | (~A1 & ~B1 & vpb_xor_vnb);

endmodule

sva_code:
module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);
    // X equals the implemented boolean expression.
    check_function_equation: assert property (
        @(posedge B2) X == ((A1 & (A2 & A3)) | ((~A1) & B1 & (B2 | VPWR)) | ((~A1) & (~B1) & (VPB ^ VNB)))
    );

    // When A1 is HIGH, X equals A2 & A3.
    check_A1_high_path: assert property (
        @(posedge B2) A1 |-> (X == (A2 & A3))
    );

    // When A1 is LOW and B1 is HIGH, X equals B2 | VPWR.
    check_A1_low_B1_high_path: assert property (
        @(posedge B2) (~A1 & B1) |-> (X == (B2 | VPWR))
    );

    // When A1 is LOW and B1 is LOW, X equals VPB ^ VNB.
    check_A1_low_B1_low_path: assert property (
        @(posedge B2) (~A1 & ~B1) |-> (X == (VPB ^ VNB))
    );

    // If A1=1 and A2=1 and A3=1, then X must be 1.
    check_A1_high_all_ones_implies_X1: assert property (
        @(posedge B2) (A1 & A2 & A3) |-> (X == 1'b1)
    );

    // If A1=1 and A2=0, then X must be 0.
    check_A1_high_A2_zero_implies_X0: assert property (
        @(posedge B2) (A1 & ~A2) |-> (X == 1'b0)
    );

    // If A1=1 and A3=0, then X must be 0.
    check_A1_high_A3_zero_implies_X0: assert property (
        @(posedge B2) (A1 & ~A3) |-> (X == 1'b0)
    );

    // If A1=0, B1=1, and B2=1, then X must be 1.
    check_else_path_B2_one_implies_X1: assert property (
        @(posedge B2) (~A1 & B1 & B2) |-> (X == 1'b1)
    );

    // If A1=0, B1=1, and VPWR=1, then X must be 1.
    check_else_path_VPWR_one_implies_X1: assert property (
        @(posedge B2) (~A1 & B1 & VPWR) |-> (X == 1'b1)
    );

    // If A1=0, B1=1, B2=0, and VPWR=0, then X must be 0.
    check_else_path_zero_inputs_implies_X0: assert property (
        @(posedge B2) (~A1 & B1 & ~B2 & ~VPWR) |-> (X == 1'b0)
    );

    // If A1=0, B1=0, and VPB==VNB, then X must be 0.
    check_xor_path_equal_inputs_implies_X0: assert property (
        @(posedge B2) (~A1 & ~B1 & (VPB ~^ VNB)) |-> (X == 1'b0)
    );

    // If A1=0, B1=0, and VPB!=VNB, then X must be 1.
    check_xor_path_unequal_inputs_implies_X1: assert property (
        @(posedge B2) (~A1 & ~B1 & (VPB ^ VNB)) |-> (X == 1'b1)
    );
endmodule

verilog_code:
module t_order_a (
   m_from_clk_lev1_r, n_from_clk_lev2, o_from_com_levs11, o_from_comandclk_levs12,
   clk, a_to_clk_levm3, b_to_clk_levm1, c_com_levs10, d_to_clk_levm2, one
   );

   input clk;
   input [7:0] a_to_clk_levm3;
   input [7:0] b_to_clk_levm1;
   input [7:0] c_com_levs10;
   input [7:0] d_to_clk_levm2;
   input [7:0] one;
   output [7:0] m_from_clk_lev1_r;
   output [7:0] n_from_clk_lev2;
   output [7:0] o_from_com_levs11;
   output [7:0] o_from_comandclk_levs12;


   reg [7:0]		m_from_clk_lev1_r;
   wire [7:0] a_to_clk_levm1;
   wire [7:0] a_to_clk_levm2;
   wire [7:0] c_com_levs11;
   reg [7:0]  o_from_comandclk_levs12;
   wire [7:0]  n_from_clk_lev2;
   wire [7:0]  n_from_clk_lev3;

   assign     a_to_clk_levm1 = a_to_clk_levm2 + d_to_clk_levm2;
   assign     a_to_clk_levm2 = a_to_clk_levm3 + 0;

   always @ (posedge clk) begin
      m_from_clk_lev1_r <= a_to_clk_levm1 + b_to_clk_levm1;
   end

   assign c_com_levs11 = c_com_levs10 + one;
   always @ (c_com_levs11 or n_from_clk_lev3) o_from_comandclk_levs12 = c_com_levs11 + n_from_clk_lev3;
   assign n_from_clk_lev2 = m_from_clk_lev1_r;
   assign n_from_clk_lev3 = n_from_clk_lev2;
   wire [7:0] o_from_com_levs11 = c_com_levs10 + 1;

endmodule

sva_code:
module t_order_a_sva (
    input logic clk,
    input logic [7:0] a_to_clk_levm3,
    input logic [7:0] b_to_clk_levm1,
    input logic [7:0] c_com_levs10,
    input logic [7:0] d_to_clk_levm2,
    input logic [7:0] one,
    input logic [7:0] m_from_clk_lev1_r,
    input logic [7:0] n_from_clk_lev2,
    input logic [7:0] o_from_com_levs11,
    input logic [7:0] o_from_comandclk_levs12
);
    // m_from_clk_lev1_r captures (a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1 on the previous cycle.
    check_m_update_from_inputs: assert property (
        @(posedge clk) m_from_clk_lev1_r == $past((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)
    );

    // n_from_clk_lev2 is a combinational mirror of m_from_clk_lev1_r.
    check_n_mirrors_m: assert property (
        @(posedge clk) n_from_clk_lev2 == m_from_clk_lev1_r
    );

    // o_from_com_levs11 is c_com_levs10 + 1 (8-bit wrap).
    check_o_com_plus1: assert property (
        @(posedge clk) o_from_com_levs11 == (c_com_levs10 + 8'd1)
    );

    // o_from_comandclk_levs12 equals (c_com_levs10 + one) + n_from_clk_lev2 (combinational).
    check_o_andclk_sum_with_n: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + n_from_clk_lev2)
    );

    // By transitivity (n == m), o_from_comandclk_levs12 also equals (c_com_levs10 + one) + m_from_clk_lev1_r.
    check_o_andclk_sum_with_m: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + m_from_clk_lev1_r)
    );

    // n_from_clk_lev2 also reflects the registered sum from the previous cycle.
    check_n_update_from_inputs: assert property (
        @(posedge clk) n_from_clk_lev2 == $past((a_to_clk_levm3 + d_to_clk_levm2) + b_to_clk_levm1)
    );

    // If the adder inputs are stable over a cycle, m_from_clk_lev1_r holds its value.
    check_m_holds_when_inputs_stable: assert property (
        @(posedge clk) ($stable(a_to_clk_levm3) && $stable(b_to_clk_levm1) && $stable(d_to_clk_levm2)) |-> (m_from_clk_lev1_r == $past(m_from_clk_lev1_r))
    );

    // If operands to o_from_comandclk_levs12 are stable over a cycle, it holds its value.
    check_o_andclk_holds_when_operands_stable: assert property (
        @(posedge clk) ($stable(c_com_levs10) && $stable(one) && $stable(n_from_clk_lev2)) |-> (o_from_comandclk_levs12 == $past(o_from_comandclk_levs12))
    );

    // Any change on m_from_clk_lev1_r must be reflected on n_from_clk_lev2 at the same clock.
    check_n_changes_with_m: assert property (
        @(posedge clk) $changed(m_from_clk_lev1_r) |-> $changed(n_from_clk_lev2)
    );

    // If m_from_clk_lev1_r does not change across a cycle, n_from_clk_lev2 does not change either.
    check_n_not_change_when_m_not_change: assert property (
        @(posedge clk) !$changed(m_from_clk_lev1_r) |-> !$changed(n_from_clk_lev2)
    );
endmodule

