module bitwise_op (x, y, z, o);

	input [31:0] x, y, z;
	output [31:0] o;

	wire [31:0] temp;

	assign temp = y ^ z;
	assign o = z ^ (x & temp);

endmodule

sva_code:
module bitwise_op_sva (
    // Environment clock for sampling; DUT has no clock/reset (pure combinational)
    input logic clk,
    // DUT ports
    input logic [31:0] x,
    input logic [31:0] y,
    input logic [31:0] z,
    input logic [31:0] o
);
    // o matches the RTL expression exactly.
    check_output_matches_rtl_expr: assert property (
        @(posedge clk) o == (z ^ (x & (y ^ z)))
    );

    // o is equivalent to a bitwise mux: x ? y : z.
    check_mux_equivalence: assert property (
        @(posedge clk) o == ((x & y) | (~x & z))
    );

    // The XOR of o and z equals x masked with (y^z).
    check_xor_mask_relation: assert property (
        @(posedge clk) (o ^ z) == (x & (y ^ z))
    );

    // When x is all zeros, o must pass through z.
    check_pass_through_when_x_zero: assert property (
        @(posedge clk) (x == 32'b0) |-> (o == z)
    );

    // When x is all ones, o must equal y.
    check_select_y_when_x_all_ones: assert property (
        @(posedge clk) (x == 32'hFFFF_FFFF) |-> (o == y)
    );

    // When y equals z, o must equal z.
    check_when_y_equals_z: assert property (
        @(posedge clk) (y == z) |-> (o == z)
    );

    // When z is all zeros, o reduces to x & y.
    check_when_z_zero: assert property (
        @(posedge clk) (z == 32'b0) |-> (o == (x & y))
    );

    // When y is all zeros, o reduces to (~x) & z.
    check_when_y_zero: assert property (
        @(posedge clk) (y == 32'b0) |-> (o == ((~x) & z))
    );

    // Bits selected by x must match y (masked equality).
    check_y_path_mask: assert property (
        @(posedge clk) (o & x) == (y & x)
    );

    // Bits not selected by x must match z (masked equality).
    check_z_path_mask: assert property (
        @(posedge clk) (o & ~x) == (z & ~x)
    );
endmodule

module shift_register_parallel_load_sva (
    input logic clk,
    input logic rst,     // active-high reset
    input logic load,
    input logic [7:0] in,
    input logic [7:0] out
);
    // Reset forces output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |-> (out == 8'b0)
    );

    // Load writes input to output on the same cycle when not in reset.
    check_load_parallel_load: assert property (
        @(posedge clk) disable iff (rst) load |-> (out == in)
    );

    // When shifting (no load), LSB becomes 0.
    check_shift_lsb_zero: assert property (
        @(posedge clk) disable iff (rst) !load |-> (out[0] == 1'b0)
    );

    // With no load, once out is zero it stays zero.
    check_no_load_zero_stays_zero: assert property (
        @(posedge clk) disable iff (rst) (!load && $past(1'b1) && ($past(out) == 8'b0)) |-> (out == 8'b0)
    );

    // After two consecutive no-load cycles, lower 2 bits are zero.
    check_two_no_loads_zero_low2: assert property (
        @(posedge clk) disable iff (rst) (!load)[*2] |-> (out[1:0] == 2'b00)
    );

    // After four consecutive no-load cycles, lower 4 bits are zero.
    check_four_no_loads_zero_low4: assert property (
        @(posedge clk) disable iff (rst) (!load)[*4] |-> (out[3:0] == 4'b0000)
    );

    // After eight consecutive no-load cycles, output is zero.
    check_eight_no_loads_clears_out: assert property (
        @(posedge clk) disable iff (rst) (!load)[*8] |-> (out == 8'b00000000)
    );

    // Loading zero drives output to zero.
    check_load_zero_clears_out: assert property (
        @(posedge clk) disable iff (rst) (load && (in == 8'b0)) |-> (out == 8'b0)
    );

    // On load, LSB of output equals LSB of input.
    check_load_lsb_transfer: assert property (
        @(posedge clk) disable iff (rst) load |-> (out[0] == in[0])
    );

    // On sampled rising edge of reset, output is zero.
    check_reset_rise_clears_out: assert property (
        @(posedge clk) $rose(rst) |-> (out == 8'b0)
    );
endmodule

