  check_symmetry_ae_ea_equal: assert property (
    @(posedge clk) out[20] == out[4]
  );
  // b^c equals c^b.
  check_symmetry_bc_cb_equal: assert property (
    @(posedge clk) out[17] == out[13]
  );
  // b^d equals d^b.
  check_symmetry_bd_db_equal: assert property (
