module nios_system_sram_addr (
                               // inputs:
                                address,
                                chipselect,
                                clk,
                                reset_n,
                                write_n,
                                writedata,

                               // outputs:
                                out_port,
                                readdata
                             )
;

  output  [ 10: 0] out_port;
  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            chipselect;
  input            clk;
  input            reset_n;
  input            write_n;
  input   [ 31: 0] writedata;

  wire             clk_en;
  reg     [ 10: 0] data_out;
  wire    [ 10: 0] out_port;
  wire    [ 10: 0] read_mux_out;
  wire    [ 31: 0] readdata;
  assign clk_en = clk & ~reset_n;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {11 {(address == 0)}} & data_out;
  always @(posedge clk or negedge reset_n)
    begin
      if (~reset_n)
          data_out <= 0;
      else if (chipselect && ~write_n && (address == 0))
          data_out <= writedata[10 : 0];
    end


  assign readdata = {32'b0, read_mux_out};
  assign out_port = data_out;

endmodule

sva_code:
module nios_system_sram_addr_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [10:0] out_port,
    input logic [31:0] readdata
);
    // During reset, out_port must be 0.
    reset_out_port_zero: assert property (
        @(posedge clk) !reset_n |-> (out_port == 11'b0)
    );

    // During reset, readdata must be 0.
    reset_readdata_zero: assert property (
        @(posedge clk) !reset_n |-> (readdata[31:11] == 21'b0 && readdata[10:0] == 11'b0)
    );

    // Upper 21 bits of readdata are always zero.
    readdata_upper_zero_always: assert property (
        @(posedge clk) disable iff (!reset_n) (readdata[31:11] == 21'b0)
    );

    // When address == 0, readdata[10:0] equals out_port.
    readdata_low_matches_out_port_on_addr0: assert property (
        @(posedge clk) disable iff (!reset_n) (address == 2'b00) |-> (readdata[10:0] == out_port)
    );

    // When address != 0, readdata[10:0] is zero.
    readdata_low_zero_on_addr_non0: assert property (
        @(posedge clk) disable iff (!reset_n) (address != 2'b00) |-> (readdata[10:0] == 11'b0)
    );

    // A write to address 0 updates out_port on the next cycle to writedata[10:0].
    write_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n) (chipselect && ~write_n && (address == 2'b00)) |=> (out_port == $past(writedata[10:0]))
    );

    // A write to a nonzero address does not change out_port.
    write_other_addr_does_not_change_out_port: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (chipselect && ~write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

    // If no write to address 0 occurs, out_port holds its value.
    out_port_holds_without_write_hit0: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && !(chipselect && ~write_n && (address == 2'b00)) |=> (out_port == $past(out_port))
    );

    // Any change to out_port must be caused by a prior write to address 0.
    out_port_change_requires_prev_write_hit0: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (out_port != $past(out_port)) |-> $past(chipselect && ~write_n && (address == 2'b00))
    );

    // After a write to address 0, if address is 0 next cycle, readdata returns the written value.
    read_after_write_returns_written_value: assert property (
        @(posedge clk) disable iff (!reset_n) (chipselect && ~write_n && (address == 2'b00)) |=> ((address == 2'b00) ? (readdata[10:0] == $past(writedata[10:0])) : 1'b1)
    );
endmodule

verilog_code:
module bitwise_logic (
  input A,
  input B,
  input [1:0] SEL,
  output C
);

  // Define logical operators based on SEL input signal
  wire AND = A & B;
  wire OR = A | B;
  wire XOR = A ^ B;
  wire NOT = ~A;

  // Compute output signal C based on input signals A and B and SEL control signal
  assign C = (SEL == 0) ? AND :
            (SEL == 1) ? OR :
            (SEL == 2) ? XOR :
            (SEL == 3) ? NOT :
            1'bx; // default value for invalid SEL input

endmodule

sva_code:
module bitwise_logic_sva (
    input logic A,
    input logic B,
    input logic [1:0] SEL,
    input logic C
);
    // When SEL==00, C equals A & B.
    check_sel00_and: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b00) |-> (C == (A & B))
    );

    // When SEL==01, C equals A | B.
    check_sel01_or: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b01) |-> (C == (A | B))
    );

    // When SEL==10, C equals A ^ B.
    check_sel10_xor: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b10) |-> (C == (A ^ B))
    );

    // When SEL==11, C equals ~A.
    check_sel11_not: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        (SEL == 2'b11) |-> (C == (~A))
    );

    // AND: if A is 0 then C is 0.
    check_and_zero_when_A0: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b00) && (A == 1'b0)) |-> (C == 1'b0)
    );

    // AND: if B is 0 then C is 0.
    check_and_zero_when_B0: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b00) && (B == 1'b0)) |-> (C == 1'b0)
    );

    // OR: if A is 1 then C is 1.
    check_or_one_when_A1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b01) && (A == 1'b1)) |-> (C == 1'b1)
    );

    // OR: if B is 1 then C is 1.
    check_or_one_when_B1: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b01) && (B == 1'b1)) |-> (C == 1'b1)
    );

    // XOR: if A equals B then C is 0.
    check_xor_zero_when_equal: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b10) && (A == B)) |-> (C == 1'b0)
    );

    // XOR: if A differs from B then C is 1.
    check_xor_one_when_diff: assert property (
        @(posedge A or negedge A or posedge B or negedge B or posedge SEL[0] or negedge SEL[0] or posedge SEL[1] or negedge SEL[1])
        ((SEL == 2'b10) && (A != B)) |-> (C == 1'b1)
    );
endmodule

module counter_sva #(
    parameter WIDTH = 8,
    parameter MODULUS = 256
)(
    input  logic                 ce,
    input  logic                 clr,
    input  logic                 clk,
    input  logic [WIDTH-1:0]     out
);
    // Local constants sized to WIDTH
    localparam logic [WIDTH-1:0] MODM1 = MODULUS - 1;
    localparam logic [WIDTH-1:0] ZERO  = {WIDTH{1'b0}};

    ///// Synchronous clear behavior /////
    // On clr, out is 0 on the next cycle (clr overrides ce).
    check_sync_clear_sets_zero: assert property (
        @(posedge clk) clr |=> (out == ZERO)
    );

    ///// Normal operation (disable during clr) /////
    // With ce low and no clr, out holds its value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) (!ce) |=> (out == $past(out))
    );

    // With ce high and not at MOD-1, out increments by 1.
    check_increment_when_enabled_nonmax: assert property (
        @(posedge clk) disable iff (clr) (ce && (out != MODM1)) |=> (out == $past(out) + 1)
    );

    // With ce high at MOD-1, out wraps to 0.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (clr) (ce && (out == MODM1)) |=> (out == ZERO)
    );

    // Any change in out must be due to prior ce or clr.
    check_change_requires_enable_or_clear: assert property (
        @(posedge clk) (out != $past(out)) |-> ($past(ce) || $past(clr))
    );

    // Transition to 0 from nonzero without clr implies wrap due to ce at MOD-1.
    check_zero_transition_cause: assert property (
        @(posedge clk)
            (!$past(clr) && ($past(out) != ZERO) && (out == ZERO)) |-> ($past(ce) && ($past(out) == MODM1))
    );

    // With ce high and no clr, next out is either prev+1 or wraps to 0.
    check_enable_defines_next_state: assert property (
        @(posedge clk) disable iff (clr)
            ce |=> ((($past(out) != MODM1) && (out == $past(out) + 1)) ||
                    (($past(out) == MODM1) && (out == ZERO)))
    );
endmodule

module csa_generate_adder_32bit_sva (
    input logic CLK,
    input logic [31:0] A,
    input logic [31:0] B,
    input logic [31:0] S,
    input logic C32
);
    // Functional equivalence: {C32,S} = {0,(A+B)} + {0,(A^B)} + {0..,A[31]&B[31]}.
    check_sum_definition: assert property (
        @(posedge CLK) {C32, S} == ({1'b0, (A + B)} + {1'b0, (A ^ B)} + {32'b0, (A[31] & B[31])})
    );

    // LSB of S equals MSB generate (A[31] & B[31]).
    check_s0_equals_msb_generate: assert property (
        @(posedge CLK) S[0] == (A[31] & B[31])
    );

    // Zero inputs yield zero outputs.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) ((A == 32'd0) && (B == 32'd0)) |-> ((S == 32'd0) && (C32 == 1'b0))
    );

    // If B is zero, output equals 2*A (33-bit).
    check_b_zero_doubles_a: assert property (
        @(posedge CLK) (B == 32'd0) |-> ({C32, S} == ({1'b0, A} + {1'b0, A}))
    );

    // If A is zero, output equals 2*B (33-bit).
    check_a_zero_doubles_b: assert property (
        @(posedge CLK) (A == 32'd0) |-> ({C32, S} == ({1'b0, B} + {1'b0, B}))
    );

    // If inputs are equal, {C32,S} = {0,(A+B)} + {0..,A[31]}.
    check_equal_inputs_rule: assert property (
        @(posedge CLK) (A == B) |-> ({C32, S} == ({1'b0, (A + B)} + {32'b0, A[31]}))
    );

    // Complementary inputs (B == ~A) yield constant {1,0xFFFFFFFE}.
    check_complement_inputs_result: assert property (
        @(posedge CLK) (B == ~A) |-> ({C32, S} == 33'h1_FFFFFFFE)
    );

    // With B zero, carry-out equals A's MSB.
    check_b_zero_carry_equals_a31: assert property (
        @(posedge CLK) (B == 32'd0) |-> (C32 == A[31])
    );

    // With A zero, carry-out equals B's MSB.
    check_a_zero_carry_equals_b31: assert property (
        @(posedge CLK) (A == 32'd0) |-> (C32 == B[31])
    );
endmodule

