sva_code:
module max_8bit_sva (
    input logic clk,           // sampling clock for assertions
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] max_val
);
    // Analysis: no clock/reset in DUT; pure combinational; max_val = (A > B) ? A : B.

    // Functional equivalence to ternary form.
    check_functional_spec: assert property (
        @(posedge clk) max_val == ((A > B) ? A : B)
    );

    // If A is strictly greater than B, output must be A.
    check_select_A_when_gt: assert property (
        @(posedge clk) (A > B) |-> (max_val == A)
    );

    // If A is less than or equal to B, output must be B.
    check_select_B_when_le: assert property (
        @(posedge clk) (A <= B) |-> (max_val == B)
    );

    // On ties, output equals both inputs (they are equal).
    check_tie_outputs_equal: assert property (
        @(posedge clk) (A == B) |-> ((max_val == A) && (max_val == B))
    );

    // Output must equal one of the inputs.
    check_output_is_input_value: assert property (
        @(posedge clk) (max_val == A) || (max_val == B)
    );

    // Output is not less than A.
    check_output_ge_A: assert property (
        @(posedge clk) max_val >= A
    );

    // Output is not less than B.
    check_output_ge_B: assert property (
        @(posedge clk) max_val >= B
    );

    // If output equals A, then A is at least B.
    check_output_eq_A_implies_A_ge_B: assert property (
        @(posedge clk) (max_val == A) |-> (A >= B)
    );

    // If output equals B, then B is at least A.
    check_output_eq_B_implies_B_ge_A: assert property (
        @(posedge clk) (max_val == B) |-> (B >= A)
    );

    // If A is strictly less than B, output cannot be A.
    check_no_A_when_A_lt_B: assert property (
        @(posedge clk) (A < B) |-> (max_val != A)
    );
endmodule

module calc_sva (
    input logic CLK,           // sampling clock for assertions
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic       op,
    input logic [3:0] result
);
    // Result matches selected operation (4-bit modular arithmetic).
    check_core_functionality: assert property (
        @(posedge CLK) result == (op ? (num1 - num2) : (num1 + num2))
    );

    // If inputs are stable across a cycle, result remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(op) && $stable(num1) && $stable(num2) |-> $stable(result)
    );

    // In subtraction mode, equal operands yield zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge CLK) op && (num1 == num2) |-> (result == 4'd0)
    );

    // In addition mode, adding zero on RHS yields num1.
    check_add_zero_rhs_identity: assert property (
        @(posedge CLK) (!op) && (num2 == 4'd0) |-> (result == num1)
    );

    // In addition mode, adding zero on LHS yields num2.
    check_add_zero_lhs_identity: assert property (
        @(posedge CLK) (!op) && (num1 == 4'd0) |-> (result == num2)
    );

    // In subtraction mode, subtracting zero yields num1.
    check_sub_zero_rhs_identity: assert property (
        @(posedge CLK) op && (num2 == 4'd0) |-> (result == num1)
    );

    // In subtraction mode, (result + num2) recovers num1 (mod 16).
    check_sub_invertibility_mod16: assert property (
        @(posedge CLK) op |-> ((result + num2) == num1)
    );

    // In addition mode, (result - num2) recovers num1 (mod 16).
    check_add_invertibility_mod16: assert property (
        @(posedge CLK) (!op) |-> ((result - num2) == num1)
    );
endmodule

module parity_checker_sva (
    input logic CLK,          // External sampling clock (DUT has no clock/reset)
    input logic [3:0] data,
    input logic parity
);
    // Parity equals XOR reduction of data (4-state exact equality).
    check_parity_matches_reduction: assert property (
        @(posedge CLK) disable iff (1'b0) parity === (^data)
    );

    // Parity not X/Z when all data bits are known.
    check_parity_known_when_data_known: assert property (
        @(posedge CLK) disable iff (1'b0) (!$isunknown(data)) |-> (!$isunknown(parity))
    );

    // If inputs do not change, parity does not change (no storage; pure function).
    check_parity_stable_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (1'b0) (data === $past(data)) |-> (parity === $past(parity))
    );

    // A single-bit flip in data causes parity to toggle.
    check_parity_toggles_on_single_bit_flip: assert property (
        @(posedge CLK) disable iff (1'b0)
            (!$isunknown(data) && !$isunknown($past(data)) && ($countones(data ^ $past(data)) == 1))
            |-> (parity !== $past(parity))
    );

    // Two-bit flips in data leave parity unchanged (even parity preservation).
    check_parity_stable_on_two_bit_flip: assert property (
        @(posedge CLK) disable iff (1'b0)
            (!$isunknown(data) && !$isunknown($past(data)) && ($countones(data ^ $past(data)) == 2))
            |-> (parity === $past(parity))
    );
endmodule

