module logic_function (
    input clk,
    input rst,
    input [3:0] din,
    output dout
);

// XOR the bits of the input together to count the number of 1's
wire [1:0] xor1 = din[0] ^ din[1];
wire [1:0] xor2 = din[2] ^ din[3];
wire [1:0] xor3 = xor1 ^ xor2;
wire [0:0] xor4 = xor3[0] ^ xor3[1];

// Invert the output to get the desired output
assign dout = ~xor4;

endmodule

sva_code:
module logic_function_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] din,
    input logic dout
);
    // Clock: clk (posedge). Reset: rst active-high.
    // Logic: combinational; dout = ~(^din).

    // dout equals the inversion of the XOR-reduction of din.
    check_inverted_parity_function: assert property (
        @(posedge clk) disable iff (rst) (dout === ~(^din))
    );

    // When din has even parity, dout must be 1.
    check_even_parity_high: assert property (
        @(posedge clk) disable iff (rst) ((^din) === 1'b0) |-> (dout === 1'b1)
    );

    // When din has odd parity, dout must be 0.
    check_odd_parity_low: assert property (
        @(posedge clk) disable iff (rst) ((^din) === 1'b1) |-> (dout === 1'b0)
    );

    // Specific case: all zeros input yields dout=1 (even parity).
    check_all_zeros_high: assert property (
        @(posedge clk) disable iff (rst) (din == 4'b0000) |-> (dout === 1'b1)
    );

    // Specific case: all ones input yields dout=1 (even parity).
    check_all_ones_high: assert property (
        @(posedge clk) disable iff (rst) (din == 4'b1111) |-> (dout === 1'b1)
    );
endmodule

verilog_code:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c1, c2, c3;
    one_bit_adder fa1(.a(A[0]), .b(B[0]), .cin(Cin), .sum(Sum[0]), .cout(c1));
    one_bit_adder fa2(.a(A[1]), .b(B[1]), .cin(c1), .sum(Sum[1]), .cout(c2));
    one_bit_adder fa3(.a(A[2]), .b(B[2]), .cin(c2), .sum(Sum[2]), .cout(c3));
    one_bit_adder fa4(.a(A[3]), .b(B[3]), .cin(c3), .sum(Sum[3]), .cout(Cout));

endmodule
module one_bit_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (b & cin) | (a & cin);

endmodule

sva_code:
module four_bit_adder_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);
    // No clock/reset in DUT; combinational logic; use $global_clock for sampling.

    // Local let expressions for ripple carries derived from DUT equations
    let c1 = (A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin);
    let c2 = (A[1] & B[1]) | (B[1] & c1)  | (A[1] & c1);
    let c3 = (A[2] & B[2]) | (B[2] & c2)  | (A[2] & c2);

    ///// Functional correctness /////
    // 5-bit sum equals A + B + Cin.
    check_full_sum: assert property (
        @(posedge $global_clock) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );
    // Sum low 4 bits match truncated addition.
    check_sum_low4: assert property (
        @(posedge $global_clock) Sum == (({1'b0, A} + {1'b0, B} + Cin)[3:0])
    );
    // Cout equals MSB of 5-bit addition result.
    check_cout_msb: assert property (
        @(posedge $global_clock) Cout == (({1'b0, A} + {1'b0, B} + Cin)[4])
    );

    ///// Bit-slice correctness /////
    // LSB sum implements XOR of A[0], B[0], Cin.
    check_sum0_xor: assert property (
        @(posedge $global_clock) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );
    // Bit1 sum uses carry c1 from bit0.
    check_sum1_xor: assert property (
        @(posedge $global_clock) Sum[1] == (A[1] ^ B[1] ^ c1)
    );
    // Bit2 sum uses carry c2 from bit1.
    check_sum2_xor: assert property (
        @(posedge $global_clock) Sum[2] == (A[2] ^ B[2] ^ c2)
    );
    // Bit3 sum uses carry c3 from bit2.
    check_sum3_xor: assert property (
        @(posedge $global_clock) Sum[3] == (A[3] ^ B[3] ^ c3)
    );
    // Cout is majority of A[3], B[3], and c3.
    check_cout_majority: assert property (
        @(posedge $global_clock) Cout == ((A[3] & B[3]) | (B[3] & c3) | (A[3] & c3))
    );

    ///// Basic identities /////
    // Adding zero B and zero Cin returns A with no carry.
    check_add_zero_B: assert property (
        @(posedge $global_clock) ((B == 4'b0000) && (Cin == 1'b0)) |=> ((Sum == A) && (Cout == 1'b0))
    );
    // Adding zero A and zero Cin returns B with no carry.
    check_add_zero_A: assert property (
        @(posedge $global_clock) ((A == 4'b0000) && (Cin == 1'b0)) |=> ((Sum == B) && (Cout == 1'b0))
    );
endmodule

verilog_code:
module alu(
		input		[3:0]	ctl,
		input		[31:0]	a, b,
		output reg	[31:0]	out,
		output				zero,
		output				oflow);

	wire [31:0] sub_ab;
	wire [31:0] add_ab;
	wire 		oflow_add;
	wire 		oflow_sub;
	wire 		slt;

	assign zero = (0 == out);

	assign sub_ab = a - b;
	assign add_ab = a + b;

	assign oflow_add = (a[31] == b[31] && add_ab[31] != a[31]) ? 1 : 0;
	assign oflow_sub = (a[31] == b[31] && sub_ab[31] != a[31]) ? 1 : 0;

	assign oflow = (ctl == 4'b0010) ? oflow_add : oflow_sub;

	assign slt = oflow_sub ? ~(a[31]) : a[31];

	always @(*) begin
		case (ctl)
			4'd2:  out <= add_ab;				
			4'd0:  out <= a & b;				
			4'd12: out <= ~(a | b);				
			4'd1:  out <= a | b;				
			4'd7:  out <= {{31{1'b0}}, slt};	
			4'd6:  out <= sub_ab;				
			4'd13: out <= a ^ b;				
			default: out <= 0;
		endcase
	end

endmodule

sva_code:
module alu_sva (
    input  logic        CLK,
    input  logic        RESETn,   // External assertion clock/reset (DUT is combinational; no reset in RTL)
    input  logic [3:0]  ctl,
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic [31:0] out,
    input  logic        zero,
    input  logic        oflow
);
    // Helper: signed-add overflow per RTL
    function automatic logic ovf_add (input logic [31:0] aa, input logic [31:0] bb);
        ovf_add = (aa[31] == bb[31]) && (((aa + bb)[31]) != aa[31]);
    endfunction
    // Helper: signed-sub overflow per RTL
    function automatic logic ovf_sub (input logic [31:0] aa, input logic [31:0] bb);
        ovf_sub = (aa[31] == bb[31]) && (((aa - bb)[31]) != aa[31]);
    endfunction
    // Helper: SLT bit per RTL
    function automatic logic slt_bit (input logic [31:0] aa, input logic [31:0] bb);
        slt_bit = ovf_sub(aa, bb) ? ~aa[31] : aa[31];
    endfunction

    ///// Output flag relations /////
    // zero is 1 iff out == 0.
    check_zero_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
        zero == (out == 32'h0000_0000)
    );

    // oflow equals add-overflow when ctl==2.
    check_oflow_add_sel: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd2) |-> (oflow == ovf_add(a, b))
    );

    // oflow equals sub-overflow when ctl!=2.
    check_oflow_else_sub: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl != 4'd2) |-> (oflow == ovf_sub(a, b))
    );

    ///// ALU operation results /////
    // AND: ctl==0 => out == a & b.
    check_out_and: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd0) |-> (out == (a & b))
    );

    // OR: ctl==1 => out == a | b.
    check_out_or: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd1) |-> (out == (a | b))
    );

    // ADD: ctl==2 => out == a + b.
    check_out_add: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd2) |-> (out == (a + b))
    );

    // SUB: ctl==6 => out == a - b.
    check_out_sub: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd6) |-> (out == (a - b))
    );

    // SLT: ctl==7 => out == {31'b0, slt_bit}.
    check_out_slt: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd7) |-> (out == {31'h0, slt_bit(a, b)})
    );

    // NOR: ctl==12 => out == ~(a | b).
    check_out_nor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd12) |-> (out == ~(a | b))
    );

    // XOR: ctl==13 => out == a ^ b.
    check_out_xor: assert property (
        @(posedge CLK) disable iff (!RESETn)
        (ctl == 4'd13) |-> (out == (a ^ b))
    );

    // Default case: for unsupported ctl, out == 0.
    check_out_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
        ((ctl != 4'd2) && (ctl != 4'd0) && (ctl != 4'd12) &&
         (ctl != 4'd1) && (ctl != 4'd7) && (ctl != 4'd6) &&
         (ctl != 4'd13)) |-> (out == 32'h0000_0000)
    );

endmodule

module my_module_sva (
    input logic clk,
    input logic rst,
    input logic [31:0] in_data,
    input logic [31:0] out_data
);
    // Next-state equation: out_data equals (prev rst ? 0 : prev in_data).
    check_next_state_equation: assert property (
        @(posedge clk) $past(1'b1) |-> (out_data == ($past(rst) ? 32'd0 : $past(in_data)))
    );

    // When rst is HIGH, out_data becomes 0 on the following cycle.
    check_reset_clears_on_next: assert property (
        @(posedge clk) rst |=> (out_data == 32'd0)
    );

    // While rst remains HIGH across cycles, out_data stays 0.
    check_hold_zero_during_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (out_data == 32'd0)
    );

    // On rst deassertion, next out_data equals current in_data.
    check_deassert_passthrough: assert property (
        @(posedge clk) $fell(rst) |=> (out_data == $past(in_data))
    );

    // In back-to-back non-reset cycles, out_data equals previous in_data.
    check_passthrough_no_reset: assert property (
        @(posedge clk) disable iff (rst) $past(!rst) |-> (out_data == $past(in_data))
    );

    // If in_data changes in a non-reset cycle, out_data changes on the next cycle.
    check_input_change_propagates: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst) && $changed(in_data)) |=> $changed(out_data)
    );

    // If in_data is stable in a non-reset cycle, out_data does not change next cycle.
    check_output_stable_if_input_stable: assert property (
        @(posedge clk) disable iff (rst) ($past(!rst) && !$changed(in_data)) |=> !$changed(out_data)
    );
endmodule

