module ripple_carry_adder(a, b, cin, sum, cout);
    parameter WIDTH = 4;
    input [WIDTH-1:0] a;
    input [WIDTH-1:0] b;
    input cin;
    output [WIDTH-1:0] sum;
    output cout;

    wire [WIDTH:0] carry;
    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < WIDTH; i = i + 1) begin : adder
            full_adder full_adder_inst (
                .a(a[i]),
                .b(b[i]),
                .cin(carry[i]),
                .sum(sum[i]),
                .cout(carry[i+1])
            );
        end
    endgenerate

    assign cout = carry[WIDTH];
endmodule

