module sky130_fd_sc_lp__a311oi_sva (
    input logic CLK,   // sampling clock for SVA (DUT has no clock/reset)
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1,
    input logic C1
);
    // Y must equal ~((A1 & A2 & A3) | B1 | C1).
    check_function_equivalence: assert property (
        @(posedge CLK) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

    // If B1 is HIGH, Y must be LOW.
    check_b1_high_forces_y_low: assert property (
        @(posedge CLK) B1 |-> (Y == 1'b0)
    );

    // If C1 is HIGH, Y must be LOW.
    check_c1_high_forces_y_low: assert property (
        @(posedge CLK) C1 |-> (Y == 1'b0)
    );

    // If A1&A2&A3 is HIGH, Y must be LOW.
    check_and3_high_forces_y_low: assert property (
        @(posedge CLK) (A1 & A2 & A3) |-> (Y == 1'b0)
    );

    // If either B1 or C1 is HIGH, Y must be LOW.
    check_b1_or_c1_high_forces_y_low: assert property (
        @(posedge CLK) (B1 || C1) |-> (Y == 1'b0)
    );

    // With B1=0 and C1=0, Y reduces to ~(A1 & A2 & A3).
    check_reduction_when_b1c1_low: assert property (
        @(posedge CLK) (!B1 && !C1) |-> (Y == ~(A1 & A2 & A3))
    );

    // If B1=0, C1=0, and A1=0, then Y must be HIGH.
    check_a1_zero_with_b1c1_zero_y_one: assert property (
        @(posedge CLK) (!B1 && !C1 && !A1) |-> (Y == 1'b1)
    );

    // If B1=0, C1=0, and A2=0, then Y must be HIGH.
    check_a2_zero_with_b1c1_zero_y_one: assert property (
        @(posedge CLK) (!B1 && !C1 && !A2) |-> (Y == 1'b1)
    );

    // If B1=0, C1=0, and A3=0, then Y must be HIGH.
    check_a3_zero_with_b1c1_zero_y_one: assert property (
        @(posedge CLK) (!B1 && !C1 && !A3) |-> (Y == 1'b1)
    );

    // If all inputs are LOW, Y must be HIGH.
    check_all_zero_inputs_y_one: assert property (
        @(posedge CLK) (!A1 && !A2 && !A3 && !B1 && !C1) |-> (Y == 1'b1)
    );

    // Y HIGH implies B1=0, C1=0, and not (A1&A2&A3).
    check_y_high_implies_inputs_not_asserting: assert property (
        @(posedge CLK) Y |-> (!B1 && !C1 && !(A1 & A2 & A3))
    );

    // Y LOW implies at least one of (B1, C1, A1&A2&A3) is HIGH.
    check_y_low_implies_some_input_asserting: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (B1 || C1 || (A1 & A2 & A3))
    );

endmodule

module alu_4bit_sva (
    input logic CLK,
    input logic [3:0] Z,
    input logic [1:0] op,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C
);
    // For op=00, Z equals 4-bit A+B.
    check_add_correct: assert property (
        @(posedge CLK) (op == 2'b00) |-> (Z == (A + B))
    );

    // For op=00, Z-B equals A modulo 16.
    check_add_inverse: assert property (
        @(posedge CLK) (op == 2'b00) |-> ((Z - B) == A)
    );

    // For op=01, Z equals 4-bit A-B.
    check_sub_correct: assert property (
        @(posedge CLK) (op == 2'b01) |-> (Z == (A - B))
    );

    // For op=01, Z+B equals A modulo 16.
    check_sub_inverse: assert property (
        @(posedge CLK) (op == 2'b01) |-> ((Z + B) == A)
    );

    // For op=10, Z equals A & B.
    check_and_correct: assert property (
        @(posedge CLK) (op == 2'b10) |-> (Z == (A & B))
    );

    // For op=10, Z can only have bits set that are set in A.
    check_and_subset_A: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~A) == 4'b0000)
    );

    // For op=10, Z can only have bits set that are set in B.
    check_and_subset_B: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~B) == 4'b0000)
    );

    // For op=11, Z equals A | B.
    check_or_correct: assert property (
        @(posedge CLK) (op == 2'b11) |-> (Z == (A | B))
    );

    // For op=11, all bits set in A must be set in Z.
    check_or_superset_A: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & A) == 4'b0000)
    );

    // For op=11, all bits set in B must be set in Z.
    check_or_superset_B: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & B) == 4'b0000)
    );

    // If op, A, and B are stable, Z must remain stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable({op,A,B}) |-> $stable(Z)
    );

    // Z must be independent of C; C changes alone cannot change Z.
    check_independent_of_C: assert property (
        @(posedge CLK) $stable({op,A,B}) && $changed(C) |-> $stable(Z)
    );
endmodule

