verilog_code:
module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));

endmodule

module ripple_adder (
    input [3:0] a,
    input [3:0] b,
    output c
);

    wire [3:0] sum;
    wire [3:1] carry;

    full_adder fa0 (
        .a(a[0]),
        .b(b[0]),
        .cin(1'b0),
        .sum(sum[0]),
        .cout(carry[1])
    );

    full_adder fa1 (
        .a(a[1]),
        .b(b[1]),
        .cin(carry[1]),
        .sum(sum[1]),
        .cout(carry[2])
    );

    full_adder fa2 (
        .a(a[2]),
        .b(b[2]),
        .cin(carry[2]),
        .sum(sum[2]),
        .cout(carry[3])
    );

    full_adder fa3 (
        .a(a[3]),
        .b(b[3]),
        .cin(carry[3]),
        .sum(sum[3]),
        .cout(c)
    );

endmodule

sva_code:
module ripple_adder_sva (
    input logic CLK,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic c
);

    // Compute ripple carry-out (cin=0) from a,b bits.
    function automatic logic carry4 (input logic [3:0] x, input logic [3:0] y);
        logic c1, c2, c3, c4;
        c1 = x[0] & y[0];
        c2 = (x[1] & y[1]) | ((x[1] ^ y[1]) & c1);
        c3 = (x[2] & y[2]) | ((x[2] ^ y[2]) & c2);
        c4 = (x[3] & y[3]) | ((x[3] ^ y[3]) & c3);
        return c4;
    endfunction

    // Compute carry-out of lower 3 bits (cin=0).
    function automatic logic carry3 (input logic [2:0] x, input logic [2:0] y);
        logic c1, c2, c3;
        c1 = x[0] & y[0];
        c2 = (x[1] & y[1]) | ((x[1] ^ y[1]) & c1);
        c3 = (x[2] & y[2]) | ((x[2] ^ y[2]) & c2);
        return c3;
    endfunction

    // Carry-out equals overflow bit of 5-bit sum {0,a}+{0,b}.
    check_c_matches_add_overflow: assert property (
        @(posedge CLK) c == ({1'b0, a} + {1'b0, b})[4]
    );

    // Carry-out matches explicit ripple-carry computation (cin=0).
    check_c_matches_ripple_chain: assert property (
        @(posedge CLK) c == carry4(a, b)
    );

    // No carry when either operand is zero.
    check_no_carry_when_operand_zero: assert property (
        @(posedge CLK) ((a == 4'b0000) || (b == 4'b0000)) |-> (c == 1'b0)
    );

    // No carry when both MSBs are 0.
    check_no_carry_when_msb00: assert property (
        @(posedge CLK) (!a[3] && !b[3]) |-> (c == 1'b0)
    );

    // Carry is 1 when both MSBs are 1.
    check_carry_when_msb11: assert property (
        @(posedge CLK) (a[3] && b[3]) |-> (c == 1'b1)
    );

    // If exactly one MSB is 1 and low 3-bit add carries, carry-out is 1.
    check_carry_one_msb_and_lower_carry: assert property (
        @(posedge CLK) ((a[3] ^ b[3]) && (carry3(a[2:0], b[2:0]) == 1'b1)) |-> (c == 1'b1)
    );

    // If exactly one MSB is 1 and low 3-bit add does not carry, carry-out is 0.
    check_no_carry_one_msb_no_lower_carry: assert property (
        @(posedge CLK) ((a[3] ^ b[3]) && (carry3(a[2:0], b[2:0]) == 1'b0)) |-> (c == 1'b0)
    );

endmodule

verilog_code:
module top_module (
    input [3:0] multiplier,
    input [3:0] multiplicand,
    input [15:0] in0,
    input [15:0] in1,
    input ctrl,
    output reg [15:0] out
);

    wire [7:0] unsigned_mult_out;
    wire [3:0] add_sub_out;
    wire [15:0] final_out;

    unsigned_multiplier unsigned_mult(.a(multiplier), .b(multiplicand), .p(unsigned_mult_out));
    add_sub add_sub(.a(multiplier), .b(multiplicand), .ctrl(ctrl), .s(add_sub_out));
    functional_module functional(.in0(unsigned_mult_out), .in1(add_sub_out), .out(final_out));

    always @(*) begin
        if (ctrl == 0) begin
            out = final_out;
        end else begin
            out = final_out + in0 + in1;
        end
    end

endmodule

module unsigned_multiplier (
    input [3:0] a,
    input [3:0] b,
    output reg [7:0] p
);

    always @(*) begin
        p = a * b;
    end

endmodule

module add_sub (
    input [3:0] a,
    input [3:0] b,
    input ctrl,
    output reg [3:0] s
);

    always @(*) begin
        if (ctrl == 0) begin
            s = a + b;
        end else begin
            s = a - b;
        end
    end

endmodule

module functional_module (
    input [7:0] in0,
    input [3:0] in1,
    output reg [15:0] out
);

    always @(*) begin
        out = {8'b0, in0} + {12'b0, in1};
    end

endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic [3:0] multiplier,
    input logic [3:0] multiplicand,
    input logic [15:0] in0,
    input logic [15:0] in1,
    input logic ctrl,
    input logic [15:0] out
);
    // Note: DUT is purely combinational with no reset; assertions are sampled on clk with no disable.

    // Helper expressions matching DUT math
    let prod8_l  = (multiplier * multiplicand);                  // 8-bit product
    let sum4_l   = (multiplier + multiplicand);                  // 4-bit add (wrap)
    let diff4_l  = (multiplier - multiplicand);                  // 4-bit sub (wrap)
    let final0_l = {8'b0, prod8_l} + {12'b0, sum4_l};            // functional_module(out) when ctrl==0
    let final1_l = {8'b0, prod8_l} + {12'b0, diff4_l};           // functional_module(out) when ctrl==1

    // When ctrl==0, out equals functional_module result (product + add) zero-extended.
    check_ctrl0_out_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out == final0_l)
    );

    // When ctrl==1, out equals functional result (product + sub) plus in0 and in1 (16-bit wrap).
    check_ctrl1_out_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b1) |-> (out == (final1_l + in0 + in1))
    );

    // Under ctrl==0, upper 8 bits of out are zero (result fits in 8 bits after nibble add).
    check_ctrl0_upper_zero: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out[15:8] == 8'h00)
    );

    // If all inputs are stable, out remains stable (purely combinational function).
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (1'b0)
            $stable({multiplier, multiplicand, ctrl, in0, in1}) |-> $stable(out)
    );

    // Under ctrl==0, with ctrl/multiplier/multiplicand stable, out is stable (ignores in0/in1).
    check_ctrl0_independent_of_in0_in1: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0 && $stable(ctrl) && $stable(multiplier) && $stable(multiplicand)) |-> $stable(out)
    );

    // Under ctrl==0, low nibble equals (prod[3:0] + (a+b))[3:0].
    check_ctrl0_low_nibble: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out[3:0] == ((prod8_l[3:0] + sum4_l)[3:0]))
    );

    // Under ctrl==0, out is within the computed bound (<= 240).
    check_ctrl0_range_bound: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b0) |-> (out <= 16'd240)
    );

    // Under ctrl==1 and in0==0 and in1==0, out reduces to functional result (product + sub).
    check_ctrl1_zero_ext_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
            (ctrl == 1'b1 && in0 == 16'h0000 && in1 == 16'h0000) |-> (out == final1_l)
    );

    // On ctrl falling edge, output selects the ctrl==0 path immediately.
    check_ctrl_fall_selects_ctrl0_path: assert property (
        @(posedge clk) disable iff (1'b0)
            $fell(ctrl) |-> (out == final0_l)
    );

    // On ctrl rising edge, output selects the ctrl==1 path immediately.
    check_ctrl_rise_selects_ctrl1_path: assert property (
        @(posedge clk) disable iff (1'b0)
            $rose(ctrl) |-> (out == (final1_l + in0 + in1))
    );

endmodule

