module sky130_fd_sc_hd__nand3b_sva (
    input logic CLK,   // sampling clock for combinational checks
    input logic Y,
    input logic A_N,
    input logic B,
    input logic C
);
    ///// Functional correctness of NAND3B (Y = ~(B & C & ~A_N)) /////

    // Combinational truth: Y equals ~(B & C & ~A_N).
    check_truth_function: assert property (
        @(posedge CLK) Y == ~(B & C & ~A_N)
    );

    // Y is LOW only when B=1, C=1, and A_N=0.
    check_low_requires_all_inputs: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (B == 1'b1) && (C == 1'b1) && (A_N == 1'b0)
    );

    // When B=1, C=1, and A_N=0, Y must be LOW.
    check_all_inputs_force_low: assert property (
        @(posedge CLK) ((B == 1'b1) && (C == 1'b1) && (A_N == 1'b0)) |-> (Y == 1'b0)
    );

    // A_N=1 forces Y=1 (since ~A_N=0 makes the AND term 0).
    check_AN_high_forces_high: assert property (
        @(posedge CLK) (A_N == 1'b1) |-> (Y == 1'b1)
    );

    // B=0 forces Y=1 (NAND with a 0 input is 1).
    check_B_low_forces_high: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

    // C=0 forces Y=1 (NAND with a 0 input is 1).
    check_C_low_forces_high: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

    // With B=1 and C=1, Y equals A_N.
    check_BC_high_output_equals_AN: assert property (
        @(posedge CLK) ((B == 1'b1) && (C == 1'b1)) |-> (Y == A_N)
    );

    // With A_N=0, Y equals ~(B & C).
    check_AN_low_output_equals_nand_BC: assert property (
        @(posedge CLK) (A_N == 1'b0) |-> (Y == ~(B & C))
    );

endmodule

verilog_code:
module clk32to40 (
  input CLK_IN1,
  output reg CLK_OUT
);

  // Clock to Q delay of 100ps
  localparam  TCQ              = 100;

  reg [1:0] counter;
  wire reset ;

  always @(posedge CLK_IN1 or negedge reset) begin
    if (!reset) begin
      counter <= 2'b00;
    end else if (counter == 2'b11) begin
      counter <= 2'b00;
    end else begin
      counter <= counter + 1;
    end
  end

  assign reset = (counter == 2'b11);

  always @(posedge CLK_IN1) begin
    if (!reset) CLK_OUT <= 1'b0;
    else begin
      if (counter == 2'b01) CLK_OUT <= 1'b1;
      else if (counter == 2'b10) CLK_OUT <= 1'b0;
    end
  end

endmodule

sva_code:
module clk32to40_sva (
    input logic CLK_IN1,
    input logic CLK_OUT,
    input logic [1:0] counter,
    input logic reset
);
    // Clock: CLK_IN1 posedge. Async reset: active-LOW 'reset' derived as (counter == 2'b11). Sequential logic.

    // 'reset' is exactly when counter is 2'b11.
    check_reset_definition: assert property (
        @(posedge CLK_IN1) reset == (counter == 2'b11)
    );

    // On any cycle, counter must be 2'b00 on the next rising edge.
    check_counter_next_zero: assert property (
        @(posedge CLK_IN1) 1'b1 |=> (counter == 2'b00)
    );

    // If reset is LOW at this edge, counter becomes 0 next cycle.
    check_counter_next_zero_when_reset_low: assert property (
        @(posedge CLK_IN1) (!reset) |=> (counter == 2'b00)
    );

    // If counter is 2'b11 at this edge, it becomes 0 next cycle.
    check_counter_wrap_from_3_to_0: assert property (
        @(posedge CLK_IN1) (counter == 2'b11) |=> (counter == 2'b00)
    );

    // When reset is LOW, CLK_OUT is forced LOW on the next cycle.
    check_clk_out_forced_low: assert property (
        @(posedge CLK_IN1) (!reset) |=> (CLK_OUT == 1'b0)
    );

    // When reset is HIGH (counter==3), CLK_OUT holds its previous value into the next cycle.
    check_clk_out_stable_when_reset_high: assert property (
        @(posedge CLK_IN1) reset |=> (CLK_OUT == $past(CLK_OUT))
    );

    // If previous cycle had reset LOW, CLK_OUT must be LOW now.
    check_clk_out_low_after_prev_reset_low: assert property (
        @(posedge CLK_IN1) $past(!reset) |-> (CLK_OUT == 1'b0)
    );

    // Counter==0 implies reset is LOW in the same cycle.
    check_reset_low_when_counter_zero: assert property (
        @(posedge CLK_IN1) (counter == 2'b00) |-> (reset == 1'b0)
    );

    // reset cannot remain HIGH for two consecutive sampled cycles.
    check_reset_single_cycle_pulse: assert property (
        @(posedge CLK_IN1) reset |=> !reset
    );

    // Once reset is LOW, it remains LOW on the next sampled cycle.
    check_reset_stays_low: assert property (
        @(posedge CLK_IN1) !reset |=> !reset
    );
endmodule

