  always @(posedge clk) begin
    if (reset) begin
      // Reset state and shift register
      state <= IDLE;
      shift_reg <= 3'b0;
      output_reg <= 1'b0;
    end else begin
      // Shift in new data
      shift_reg <= {shift_reg[1:0], data};

      // State machine
      case(state)
        IDLE: begin
          if (shift_reg == PATTERN) begin
            state <= STATE1;
            output_reg <= 1'b1;
          end else begin
            state <= IDLE;
            output_reg <= 1'b0;
          end
        end
        STATE1: begin
          state <= STATE2;
          output_reg <= 1'b1;
        end
        STATE2: begin
          state <= IDLE;
          output_reg <= 1'b0;
        end
      endcase
    end
  end

  // Assign output
  assign detected = output_reg;

endmodule

