module counter (
    input Clk,
    input Reset,
    input Enable,
    output [3:0] Q
);

reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(posedge Clk) begin
    if (Reset) begin
        Q_reg <= 4'b0000;
    end else if (Enable) begin
        Q_reg <= Q_next;
    end
end

always @(*) begin
    if (Enable)
        Q_next = Q_reg + 1;
    else
        Q_next = Q_reg;
end

assign Q = Q_reg;

endmodule

sva_code:
module counter_sva (
    input logic Clk,
    input logic Reset,     // Active-HIGH synchronous reset
    input logic Enable,
    input logic [3:0] Q
);

    ///// Reset behavior /////
    // On any cycle with Reset HIGH, Q is 0 on the next cycle.
    reset_forces_zero_next: assert property (
        @(posedge Clk) Reset |=> (Q == 4'd0)
    );

    // If Reset is held HIGH for consecutive cycles, Q must read 0.
    reset_hold_zero: assert property (
        @(posedge Clk) (Reset && $past(Reset)) |-> (Q == 4'd0)
    );

    ///// Enable/hold/increment rules /////
    // When disabled (and not in reset), Q holds its value into the next cycle.
    hold_when_disabled: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable) |=> (Q == $past(Q))
    );

    // When enabled and Q != 15, Q increments by 1 next cycle.
    increment_when_enabled_no_overflow: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q != 4'hF)) |=> (Q == $past(Q) + 4'd1)
    );

    // When enabled and Q == 15, Q wraps to 0 next cycle.
    rollover_when_enabled_at_max: assert property (
        @(posedge Clk) disable iff (Reset) (Enable && (Q == 4'hF)) |=> (Q == 4'd0)
    );

    // Any change to Q (without a reset in the previous cycle) requires previous Enable.
    change_requires_prev_enable: assert property (
        @(posedge Clk) disable iff (Reset) ($changed(Q) && !$past(Reset)) |-> $past(Enable)
    );

    // With 16 consecutive enabled cycles (no reset), Q returns to its value 16 cycles earlier.
    wrap_after_16_enables: assert property (
        @(posedge Clk) disable iff (Reset) (Enable[*16]) |=> (Q == $past(Q, 16))
    );

    // With two consecutive disabled cycles (no reset), Q matches its value two cycles earlier.
    hold_across_two_disabled_cycles: assert property (
        @(posedge Clk) disable iff (Reset) (!Enable[*2]) |=> (Q == $past(Q, 2))
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic [3:0] input_data,
    input logic [3:0] Q
);
    // When load is HIGH, next Q equals current input_data.
    check_load_captures_input_data: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

    // When load is LOW and up_down is HIGH, next Q increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == (($past(Q) + 1) & 4'hF))
    );

    // When load is LOW and up_down is LOW, next Q decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == (($past(Q) - 1) & 4'hF))
    );

    // Increment from 0xF wraps to 0x0 when not loading.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

    // Decrement from 0x0 wraps to 0xF when not loading.
    check_wrap_decrement_from_min: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

    // Each cycle Q equals the function of prior-cycle controls and data.
    check_functional_update_each_cycle: assert property (
        @(posedge clk)
        Q == ( $past(load)
               ? $past(input_data)
               : ( $past(up_down)
                   ? (($past(Q) + 1) & 4'hF)
                   : (($past(Q) - 1) & 4'hF)))
    );

    // Two consecutive UP steps (no load) increment Q by 2 (mod 16).
    check_two_cycle_increment: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && up_down) |=> (Q == (($past(Q,2) + 2) & 4'hF))
    );

    // Two consecutive DOWN steps (no load) decrement Q by 2 (mod 16).
    check_two_cycle_decrement: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && !up_down) |=> (Q == (($past(Q,2) - 2) & 4'hF))
    );

    // UP followed by DOWN with no loads returns Q to original value after 2 cycles.
    check_up_then_down_cancels: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && !up_down) |=> (Q == $past(Q,2))
    );

    // DOWN followed by UP with no loads returns Q to original value after 2 cycles.
    check_down_then_up_cancels: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && up_down) |=> (Q == $past(Q,2))
    );

    // Two consecutive loads use the second cycle's input_data value.
    check_two_consecutive_loads_use_second_value: assert property (
        @(posedge clk) load ##1 load |=> (Q == $past(input_data,1))
    );
endmodule

module calculator_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [1:0] op,
    input logic [3:0] result
);
    // For op==00, result is low 4 bits of a+b.
    check_addition_result: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op == 2'b00) |-> (result == (a + b)[3:0])
    );

    // For op==01, result is low 4 bits of a-b.
    check_subtraction_result: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op == 2'b01) |-> (result == (a - b)[3:0])
    );

    // For op values not 00/01 (i.e., 10 or 11), result is 0.
    check_default_zero_for_other_ops: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) (op[1] == 1'b1) |-> (result == 4'b0000)
    );

    // Addition identity: when op==00 and b==0, result equals a.
    check_addition_with_b_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b00) && (b == 4'b0000)) |-> (result == a)
    );

    // Addition identity: when op==00 and a==0, result equals b.
    check_addition_with_a_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b00) && (a == 4'b0000)) |-> (result == b)
    );

    // Subtraction identity: when op==01 and b==0, result equals a.
    check_subtraction_with_b_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b01) && (b == 4'b0000)) |-> (result == a)
    );

    // Subtraction equality: when op==01 and a==b, result is 0.
    check_subtraction_equal_operands_zero: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1]) ((op == 2'b01) && (a == b)) |-> (result == 4'b0000)
    );

    // Functional mapping completeness: result matches the selected operation.
    check_functional_mapping_complete: assert property (
        @(posedge a[0] or posedge b[0] or posedge op[0] or posedge op[1])
            1'b1 |-> (
                ((op == 2'b00) && (result == (a + b)[3:0])) ||
                ((op == 2'b01) && (result == (a - b)[3:0])) ||
                ((op[1] == 1'b1) && (result == 4'b0000))
            )
    );
endmodule

