module RegisterAdd
	# (parameter W = 16)
	(
		input wire clk, input wire rst, input wire load, input wire [W-1:0] D, output reg [W-1:0] Q );

	always @(posedge clk, posedge rst)
		if(rst)
			Q <= 0;
		else if(load)
			Q <= D;
		else
			Q <= Q;

endmodule

module FFD_NoCE
	# (parameter W = 16)
	(
		input wire clk, input wire rst, input wire [W-1:0] D, output reg [W-1:0] Q );

	always @(posedge clk, posedge rst)
		if(rst)
			Q <= 0;
		else
			Q <= D;

endmodule

sva_code:
module RegisterAdd_sva #(
    parameter W = 16
) (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [W-1:0] D,
    input logic [W-1:0] Q
);
    // Clock: clk; Reset: rst (active-high async)

    // Reset drives Q to zero whenever rst is HIGH.
    registeradd_check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (Q == '0)
    );

    // When not in reset (now and last cycle) and load is LOW, Q holds its value.
    registeradd_check_hold_when_not_load: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !load) |=> (Q == $past(Q))
    );

    // When not in reset (now and last cycle) and load is HIGH, Q updates to D.
    registeradd_check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && load) |=> (Q == $past(D))
    );

    // Immediately after reset deasserts, if load is LOW, Q remains zero.
    registeradd_check_after_reset_no_load_q_zero: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst) && !load) |-> (Q == '0)
    );

    // Immediately after reset deasserts, if load is HIGH, next Q equals current D.
    registeradd_check_after_reset_with_load_captures_d: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst) && load) |=> (Q == $past(D))
    );

    // If load stayed LOW across two cycles with no reset, Q must be stable.
    registeradd_check_two_cycle_hold: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && !load && !$past(load)) |-> (Q == $past(Q))
    );

endmodule


module FFD_NoCE_sva #(
    parameter W = 16
) (
    input logic clk,
    input logic rst,
    input logic [W-1:0] D,
    input logic [W-1:0] Q
);
    // Clock: clk; Reset: rst (active-high async)

    // Reset drives Q to zero whenever rst is HIGH.
    ffd_check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (Q == '0)
    );

    // With no reset in the previous cycle, Q equals prior D on this cycle.
    ffd_check_d_captured_no_reset: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst)) |-> (Q == $past(D))
    );

    // On the first cycle after reset deasserts, next Q equals current D.
    ffd_check_after_reset_capture: assert property (
        @(posedge clk) disable iff (rst)
            ($past(rst)) |=> (Q == $past(D))
    );

    // While reset remains asserted across cycles, Q stays at zero.
    ffd_check_reset_holds_zero: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (Q == '0)
    );

endmodule

verilog_code:
module posManager (
   input         clk,
   input [15:0]  pos11,
   input [15:0]  pos12,
   input [15:0]  pos21,
   input [15:0]  pos22,
   output [15:0] pos_diff_x,
   output [15:0] pos_diff_y,
   output [31:0] count_clk,
   input  [1:0]  clear,
   input  [0:0]  m1,
   input  [0:0]  m2
);

   reg [15:0] prev_pos11, prev_pos12, prev_pos21, prev_pos22;
   reg [31:0] prev_count_clk;

   always @(posedge clk) begin
      if (clear == 2'b10 || clear == 2'b11) begin
         prev_count_clk <= 0;
      end else begin
         prev_count_clk <= prev_count_clk + 1;
      end

      if (clear == 2'b01 || clear == 2'b10 || clear == 2'b11) begin
         prev_pos11 <= pos11;
         prev_pos12 <= pos12;
         prev_pos21 <= pos21;
         prev_pos22 <= pos22;
      end else begin
         if (m1 == 1'b1) begin
            prev_pos11 <= prev_pos11 + 1;
            prev_pos12 <= prev_pos12 + 1;
         end else begin
            prev_pos11 <= prev_pos11 - 1;
            prev_pos12 <= prev_pos12 - 1;
         end

         if (m2 == 1'b1) begin
            prev_pos21 <= prev_pos21 + 1;
            prev_pos22 <= prev_pos22 + 1;
         end else begin
            prev_pos21 <= prev_pos21 - 1;
            prev_pos22 <= prev_pos22 - 1;
         end
      end
   end

   assign pos_diff_x = clear == 2'b10 || clear == 2'b11 ? 0 : pos11 - pos21;
   assign pos_diff_y = clear == 2'b10 || clear == 2'b11 ? 0 : pos12 - pos22;
   assign count_clk = clear == 2'b10 || clear == 2'b11 ? 0 : prev_count_clk;

endmodule

sva_code:
module posManager_sva (
   input logic        clk,
   input logic [15:0] pos11,
   input logic [15:0] pos12,
   input logic [15:0] pos21,
   input logic [15:0] pos22,
   input logic [15:0] pos_diff_x,
   input logic [15:0] pos_diff_y,
   input logic [31:0] count_clk,
   input logic [1:0]  clear,
   input logic [0:0]  m1,
   input logic [0:0]  m2
);
   // Clock: clk (posedge). No explicit reset. Mixed logic: sequential counter, combinational diffs with clear gating.

   // count_clk must be 0 when clear is 2'b10 or 2'b11.
   check_count_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (count_clk == 32'd0)
   );

   // pos_diff_x must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffx_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == 16'd0)
   );

   // pos_diff_y must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffy_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == 16'd0)
   );

   // pos_diff_x equals pos11 - pos21 when clear is not 2'b10 or 2'b11.
   check_posdiffx_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == (pos11 - pos21))
   );

   // pos_diff_y equals pos12 - pos22 when clear is not 2'b10 or 2'b11.
   check_posdiffy_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == (pos12 - pos22))
   );

   // With two consecutive active cycles, count_clk increments by 1 each cycle.
   check_count_inc_on_two_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk) + 32'd1)
   );

   // With three consecutive active cycles, count_clk increases by 2 over two cycles.
   check_count_inc_by_two_on_three_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk,2) + 32'd2)
   );

   // When clear goes from 2'b10/2'b11 to active, next count_clk must be 1.
   check_count_one_after_release: assert property (
      @(posedge clk)
      ( ((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == 32'd1)
   );

   // pos_diff_x remains stable if clear, pos11 and pos21 are stable.
   check_posdiffx_stable_on_input_stable: assert property (
      @(posedge clk) ($stable(clear) && $stable(pos11) && $stable(pos21)) |-> $stable(pos_diff_x)
   );

   // pos_diff_y remains stable if clear, pos12 and pos22 are stable.
   check_posdiffy_stable_on_input_stable: assert property (
      @(posedge clk) ($stable(clear) && $stable(pos12) && $stable(pos22)) |-> $stable(pos_diff_y)
   );

endmodule

verilog_code:
module errman_nfl (
  output nfl_num,
  output inc_dec_b,
  input cfg_err_cpl_timeout_n,
  input decr_nfl,
  input rst,
  input clk
);

  parameter FFD = 1; // clock to out delay model

  reg to_incr;
  reg add_sub_b;

  always @ (cfg_err_cpl_timeout_n or decr_nfl) begin
    case ({cfg_err_cpl_timeout_n, decr_nfl})
      2'b10: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
      2'b11: begin
        to_incr = 1'b1;
        add_sub_b = 1'b0;
      end
      2'b00: begin
        to_incr = 1'b1;
        add_sub_b = 1'b1;
      end
      2'b01: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
      default: begin
        to_incr = 1'b0;
        add_sub_b = 1'b1;
      end
    endcase
  end

  reg reg_nfl_num;
  reg reg_inc_dec_b;

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      reg_nfl_num <= #FFD 1'b0;
      reg_inc_dec_b <= #FFD 1'b0;
    end else begin
      reg_nfl_num <= #FFD to_incr ? reg_nfl_num + 1 : reg_nfl_num - 1;
      reg_inc_dec_b <= #FFD add_sub_b;
    end
  end

  assign nfl_num = reg_nfl_num;
  assign inc_dec_b = reg_inc_dec_b;

endmodule

sva_code:
module errman_nfl_sva (
  input logic clk,
  input logic rst, // active-high async reset
  input logic cfg_err_cpl_timeout_n,
  input logic decr_nfl,
  input logic nfl_num,
  input logic inc_dec_b
);

  ///// Reset behavior /////
  // While reset is asserted, outputs are held LOW.
  reset_outputs_low: assert property (
    @(posedge clk) rst |-> (nfl_num == 1'b0) && (inc_dec_b == 1'b0)
  );

  ///// Sequential behavior of nfl_num /////
  // nfl_num toggles every active clock (one-cycle complement).
  check_nfl_num_toggle_each_cycle: assert property (
    @(posedge clk) disable iff (rst) $past(1'b1) |-> (nfl_num == ~$past(nfl_num))
  );
  // nfl_num must change on every active clock edge.
  check_nfl_num_always_changes: assert property (
    @(posedge clk) disable iff (rst) $past(1'b1) |-> $changed(nfl_num)
  );

  ///// Registered capture of inc_dec_b /////
  // inc_dec_b equals NAND of inputs from the previous cycle (when previous cycle not in reset).
  check_inc_dec_b_captures_prev_nand: assert property (
    @(posedge clk) disable iff (rst) $past(!rst) |-> inc_dec_b == ~( $past(cfg_err_cpl_timeout_n) & $past(decr_nfl) )
  );
  // Any change on inc_dec_b reflects a change in previous-cycle NAND of inputs.
  check_inc_dec_b_change_matches_prev_input_change: assert property (
    @(posedge clk) disable iff (rst)
      $past(!rst,1) && $past(!rst,2) && $changed(inc_dec_b)
      |-> ($past(~(cfg_err_cpl_timeout_n & decr_nfl),1) != $past(~(cfg_err_cpl_timeout_n & decr_nfl),2))
  );
  // If previous-cycle NAND of inputs is unchanged, inc_dec_b does not change.
  check_inc_dec_b_no_change_if_prev_input_nand_unchanged: assert property (
    @(posedge clk) disable iff (rst)
      $past(!rst,1) && $past(!rst,2) && ($past(~(cfg_err_cpl_timeout_n & decr_nfl),1) == $past(~(cfg_err_cpl_timeout_n & decr_nfl),2))
      |-> !$changed(inc_dec_b)
  );

  ///// Consistency checks for inc_dec_b values /////
  // inc_dec_b can be 0 only if both inputs were 1 in the previous cycle.
  check_inc_dec_b_zero_only_on_prev_both_high: assert property (
    @(posedge clk) disable iff (rst) ($past(!rst) && (inc_dec_b == 1'b0)) |-> ($past(cfg_err_cpl_timeout_n) && $past(decr_nfl))
  );
  // inc_dec_b is 1 if at least one previous input was 0.
  check_inc_dec_b_one_on_prev_not_both_high: assert property (
    @(posedge clk) disable iff (rst) ($past(!rst) && (inc_dec_b == 1'b1)) |-> !($past(cfg_err_cpl_timeout_n) && $past(decr_nfl))
  );

endmodule

