module CLK_GEN(
  input CLK_IN,
  output reg CLK_OUT
);

reg [24:0] counter;

always @(posedge CLK_IN) begin
  counter <= counter + 1;
  if (counter == 25'd4166) begin
    counter <= 0;
    CLK_OUT <= ~CLK_OUT;
  end
end

endmodule

sva_code:
module CLK_GEN_sva (
    input logic CLK_IN,
    input logic CLK_OUT,
    input logic [24:0] counter
);
    // Counter resets to 0 on the cycle after it was 4166.
    check_counter_resets_at_4166: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            ($past(counter) == 25'd4166) |-> (counter == 25'd0)
    );

    // Counter increments by 1 when previous value was not 4166.
    check_counter_increments_otherwise: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            ($past(counter) != 25'd4166) |-> (counter == $past(counter) + 25'd1)
    );

    // If counter is 4166 in this cycle, it becomes 0 in the next cycle.
    check_counter_4166_then_zero_next: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            (counter == 25'd4166) |=> (counter == 25'd0)
    );

    // CLK_OUT can change only on cycles following counter==4166.
    check_clkout_change_only_on_4166: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            $changed(CLK_OUT) |-> ($past(counter) == 25'd4166)
    );

    // When previous counter != 4166, CLK_OUT must not change.
    check_clkout_stable_when_not_4166: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            ($past(counter) != 25'd4166) |-> (!$changed(CLK_OUT))
    );

    // When previous counter==4166 and CLK_OUT is known, it must toggle.
    check_clkout_toggles_on_4166_when_known: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            (($past(counter) == 25'd4166) && !$isunknown(CLK_OUT) && !$isunknown($past(CLK_OUT)))
            |-> (CLK_OUT == ~$past(CLK_OUT))
    );

    // A transition to counter==0 only comes from 4166 or from max-value overflow.
    check_counter_zero_from_only_4166_or_overflow: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            (counter == 25'd0) |-> (($past(counter) == 25'd4166) || ($past(counter) == 25'd33554431))
    );

    // If previous counter was neither 4166 nor max, next counter cannot be 0.
    check_no_spurious_zero: assert property (
        @(posedge CLK_IN) disable iff ($initstate)
            (($past(counter) != 25'd4166) && ($past(counter) != 25'd33554431)) |-> (counter != 25'd0)
    );
endmodule

module up_counter_sva (
    input logic clk,
    input logic reset,   // active-high synchronous reset
    input logic enable,
    input logic [2:0] count
);

    ///// Reset behavior /////
    // When reset is asserted, count is driven to 0 on that clock.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 3'b000)
    );

    ///// Increment and hold behavior /////
    // When enabled (and not in reset), count increments by 1.
    increment_on_enable: assert property (
        @(posedge clk) disable iff (reset) (!$initstate && enable) |-> (count == $past(count) + 3'd1)
    );

    // When not enabled (and not in reset), count holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!$initstate && !enable) |-> (count == $past(count))
    );

    // Any change to count (out of reset) must be due to enable being 1.
    change_only_with_enable: assert property (
        @(posedge clk) disable iff (reset) (!$initstate && (count != $past(count))) |-> enable
    );

    // Explicit wrap-around: from 7 to 0 when enabled (out of reset).
    wrap_7_to_0: assert property (
        @(posedge clk) disable iff (reset) (!$initstate && enable && ($past(count) == 3'd7)) |-> (count == 3'd0)
    );

    ///// Behavior immediately after leaving reset /////
    // If reset deasserts and enable is 0, count remains 0.
    hold_zero_after_reset_if_disabled: assert property (
        @(posedge clk) $fell(reset) && !enable |-> (count == 3'd0)
    );

    // If reset deasserts and enable is 1, count becomes 1.
    increment_from_zero_after_reset_if_enabled: assert property (
        @(posedge clk) $fell(reset) && enable |-> (count == 3'd1)
    );

endmodule

verilog_code:
module clock_divider (
  input clk_in, rst,
  output reg clk_out
);

parameter div_factor = 2; // divide by 2

reg [31:0] counter;

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    counter <= 0;
    clk_out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == div_factor - 1) begin
      counter <= 0;
      clk_out <= ~clk_out;
    end
  end
end

endmodule

sva_code:
module clock_divider_sva #(
    parameter int unsigned div_factor = 2
) (
    input  logic clk_in,
    input  logic rst,
    input  logic clk_out
);

    ///// Reset behavior /////
    // While reset is asserted, clk_out must be 0.
    reset_drives_low: assert property (
        @(posedge clk_in) rst |-> (clk_out == 1'b0)
    );

    // If reset is held high across cycles, clk_out stays at 0 and stable.
    reset_holds_low_stable: assert property (
        @(posedge clk_in) (rst && $past(rst)) |-> (clk_out == 1'b0) && $stable(clk_out)
    );

    ///// Active behavior /////
    // When active (not in reset), any change on clk_out is by inversion of its previous value.
    invert_on_toggle_when_active: assert property (
        @(posedge clk_in) disable iff (rst)
            ($changed(clk_out) && !$isunknown($past(clk_out)) && !$isunknown(clk_out)) |-> (clk_out == ~$past(clk_out))
    );

    // Properties that depend on div_factor being at least 1.
    generate
        if (div_factor >= 1) begin : gen_df_ge_1
            // After a toggle, there are exactly (div_factor-1) stable cycles, then a toggle.
            toggle_period_exact: assert property (
                @(posedge clk_in) disable iff (rst)
                    $changed(clk_out) |-> $stable(clk_out)[* (div_factor - 1)] ##1 $changed(clk_out)
            );

            // Starting at any cycle, if clk_out remains stable for (div_factor-1) cycles, it toggles next.
            must_toggle_after_wait: assert property (
                @(posedge clk_in) disable iff (rst)
                    $stable(clk_out)[* (div_factor - 1)] |-> ##1 $changed(clk_out)
            );

            // After reset de-asserts, the first toggle occurs after exactly div_factor cycles.
            first_toggle_after_reset: assert property (
                @(posedge clk_in) disable iff (rst)
                    $fell(rst) |-> $stable(clk_out)[* (div_factor - 1)] ##1 $changed(clk_out)
            );

            // For div_factor > 1, no back-to-back toggles in consecutive cycles.
            if (div_factor > 1) begin : gen_df_gt_1
                no_adjacent_toggles: assert property (
                    @(posedge clk_in) disable iff (rst)
                        $changed(clk_out) |-> ##1 !$changed(clk_out)
                );
            end
        end
    endgenerate

endmodule

