module top_module_sva (
    input  logic [3:0] in,
    input  logic       out_add,
    input  logic       out_sub,
    input  logic       out_mul
);
    // out_add is LSB of (in + 1)
    check_out_add_is_lsb_of_in_plus_one: assert property (
        @(posedge $global_clock) out_add == ((in + 4'd1)[0])
    );

    // out_sub is LSB of (in - 1)
    check_out_sub_is_lsb_of_in_minus_one: assert property (
        @(posedge $global_clock) out_sub == ((in - 4'd1)[0])
    );

    // out_mul is LSB of (in * in)
    check_out_mul_is_lsb_of_square: assert property (
        @(posedge $global_clock) out_mul == ((in * in)[0])
    );

    // LSB of (in + 1) equals ~in[0]
    check_out_add_equals_not_in0: assert property (
        @(posedge $global_clock) out_add == ~in[0]
    );

    // LSB of (in - 1) equals ~in[0]
    check_out_sub_equals_not_in0: assert property (
        @(posedge $global_clock) out_sub == ~in[0]
    );

    // LSB of (in * in) equals in[0]
    check_out_mul_equals_in0: assert property (
        @(posedge $global_clock) out_mul == in[0]
    );

    // out_add and out_sub match
    check_add_and_sub_match: assert property (
        @(posedge $global_clock) out_add == out_sub
    );

    // out_mul is the inverse of out_add
    check_mul_is_inverse_of_add: assert property (
        @(posedge $global_clock) out_mul == ~out_add
    );

    // If in[0] is 0, then add/sub LSBs are 1 and mul LSB is 0
    check_outputs_when_in0_is_zero: assert property (
        @(posedge $global_clock) (in[0] == 1'b0) |-> (out_add == 1'b1) && (out_sub == 1'b1) && (out_mul == 1'b0)
    );

    // If in[0] is 1, then add/sub LSBs are 0 and mul LSB is 1
    check_outputs_when_in0_is_one: assert property (
        @(posedge $global_clock) (in[0] == 1'b1) |-> (out_add == 1'b0) && (out_sub == 1'b0) && (out_mul == 1'b1)
    );

    // With stable input, outputs remain stable (pure combinational)
    check_stability_with_stable_input: assert property (
        @(posedge $global_clock) $stable(in) |-> $stable(out_add) && $stable(out_sub) && $stable(out_mul)
    );
endmodule

verilog_code:
module updown_counter (
    input clk,
    input U_D,
    output reg [3:0] Q
);

reg [3:0] Q_reg1;
reg [3:0] Q_reg2;

always @(posedge clk) begin
    Q_reg1 <= Q;
end

always @(posedge clk) begin
    Q_reg2 <= Q_reg1;
end

always @(posedge clk) begin
    if (U_D) begin
        Q <= Q_reg2 + 1;
    end else begin
        Q <= Q_reg2 - 1;
    end
end

endmodule

sva_code:
module updown_counter_sva (
    input logic clk,
    input logic U_D,
    input logic [3:0] Q,
    input logic [3:0] Q_reg1,
    input logic [3:0] Q_reg2
);
    // Q_reg1 captures Q each cycle.
    check_q_reg1_captures_q: assert property (
        @(posedge clk) Q_reg1 == $past(Q)
    );

    // Q_reg2 captures Q_reg1 each cycle.
    check_q_reg2_captures_q_reg1: assert property (
        @(posedge clk) Q_reg2 == $past(Q_reg1)
    );

    // Q_reg2 equals Q delayed by 2 cycles.
    check_q_reg2_two_cycle_delay_of_q: assert property (
        @(posedge clk) Q_reg2 == $past(Q, 2)
    );

    // When counting up, Q equals previous Q_reg2 + 1 (mod-16).
    check_q_update_from_q_reg2_up: assert property (
        @(posedge clk) U_D |-> (Q == ($past(Q_reg2) + 4'd1))
    );

    // When counting down, Q equals previous Q_reg2 - 1 (mod-16).
    check_q_update_from_q_reg2_down: assert property (
        @(posedge clk) (!U_D) |-> (Q == ($past(Q_reg2) - 4'd1))
    );

    // End-to-end: when counting up, Q equals Q from 3 cycles ago + 1.
    check_e2e_up_from_q_delay3: assert property (
        @(posedge clk) U_D |-> (Q == ($past(Q, 3) + 4'd1))
    );

    // End-to-end: when counting down, Q equals Q from 3 cycles ago - 1.
    check_e2e_down_from_q_delay3: assert property (
        @(posedge clk) (!U_D) |-> (Q == ($past(Q, 3) - 4'd1))
    );

    // Wrap on increment: F + 1 -> 0.
    check_wrap_up: assert property (
        @(posedge clk) (U_D && ($past(Q_reg2) == 4'hF)) |-> (Q == 4'h0)
    );

    // Wrap on decrement: 0 - 1 -> F.
    check_wrap_down: assert property (
        @(posedge clk) (!U_D && ($past(Q_reg2) == 4'h0)) |-> (Q == 4'hF)
    );

    // LSB always toggles relative to previous Q_reg2 for +/-1.
    check_lsb_toggle_vs_qreg2: assert property (
        @(posedge clk) Q[0] == ~($past(Q_reg2[0]))
    );
endmodule

verilog_code:
module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT
);

wire [3:0] sum;
wire [3:0] carry;

// First stage
assign {carry[0], sum[0]} = A + B;

// Second stage
assign {carry[1], sum[1]} = sum[0] + carry[0];

// Third stage
assign {carry[2], sum[2]} = sum[1] + carry[1];

// Fourth stage
assign {carry[3], sum[3]} = sum[2] + carry[2];

assign OUT = sum[3:0];

endmodule

sva_code:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] OUT
);
    // DUT is purely combinational with no clock/reset; assertions are sampled on external clk.

    // OUT[0] equals bit 0 of (A + B).
    check_out0_eq_sum0: assert property (
        @(posedge clk) OUT[0] == (A + B)[0]
    );

    // OUT[1] equals XOR of bits 0 and 1 of (A + B).
    check_out1_eq_xor_lsb: assert property (
        @(posedge clk) OUT[1] == ((A + B)[0] ^ (A + B)[1])
    );

    // OUT[2] equals OR of bits 0 and 1 of (A + B).
    check_out2_eq_or_lsb: assert property (
        @(posedge clk) OUT[2] == ((A + B)[0] | (A + B)[1])
    );

    // OUT[3] equals OR of bits 0 and 1 of (A + B).
    check_out3_eq_or_lsb: assert property (
        @(posedge clk) OUT[3] == ((A + B)[0] | (A + B)[1])
    );

    // OUT must be one of 0000, 1111, 1110, or 1101.
    check_output_value_domain: assert property (
        @(posedge clk) OUT inside {4'b0000, 4'b1111, 4'b1110, 4'b1101}
    );

    // If OUT[2] is 0 then all OUT bits are 0.
    check_out2_zero_implies_zero: assert property (
        @(posedge clk) (OUT[2] == 1'b0) |-> (OUT == 4'b0000)
    );

    // If OUT[0] is 1 then OUT[2] and OUT[3] are 1.
    check_out0_one_implies_msbs_one: assert property (
        @(posedge clk) OUT[0] |-> (OUT[2] && OUT[3])
    );

    // If OUT[1] is 1 then OUT[2] and OUT[3] are 1.
    check_out1_one_implies_msbs_one: assert property (
        @(posedge clk) OUT[1] |-> (OUT[2] && OUT[3])
    );

    // If A[1:0] and B[1:0] are stable, OUT remains stable.
    check_stable_on_low2bits_stable: assert property (
        @(posedge clk) $stable({A[1:0], B[1:0]}) |-> $stable(OUT)
    );

    // If all inputs are stable, OUT remains stable (combinational behavior).
    check_stable_on_inputs_stable: assert property (
        @(posedge clk) $stable({A, B}) |-> $stable(OUT)
    );

endmodule

