module d_ff_sr (clk, rst, set, d, q);
input clk, rst, set, d;
output reg q;

always @(posedge clk, negedge rst) begin
    if (!rst) begin
        q <= 1'b0;
    end else if (set) begin
        q <= 1'b1;
    end else begin
        q <= d;
    end
end

endmodule

sva_code:
module d_ff_sr_sva (
    input logic clk,
    input logic rst,   // active-low async reset
    input logic set,
    input logic d,
    input logic q
);

    ///// Reset behavior /////
    // When reset is asserted (low), q must be 0 at the sample.
    check_reset_forces_q0_now: assert property (
        @(posedge clk) !rst |-> (q == 1'b0)
    );

    // If reset was low on the previous cycle, q is 0 now.
    check_prev_reset_keeps_q0: assert property (
        @(posedge clk) $past(!rst) |-> (q == 1'b0)
    );

    ///// Functional behavior (gated off during reset) /////
    // With reset deasserted, set=1 drives q to 1 on the next clock.
    check_set_drives_one_next: assert property (
        @(posedge clk) disable iff (!rst) set |=> (!rst || (q == 1'b1))
    );

    // With reset deasserted and set=0, q captures d on the next clock.
    check_no_set_captures_d_next: assert property (
        @(posedge clk) disable iff (!rst) !set |=> (!rst || (q == $past(d)))
    );

    // Set has priority over data when d=0 (q still becomes 1 next).
    check_set_overrides_data_when_d0: assert property (
        @(posedge clk) disable iff (!rst) (set && (d == 1'b0)) |=> (!rst || (q == 1'b1))
    );

    // When set=0 and d=0, q becomes 0 on the next clock.
    check_no_set_d0_yields_q0: assert property (
        @(posedge clk) disable iff (!rst) (!set && (d == 1'b0)) |=> (!rst || (q == 1'b0))
    );

    // When set=0 and d=1, q becomes 1 on the next clock.
    check_no_set_d1_yields_q1: assert property (
        @(posedge clk) disable iff (!rst) (!set && (d == 1'b1)) |=> (!rst || (q == 1'b1))
    );

    // If set=0 and previous d equals previous q, q holds its value.
    check_hold_when_no_set_and_prev_d_eq_prev_q: assert property (
        @(posedge clk) disable iff (!rst) (!set && ($past(d) == $past(q))) |=> (!rst || (q == $past(q)))
    );

endmodule

verilog_code:
module vco_interface #(
  parameter n = 8 // number of bits used to represent the control voltage
)(
  input wire clk,
  input wire rst,
  input wire [n-1:0] vctrl,
  output reg vco_out
);

parameter fmin = 1000000; // minimum output frequency of VCO
parameter fmax = 2000000; // maximum output frequency of VCO

reg [31:0] count; // counter for VCO output waveform
reg [31:0] threshold; // threshold value for VCO output waveform

always @(*) begin
  threshold = ((fmax - fmin) * vctrl) / (2 ** n) + fmin;
end

always @(posedge clk) begin
  if (rst) begin
    count <= 0;
    vco_out <= 0;
  end else begin
    count <= count + 1;
    if (count >= threshold) begin
      count <= 0;
      vco_out <= ~vco_out;
    end
  end
end

endmodule

sva_code:
module vco_interface_sva #(
    parameter int n = 8,
    parameter int unsigned fmin = 1000000,
    parameter int unsigned fmax = 2000000
)(
    input  logic              clk,
    input  logic              rst,
    input  logic [n-1:0]      vctrl,
    input  logic              vco_out,
    input  logic [31:0]       count,
    input  logic [31:0]       threshold
);
    localparam int unsigned TWO_TO_N = (1 << n);

    // During reset, count and vco_out are driven to 0.
    reset_state_is_zero: assert property (
        @(posedge clk) rst |-> (count == 32'd0) && (vco_out == 1'b0)
    );

    // Count update: increment by 1 unless at/over threshold, then reset to 0.
    count_update_rule: assert property (
        @(posedge clk) disable iff (rst)
            count == (($past(count) >= $past(threshold)) ? 32'd0 : ($past(count) + 32'd1))
    );

    // vco_out toggles only when previous count reached/exceeded threshold.
    vco_toggle_only_when_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            (vco_out ^ $past(vco_out)) |-> ($past(count) >= $past(threshold))
    );

    // When previous count reached/exceeded threshold, vco_out must toggle.
    vco_toggle_on_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            ($past(count) >= $past(threshold)) |-> (vco_out ^ $past(vco_out))
    );

    // When previous count was below threshold, vco_out must hold its value.
    vco_stable_when_below_threshold: assert property (
        @(posedge clk) disable iff (rst)
            ($past(count) < $past(threshold)) |-> (vco_out == $past(vco_out))
    );

    // A vco_out toggle coincides with count being reset to 0.
    toggle_implies_count_zero: assert property (
        @(posedge clk) disable iff (rst)
            (vco_out ^ $past(vco_out)) |-> (count == 32'd0)
    );

    // If not coming out of reset, count==0 implies previous count hit/exceeded threshold.
    count_zero_implies_previous_threshold_reached: assert property (
        @(posedge clk) disable iff (rst)
            (!$past(rst) && (count == 32'd0)) |-> ($past(count) >= $past(threshold))
    );

    // Threshold computation matches the RTL formula.
    threshold_computation_equation: assert property (
        @(posedge clk) disable iff (rst)
            threshold == (((fmax - fmin) * vctrl) / TWO_TO_N) + fmin
    );

    // Threshold is never below fmin.
    threshold_min_bound_fmin: assert property (
        @(posedge clk) disable iff (rst)
            threshold >= fmin
    );

    // Threshold is never above fmax.
    threshold_max_bound_fmax: assert property (
        @(posedge clk) disable iff (rst)
            threshold <= fmax
    );

    // Threshold is non-decreasing when vctrl increases.
    threshold_non_decreasing_with_vctrl: assert property (
        @(posedge clk) disable iff (rst)
            ($past(vctrl) < vctrl) |-> (threshold >= $past(threshold))
    );

    // Threshold holds constant when vctrl is unchanged.
    threshold_stable_when_vctrl_constant: assert property (
        @(posedge clk) disable iff (rst)
            (vctrl == $past(vctrl)) |-> (threshold == $past(threshold))
    );

endmodule

