module dual_edge_ff (
    input clk,
    input d,
    output q
);

reg q1, q2;

always @(posedge clk) begin
    q1 <= d;
end

always @(negedge clk) begin
    q2 <= q1;
end

assign q = q2;

endmodule

sva_code:
module dual_edge_ff_sva (
    input logic clk,
    input logic d,
    input logic q
);
    // Clock: clk (both posedge and negedge used). Reset: none.
    // Logic: sequential across both edges; q updates on negedge to prior posedge d.

    // On each negedge, q equals d captured at the most recent posedge.
    check_q_eq_prev_posedge_d_at_negedge: assert property (
        @(negedge clk) q == $past(d, 1, posedge clk)
    );

    // On each posedge, q still equals d from the previous posedge.
    check_q_eq_prev_posedge_d_at_posedge: assert property (
        @(posedge clk) q == $past(d)
    );

    // If q changes at a negedge, then d must have changed at the preceding posedge vs. the one before it.
    check_q_change_at_negedge_implies_d_change: assert property (
        @(negedge clk) $changed(q) |-> ($past(d, 1, posedge clk) != $past(d, 2, posedge clk))
    );

    // If d changed at the current posedge vs. the prior posedge, q must change at this negedge.
    check_d_change_at_posedge_implies_q_change: assert property (
        @(negedge clk) ($past(d, 1, posedge clk) != $past(d, 2, posedge clk)) |-> (q != $past(q))
    );

    // If d did not change across the last two posedges, q must be stable across the last two negedges.
    check_q_stable_when_d_stable_across_posedges: assert property (
        @(negedge clk) ($past(d, 1, posedge clk) == $past(d, 2, posedge clk)) |-> (q == $past(q))
    );

    // At each posedge, q equals its value from the most recent negedge (no update occurs at posedge).
    check_q_const_through_posedge: assert property (
        @(posedge clk) q == $past(q, 1, negedge clk)
    );
endmodule

module mm_sva (
    input logic clk,
    input logic rst_n,
    input logic [31:0] addr,
    input logic [7:0] mod,
    input logic [31:0] eff_addr
);
    // mod must equal the decode function of addr
    check_mod_decode_function: assert property (
        @(posedge clk) disable iff (!rst_n)
        mod == (
            (addr[31:20] == 12'h000) ? 8'h00 :
            (addr[31:24] ==   8'h10) ? 8'h01 :
            (addr[31:20] == 12'hf00) ? 8'h02 :
            (addr[31:20] == 12'hf01) ? 8'h03 :
            (addr[31:20] == 12'hf02) ? 8'h04 :
            (addr[31:20] == 12'hf03) ? 8'h05 :
            (addr[31:20] == 12'hf04) ? 8'h06 :
            (addr[31:20] == 12'hf05) ? 8'h07 :
            (addr[31:20] == 12'hf06) ? 8'h08 :
            (addr[31:20] == 12'hf07) ? 8'h0a :
            (addr[31:20] == 12'hf08) ? 8'h0b :
            (addr[31:20] == 12'hf0a) ? 8'h09 :
                                       8'h00
        )
    );

    // mod takes only values produced by the decode
    check_mod_value_set: assert property (
        @(posedge clk) disable iff (!rst_n)
        mod inside {8'h00,8'h01,8'h02,8'h03,8'h04,8'h05,8'h06,8'h07,8'h08,8'h09,8'h0a,8'h0b}
    );

    // If addr[31:20]==0x000 then mod==0
    decode_000_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'h000) |-> (mod == 8'h00)
    );

    // If addr[31:24]==0x10 then mod==1
    decode_10_to_1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:24] == 8'h10) |-> (mod == 8'h01)
    );

    // If addr[31:20]==0xf00 then mod==2
    decode_f00_to_2: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf00) |-> (mod == 8'h02)
    );

    // If addr[31:20]==0xf06 then mod==8
    decode_f06_to_8: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf06) |-> (mod == 8'h08)
    );

    // If addr[31:20]==0xf07 then mod==10
    decode_f07_to_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf07) |-> (mod == 8'h0a)
    );

    // If addr[31:20]==0xf08 then mod==11
    decode_f08_to_11: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf08) |-> (mod == 8'h0b)
    );

    // If addr[31:20]==0xf0a then mod==9
    decode_f0a_to_9: assert property (
        @(posedge clk) disable iff (!rst_n)
        (addr[31:20] == 12'hf0a) |-> (mod == 8'h09)
    );

    // If no decode case matches, mod==0 (default)
    decode_default_to_0: assert property (
        @(posedge clk) disable iff (!rst_n)
        !(
            (addr[31:20] == 12'h000) ||
            (addr[31:24] == 8'h10)   ||
            (addr[31:20] inside {12'hf00,12'hf01,12'hf02,12'hf03,12'hf04,12'hf05,12'hf06,12'hf07,12'hf08,12'hf0a})
        ) |-> (mod == 8'h00)
    );

    // If mod==1 then addr[31:24]==0x10
    mod1_implies_10: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (addr[31:24] == 8'h10)
    );

    // If mod==10 then addr[31:20]==0xf07
    mod10_implies_f07: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0a) |-> (addr[31:20] == 12'hf07)
    );

    // If mod==11 then addr[31:20]==0xf08
    mod11_implies_f08: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h0b) |-> (addr[31:20] == 12'hf08)
    );

    // If mod==9 then addr[31:20]==0xf0a
    mod9_implies_f0a: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h09) |-> (addr[31:20] == 12'hf0a)
    );

    // eff_addr must equal the function of mod and addr
    check_eff_addr_function: assert property (
        @(posedge clk) disable iff (!rst_n)
        eff_addr == ((mod == 8'h01) ? {8'h00, addr[23:0]} : {12'h000, addr[19:0]})
    );

    // When mod==1, eff_addr upper 8 bits are zero and low 24 mirror addr
    eff_addr_when_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod == 8'h01) |-> (eff_addr[31:24] == 8'h00) && (eff_addr[23:0] == addr[23:0])
    );

    // When mod!=1, eff_addr upper 12 bits are zero and low 20 mirror addr
    eff_addr_when_not_mod1: assert property (
        @(posedge clk) disable iff (!rst_n)
        (mod != 8'h01) |-> (eff_addr[31:20] == 12'h000) && (eff_addr[19:0] == addr[19:0])
    );
endmodule

verilog_code:
module binary_counter (
  input clk,
  input reset,
  output reg [1:0] count
);

  reg [1:0] next_count;

  always @(posedge clk) begin
    if (reset) begin
      count <= 2'b00;
    end else begin
      count <= next_count;
    end
  end

  always @(*) begin
    case (count)
      2'b00: next_count = 2'b01;
      2'b01: next_count = 2'b10;
      2'b10: next_count = 2'b11;
      2'b11: next_count = 2'b00;
    endcase
  end

endmodule

sva_code:
module binary_counter_sva (
  input logic clk,
  input logic reset,
  input logic [1:0] count
);
  // Clock: clk (posedge). Reset: reset active-high synchronous.
  // Logic: mixed (sequential count, combinational next_count).
  // Behavior: modulo-4 up-counter 00->01->10->11->00.

  // On reset, count becomes 00 on the next cycle.
  reset_clears_count_next: assert property (
    @(posedge clk) reset |=> (count == 2'b00)
  );

  // If reset held for consecutive cycles, count is 00 in the current cycle.
  reset_held_keeps_zero: assert property (
    @(posedge clk) (reset && $past(reset)) |-> (count == 2'b00)
  );

  // On reset deassertion cycle, count is still 00 before increment.
  deassert_reset_current_zero: assert property (
    @(posedge clk) $fell(reset) |-> (count == 2'b00)
  );

  // One cycle after reset deasserts, count becomes 01.
  deassert_reset_next_one: assert property (
    @(posedge clk) $fell(reset) |=> (count == 2'b01)
  );

  // From 00, next count is 01 when not in reset.
  step_from_00_to_01: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b00) |=> (count == 2'b01)
  );

  // From 01, next count is 10 when not in reset.
  step_from_01_to_10: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b01) |=> (count == 2'b10)
  );

  // From 10, next count is 11 when not in reset.
  step_from_10_to_11: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b10) |=> (count == 2'b11)
  );

  // From 11, next count is 00 when not in reset.
  step_from_11_to_00: assert property (
    @(posedge clk) disable iff (reset) (count == 2'b11) |=> (count == 2'b00)
  );

  // Count changes every cycle when not in reset.
  count_changes_without_reset: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> (count != $past(count))
  );

  // After 4 cycles without reset, count returns to the same value.
  period_four_cycle: assert property (
    @(posedge clk) disable iff (reset) 1'b1 |=> ##4 (count == $past(count,4))
  );
endmodule

verilog_code:
module binary_full_adder_74283 (
  input [3:0] num1,
  input [3:0] num2,
  input carry_in,
  output [3:0] sum,
  output carry_out
);

  assign {carry_out, sum} = num1 + num2 + carry_in;

endmodule

sva_code:
module binary_full_adder_74283_sva (
    input logic clk,
    input logic [3:0] num1,
    input logic [3:0] num2,
    input logic carry_in,
    input logic [3:0] sum,
    input logic carry_out
);
    function automatic logic maj3 (input logic a, input logic b, input logic c);
        maj3 = (a & b) | (a & c) | (b & c);
    endfunction

    // Sum and carry concatenation equals 5-bit addition of operands.
    check_full_sum_concat: assert property (
        @(posedge clk) {carry_out, sum} == (num1 + num2 + carry_in)
    );

    // LSB sum bit is XOR of inputs and carry_in.
    check_sum_bit0_xor: assert property (
        @(posedge clk) sum[0] == (num1[0] ^ num2[0] ^ carry_in)
    );

    // Bit1 sum is XOR of inputs and carry from bit0.
    check_sum_bit1_xor: assert property (
        @(posedge clk) sum[1] == (num1[1] ^ num2[1] ^ maj3(num1[0], num2[0], carry_in))
    );

    // Bit2 sum is XOR of inputs and carry from bit1.
    check_sum_bit2_xor: assert property (
        @(posedge clk) sum[2] == (num1[2] ^ num2[2] ^ maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in)))
    );

    // Bit3 sum is XOR of inputs and carry from bit2.
    check_sum_bit3_xor: assert property (
        @(posedge clk) sum[3] == (num1[3] ^ num2[3] ^ maj3(num1[2], num2[2], maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in))))
    );

    // Final carry_out equals carry from bit3.
    check_carry_out_majority: assert property (
        @(posedge clk) carry_out == maj3(num1[3], num2[3], maj3(num1[2], num2[2], maj3(num1[1], num2[1], maj3(num1[0], num2[0], carry_in))))
    );

    // When no overflow occurs, carry_out must be 0.
    check_no_overflow_implies_carry0: assert property (
        @(posedge clk) ((num1 + num2 + carry_in) <= 5'd15) |-> (carry_out == 1'b0)
    );

    // When overflow occurs, carry_out must be 1.
    check_overflow_implies_carry1: assert property (
        @(posedge clk) ((num1 + num2 + carry_in) > 5'd15) |-> (carry_out == 1'b1)
    );

    // If num1==0 and carry_in==0, output equals num2 with no carry.
    check_passthrough_num2_when_num1_zero_cin0: assert property (
        @(posedge clk) ((num1 == 4'd0) && (carry_in == 1'b0)) |-> ((sum == num2) && (carry_out == 1'b0))
    );

    // If num2==0 and carry_in==0, output equals num1 with no carry.
    check_passthrough_num1_when_num2_zero_cin0: assert property (
        @(posedge clk) ((num2 == 4'd0) && (carry_in == 1'b0)) |-> ((sum == num1) && (carry_out == 1'b0))
    );

    // If num2==0 and carry_in==1, output equals num1+1 with carry on overflow.
    check_increment_when_cin1_num2_zero: assert property (
        @(posedge clk) ((num2 == 4'd0) && (carry_in == 1'b1)) |-> ((sum == (num1 + 5'd1)[3:0]) && (carry_out == (num1 == 4'hF)))
    );

    // Outputs remain stable when inputs do not change.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(num1) && $stable(num2) && $stable(carry_in)) |-> ($stable(sum) && $stable(carry_out))
    );
endmodule

verilog_code:
module mult_select (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;

    // Implement the logic for the mult_select module
    assign X = (A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N));

endmodule

sva_code:
module mult_select_sva (
    input logic CLK,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);
    // X equals its defined boolean function.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

    // When B1_N is LOW, X equals A2.
    check_b1n_low_gives_a2: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == A2)
    );

    // When B1_N is HIGH, X equals ~A1.
    check_b1n_high_gives_not_a1: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == (~A1))
    );

    // When A1 is LOW, X equals (A2 | B1_N).
    check_a1_low_gives_a2_or_b1n: assert property (
        @(posedge CLK) (A1 == 1'b0) |-> (X == (A2 | B1_N))
    );

    // When A1 is HIGH, X equals (A2 & ~B1_N).
    check_a1_high_gives_a2_and_not_b1n: assert property (
        @(posedge CLK) (A1 == 1'b1) |-> (X == (A2 & ~B1_N))
    );

    // When A2 is LOW, X equals (~A1 & B1_N).
    check_a2_low_gives_not_a1_and_b1n: assert property (
        @(posedge CLK) (A2 == 1'b0) |-> (X == ((~A1) & B1_N))
    );

    // When A2 is HIGH, X equals (~A1 | ~B1_N).
    check_a2_high_gives_not_a1_or_not_b1n: assert property (
        @(posedge CLK) (A2 == 1'b1) |-> (X == ((~A1) | (~B1_N)))
    );

    // Corner: A1=0, A2=0, B1_N=0 => X=0.
    check_corner_all_zeroes: assert property (
        @(posedge CLK) (A1==1'b0 && A2==1'b0 && B1_N==1'b0) |-> (X==1'b0)
    );

    // Corner: A1=1, A2=1, B1_N=0 => X=1.
    check_corner_a1a2_high_b1n_low: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b0) |-> (X==1'b1)
    );

    // Corner: A1=1, A2=1, B1_N=1 => X=0.
    check_corner_a1a2_high_b1n_high: assert property (
        @(posedge CLK) (A1==1'b1 && A2==1'b1 && B1_N==1'b1) |-> (X==1'b0)
    );

    // If inputs are stable across a cycle, X is stable.
    check_stable_inputs_imply_stable_output: assert property (
        @(posedge CLK) $stable({A1, A2, B1_N}) |-> $stable(X)
    );

    // If X changes across a cycle, at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) !$stable(X) |-> !$stable({A1, A2, B1_N})
    );
endmodule

