module sum_4bit(input [3:0] input_a, output reg [4:0] output_sum);

always @(*) begin
    output_sum = {1'b0, input_a} + 4'b0001;
end

endmodule

sva_code:
module sum_4bit_sva (
    input logic clk,
    input logic [3:0] input_a,
    input logic [4:0] output_sum
);
    // Output is zero-extended input_a plus 1.
    check_sum_functional: assert property (
        @(posedge clk) output_sum == ({1'b0, input_a} + 5'd1)
    );

    // Lower 4 bits equal input_a + 1 modulo 16.
    check_lower_nibble_increment: assert property (
        @(posedge clk) output_sum[3:0] == (input_a + 4'd1)
    );

    // Carry-out equals reduction AND of input_a (overflow on 0xF).
    check_carry_out_condition: assert property (
        @(posedge clk) output_sum[4] == (&input_a)
    );

    // LSB toggles on +1 increment.
    check_bit0_toggle: assert property (
        @(posedge clk) output_sum[0] == ~input_a[0]
    );

    // Bit1 equals a1 XOR a0 for +1 increment.
    check_bit1_logic: assert property (
        @(posedge clk) output_sum[1] == (input_a[1] ^ input_a[0])
    );

    // Bit2 equals a2 XOR (a1 & a0) for +1 increment.
    check_bit2_logic: assert property (
        @(posedge clk) output_sum[2] == (input_a[2] ^ (input_a[1] & input_a[0]))
    );

    // Bit3 equals a3 XOR (a2 & a1 & a0) for +1 increment.
    check_bit3_logic: assert property (
        @(posedge clk) output_sum[3] == (input_a[3] ^ (input_a[2] & input_a[1] & input_a[0]))
    );

    // When input is 0xF, sum is 0x10.
    check_overflow_case: assert property (
        @(posedge clk) (input_a == 4'hF) |-> (output_sum == 5'h10)
    );

    // When input is 0x0, sum is 0x01.
    check_zero_input_case: assert property (
        @(posedge clk) (input_a == 4'h0) |-> (output_sum == 5'h01)
    );

    // If input_a is unchanged across cycles, output_sum is unchanged.
    check_functional_stability: assert property (
        @(posedge clk) (input_a == $past(input_a)) |-> (output_sum == $past(output_sum))
    );
endmodule

verilog_code:
module mux2to1(
   input         in0, in1, sel,
   output        out);

   assign out = sel ? in1 : in0;

endmodule

sva_code:
module mux2to1_sva (
    input logic CLK,
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);
    // Out equals selected input per mux function.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

    // When sel=0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

    // When sel=1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

    // If in0,in1,sel are unchanged across cycles, out is unchanged.
    check_out_stable_if_inputs_stable: assert property (
        @(posedge CLK) (!$changed(in0) && !$changed(in1) && !$changed(sel)) |-> !$changed(out)
    );

    // With sel stable 0, out changes only if in0 changes.
    check_out_change_requires_in0_when_sel0: assert property (
        @(posedge CLK) (sel == 1'b0 && $past(sel) == 1'b0 && $changed(out)) |-> $changed(in0)
    );

    // With sel stable 1, out changes only if in1 changes.
    check_out_change_requires_in1_when_sel1: assert property (
        @(posedge CLK) (sel == 1'b1 && $past(sel) == 1'b1 && $changed(out)) |-> $changed(in1)
    );

    // With sel stable 0 and in0 unchanged, out is unchanged.
    check_out_stable_sel0_if_in0_stable: assert property (
        @(posedge CLK) (sel == 1'b0 && $past(sel) == 1'b0 && !$changed(in0)) |-> !$changed(out)
    );

    // With sel stable 1 and in1 unchanged, out is unchanged.
    check_out_stable_sel1_if_in1_stable: assert property (
        @(posedge CLK) (sel == 1'b1 && $past(sel) == 1'b1 && !$changed(in1)) |-> !$changed(out)
    );
endmodule

module decoder_4to16_sva (
    input logic [1:0] sel,
    input logic [15:0] out
);
    // Output equals 1'h1 shifted by sel (core decode relation).
    check_decode_equivalence: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out == (16'b0000000000000001 << sel)
    );

    // Output is always one of the four valid patterns.
    check_out_valid_set: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out inside {16'h0001,16'h0002,16'h0004,16'h0008}
    );

    // Upper bits [15:4] are always zero.
    check_upper_bits_zero: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out[15:4] == 12'b0
    );

    // Exactly one output bit is HIGH at a time.
    check_onehot_out: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        $onehot(out)
    );

    // sel==2'b00 maps to out==16'h0001.
    check_map_00_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b00) |=> (out == 16'h0001)
    );

    // sel==2'b01 maps to out==16'h0002.
    check_map_01_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b01) |=> (out == 16'h0002)
    );

    // sel==2'b10 maps to out==16'h0004.
    check_map_10_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b10) |=> (out == 16'h0004)
    );

    // sel==2'b11 maps to out==16'h0008.
    check_map_11_forward: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (sel == 2'b11) |=> (out == 16'h0008)
    );

    // Reverse: out==16'h0001 implies sel==2'b00.
    check_map_0001_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0001) |=> (sel == 2'b00)
    );

    // Reverse: out==16'h0002 implies sel==2'b01.
    check_map_0002_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0002) |=> (sel == 2'b01)
    );

    // Reverse: out==16'h0004 implies sel==2'b10.
    check_map_0004_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0004) |=> (sel == 2'b10)
    );

    // Reverse: out==16'h0008 implies sel==2'b11.
    check_map_0008_reverse: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        (out == 16'h0008) |=> (sel == 2'b11)
    );

    // Out is never all zeros (default branch unreachable for 2-bit sel).
    check_out_nonzero: assert property (
        @(posedge sel[0] or negedge sel[0] or posedge sel[1] or negedge sel[1])
        out != 16'h0000
    );
endmodule

verilog_code:
module mi_nios_cpu_nios2_oci_td_mode (
  // inputs:
  ctrl,

  // outputs:
  td_mode
);

  output [3:0] td_mode;
  input [8:0] ctrl;

  wire [2:0] ctrl_bits_for_mux;
  reg [3:0] td_mode;
  assign ctrl_bits_for_mux = ctrl[7:5];

  always @(*) begin
    case (ctrl_bits_for_mux)
      3'b000: td_mode = 4'b0000;
      3'b001: td_mode = 4'b1000;
      3'b010: td_mode = 4'b0100;
      3'b011: td_mode = 4'b1100;
      3'b100: td_mode = 4'b0010;
      3'b101: td_mode = 4'b1010;
      3'b110: td_mode = 4'b0101;
      3'b111: td_mode = 4'b1111;
      default: td_mode = 4'b0000;
    endcase
  end

endmodule

sva_code:
