    map_sel_010: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b010) |-> (td_mode == 4'b0100)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b011
    map_sel_011: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b011) |-> (td_mode == 4'b1100)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b100
    map_sel_100: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b100) |-> (td_mode == 4'b0010)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b101
    map_sel_101: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b101) |-> (td_mode == 4'b1010)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b110
    map_sel_110: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b110) |-> (td_mode == 4'b0101)
    );

    // td_mode mapping when ctrl_bits_for_mux == 3'b111
    map_sel_111: assert property (
        @(posedge clk) (ctrl_bits_for_mux == 3'b111) |-> (td_mode == 4'b1111)
    );

    // td_mode always matches the combinational decode of ctrl[7:5]
    decode_consistency: assert property (
        @(posedge clk)
            td_mode ==
            ((ctrl_bits_for_mux == 3'b000) ? 4'b0000 :
             (ctrl_bits_for_mux == 3'b001) ? 4'b1000 :
             (ctrl_bits_for_mux == 3'b010) ? 4'b0100 :
             (ctrl_bits_for_mux == 3'b011) ? 4'b1100 :
             (ctrl_bits_for_mux == 3'b100) ? 4'b0010 :
             (ctrl_bits_for_mux == 3'b101) ? 4'b1010 :
             (ctrl_bits_for_mux == 3'b110) ? 4'b0101 :
                                             4'b1111)
    );

    // td_mode can only be one of the enumerated decode values
    td_mode_range_check: assert property (
        @(posedge clk) td_mode inside {
            4'b0000, 4'b1000, 4'b0100, 4'b1100,
            4'b0010, 4'b1010, 4'b0101, 4'b1111
        }
    );
endmodule

verilog_code:
module top_module( 
    input [2:0] a,
    input [2:0] b,
    output [2:0] out_and_bitwise,
    output out_and_logical,
    output [2:0] out_xor,
    output [5:0] out_not
);

    // Inverse of input a
    wire [2:0] a_inv = ~a;

    // Inverse of input b
    wire [2:0] b_inv = ~b;

    // Bitwise AND
    assign out_and_bitwise = a & b;

    // Logical AND
    assign out_and_logical = (a != 0) && (b != 0);

    // Bitwise XOR
    assign out_xor = a ^ b;

    // MUX to select between input and its inverse
    assign out_not[5:3] = a_inv;
    assign out_not[2:0] = b_inv;

endmodule

sva_code:
module top_module_sva (
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [2:0] out_and_bitwise,
    input logic       out_and_logical,
    input logic [2:0] out_xor,
    input logic [5:0] out_not
);
    // No clock/reset in RTL; use posedge of $global_clock for sampling.

    // Bitwise AND output matches a & b.
    check_bitwise_and_def: assert property (
        @(posedge $global_clock) out_and_bitwise == (a & b)
    );

    // Logical AND output is 1 only when both a and b are non-zero.
    check_logical_and_def: assert property (
        @(posedge $global_clock) out_and_logical == ((a != 3'b000) && (b != 3'b000))
    );

    // XOR output matches a ^ b.
    check_xor_def: assert property (
        @(posedge $global_clock) out_xor == (a ^ b)
    );

    // Upper out_not bits are bitwise NOT of a.
    check_out_not_upper_def: assert property (
        @(posedge $global_clock) out_not[5:3] == ~a
    );

    // Lower out_not bits are bitwise NOT of b.
    check_out_not_lower_def: assert property (
        @(posedge $global_clock) out_not[2:0] == ~b
    );

    // When a equals b, XOR output is zero.
    check_xor_zero_when_equal: assert property (
        @(posedge $global_clock) (a == b) |-> (out_xor == 3'b000)
    );

    // If a is zero, bitwise AND output is zero.
    check_and_zero_if_a_zero: assert property (
        @(posedge $global_clock) (a == 3'b000) |-> (out_and_bitwise == 3'b000)
    );

    // If b is zero, bitwise AND output is zero.
    check_and_zero_if_b_zero: assert property (
        @(posedge $global_clock) (b == 3'b000) |-> (out_and_bitwise == 3'b000)
    );

    // If either input is zero, logical AND output is zero.
    check_logical_and_zero_if_any_zero: assert property (
        @(posedge $global_clock) ((a == 3'b000) || (b == 3'b000)) |-> (out_and_logical == 1'b0)
    );

    // If both inputs are non-zero, logical AND output is one.
    check_logical_and_one_if_both_nonzero: assert property (
        @(posedge $global_clock) ((a != 3'b000) && (b != 3'b000)) |-> (out_and_logical == 1'b1)
    );

endmodule

