    );

    // VGND high forces X low.
    check_x_low_when_VGND_high: assert property (
        @(posedge VGND) X == 1'b0
    );

    // VPB high forces X low.
    check_x_low_when_VPB_high: assert property (
        @(posedge VPB) X == 1'b0
    );

    // VNB high forces X low.
    check_x_low_when_VNB_high: assert property (
        @(posedge VNB) X == 1'b0
