module top_module (
   input clk,
   input reset,      // Synchronous active-high reset
   input [7:0] d1,   // 8-bit input for adder 1
   input [7:0] d2,   // 8-bit input for adder 2
   input select,      // Select input to choose between adder 1 and adder 2
   output reg [7:0] q    // 8-bit output from the functional module
);

reg [7:0] q1, q2;
reg cin1, cin2;
wire [7:0] sum1, sum2;
wire cout1, cout2;

adder adder1(
   .a(d1),
   .b(q1),
   .cin(cin1),
   .sum(sum1),
   .cout(cout1)
);

adder adder2(
   .a(d2),
   .b(q2),
   .cin(cin2),
   .sum(sum2),
   .cout(cout2)
);

always @(posedge clk) begin
   if (reset) begin
      q <= 0;
   end else begin
      if (select) begin
         q <= sum1;
      end else begin
         q <= sum2;
      end
   end
end

always @(posedge clk) begin
   if (reset) begin
      q1 <= 0;
      q2 <= 0;
      cin1 <= 0;
      cin2 <= 0;
   end else begin
      if (select) begin
         q1 <= d1;
         cin1 <= 1'b0;
         q2 <= sum1;
         cin2 <= cout1;
      end else begin
         q2 <= d2;
         cin2 <= 1'b0;
         q1 <= sum2;
         cin1 <= cout2;
      end
   end
end

endmodule

module adder (
   input [7:0] a,
   input [7:0] b,
   input cin,
   output [7:0] sum,
   output cout
);
   assign {cout, sum} = a + b + cin;
endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic reset,        // Synchronous active-high reset
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic select,
    input logic [7:0] q
);
    // 9-bit adder helper (matches adder module behavior)
    function automatic logic [8:0] f_add9(input logic [7:0] a, input logic [7:0] b, input logic c);
        f_add9 = {1'b0, a} + {1'b0, b} + {8'b0, c};
    endfunction

    // Reference model for internal state behavior
    logic [7:0] m_q1, m_q2;
    logic m_cin1, m_cin2;

    always_ff @(posedge clk) begin
        if (reset) begin
            m_q1  <= '0;
            m_q2  <= '0;
            m_cin1 <= 1'b0;
            m_cin2 <= 1'b0;
        end else begin
            if (select) begin
                m_q1  <= d1;
                m_cin1 <= 1'b0;
                m_q2  <= f_add9(d1, m_q1, m_cin1)[7:0];
                m_cin2 <= f_add9(d1, m_q1, m_cin1)[8];
            end else begin
                m_q2  <= d2;
                m_cin2 <= 1'b0;
                m_q1  <= f_add9(d2, m_q2, m_cin2)[7:0];
                m_cin1 <= f_add9(d2, m_q2, m_cin2)[8];
            end
        end
    end

    ///// Assertions /////
    // Q must be 0 during synchronous active-high reset.
    check_q_zero_during_reset: assert property (
        @(posedge clk) reset |-> (q == 8'h00)
    );

    // When select=1, q equals d1 + m_q1 + m_cin1 (low 8 bits).
    check_q_model_sel1: assert property (
        @(posedge clk) disable iff (reset) select |-> (q == f_add9(d1, m_q1, m_cin1)[7:0])
    );

    // When select=0, q equals d2 + m_q2 + m_cin2 (low 8 bits).
    check_q_model_sel0: assert property (
        @(posedge clk) disable iff (reset) !select |-> (q == f_add9(d2, m_q2, m_cin2)[7:0])
    );

    // First cycle after reset deasserts, q equals selected input (internal state zeros).
    check_q_after_reset_release: assert property (
        @(posedge clk) disable iff (reset) $fell(reset) |-> (q == (select ? d1 : d2))
    );

    // With select=1 for two cycles, q equals d1 + $past(d1) (no carry-in).
    check_two_cycle_sel1_addition: assert property (
        @(posedge clk) disable iff (reset)
            (select && $past(select) && !$past(reset)) |-> (q == f_add9(d1, $past(d1), 1'b0)[7:0])
    );

    // With select=0 for two cycles, q equals d2 + $past(d2) (no carry-in).
    check_two_cycle_sel0_addition: assert property (
        @(posedge clk) disable iff (reset)
            (!select && !$past(select) && !$past(reset)) |-> (q == f_add9(d2, $past(d2), 1'b0)[7:0])
    );
endmodule

module d_flip_flop_async_reset_sva (
    input logic CLK,
    input logic RESET_B, // active-low async reset
    input logic D,
    input logic Q
);

    ///// Reset behavior /////
    // While reset is asserted low, Q must be 0.
    check_reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

    // When reset falls (1->0), Q is 0 at this sample.
    check_reset_fall_clears_q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

    // If reset is low in consecutive cycles, Q remains 0 across them.
    check_reset_hold_zero: assert property (
        @(posedge CLK) (!$past(RESET_B) && !RESET_B) |-> ($past(Q) == 1'b0 && Q == 1'b0)
    );

    ///// Normal capture behavior /////
    // With reset high now and previously, Q equals previous D.
    check_capture_prev_d_when_reset_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) $past(RESET_B) |-> (Q == $past(D))
    );

    // After reset deasserts (prev low, now high), next cycle Q equals D from deassert cycle.
    check_capture_after_reset_release: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!$past(RESET_B) && RESET_B) |=> (Q == $past(D))
    );

    // If reset high for last two cycles and D did not change, Q does not change.
    check_q_stable_if_prev_two_d_equal: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && ($past(D) == $past(D,2))) |-> (Q == $past(Q))
    );

    // If reset high for last two cycles and D changed, Q must change.
    check_q_changes_if_prev_two_d_differ: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && ($past(D) != $past(D,2))) |-> (Q != $past(Q))
    );

    // If reset high for last two cycles and Q changed, D must have changed in prior cycle.
    check_q_change_implies_prev_d_change: assert property (
        @(posedge CLK) disable iff (!RESET_B)
            ($past(RESET_B) && $past(RESET_B,2) && (Q != $past(Q))) |-> ($past(D) != $past(D,2))
    );

endmodule

