module mdio_1to2_sva (
    input logic mdio_mdc,
    input logic mdio_o,
    input logic mdio_t,
    input logic mdio_i,

    input logic phy0_mdc,
    input logic phy0_mdio_o,
    input logic phy0_mdio_t,
    input logic phy0_mdio_i,

    input logic phy1_mdc,
    input logic phy1_mdio_o,
    input logic phy1_mdio_t,
    input logic phy1_mdio_i
);
    // Clock: mdio_mdc; Reset: none. Logic: combinational pass-through and AND on mdio_i.

    // phy0_mdc mirrors mdio_mdc.
    check_phy0_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdc == mdio_mdc)
    );

    // phy1_mdc mirrors mdio_mdc.
    check_phy1_mdc_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdc == mdio_mdc)
    );

    // phy0_mdio_t mirrors mdio_t.
    check_phy0_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == mdio_t)
    );

    // phy1_mdio_t mirrors mdio_t.
    check_phy1_t_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_t == mdio_t)
    );

    // phy0_mdio_o mirrors mdio_o.
    check_phy0_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == mdio_o)
    );

    // phy1_mdio_o mirrors mdio_o.
    check_phy1_o_pass_through: assert property (
        @(posedge mdio_mdc) (phy1_mdio_o == mdio_o)
    );

    // mdio_i is the AND of phy0_mdio_i and phy1_mdio_i.
    check_mdio_i_and: assert property (
        @(posedge mdio_mdc) (mdio_i == (phy0_mdio_i & phy1_mdio_i))
    );

    // The two PHY MDC outputs are identical.
    check_mdc_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdc == phy1_mdc)
    );

    // The two PHY MDIO_t outputs are identical.
    check_t_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_t == phy1_mdio_t)
    );

    // The two PHY MDIO_o outputs are identical.
    check_o_consistency_between_phys: assert property (
        @(posedge mdio_mdc) (phy0_mdio_o == phy1_mdio_o)
    );

    // If either PHY MDIO input is 0, mdio_i must be 0.
    check_mdio_i_zero_if_any_zero: assert property (
        @(posedge mdio_mdc) ((!phy0_mdio_i) || (!phy1_mdio_i)) |-> (mdio_i == 1'b0)
    );

    // If both PHY MDIO inputs are 1, mdio_i must be 1.
    check_mdio_i_one_if_both_one: assert property (
        @(posedge mdio_mdc) (phy0_mdio_i && phy1_mdio_i) |-> (mdio_i == 1'b1)
    );
endmodule

verilog_code:
module top_module (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] q
);

    wire greater_than;
    wire equal;
    wire enable;
    wire [3:0] count;
    wire [7:0] sum;

    // Instantiate the 8-bit comparator module
    comparator_module comparator_inst(
        .a(a),
        .b(b),
        .greater_than(greater_than)
    );

    // Instantiate the 4-bit binary counter module
    counter_module counter_inst(
        .clk(clk),
        .reset(reset),
        .enable(enable),
        .count(count)
    );

    // Instantiate the control logic module
    control_logic_module control_inst(
        .a(a),
        .b(b),
        .greater_than(greater_than),
        .equal(equal),
        .enable(enable)
    );

    // Instantiate the additional functional module
    functional_module functional_inst(
        .a(a[0]),
        .b(count),
        .sum(sum)
    );

    // Output the appropriate value based on the control logic
    always @(posedge clk) begin
        if (reset) begin
            q <= 0;
        end else if (greater_than) begin
            q <= count;
        end else if (equal) begin
            q <= sum;
        end else begin
            q <= a;
        end
    end

endmodule
module comparator_module (
    input [7:0] a,
    input [7:0] b,
    output reg greater_than
);

    always @(*) begin
        if (a > b) begin
            greater_than = 1;
        end else begin
            greater_than = 0;
        end
    end

endmodule
module counter_module (
    input clk,
    input reset,
    input enable,
    output reg [3:0] count
);

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
        end else if (enable) begin
            count <= count + 1;
        end
    end

endmodule
module control_logic_module (
    input [7:0] a,
    input [7:0] b,
    input greater_than,
    output reg equal,
    output reg enable
);

    always @(*) begin
        if (a > b) begin
            equal = 0;
            enable = 1;
        end else if (a < b) begin
            equal = 0;
            enable = 0;
        end else begin
            equal = 1;
            enable = 1;
        end
    end

endmodule
module functional_module (
    input a,
    input [3:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = {7'b0, a} + b;
    end

endmodule

sva_code:
module top_module_sva (
    input  logic        clk,
    input  logic        reset,   // active-high synchronous
    input  logic [7:0]  a,
    input  logic [7:0]  b,
    input  logic [7:0]  q
);

    ///// Reset behavior /////
    // When reset is asserted, q must be 0.
    reset_q_zero: assert property (
        @(posedge clk) reset |-> (q == 8'h00)
    );

    ///// Output selection rules /////
    // If a<b, q must equal a.
    q_matches_a_when_a_lt_b: assert property (
        @(posedge clk) disable iff (reset) (a < b) |-> (q == a)
    );

    // If a<b, q is strictly less than b.
    q_lt_b_when_a_lt_b: assert property (
        @(posedge clk) disable iff (reset) (a < b) |-> (q < b)
    );

    // If a>b, q comes from 4-bit counter, so upper nibble is zero.
    q_upper_nibble_zero_when_a_gt_b: assert property (
        @(posedge clk) disable iff (reset) (a > b) |-> (q[7:4] == 4'b0000)
    );

    // If a>=b, q is from counter or sum, so q <= 16.
    q_bounded_when_a_ge_b: assert property (
        @(posedge clk) disable iff (reset) (a >= b) |-> (q <= 8'h10)
    );

    // If a==b, q equals count + a[0], so q >= a[0].
    q_min_bound_when_equal: assert property (
        @(posedge clk) disable iff (reset) (a == b) |-> (q >= {7'b0, a[0]})
    );

    // If a==b and a[0]==0, q equals count (0..15).
    q_max_15_when_equal_a0_zero: assert property (
        @(posedge clk) disable iff (reset) (a == b) && (a[0] == 1'b0) |-> (q <= 8'h0F)
    );

    ///// Cross-cycle behaviors /////
    // If a>b in two consecutive cycles, q's low nibble increments by 1 (mod 16) and upper nibble stays zero.
    gt_consecutive_incr_low_nibble: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) > $past(b)) && (a > b))
            |-> ($past(q[7:4]) == 4'b0000) && (q[7:4] == 4'b0000) && (q[3:0] == $past(q[3:0]) + 4'd1)
    );

    // If a==b in two consecutive cycles and a[0] is stable, q's low nibble increments by 1 (mod 16).
    eq_consecutive_incr_low_nibble_a0_stable: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(a) == $past(b)) && (a == b) && ($past(a[0]) == a[0]))
            |-> (q[3:0] == $past(q[3:0]) + 4'd1)
    );

    ///// Range disambiguation /////
    // If a>=b and q>15, it must be the equal-path producing exactly 16.
    high_value_only_on_equal_16: assert property (
        @(posedge clk) disable iff (reset)
            ((a >= b) && (q > 8'h0F)) |-> ((a == b) && (q == 8'h10))
    );

endmodule

