    check_or_function: assert property (
        @(posedge CLK) X == (A | B)
    );

    // When both inputs are 0, output must be 0.
    check_zero_zero_low: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0) |-> (X == 1'b0)
    );

    // If output is 1, at least one input must be 1.
    check_x_high_requires_input_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((A == 1'b1) || (B == 1'b1))
    );

    // If A is 1, output must be 1.
    check_a_high_implies_x_high: assert property (
        @(posedge CLK) (A == 1'b1) |-> (X == 1'b1)
    );

    // If B is 1, output must be 1.
    check_b_high_implies_x_high: assert property (
        @(posedge CLK) (B == 1'b1) |-> (X == 1'b1)
    );

    // When B is 0, output follows A.
    check_follow_a_when_b_zero: assert property (
        @(posedge CLK) (B == 1'b0) |-> (X == A)
    );

    // When A is 0, output follows B.
    check_follow_b_when_a_zero: assert property (
        @(posedge CLK) (A == 1'b0) |-> (X == B)
    );

    // If inputs are stable, output remains stable.
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge CLK) $stable(A) && $stable(B) |-> $stable(X)
    );

    // Output change implies at least one input changed.
    check_output_change_implies_input_change: assert property (
        @(posedge CLK) $changed(X) |-> ($changed(A) || $changed(B))
    );
endmodule

verilog_code:
module binary_counter(
    input clk, reset, enable, load,
    input [3:0] in,
    output [3:0] out,
    output overflow
);

reg [3:0] counter;
reg [3:0] next_val;

assign overflow = (counter == 4'b1111);

always @(posedge clk) begin
    if (reset) begin
        counter <= 4'b0000;
    end else begin
        if (load) begin
            counter <= in;
        end else if (enable) begin
            counter <= counter + 4'b0001;
        end
    end
end

assign out = counter;

endmodule

sva_code:
module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic load,
    input logic [3:0] in,
    input logic [3:0] out,
    input logic overflow
);
    // overflow reflects out == 4'hF.
    check_overflow_definition: assert property (
        @(posedge clk) disable iff (reset) overflow == (out == 4'hF)
    );

    // After a reset cycle, out is 0 on the next cycle.
    check_sync_reset_clears_out: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (out == 4'h0)
    );

    // Load updates out with in on the next cycle.
    check_load_updates_out: assert property (
        @(posedge clk) disable iff (reset) ($past(load) && !$past(reset)) |-> (out == $past(in))
    );

    // Enable increments out by 1 when not wrapping (no load).
    check_enable_increments_no_wrap: assert property (
        @(posedge clk) disable iff (reset)
            ($past(enable) && !$past(load) && !$past(reset) && ($past(out) != 4'hF))
            |-> (out == ($past(out) + 4'd1))
    );

    // Enable wraps from 4'hF to 4'h0 (no load).
    check_enable_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
            ($past(enable) && !$past(load) && !$past(reset) && ($past(out) == 4'hF))
            |-> (out == 4'h0)
    );

    // Hold value when neither load nor enable are asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && !$past(load) && !$past(enable))
            |-> (out == $past(out))
    );

    // Load has priority over enable when both are asserted.
    check_load_has_priority_over_enable: assert property (
        @(posedge clk) disable iff (reset)
            ($past(load) && $past(enable) && !$past(reset))
            |-> (out == $past(in))
    );

    // Any change in out must be caused by reset, load, or enable in the previous cycle.
    check_change_has_known_cause: assert property (
        @(posedge clk) disable iff (reset)
            (out != $past(out)) |-> ($past(reset) || $past(load) || $past(enable))
    );

    // Overflow can only rise when out reaches 4'hF.
    check_overflow_rise_on_out_max: assert property (
        @(posedge clk) disable iff (reset)
            $rose(overflow) |-> (out == 4'hF) && ($past(out) != 4'hF)
    );

    // Overflow can only fall when leaving 4'hF.
    check_overflow_fall_on_out_below_max: assert property (
        @(posedge clk) disable iff (reset)
            $fell(overflow) |-> ($past(out) == 4'hF) && (out != 4'hF)
    );
endmodule

module mux_4to1_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);
    // Y must equal the coded 4:1 mux equation.
    check_mux_equation: assert property (
        @(posedge CLK) Y == ((~S1 & ~S0 & A) | (~S1 & S0 & B) | (S1 & ~S0 & C) | (S1 & S0 & D))
    );

    // When S1S0==00, Y equals A.
    check_sel_00_maps_to_A: assert property (
        @(posedge CLK) (!S1 && !S0) |-> (Y == A)
    );

    // When S1S0==01, Y equals B.
    check_sel_01_maps_to_B: assert property (
        @(posedge CLK) (!S1 && S0) |-> (Y == B)
    );

    // When S1S0==10, Y equals C.
    check_sel_10_maps_to_C: assert property (
        @(posedge CLK) (S1 && !S0) |-> (Y == C)
    );

    // When S1S0==11, Y equals D.
    check_sel_11_maps_to_D: assert property (
        @(posedge CLK) (S1 && S0) |-> (Y == D)
    );

    // If A changes while selected and selects are stable, Y changes accordingly.
    check_A_change_reflects_Y: assert property (
        @(posedge CLK) ($stable(S1) && $stable(S0) && !S1 && !S0 && $changed(A)) |-> $changed(Y)
    );

    // If B changes while selected and selects are stable, Y changes accordingly.
    check_B_change_reflects_Y: assert property (
        @(posedge CLK) ($stable(S1) && $stable(S0) && !S1 && S0 && $changed(B)) |-> $changed(Y)
    );

    // If C changes while selected and selects are stable, Y changes accordingly.
    check_C_change_reflects_Y: assert property (
        @(posedge CLK) ($stable(S1) && $stable(S0) && S1 && !S0 && $changed(C)) |-> $changed(Y)
    );

    // If D changes while selected and selects are stable, Y changes accordingly.
    check_D_change_reflects_Y: assert property (
        @(posedge CLK) ($stable(S1) && $stable(S0) && S1 && S0 && $changed(D)) |-> $changed(Y)
    );
endmodule

