module halves_sum_sva (
    input logic [31:0] in,
    input logic [15:0] out
);
    // No clock or reset in RTL; pure combinational: out = (in[31:16] + in[15:0]) truncated to 16 bits.

    always_comb begin
        // out equals the 16-bit sum of upper and lower halves (truncated).
        check_out_eq_halves_sum: assert (out == (in[31:16] + in[15:0]));
        // If upper half is zero, out equals lower half.
        check_upper_zero_passthrough: assert ((in[31:16] != 16'h0000) || (out == in[15:0]));
        // If lower half is zero, out equals upper half.
        check_lower_zero_passthrough: assert ((in[15:0] != 16'h0000) || (out == in[31:16]));
        // When both halves are 0xFFFF, sum truncates to 0xFFFE.
        check_overflow_fffe: assert (!((in[31:16] == 16'hFFFF) && (in[15:0] == 16'hFFFF)) || (out == 16'hFFFE));
        // When upper is 0x0001 and lower is 0xFFFF, sum wraps to 0x0000.
        check_wrap_zero_example: assert (!((in[31:16] == 16'h0001) && (in[15:0] == 16'hFFFF)) || (out == 16'h0000));
    end
endmodule

verilog_code:
module top_module( 
    input wire [31:0] in,
    output wire [31:0] out_xor,
    output wire [31:0] out_and );

    wire [15:0] lower_half;
    wire [15:0] upper_half;
    wire [15:0] xor_half;
    wire [15:0] and_half;

    // Pipeline stage 1
    pipeline_stage_1 stage_1(
        .in(in),
        .lower_half(lower_half),
        .upper_half(upper_half)
    );

    // Pipeline stage 2
    pipeline_stage_2 stage_2(
        .lower_half(lower_half),
        .upper_half(upper_half),
        .xor_half(xor_half),
        .and_half(and_half)
    );

    // Pipeline stage 3
    pipeline_stage_3 stage_3(
        .xor_half(xor_half),
        .and_half(and_half),
        .out_xor(out_xor),
        .out_and(out_and)
    );

endmodule

// Pipeline stage 1
module pipeline_stage_1(
    input wire [31:0] in,
    output wire [15:0] lower_half,
    output wire [15:0] upper_half
);

    assign lower_half = in[15:0];
    assign upper_half = in[31:16];

endmodule

// Pipeline stage 2
module pipeline_stage_2(
    input wire [15:0] lower_half,
    input wire [15:0] upper_half,
    output wire [15:0] xor_half,
    output wire [15:0] and_half
);

    assign xor_half = lower_half ^ upper_half;
    assign and_half = lower_half & upper_half;

endmodule

// Pipeline stage 3
module pipeline_stage_3(
    input wire [15:0] xor_half,
    input wire [15:0] and_half,
    output wire [31:0] out_xor,
    output wire [31:0] out_and
);

    assign out_xor = {16'b0, xor_half};
    assign out_and = {16'b0, and_half};

endmodule

sva_code:
module top_module_sva (
    input logic [31:0] in,
    input logic [31:0] out_xor,
    input logic [31:0] out_and,
    input logic [15:0] lower_half,
    input logic [15:0] upper_half,
    input logic [15:0] xor_half,
    input logic [15:0] and_half
);
    // No explicit clock/reset in RTL; combinational design; sample on $global_clock.

    // Stage1: lower_half is in[15:0].
    check_stage1_lower_map: assert property (
        @(posedge $global_clock) lower_half == in[15:0]
    );

    // Stage1: upper_half is in[31:16].
    check_stage1_upper_map: assert property (
        @(posedge $global_clock) upper_half == in[31:16]
    );

    // Stage2: xor_half equals lower_half ^ upper_half.
    check_stage2_xor: assert property (
        @(posedge $global_clock) xor_half == (lower_half ^ upper_half)
    );

    // Stage2: and_half equals lower_half & upper_half.
    check_stage2_and: assert property (
        @(posedge $global_clock) and_half == (lower_half & upper_half)
    );

    // Stage3: out_xor[15:0] equals xor_half.
    check_stage3_out_xor_lsb: assert property (
        @(posedge $global_clock) out_xor[15:0] == xor_half
    );

    // Stage3: out_xor[31:16] are zero.
    check_stage3_out_xor_msb_zero: assert property (
        @(posedge $global_clock) out_xor[31:16] == 16'b0
    );

    // Stage3: out_and[15:0] equals and_half.
    check_stage3_out_and_lsb: assert property (
        @(posedge $global_clock) out_and[15:0] == and_half
    );

    // Stage3: out_and[31:16] are zero.
    check_stage3_out_and_msb_zero: assert property (
        @(posedge $global_clock) out_and[31:16] == 16'b0
    );

    // End-to-end: out_xor is zero-extended XOR of input halves.
    check_e2e_xor: assert property (
        @(posedge $global_clock) out_xor == {16'b0, (in[15:0] ^ in[31:16])}
    );

    // End-to-end: out_and is zero-extended AND of input halves.
    check_e2e_and: assert property (
        @(posedge $global_clock) out_and == {16'b0, (in[15:0] & in[31:16])}
    );
endmodule

module memory_sva #(
  parameter bits = 32,
  parameter words = 1024
)(
  input logic clk,
  input logic [9:0] addr,
  input logic [bits-1:0] data_in,
  input logic [bits-1:0] mem
);
    // Clock: clk (posedge). No reset in RTL.
    // Sequential: mem captures data_in when (addr < words), else holds.

    // If in-range last cycle, mem now equals last cycle's data_in.
    update_on_prev_in_range: assert property (
        @(posedge clk) disable iff ($initstate) $past(addr < words) |-> (mem == $past(data_in))
    );

    // If out-of-range last cycle, mem holds its previous value.
    hold_on_prev_out_of_range: assert property (
        @(posedge clk) disable iff ($initstate) !$past(addr < words) |-> (mem == $past(mem))
    );

    // Any change in mem requires in-range condition last cycle.
    change_requires_prev_in_range: assert property (
        @(posedge clk) disable iff ($initstate) (mem != $past(mem)) |-> $past(addr < words)
    );

    // When mem changes, the new value must equal last cycle's data_in.
    change_value_matches_prev_data_in: assert property (
        @(posedge clk) disable iff ($initstate) (mem != $past(mem)) |-> (mem == $past(data_in))
    );

    // Exact next-state function for mem based on previous cycle.
    next_state_function: assert property (
        @(posedge clk) disable iff ($initstate) mem == ($past(addr < words) ? $past(data_in) : $past(mem))
    );

    // If in-range last cycle and data_in differed from prior mem, mem must change.
    must_change_when_prev_in_range_and_data_differs: assert property (
        @(posedge clk) disable iff ($initstate) ($past(addr < words) && ($past(data_in) != $past(mem))) |-> (mem != $past(mem))
    );

    // If in-range last cycle and data_in equaled prior mem, mem must not change.
    no_change_when_prev_in_range_and_data_same: assert property (
        @(posedge clk) disable iff ($initstate) ($past(addr < words) && ($past(data_in) == $past(mem))) |-> (mem == $past(mem))
    );

    // If mem did not change, either last cycle was out-of-range or same data was captured.
    no_change_reason: assert property (
        @(posedge clk) disable iff ($initstate) (mem == $past(mem)) |-> (!$past(addr < words) || ($past(data_in) == $past(mem)))
    );

endmodule

