module bitwise_xor(
  input [31:0] a,
  input [31:0] b,
  output [31:0] out
);

  reg [31:0] temp;

  always @(*) begin
    temp = a ^ b;
  end

  assign out = temp;

endmodule

sva_code:
module bitwise_xor_sva (
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] out
);
    // Combinational DUT with no clock/reset; sample on $global_clock and mask $initstate.

    // out equals bitwise XOR of a and b.
    check_out_is_xor: assert property (
        @($global_clock) disable iff ($initstate) (out == (a ^ b))
    );

    // If inputs are equal, out must be zero.
    check_zero_when_inputs_equal: assert property (
        @($global_clock) disable iff ($initstate) (a == b) |-> (out == 32'h0000_0000)
    );

    // If b is zero, out equals a.
    check_out_equals_a_when_b_zero: assert property (
        @($global_clock) disable iff ($initstate) (b == 32'h0000_0000) |-> (out == a)
    );

    // If a is zero, out equals b.
    check_out_equals_b_when_a_zero: assert property (
        @($global_clock) disable iff ($initstate) (a == 32'h0000_0000) |-> (out == b)
    );

    // If b is all ones, out equals bitwise NOT of a.
    check_out_is_invert_a_when_b_ones: assert property (
        @($global_clock) disable iff ($initstate) (b == 32'hFFFF_FFFF) |-> (out == ~a)
    );

    // If a is all ones, out equals bitwise NOT of b.
    check_out_is_invert_b_when_a_ones: assert property (
        @($global_clock) disable iff ($initstate) (a == 32'hFFFF_FFFF) |-> (out == ~b)
    );

    // XOR inverse: out ^ a equals b.
    check_inverse_property_with_a: assert property (
        @($global_clock) disable iff ($initstate) ((out ^ a) == b)
    );

    // XOR inverse: out ^ b equals a.
    check_inverse_property_with_b: assert property (
        @($global_clock) disable iff ($initstate) ((out ^ b) == a)
    );

    // If inputs are stable across a cycle, output must be stable.
    check_stability_when_inputs_stable: assert property (
        @($global_clock) disable iff ($initstate) ($stable(a) && $stable(b)) |-> $stable(out)
    );

    // If output changes, at least one input must have changed.
    check_output_change_requires_input_change: assert property (
        @($global_clock) disable iff ($initstate) (!$stable(out)) |-> (!$stable(a) || !$stable(b))
    );

endmodule

verilog_code:
module div8(input [7:0] a, b, input [7:0] wa, wb, output reg [7:0] result, output reg [7:0] wresult);

always @(*) begin
    if (b == 0) begin
        result = 8'b0;
        wresult = 8'b0;
    end
    else if (a != 0 && b != 0) begin
        result = a / b;
        wresult = wa / wb;
    end
    else begin
        result = 8'hFF;
        wresult = 8'hFF;
    end
end

endmodule

sva_code:
module div8_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] wa,
    input logic [7:0] wb,
    input logic [7:0] result,
    input logic [7:0] wresult
);

    // If b is zero, both outputs are driven to 0.
    check_b_zero_outputs_zero: assert property (
        @(posedge clk) (b == 8'd0) |-> (result == 8'd0) && (wresult == 8'd0)
    );

    // If a and b are non-zero, result equals a / b.
    check_result_div_when_a_b_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) |-> (result == (a / b))
    );

    // If a and b are non-zero and wb is non-zero, wresult equals wa / wb.
    check_wresult_div_when_branch_and_wb_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (wb != 8'd0) |-> (wresult == (wa / wb))
    );

    // If a is zero and b is non-zero, both outputs are 0xFF.
    check_a_zero_b_nonzero_outputs_ff: assert property (
        @(posedge clk) (a == 8'd0) && (b != 8'd0) |-> (result == 8'hFF) && (wresult == 8'hFF)
    );

    // If b == 1 and a is non-zero, result equals a.
    check_result_identity_when_b_eq_1: assert property (
        @(posedge clk) (b == 8'd1) && (a != 8'd0) |-> (result == a)
    );

    // If a == b and both are non-zero, result equals 1.
    check_result_one_when_a_eq_b_nonzero: assert property (
        @(posedge clk) (a == b) && (a != 8'd0) |-> (result == 8'd1)
    );

    // If a < b with both non-zero, result equals 0 (integer division).
    check_result_zero_when_a_lt_b_nonzero: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (a < b) |-> (result == 8'd0)
    );

    // If wb == 1 and branch a!=0 && b!=0 is taken, wresult equals wa.
    check_wresult_identity_when_wb_eq_1: assert property (
        @(posedge clk) (a != 8'd0) && (b != 8'd0) && (wb == 8'd1) |-> (wresult == wa)
    );

endmodule

verilog_code:
module counter (
    input clk,
    input reset,
    input [3:0] N,
    output reg [3:0] count_out
);

    always @(posedge clk, posedge reset) begin
        if (reset) begin
            count_out <= 4'b0000;
        end else if (count_out == N) begin
            count_out <= 4'b0000;
        end else begin
            count_out <= count_out + 1;
        end
    end

endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input mode,
    output reg [3:0] out
);

    always @(*) begin
        if (mode) begin
            out = A + B;
        end else begin
            out = A - B;
        end
    end

endmodule
module top_module (
    input clk,
    input reset,
    input [3:0] N,
    input [3:0] B,
    input mode,
    input select,
    output reg [3:0] q
);

    wire [3:0] count_out;
    wire [3:0] out;

    counter counter_inst (
        .clk(clk),
        .reset(reset),
        .N(N),
        .count_out(count_out)
    );

    adder_subtractor adder_subtractor_inst (
        .A(count_out),
        .B(B),
        .mode(mode),
        .out(out)
    );

    always @(posedge clk) begin
        if (select) begin
            q <= count_out;
        end else begin
            q <= out;
        end
    end

endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] N,
    input logic [3:0] B,
    input logic mode,
    input logic select,
    input logic [3:0] q
);
    ///// counter: reset and step rules /////
    // After a cycle with reset HIGH, counter must be 0 on the next clock.
    check_counter_reset_next_zero: assert property (
        @(posedge clk) disable iff (reset)
            $past(reset) |-> (counter_inst.count_out == 4'd0)
    );

    // If previous cycle was not in reset and count_out != N, it increments by 1.
    check_counter_increment: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(counter_inst.count_out) != $past(N))) |-> 
                (counter_inst.count_out == ($past(counter_inst.count_out) + 4'd1))
    );

    // If previous cycle was not in reset and count_out == N, it wraps to 0.
    check_counter_wrap_to_zero_on_match: assert property (
        @(posedge clk) disable iff (reset)
            (!$past(reset) && ($past(counter_inst.count_out) == $past(N))) |-> 
                (counter_inst.count_out == 4'd0)
    );

    ///// adder_subtractor: combinational function /////
    // In add mode, out equals A + B (A is counter_inst.count_out).
    check_adder_add_mode: assert property (
        @(posedge clk) disable iff (reset)
            mode |-> (adder_subtractor_inst.out == (counter_inst.count_out + B))
    );

    // In sub mode, out equals A - B (A is counter_inst.count_out).
    check_adder_sub_mode: assert property (
        @(posedge clk) disable iff (reset)
            !mode |-> (adder_subtractor_inst.out == (counter_inst.count_out - B))
    );

    ///// q register: loads selected source on each clock /////
    // If previous cycle selected counter path, q equals previous count_out.
    check_q_load_prev_count_on_select1: assert property (
        @(posedge clk) disable iff (reset)
            $past(select) |-> (q == $past(counter_inst.count_out))
    );

    // If previous cycle selected adder/subtractor path, q equals previous out.
    check_q_load_prev_out_on_select0: assert property (
        @(posedge clk) disable iff (reset)
            !$past(select) |-> (q == $past(adder_subtractor_inst.out))
    );

    ///// End-to-end: when select stays HIGH, q behaves like the counter /////
    // With select HIGH in consecutive cycles, q steps by +1 unless it hits N, then wraps to 0.
    check_q_steps_like_counter_when_select_held: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset)) |-> 
                (q == (($past(q) == $past(N)) ? 4'd0 : ($past(q) + 4'd1)))
    );

    // With select HIGH in consecutive cycles and q hit N previously, q must be 0 now.
    check_q_wrap_when_select_held: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset) && ($past(q) == $past(N))) |-> 
                (q == 4'd0)
    );

    // With select HIGH in consecutive cycles and q != N previously, q increments by 1.
    check_q_inc_when_select_held_not_at_N: assert property (
        @(posedge clk) disable iff (reset)
            ($past(select) && select && !$past(reset) && ($past(q) != $past(N))) |-> 
                (q == ($past(q) + 4'd1))
    );
endmodule

verilog_code:
module mem_encrypt_decrypt (
  input clk,
  input reset,
  input [7:0] data_in,
  input [7:0] key,
  input enable,
  output reg [7:0] data_out
);

  reg [7:0] encrypted_data;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      data_out <= 8'b0;
      encrypted_data <= 8'b0;
    end else begin
      if (enable) begin
        encrypted_data <= data_in ^ key;
        data_out <= encrypted_data;
      end else begin
        data_out <= data_in;
      end
    end
  end

endmodule

sva_code:
module mem_encrypt_decrypt_sva (
  input logic clk,
  input logic reset,
  input logic [7:0] data_in,
  input logic [7:0] key,
  input logic enable,
  input logic [7:0] data_out,
  input logic [7:0] encrypted_data
);
  // Reset drives data_out and encrypted_data to zero.
  reset_clears_regs: assert property (
    @(posedge clk) reset |-> (data_out == 8'h00) && (encrypted_data == 8'h00)
  );

  // With enable=0, encrypted_data holds its value to the next cycle.
  en0_holds_encrypted: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (encrypted_data == $past(encrypted_data))
  );

  // With enable=1, encrypted_data updates to data_in ^ key on the next cycle.
  en1_updates_encrypted: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (encrypted_data == ($past(data_in) ^ $past(key)))
  );

  // With enable=0, data_out passes through data_in on the next cycle.
  en0_bypass_data_out: assert property (
    @(posedge clk) disable iff (reset) (!enable) |=> (data_out == $past(data_in))
  );

  // With enable=1, data_out takes the previous encrypted_data on the next cycle.
  en1_pipeline_data_out: assert property (
    @(posedge clk) disable iff (reset) (enable) |=> (data_out == $past(encrypted_data))
  );

  // Each cycle after reset, data_out equals the previous cycle's muxed source.
  data_out_prev_mux: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (data_out == ($past(enable) ? $past(encrypted_data) : $past(data_in)))
  );

  // Each cycle after reset, encrypted_data equals the previous cycle's selected update.
  encrypted_prev_mux: assert property (
    @(posedge clk) disable iff (reset) $past(!reset) |-> (encrypted_data == ($past(enable) ? ($past(data_in) ^ $past(key)) : $past(encrypted_data)))
  );

  // Back-to-back enable cycles propagate the first cycle's XOR to data_out two cycles later.
  back_to_back_enable_pipeline: assert property (
    @(posedge clk) disable iff (reset) (enable ##1 enable) |=> (data_out == $past(data_in ^ key, 2))
  );
endmodule

verilog_code:
module traffic_light_controller (
  input clk,
  input reset,
  output reg green_led,
  output reg yellow_led,
  output reg red_led
);

  // Define states and their corresponding values
  parameter GREEN = 2'b00;
  parameter YELLOW = 2'b01;
  parameter RED = 2'b10;

  // Define state register and initialize to GREEN
  reg [1:0] state = GREEN;

  // Define counter for each state
  reg [3:0] green_counter = 0;
  reg [1:0] yellow_counter = 0;
  reg [4:0] red_counter = 0;

  // Define state transitions and counter values
  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= GREEN;
      green_counter <= 0;
      yellow_counter <= 0;
      red_counter <= 0;
    end else begin
      case (state)
        GREEN: begin
          if (green_counter == 10) begin
            state <= YELLOW;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            green_counter <= green_counter + 1;
          end
        end
        YELLOW: begin
          if (yellow_counter == 2) begin
            state <= RED;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            yellow_counter <= yellow_counter + 1;
          end
        end
        RED: begin
          if (red_counter == 15) begin
            state <= GREEN;
            green_counter <= 0;
            yellow_counter <= 0;
            red_counter <= 0;
          end else begin
            red_counter <= red_counter + 1;
          end
        end
      endcase
    end
  end

  // Define output logic based on state
  always @(state) begin
    case (state)
      GREEN: begin
        green_led <= 1;
        yellow_led <= 0;
        red_led <= 0;
      end
      YELLOW: begin
        green_led <= 0;
        yellow_led <= 1;
        red_led <= 0;
      end
      RED: begin
        green_led <= 0;
        yellow_led <= 0;
        red_led <= 1;
      end
    endcase
  end

endmodule

sva_code:
module traffic_light_controller_sva (
  input logic clk,
  input logic reset,
  input logic green_led,
  input logic yellow_led,
  input logic red_led,
  input logic [1:0] state,
  input logic [3:0] green_counter,
  input logic [1:0] yellow_counter,
  input logic [4:0] red_counter
);
  // Local copies of state encodings
  localparam logic [1:0] GREEN  = 2'b00;
  localparam logic [1:0] YELLOW = 2'b01;
  localparam logic [1:0] RED    = 2'b10;

  ///// Reset behavior /////
  // On a clock edge while reset is HIGH, state/counters are in reset values.
  reset_state_counters: assert property (
    @(posedge clk) reset |-> (state == GREEN) && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // On a clock edge while reset is HIGH, outputs reflect GREEN.
  reset_outputs_green: assert property (
    @(posedge clk) reset |-> (green_led == 1'b1) && (yellow_led == 1'b0) && (red_led == 1'b0)
  );

  ///// State encoding and outputs /////
  // State must always be one of GREEN/YELLOW/RED.
  state_valid_encoding: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) || (state == YELLOW) || (state == RED)
  );
  // Output decode for GREEN.
  decode_green: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) |-> (green_led == 1'b1) && (yellow_led == 1'b0) && (red_led == 1'b0)
  );
  // Output decode for YELLOW.
  decode_yellow: assert property (
    @(posedge clk) disable iff (reset) (state == YELLOW) |-> (green_led == 1'b0) && (yellow_led == 1'b1) && (red_led == 1'b0)
  );
  // Output decode for RED.
  decode_red: assert property (
    @(posedge clk) disable iff (reset) (state == RED) |-> (green_led == 1'b0) && (yellow_led == 1'b0) && (red_led == 1'b1)
  );
  // Exactly one LED is ON at a time.
  leds_onehot: assert property (
    @(posedge clk) disable iff (reset) $onehot({green_led, yellow_led, red_led})
  );

  ///// GREEN state behavior /////
  // While in GREEN and count < 10, stay in GREEN and increment green_counter; others unchanged.
  green_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == GREEN) && (green_counter != 4'd10)
      |=> (state == GREEN)
       && (green_counter == $past(green_counter) + 1)
       && (yellow_counter == $past(yellow_counter))
       && (red_counter == $past(red_counter))
  );
  // When green_counter == 10, transition to YELLOW and clear all counters.
  green_to_yellow_on_10: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == GREEN) && (green_counter == 4'd10)
      |=> (state == YELLOW)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In GREEN, green_counter never exceeds 10.
  green_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == GREEN) |-> (green_counter <= 4'd10)
  );

  ///// YELLOW state behavior /////
  // While in YELLOW and count < 2, stay in YELLOW and increment yellow_counter; others unchanged.
  yellow_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == YELLOW) && (yellow_counter != 2'd2)
      |=> (state == YELLOW)
       && (yellow_counter == $past(yellow_counter) + 1)
       && (green_counter == $past(green_counter))
       && (red_counter == $past(red_counter))
  );
  // When yellow_counter == 2, transition to RED and clear all counters.
  yellow_to_red_on_2: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == YELLOW) && (yellow_counter == 2'd2)
      |=> (state == RED)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In YELLOW, yellow_counter never exceeds 2.
  yellow_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == YELLOW) |-> (yellow_counter <= 2'd2)
  );

  ///// RED state behavior /////
  // While in RED and count < 15, stay in RED and increment red_counter; others unchanged.
  red_count_increments: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == RED) && (red_counter != 5'd15)
      |=> (state == RED)
       && (red_counter == $past(red_counter) + 1)
       && (green_counter == $past(green_counter))
       && (yellow_counter == $past(yellow_counter))
  );
  // When red_counter == 15, transition to GREEN and clear all counters.
  red_to_green_on_15: assert property (
    @(posedge clk) disable iff (reset)
      $past(!reset) && (state == RED) && (red_counter == 5'd15)
      |=> (state == GREEN)
       && (green_counter == 4'd0) && (yellow_counter == 2'd0) && (red_counter == 5'd0)
  );
  // In RED, red_counter never exceeds 15.
  red_counter_bounded: assert property (
    @(posedge clk) disable iff (reset) (state == RED) |-> (red_counter <= 5'd15)
  );

  ///// Counters outside active state /////
  // green_counter is 0 outside GREEN.
  green_zero_outside_green: assert property (
    @(posedge clk) disable iff (reset) (state != GREEN) |-> (green_counter == 4'd0)
  );
  // yellow_counter is 0 outside YELLOW.
  yellow_zero_outside_yellow: assert property (
    @(posedge clk) disable iff (reset) (state != YELLOW) |-> (yellow_counter == 2'd0)
  );
  // red_counter is 0 outside RED.
  red_zero_outside_red: assert property (
    @(posedge clk) disable iff (reset) (state != RED) |-> (red_counter == 5'd0)
  );

endmodule

