        @(posedge A1 or posedge A2 or posedge B1 or posedge C1)
        (Y == 1'b0) |-> (C1 && B1 && (A1 || A2))
    );

    // Y HIGH implies at least one of C1 LOW, B1 LOW, or both A inputs LOW.
    check_y_high_condition: assert property (
        @(posedge A1 or posedge A2 or posedge B1 or posedge C1)
        (Y == 1'b1) |-> (!C1 || !B1 || (!A1 && !A2))
    );
