    wire Q_bar;
    wire SCD;
    wire SCE;
    wire SET_B;

    assign SCD = R;
    assign SCE = 1;
    assign SET_B = S;

    dff base (
        .Q(Q),
        .CLK(CLK),
        .D(D),
        .SCD(SCD),
        .SCE(SCE),
        .SET_B(SET_B)
    );

endmodule

