    check_y_high_when_C0: assert property (
        @(posedge CLK) disable iff (!RESETn) (C == 1'b0) |-> (Y == 1'b1)
    );

    // If all inputs are 1, Y must be 0.
    check_y_low_when_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) (A && B && C) |-> (Y == 1'b0)
    );

    // Y can be 0 only when all inputs are 1.
    check_y_zero_only_if_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) (Y == 1'b0) |-> (A && B && C)
    );

    // A falling edge on Y implies all inputs are 1 this cycle.
    check_y_fall_implies_all1: assert property (
        @(posedge CLK) disable iff (!RESETn) $fell(Y) |-> (A && B && C)
    );

    // A rising edge on Y implies at least one input is 0 this cycle.
    check_y_rise_implies_any0: assert property (
        @(posedge CLK) disable iff (!RESETn) $rose(Y) |-> ((A == 1'b0) || (B == 1'b0) || (C == 1'b0))
    );

    // If inputs are stable, Y must be stable.
    check_stable_inputs_imply_stable_y: assert property (
        @(posedge CLK) disable iff (!RESETn) $stable({A,B,C}) |-> $stable(Y)
    );

    // With B and C high and stable, a rising edge on A causes a falling edge on Y.
    check_y_fall_on_A_rise_with_BC_high_stable: assert property (
        @(posedge CLK) disable iff (!RESETn) ($rose(A) && (B && C) && $past(B && C)) |-> $fell(Y)
    );
endmodule

verilog_code:
module counter_mod_rtl(
  input clk, rst, up_down,
  output reg [3:0] q,
  output reg carry
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q <= 4'b0;
      carry <= 1'b0;
    end else if (up_down == 1'b0) begin
      // Up counter
      if (q == 4'b1111) begin
        q <= 4'b0;
        carry <= 1'b1;
      end else begin
        q <= q + 4'b1;
        carry <= 1'b0;
      end
    end else begin
      // Down counter
      if (q == 4'b0000) begin
        q <= 4'b1111;
        carry <= 1'b1;
      end else begin
        q <= q - 4'b1;
        carry <= 1'b0;
      end
    end
  end

endmodule

sva_code:
module counter_mod_rtl_sva (
  input logic clk,
  input logic rst,
  input logic up_down,
  input logic [3:0] q,
  input logic carry
);

  // Reset drives q and carry LOW when rst is HIGH at the clock edge.
  check_reset_outputs: assert property (
    @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
  );

  // Up-count non-wrap: if last q != 15 and up mode, next q = q+1 and carry=0.
  check_up_nonwrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && ($past(q) != 4'hF))
      |-> (q == $past(q) + 4'd1) && (carry == 1'b0)
  );

  // Up-count wrap: if last q == 15 and up mode, next q = 0 and carry=1.
  check_up_wrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && ($past(q) == 4'hF))
      |-> (q == 4'd0) && (carry == 1'b1)
  );

  // Down-count non-wrap: if last q != 0 and down mode, next q = q-1 and carry=0.
  check_down_nonwrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && ($past(q) != 4'd0))
      |-> (q == $past(q) - 4'd1) && (carry == 1'b0)
  );

  // Down-count wrap: if last q == 0 and down mode, next q = 15 and carry=1.
  check_down_wrap_next: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && ($past(q) == 4'd0))
      |-> (q == 4'hF) && (carry == 1'b1)
  );

  // Carry definition: carry is 1 iff a wrap occurs based on direction and last q.
  check_carry_definition: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst))
      |-> (carry == (((up_down == 1'b0) && ($past(q) == 4'hF)) ||
                     ((up_down == 1'b1) && ($past(q) == 4'd0))))
  );

  // No spurious carry when last q was mid-range (1..14).
  check_no_carry_midrange: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && ($past(q) != 4'd0) && ($past(q) != 4'hF))
      |-> (carry == 1'b0)
  );

  // If carry is 1 in up mode, last q was 15 and q wrapped to 0.
  check_carry_only_on_up_wrap: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b0) && (carry == 1'b1))
      |-> ($past(q) == 4'hF) && (q == 4'd0)
  );

  // If carry is 1 in down mode, last q was 0 and q wrapped to 15.
  check_carry_only_on_down_wrap: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && (up_down == 1'b1) && (carry == 1'b1))
      |-> ($past(q) == 4'd0) && (q == 4'hF)
  );

endmodule

