    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] S,
    input logic [1:0] O,
    input logic [1:0] sum,
    input logic [1:0] diff,
    input logic       s_not
);
    // sum must equal A+B (2-bit modulo arithmetic).
    check_sum_def: assert property (
        @(posedge CLK) sum == (A + B)
    );

    // sum[0] equals A[0] XOR B[0].
    check_sum_bit0_xor: assert property (
        @(posedge CLK) sum[0] == (A[0] ^ B[0])
    );

    // sum[1] equals A[1] XOR B[1] XOR carry from bit0.
    check_sum_bit1: assert property (
        @(posedge CLK) sum[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // diff equals truncated 2 LSBs of the 3-bit addition per RTL.
    check_diff_def: assert property (
        @(posedge CLK) diff == ( {A[1]^B[1], A[0]^B[0]} + {~B[1], ~B[0], 1'b0} )[1:0]
    );

    // diff[0] equals A[0] XOR B[0].
    check_diff_bit0_xor: assert property (
        @(posedge CLK) diff[0] == (A[0] ^ B[0])
    );

    // diff[1] equals (A[1] XOR B[1]) XOR (~B[0]).
    check_diff_bit1_expr: assert property (
        @(posedge CLK) diff[1] == ((A[1] ^ B[1]) ^ ~B[0])
    );

    // Output O must select sum when s_not is 1, else diff.
    check_o_mux: assert property (
        @(posedge CLK) O == (s_not ? sum : diff)
    );

    // When s_not is 1, O equals sum.
    check_o_when_snot_1: assert property (
        @(posedge CLK) s_not |-> (O == sum)
    );

    // When s_not is 0, O equals diff.
    check_o_when_snot_0: assert property (
        @(posedge CLK) !s_not |-> (O == diff)
    );
endmodule

module adder_subtractor_sva (
    // DUT ports
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       C,
    input logic [3:0] out,
    // Sampling clock for SVA (DUT is combinational; no reset present)
    input logic       clk
);
    // When C==0, output equals A+B (4-bit wraparound).
    compute_add_correct: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == (A + B))
    );

    // When C==1, output equals A-B (4-bit wraparound).
    compute_sub_correct: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (A - B))
    );

    // If both inputs are zero, output is zero (both modes).
    zero_when_both_zero: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0)) |-> (out == 4'd0)
    );

    // In subtraction mode and A==B, output is zero.
    sub_equal_zero: assert property (
        @(posedge clk) (C == 1'b1 && (A == B)) |-> (out == 4'd0)
    );

    // In addition mode with B==0, output passes A.
    add_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b0 && (B == 4'd0)) |-> (out == A)
    );

    // In subtraction mode with B==0, output passes A.
    sub_passthrough_b_zero: assert property (
        @(posedge clk) (C == 1'b1 && (B == 4'd0)) |-> (out == A)
    );

    // In addition mode with A==0, output passes B.
    add_passthrough_a_zero: assert property (
        @(posedge clk) (C == 1'b0 && (A == 4'd0)) |-> (out == B)
    );
endmodule

verilog_code:
module adder_4bit(
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] out,
    output carry
);

wire [3:0] temp_sum;
wire [4:0] temp_carry; // 4 bits for carry

// Generate the sum and carry for each bit
genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : bit_adder
        full_adder adder(
            .in1(in1[i]),
            .in2(in2[i]),
            .carry_in(temp_carry[i]),
            .sum(temp_sum[i]),
            .carry_out(temp_carry[i+1])
        );
    end
endgenerate

assign temp_carry[0] = 0; // Initial value for carry_in

// Assign the output and carry
assign out = temp_sum;
assign carry = temp_carry[4];

endmodule
module full_adder(
    input in1,
    input in2,
    input carry_in,
    output sum,
    output carry_out
);

assign sum = in1 ^ in2 ^ carry_in;
assign carry_out = (in1 & in2) | (in1 & carry_in) | (in2 & carry_in);

endmodule

sva_code:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out,
    input logic carry
);
    // {carry,out} equals 5-bit zero-extended sum of inputs.
    check_full_sum_5bit: assert property (
        @(posedge clk) {carry, out} == ({1'b0, in1} + {1'b0, in2})
    );

    // LSB sum is XOR of inputs (carry_in = 0).
    check_lsb_xor: assert property (
        @(posedge clk) out[0] == (in1[0] ^ in2[0])
    );

    // Bit1 sum includes carry from bit0 = in1[0]&in2[0].
    check_bit1_sum_with_carry0: assert property (
        @(posedge clk) out[1] == (in1[1] ^ in2[1] ^ (in1[0] & in2[0]))
    );

    // Bit2 sum with ripple carry from lower bits.
    check_bit2_sum_with_ripple: assert property (
        @(posedge clk)
            out[2] == (
                in1[2] ^ in2[2] ^
                ( (in1[1] & in2[1]) | ((in1[1] ^ in2[1]) & (in1[0] & in2[0])) )
            )
    );

    // Bit3 sum with ripple carry from lower bits.
    check_bit3_sum_with_ripple: assert property (
        @(posedge clk)
            out[3] == (
                in1[3] ^ in2[3] ^
                ( (in1[2] & in2[2]) | ((in1[2] ^ in2[2]) &
                    ( (in1[1] & in2[1]) | ((in1[1] ^ in2[1]) & (in1[0] & in2[0])) )
                  )
                )
            )
    );

    // Final carry equals ripple-carry chain from bit3.
    check_carry_chain_formula: assert property (
        @(posedge clk)
            carry == (
                (in1[3] & in2[3]) | ((in1[3] ^ in2[3]) &
                    ( (in1[2] & in2[2]) | ((in1[2] ^ in2[2]) &
                        ( (in1[1] & in2[1]) | ((in1[1] ^ in2[1]) & (in1[0] & in2[0])) )
                      )
                    )
                )
            )
    );

    // Carry equals MSB of 5-bit zero-extended sum.
    check_carry_is_msb_of_sum: assert property (
        @(posedge clk) carry == (({1'b0, in1} + {1'b0, in2})[4])
    );

    // Outputs remain stable when inputs are stable across cycles.
    check_outputs_stable_if_inputs_stable: assert property (
        @(posedge clk) ($stable(in1) && $stable(in2)) |-> ($stable(out) && $stable(carry))
    );

    // Right identity: adding zero on in2 yields out=in1 and carry=0.
    check_add_zero_right_identity: assert property (
        @(posedge clk) (in2 == 4'b0000) |-> (out == in1 && carry == 1'b0)
    );

    // Left identity: adding zero on in1 yields out=in2 and carry=0.
    check_add_zero_left_identity: assert property (
        @(posedge clk) (in1 == 4'b0000) |-> (out == in2 && carry == 1'b0)
    );
endmodule

module ascending_order_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic Y
);
    ///// Functional equivalence /////
    // Y reflects strict ascending order A < B < C.
    check_y_definition: assert property (
        @(posedge CLK) Y == ((A < B) && (B < C))
    );

    ///// Consequences of the definition /////
    // If A >= B, Y must be 0.
    check_y_zero_when_A_ge_B: assert property (
        @(posedge CLK) (A >= B) |-> (Y == 1'b0)
    );
    // If B >= C, Y must be 0.
    check_y_zero_when_B_ge_C: assert property (
        @(posedge CLK) (B >= C) |-> (Y == 1'b0)
    );
    // If Y is 1, then A < C (implied by A < B and B < C).
    check_transitive_A_lt_C_when_Y_one: assert property (
        @(posedge CLK) (Y == 1'b1) |-> (A < C)
    );

    ///// Combinational determinism /////
    // If A,B,C are unchanged from the previous cycle, Y must be unchanged.
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) (A == $past(A) && B == $past(B) && C == $past(C)) |-> (Y == $past(Y))
    );
    // If Y changes, at least one of A,B,C must have changed.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) (Y != $past(Y)) |-> ((A != $past(A)) || (B != $past(B)) || (C != $past(C)))
    );
endmodule

module figuras_Gato_sva (
    input logic        video_mostrar,
    input logic [3:0]  entrada,
    input logic [9:0]  pixel_x,
    input logic [9:0]  pixel_y,
    input logic [2:0]  salida_rgb
);

    // salida_rgb outputs only 000, 001, or 111.
    check_rgb_value_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b000) || (salida_rgb == 3'b001) || (salida_rgb == 3'b111)
    );

    // When video_mostrar=1 and entrada=0011 in rect (150..200,100..150), output 111.
    check_video_on_rect1_white: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        (entrada == 4'b0011) &&
        (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b111)
    );

    // When video_mostrar=1 and not in rect1 with entrada=0011, output 000.
    check_video_on_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) &&
        !((entrada == 4'b0011) &&
          (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd100) && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

    // When video_mostrar=0 and entrada=0100 in rect (100..200,50..150), output 001.
    check_video_off_rect2_blue: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        (entrada == 4'b0100) &&
        (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
        (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
        |-> (salida_rgb == 3'b001)
    );

    // When video_mostrar=0 and not in rect2 with entrada=0100, output 000.
    check_video_off_else_black: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) &&
        !((entrada == 4'b0100) &&
          (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
          (pixel_y >= 10'd50)  && (pixel_y <= 10'd150))
        |-> (salida_rgb == 3'b000)
    );

    // Output 111 occurs only when video_mostrar=1 with entrada=0011 in rect1.
    check_white_implies_video_on_rect1: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b111)
        |-> (video_mostrar == 1'b1) &&
            (entrada == 4'b0011) &&
            (pixel_x >= 10'd150) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd100) && (pixel_y <= 10'd150)
    );

    // Output 001 occurs only when video_mostrar=0 with entrada=0100 in rect2.
    check_blue_implies_video_off_rect2: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (salida_rgb == 3'b001)
        |-> (video_mostrar == 1'b0) &&
            (entrada == 4'b0100) &&
            (pixel_x >= 10'd100) && (pixel_x <= 10'd200) &&
            (pixel_y >= 10'd50)  && (pixel_y <= 10'd150)
    );

    // When video_mostrar=1, output is either 000 or 111.
    check_video_on_output_domain: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb == 3'b000) || (salida_rgb == 3'b111)
    );

    // When video_mostrar=1, all RGB bits are equal (000 or 111).
    check_video_on_bits_equal: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b1) |-> (salida_rgb[2] == salida_rgb[1]) && (salida_rgb[1] == salida_rgb[0])
    );

    // When video_mostrar=0, upper RGB bits are 0 (outputs 000 or 001).
    check_video_off_upper_bits_zero: assert property (
        @(posedge pixel_x[0]) disable iff (1'b0)
        (video_mostrar == 1'b0) |-> (salida_rgb[2] == 1'b0) && (salida_rgb[1] == 1'b0)
    );

endmodule

