module four_bit_adder_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);
    // Assertions sample on posedge of cin (no clock/reset in DUT).

    // Sum+cout must equal 5-bit arithmetic result of a + b + cin.
    check_add_full_concat_on_cin: assert property (
        @(posedge cin) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

    // sum[0] must be the XOR of a[0], b[0], and cin.
    check_sum0_xor: assert property (
        @(posedge cin) sum[0] == (a[0] ^ b[0] ^ cin)
    );

    // sum[1] must equal XOR of a[1], b[1], and carry from bit0.
    check_sum1_chain: assert property (
        @(posedge cin)
            sum[1] == (a[1] ^ b[1] ^
                      ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin)))
    );

    // sum[2] must equal XOR of a[2], b[2], and carry from bit1.
    check_sum2_chain: assert property (
        @(posedge cin)
            sum[2] == (a[2] ^ b[2] ^
                      ((a[1] & b[1]) | ((a[1] ^ b[1]) &
                      ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin)))))
    );

    // sum[3] must equal XOR of a[3], b[3], and carry from bit2.
    check_sum3_chain: assert property (
        @(posedge cin)
            sum[3] == (a[3] ^ b[3] ^
                      ((a[2] & b[2]) | ((a[2] ^ b[2]) &
                      ((a[1] & b[1]) | ((a[1] ^ b[1]) &
                      ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin)))))))
    );

    // cout must equal carry from bit3.
    check_cout_chain: assert property (
        @(posedge cin)
            cout == ((a[3] & b[3]) | ((a[3] ^ b[3]) &
                   ((a[2] & b[2]) | ((a[2] ^ b[2]) &
                   ((a[1] & b[1]) | ((a[1] ^ b[1]) &
                   ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))))))))
    );

    // sum must match the lower 4 bits of a + b + cin.
    check_sum_lower_bits_from_arith: assert property (
        @(posedge cin) sum == ({1'b0, a} + {1'b0, b} + cin)[3:0]
    );

    // cout must match the MSB of a + b + cin.
    check_cout_from_arith: assert property (
        @(posedge cin) cout == ({1'b0, a} + {1'b0, b} + cin)[4]
    );

    // All zeros on inputs must yield zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge cin) (a == 4'b0000 && b == 4'b0000 && cin == 1'b0) |-> (sum == 4'b0000 && cout == 1'b0)
    );

    // Max case 0xF + 0xF + 1 must yield sum=0xF and cout=1.
    check_max_case: assert property (
        @(posedge cin) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hF && cout == 1'b1)
    );
endmodule

verilog_code:
module Mealy (
    input [n-1:0] in,      // n-bit input signal
    output reg [m-1:0] out,     // m-bit output signal
    input clk             // clock signal
);

parameter n = 4;          // number of input signals
parameter m = 2;          // number of output signals
parameter s = 3;          // number of states

reg [s-1:0] state;        // current state
reg [s-1:0] next_state;  // next state
reg [m-1:0] output_next; // next output

// State transition logic
always @(*) begin
    case (state)
        0: begin // State 0
            if (in[0] && in[1]) begin
                next_state = 1;
                output_next = {1'b1, 1'b0};
            end else begin
                next_state = 2;
                output_next = {1'b0, 1'b1};
            end
        end

        1: begin // State 1
            if (in[2]) begin
                next_state = 0;
                output_next = {1'b0, 1'b1};
            end else begin
                next_state = 2;
                output_next = {1'b0, 1'b0};
            end
        end

        2: begin // State 2
            if (in[3]) begin
                next_state = 0;
                output_next = {1'b1, 1'b1};
            end else begin
                next_state = 1;
                output_next = {1'b0, 1'b0};
            end
        end

        default: begin // Default state
            next_state = 0;
            output_next = {1'b0, 1'b0};
        end
    endcase
end

// State register
always @(posedge clk) begin
    state <= next_state;
end

// Output register
always @(posedge clk) begin
    out <= output_next;
end

endmodule

sva_code:
module Mealy_sva #(
    parameter int n = 4,
    parameter int m = 2,
    parameter int s = 3
) (
    input logic clk,
    input logic [n-1:0] in,
    input logic [m-1:0] out,
    input logic [s-1:0] state,
    input logic [s-1:0] next_state,
    input logic [m-1:0] output_next
);

    ///// Combinational next_state/output_next mapping /////
    // In state 0 with in[0]&in[1], next_state=1 and output_next=2'b10.
    comb_map_s0_t: assert property (
        @(posedge clk) (state == '0) && (in[0] && in[1]) |-> (next_state == '1) && (output_next == 2'b10)
    );
    // In state 0 with !(in[0]&in[1]), next_state=2 and output_next=2'b01.
    comb_map_s0_f: assert property (
        @(posedge clk) (state == '0) && !(in[0] && in[1]) |-> (next_state == '2) && (output_next == 2'b01)
    );
    // In state 1 with in[2], next_state=0 and output_next=2'b01.
    comb_map_s1_t: assert property (
        @(posedge clk) (state == '1) && in[2] |-> (next_state == '0) && (output_next == 2'b01)
    );
    // In state 1 with !in[2], next_state=2 and output_next=2'b00.
    comb_map_s1_f: assert property (
        @(posedge clk) (state == '1) && !in[2] |-> (next_state == '2) && (output_next == 2'b00)
    );
    // In state 2 with in[3], next_state=0 and output_next=2'b11.
    comb_map_s2_t: assert property (
        @(posedge clk) (state == '2) && in[3] |-> (next_state == '0) && (output_next == 2'b11)
    );
    // In state 2 with !in[3], next_state=1 and output_next=2'b00.
    comb_map_s2_f: assert property (
        @(posedge clk) (state == '2) && !in[3] |-> (next_state == '1) && (output_next == 2'b00)
    );
    // In any other state, next_state=0 and output_next=2'b00.
    comb_map_default: assert property (
        @(posedge clk) (state != '0) && (state != '1) && (state != '2) |-> (next_state == '0) && (output_next == 2'b00)
    );

    ///// Sequential register updates derived from previous state/input /////
    // From prev state 0 with in[0]&in[1], state->1 and out->2'b10.
    seq_s0_t: assert property (
        @(posedge clk) $past((state == '0) && (in[0] && in[1]), 1, 1'b0) |-> (state == '1) && (out == 2'b10)
    );
    // From prev state 0 with !(in[0]&in[1]), state->2 and out->2'b01.
    seq_s0_f: assert property (
        @(posedge clk) $past((state == '0) && !(in[0] && in[1]), 1, 1'b0) |-> (state == '2) && (out == 2'b01)
    );
    // From prev state 1 with in[2], state->0 and out->2'b01.
    seq_s1_t: assert property (
        @(posedge clk) $past((state == '1) && in[2], 1, 1'b0) |-> (state == '0) && (out == 2'b01)
    );
    // From prev state 1 with !in[2], state->2 and out->2'b00.
    seq_s1_f: assert property (
        @(posedge clk) $past((state == '1) && !in[2], 1, 1'b0) |-> (state == '2) && (out == 2'b00)
    );
    // From prev state 2 with in[3], state->0 and out->2'b11.
    seq_s2_t: assert property (
        @(posedge clk) $past((state == '2) && in[3], 1, 1'b0) |-> (state == '0) && (out == 2'b11)
    );
    // From prev state 2 with !in[3], state->1 and out->2'b00.
    seq_s2_f: assert property (
        @(posedge clk) $past((state == '2) && !in[3], 1, 1'b0) |-> (state == '1) && (out == 2'b00)
    );
    // From any other prev state, state->0 and out->2'b00.
    seq_default: assert property (
        @(posedge clk) $past(((state != '0) && (state != '1) && (state != '2)), 1, 1'b0) |-> (state == '0) && (out == 2'b00)
    );

endmodule

module simple_counter_sva (
  input logic clk,
  input logic rst,
  input logic en,
  input logic [31:0] count
);
  // Clock: clk posedge. Reset: rst synchronous active-high. Counter increments on en, holds otherwise.

  // Reset drives count to 0 on each asserted cycle.
  reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 32'd0)
  );

  // When not in reset and en is LOW, count holds its previous value.
  hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && !en) |-> (count == $past(count))
  );

  // When not in reset and en is HIGH, count increments by 1.
  increment_when_en_high: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && en) |-> (count == $past(count) + 32'd1)
  );

  // In non-reset cycles, count can change only if en is HIGH.
  change_requires_en: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && $changed(count)) |-> en
  );

  // When en stays LOW for two consecutive non-reset cycles, count is unchanged across two cycles.
  two_cycle_hold_when_en_low: assert property (
    @(posedge clk) disable iff (rst)
      ($past(1'b1,2) && !en && !$past(en) && !$past(rst) && !$past(rst,2))
      |-> (count == $past(count,2))
  );

  // With en HIGH at max value, count wraps to 0 on next cycle.
  wrap_to_zero_on_max: assert property (
    @(posedge clk) disable iff (rst) ($past(1'b1) && en && ($past(count) == 32'hFFFF_FFFF)) |-> (count == 32'h0000_0000)
  );

  // If both rst and en are HIGH, reset dominates and count is 0.
  reset_dominates_enable: assert property (
    @(posedge clk) (rst && en) |-> (count == 32'd0)
  );

endmodule

