        @(posedge CLK) disable iff ($initstate) ($rose(EN) && !TE) |=> (ENCLK == 1'b1)
    );

    // Falling EN with TE LOW sets ENCLK LOW on the next clock.
    check_en_fall_effect_when_te_low: assert property (
