module mux_4to1 (
    input [3:0] in,
    input [1:0] sel,
    output reg out
);
    always @ (sel, in) begin
        case (sel)
            2'b00: out <= in[0];
            2'b01: out <= in[1];
            2'b10: out <= in[2];
            2'b11: out <= in[3];
        endcase
    end
endmodule
module dff_8 (
    input clk,
    input reset,
    output reg [7:0] q
);
    always @(posedge clk) begin
        if (reset) begin
            q <= 8'b0;
        end else begin
            q <= 8'b0;
        end
    end
endmodule
module functional_module (
