verilog_code:
module nios_system_switches (
  // inputs:
  address,
  clk,
  in_port,
  reset_n,

  // outputs:
  readdata
);

  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [  9: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [  9: 0] data_in;
  wire    [  9: 0] read_mux_out;
  reg     [ 31: 0] readdata;

  // Select the data to be read from the input port
  assign read_mux_out = {10 {(address == 2'b00)}} & in_port;

  // Enable the clock signal
  assign clk_en = 1;

  // Assign the selected data to the data_in signal
  assign data_in = read_mux_out;

  // Update the readdata signal on the rising edge of the clock signal
  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      readdata <= 0;
    end else if (clk_en) begin
      readdata <= {32'b0 | data_in};
    end
  end

endmodule

sva_code:
module nios_system_switches_sva (
    input logic        clk,
    input logic        reset_n,    // active-low, async in RTL
    input logic [1:0]  address,
    input logic [9:0]  in_port,
    input logic [31:0] readdata
);
    // Clock: clk (posedge). Logic: combinational mux into a registered 32-bit output.

    // During reset, readdata must be cleared to 0.
    reset_clears_readdata: assert property (
        @(posedge clk) (!reset_n) |-> (readdata == 32'd0)
    );

    // After one cycle out of reset, upper 22 bits are always zero (zero-extension).
    upper_bits_zero_postreset: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[31:10] == 22'd0)
    );

    // After one cycle out of reset, LSBs equal prior-cycle muxed input: (address==0)? in_port : 0.
    lsb_matches_masked_in_port: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) |-> (readdata[9:0] == $past((address == 2'b00) ? in_port : 10'd0))
    );

    // When prior address was 0, full word is zero-extended prior in_port.
    full_word_zeroext_on_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) == 2'b00) |-> (readdata == {22'd0, $past(in_port)})
    );

    // When prior address was not 0, the full word must be zero.
    full_word_zero_when_addr_not00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && ($past(address) != 2'b00) |-> (readdata == 32'd0)
    );

    // Nonzero LSBs imply prior address selected the port (address==0).
    lsb_nonzero_implies_addr00: assert property (
        @(posedge clk) disable iff (!reset_n) $past(reset_n) && (readdata[9:0] != 10'd0) |-> ($past(address) == 2'b00)
    );
endmodule

module dff_clear_reset_sva (
    input logic clock,
    input logic clr,       // active-low synchronous clear
    input logic clr_val,   // load enable when high and clr is high
    input logic d,
    input logic q
);
    // Clear low drives q to 0 on the next clock.
    check_clear_forces_zero_next: assert property (
        @(posedge clock) (!clr) |=> (q == 1'b0)
    );

    // Clear has priority over load when both are asserted.
    check_clear_priority_over_load: assert property (
        @(posedge clock) (!clr && clr_val) |=> (q == 1'b0)
    );

    // With clr high and clr_val high, q loads d on the next clock.
    check_load_updates_q: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && clr_val) |=> (q == $past(d))
    );

    // With clr high and clr_val low, q holds its value.
    check_hold_when_no_load: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && !clr_val) |=> (q == $past(q))
    );

    // Any change on q must be caused by prior clear or prior load.
    check_q_changes_only_on_clear_or_load: assert property (
        @(posedge clock) disable iff ($initstate) $changed(q) |-> $past((!clr) || (clr && clr_val))
    );

    // After a cycle with clr low, q must be 0 on this cycle.
    check_zero_after_prior_clear: assert property (
        @(posedge clock) disable iff ($initstate) $past(!clr) |-> (q == 1'b0)
    );

    // D changes are ignored when not loading (clr high, clr_val low).
    check_ignore_d_when_no_load: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (!clr_val && $changed(d)) |=> (q == $past(q))
    );

    // Loading the same value leaves q unchanged across the boundary.
    check_load_same_value_no_change: assert property (
        @(posedge clock) disable iff ($initstate || !clr) (clr && clr_val && (d == q)) |=> (q == $past(q))
    );
endmodule

