module counter(clk, rst, up_down, enable, count);

    input clk;
    input rst;
    input up_down;
    input enable;
    output reg [3:0] count;

    always @(posedge clk) begin
        if (rst) begin
            count <= 4'b0;
        end
        else if (enable) begin
            if (up_down) begin
                count <= count + 1;
            end
            else begin
                count <= count - 1;
            end
        end
    end

endmodule

sva_code:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic up_down,
    input logic enable,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (synchronous, active-high). Logic: sequential up/down counter.

    // Reset drives count to zero on the following clock.
    reset_clears_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

    // While reset stays asserted across cycles, count remains zero.
    hold_zero_while_reset: assert property (
        @(posedge clk) rst && $past(rst,1,1'b0) |-> (count == 4'd0)
    );

    // With enable=0 (not in reset), count holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!enable) |=> $stable(count)
    );

    // With enable=1 and up_down=1, count increments by 1 modulo 16 on next cycle.
    increment_when_up: assert property (
        @(posedge clk) disable iff (rst) (enable && up_down) |=> (count == (($past(count,1,4'd0) + 4'd1) & 4'hF))
    );

    // With enable=1 and up_down=0, count decrements by 1 modulo 16 on next cycle.
    decrement_when_down: assert property (
        @(posedge clk) disable iff (rst) (enable && !up_down) |=> (count == (($past(count,1,4'd0) - 4'd1) & 4'hF))
    );

    // With enable=1 (not in reset), count must change on the next cycle.
    change_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (enable) |=> !$stable(count)
    );

    // If count changes (not in reset), enable must have been 1 in the previous cycle.
    change_implies_enable_prev: assert property (
        @(posedge clk) disable iff (rst) (count != $past(count,1,4'd0)) |-> $past(enable,1,1'b0)
    );

    // With enable=1, next value is either +1 or -1 modulo 16.
    next_is_pm1_when_enabled: assert property (
        @(posedge clk) disable iff (rst) (enable) |=> (
            (count == (($past(count,1,4'd0) + 4'd1) & 4'hF)) ||
            (count == (($past(count,1,4'd0) - 4'd1) & 4'hF))
        )
    );

endmodule

verilog_code:
module calculator(
  input clk,
  input reset,
  input [7:0] A,
  input [7:0] B,
  input [2:0] op,
  output reg [15:0] out
);

  always @(posedge clk) begin
    if(reset) begin
      out <= 16'h0000;
    end
    else begin
      case(op)
        3'b000: out <= A + B;
        3'b001: out <= A - B;
        3'b010: out <= A * B;
        3'b011: out <= A / B;
        default: out <= 16'h0000;
      endcase
    end
  end
endmodule

sva_code:
module calculator_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [2:0] op,
    input logic [15:0] out
);
    ///// Reset behavior /////
    // On reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 16'h0000)
    );

    ///// Operation decoding /////
    // When op==000 (ADD) and not in reset, out equals A + B.
    check_add_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b000) |-> (out == (A + B))
    );
    // When op==001 (SUB) and not in reset, out equals A - B.
    check_sub_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b001) |-> (out == (A - B))
    );
    // When op==010 (MUL) and not in reset, out equals A * B.
    check_mul_output: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b010) |-> (out == (A * B))
    );
    // When op==011 (DIV) with B!=0 and not in reset, out equals A / B.
    check_div_output_when_B_nonzero: assert property (
        @(posedge clk) disable iff (reset) (op == 3'b011 && B != 8'h00) |-> (out == (A / B))
    );
    // For any undefined op (100,101,110,111) and not in reset, out must be 0.
    check_default_zero: assert property (
        @(posedge clk) disable iff (reset) (op inside {3'b100,3'b101,3'b110,3'b111}) |-> (out == 16'h0000)
    );

    ///// Functional consistency /////
    // If inputs (A,B,op) are stable and not dividing by zero, out remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) disable iff (reset)
            $stable({A,B,op}) && !(op == 3'b011 && B == 8'h00) |-> $stable(out)
    );
endmodule

