module sky130_fd_sc_hd__and2b_sva (
    input logic clk,
    input logic X,
    input logic A_N,
    input logic B
);
    // X equals (~A_N) & B
    check_function_equation: assert property (
        @(posedge clk) X == ((~A_N) & B)
    );

    // When B is 0, X must be 0
    check_x_zero_when_b_zero: assert property (
        @(posedge clk) (B == 1'b0) |-> (X == 1'b0)
    );

    // When A_N is 1, X must be 0
    check_x_zero_when_a_n_one: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (X == 1'b0)
    );

    // When A_N is 0 and B is 1, X must be 1
    check_x_one_when_a0_b1: assert property (
        @(posedge clk) ((A_N == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

    // On B rising edge with A_N==0, X must be 1
    check_x_one_on_b_rise_when_a0: assert property (
        @(posedge clk) ($rose(B) && (A_N == 1'b0)) |-> (X == 1'b1)
    );

    // On B falling edge, X must be 0
    check_x_zero_on_b_fall: assert property (
        @(posedge clk) $fell(B) |-> (X == 1'b0)
    );

    // On A_N falling edge with B==1, X must be 1
    check_x_one_on_an_fall_when_b1: assert property (
        @(posedge clk) ($fell(A_N) && (B == 1'b1)) |-> (X == 1'b1)
    );

    // On A_N rising edge with B==1, X must be 0
    check_x_zero_on_an_rise_when_b1: assert property (
        @(posedge clk) ($rose(A_N) && (B == 1'b1)) |-> (X == 1'b0)
    );

    // X can only rise when B==1 and A_N==0
    check_x_rise_requires_b1_a0: assert property (
        @(posedge clk) $rose(X) |-> ((B == 1'b1) && (A_N == 1'b0))
    );

    // X can only fall when B==0 or A_N==1
    check_x_fall_requires_b0_or_a1: assert property (
        @(posedge clk) $fell(X) |-> ((B == 1'b0) || (A_N == 1'b1))
    );
endmodule

verilog_code:
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output reg [3:0] sum,
    output reg cout
);

  reg [4:0] temp_sum;
  reg temp_cout;

  always @* begin
    temp_sum = a + b + cin;
    sum = temp_sum[3:0];
    temp_cout = (temp_sum > 4'b1111);
    cout = temp_cout;
  end

endmodule

sva_code:
module four_bit_adder_sva (
    input logic clk,            // sampling clock for SVA (RTL is combinational)
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);
    // Analysis: No clock/reset in RTL; pure combinational; behavior: sum=(a+b+cin)[3:0], cout=((a+b+cin)>4'hF).

    // sum equals lower 4 bits of a+b+cin.
    check_sum_mod16: assert property (
        @(posedge clk) sum == (({1'b0,a} + {1'b0,b} + cin)[3:0])
    );

    // cout equals ((a+b+cin) > 4'hF) as written in the RTL.
    check_cout_comparator: assert property (
        @(posedge clk) cout == ((a + b + cin) > 4'hF)
    );

    // When no overflow in 5-bit addition, {cout,sum} equals the 5-bit sum.
    check_pair_no_overflow: assert property (
        @(posedge clk) (({1'b0,a} + {1'b0,b} + cin) <= 5'd15) |-> ({cout, sum} == ({1'b0,a} + {1'b0,b} + cin))
    );

    // Outputs remain stable when all inputs are stable (combinational purity).
    check_outputs_pure_function: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(cin)) |-> ($stable(sum) && $stable(cout))
    );

    // sum can only change if at least one input changed.
    check_sum_change_requires_input_change: assert property (
        @(posedge clk) (!$stable(sum)) |-> (!$stable(a) || !$stable(b) || !$stable(cin))
    );

    // cout can only change if at least one input changed.
    check_cout_change_requires_input_change: assert property (
        @(posedge clk) (!$stable(cout)) |-> (!$stable(a) || !$stable(b) || !$stable(cin))
    );

    // With b==0 and cin==0, sum passes a and cout is 0.
    check_transparency_b_zero_cin_zero: assert property (
        @(posedge clk) (b == 4'd0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

    // With a==0 and cin==0, sum passes b and cout is 0.
    check_transparency_a_zero_cin_zero: assert property (
        @(posedge clk) (a == 4'd0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

    // With a==0 and b==0, sum equals cin and cout is 0.
    check_sum_equals_cin_when_a_b_zero: assert property (
        @(posedge clk) (a == 4'd0 && b == 4'd0) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

    // Least-significant sum bit equals XOR of inputs' LSBs.
    check_sum_bit0_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

endmodule

verilog_code:
module clock_gate(clk, en, enclk, te);

  input clk;
  input en;
  input te;
  output enclk;

  reg gated_clk;

  always @(posedge clk) begin
    if (en) begin
      if (te) begin
        gated_clk <= 1'b1;
      end else begin
        gated_clk <= 1'b0;
      end
    end else begin
      gated_clk <= 1'b0;
    end
  end

  assign enclk = gated_clk & clk;

endmodule

sva_code:
module clock_gate_sva (
    input logic clk,
    input logic en,
    input logic te,
    input logic enclk
);
    // enclk must be LOW at each clk posedge (clk is LOW just before the edge).
    check_enclk_low_at_posedge: assert property (
        @(posedge clk) enclk == 1'b0
    );

    // During high phase, enclk equals en & te sampled at prior posedge.
    check_enclk_matches_latched_enable: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1)
            |-> (enclk == $past(en && te, 1, posedge clk))
    );

    // If en was LOW at posedge, enclk must be LOW this high phase.
    check_en_low_clears_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(en, 1, posedge clk) == 1'b0)
            |-> (enclk == 1'b0)
    );

    // If te was LOW at posedge, enclk must be LOW this high phase.
    check_te_low_clears_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(te, 1, posedge clk) == 1'b0)
            |-> (enclk == 1'b0)
    );

    // If both en and te were HIGH at posedge, enclk must be HIGH this high phase.
    check_both_high_sets_enclk: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && ($past(en && te, 1, posedge clk))
            |-> (enclk == 1'b1)
    );

    // A rising enclk at negedge implies en&te latched to 1 now and 0 previously.
    check_enclk_rise_cause: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && $rose(enclk)
            |-> ($past(en && te, 1, posedge clk) && !$past(en && te, 2, posedge clk))
    );

    // A falling enclk at negedge implies en&te latched to 0 now and 1 previously.
    check_enclk_fall_cause: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) && $fell(enclk)
            |-> (!$past(en && te, 1, posedge clk) && $past(en && te, 2, posedge clk))
    );

    // If en&te were 1 for two consecutive posedges, enclk stays HIGH across two negedges.
    check_enclk_stays_high_when_enable_stays_high: assert property (
        @(negedge clk)
            ($past(1'b1, 1, posedge clk) == 1'b1) &&
            $past(en && te, 1, posedge clk) && $past(en && te, 2, posedge clk)
