    // With EN held low across cycles, Y change matches B change.
    check_y_follows_b_when_en_held_low: assert property (
        @(posedge CLK) (!EN && !$past(EN)) |-> ($changed(Y) == $changed(B))
    );

endmodule

module comparator_2bit_sva (
    input logic [1:0] A,
    input logic [1:0] B,
    input logic       EQ
);
    // No explicit clock/reset in RTL; sample on any input/output edge.
    localparam dummy = 1'b0;

    // EQ must be 1 when A equals B (4-state equality).
    check_eq_when_equal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (A == B) |-> (EQ == 1'b1)
    );

    // EQ must be 0 when A does not equal B (4-state inequality is true).
    check_eq_low_when_unequal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (A != B) |-> (EQ == 1'b0)
    );

    // If EQ is 1, inputs must be equal.
    check_eq_one_implies_equal: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (EQ == 1'b1) |-> (A == B)
    );

    // Output is binary 0/1 (never X/Z at sampling times).
    check_output_is_binary: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        (EQ inside {1'b0, 1'b1})
    );

    // If inputs are stable, output must be stable (pure combinational behavior).
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        ($stable(A) && $stable(B)) |-> $stable(EQ)
    );

    // Output changes only if at least one input changed.
    check_output_change_requires_input_change: assert property (
        @(posedge A[0] or negedge A[0] or posedge A[1] or negedge A[1]
        or posedge B[0] or negedge B[0] or posedge B[1] or negedge B[1]
        or posedge EQ or negedge EQ)
        $changed(EQ) |-> (!$stable(A) || !$stable(B))
    );
endmodule

verilog_code:
module binary_adder_4bit(
    input [3:0] A, 
    input [3:0] B, 
    input CI, 
    input CLK, 
    output reg [3:0] SUM, 
    output CO
);

reg [4:0] C;

always @(posedge CLK) begin
    SUM <= A + B + C[3:0];
    C <= (A + B + C) > 4'b1111 ? 1 : 0;
end

assign CO = C[4];

endmodule

sva_code:
module binary_adder_4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic CLK,
    input logic [3:0] SUM,
    input logic CO
);
    // CO never has a rising edge (MSB of C is never driven to 1 by the RTL).
    check_co_never_rises: assert property (
        @(posedge CLK) !$rose(CO)
    );

    // If CO is HIGH now, it must be LOW on the next cycle.
    check_co_clears_next_if_high: assert property (
        @(posedge CLK) (CO == 1'b1) |=> (CO == 1'b0)
    );

    // Once CO is LOW, it remains LOW on the next cycle.
    check_co_low_sticky: assert property (
        @(posedge CLK) (CO == 1'b0) |=> (CO == 1'b0)
    );

    // From any time, CO becomes LOW within two cycles and thus cannot persist HIGH.
    check_co_eventually_low_within_two: assert property (
        @(posedge CLK) 1'b1 |-> ##[0:2] (CO == 1'b0)
    );

    // After any falling edge of CO, it stays LOW forever.
    check_co_stays_low_after_fall: assert property (
        @(posedge CLK) $fell(CO) |-> (CO == 1'b0)[*1:$]
    );

    // If A and B are zero for three consecutive cycles and CO is LOW at the first, SUM is zero on the third.
    check_sum_zero_after_three_zero_inputs_when_co_zero: assert property (
        @(posedge CLK)
            ((CO == 1'b0) && (A == 4'b0000) && (B == 4'b0000)) ##1
            ((A == 4'b0000) && (B == 4'b0000)) ##1
            ((A == 4'b0000) && (B == 4'b0000) && (SUM == 4'b0000))
    );
endmodule

