module mux(
    input in0,
    input in1,
    input sel,
    output out
);

assign out = sel ? in1 : in0;

endmodule

sva_code:
module mux_sva (
    // Note: RTL has no clock/reset; use CLK only for sampling assertions.
    input logic CLK,
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);
    // out equals selected input per mux function.
    check_mux_equivalence: assert property (
        @(posedge CLK) out == (sel ? in1 : in0)
    );

    // When sel is 0, out mirrors in0.
    check_sel0_path: assert property (
        @(posedge CLK) (sel == 1'b0) |-> (out == in0)
    );

    // When sel is 1, out mirrors in1.
    check_sel1_path: assert property (
        @(posedge CLK) (sel == 1'b1) |-> (out == in1)
    );

    // On a rising edge of sel, out equals in1 in the same cycle.
    check_sel_rise_selects_in1: assert property (
        @(posedge CLK) $rose(sel) |-> (out == in1)
    );

    // On a falling edge of sel, out equals in0 in the same cycle.
    check_sel_fall_selects_in0: assert property (
        @(posedge CLK) $fell(sel) |-> (out == in0)
    );

    // If inputs are equal, out equals that common value regardless of sel.
    check_inputs_equal_forces_out: assert property (
        @(posedge CLK) (in0 == in1) |-> (out == in0)
    );

    // If sel and both inputs are stable, out must be stable.
    check_no_spurious_change: assert property (
        @(posedge CLK) $stable(sel) && $stable(in0) && $stable(in1) |-> $stable(out)
    );

    // Out can change only if at least one of sel/in0/in1 changes.
    check_out_change_has_cause: assert property (
        @(posedge CLK) $changed(out) |-> ($changed(sel) || $changed(in0) || $changed(in1))
    );
endmodule

verilog_code:
module mux_2to1(
    input A,
    input B,
    input SEL,
    output Y
);

    assign Y = SEL ? B : A;

endmodule

sva_code:
module mux_2to1_sva (
    input  logic CLK,  // External sampling clock (RTL is pure combinational)
    input  logic A,
    input  logic B,
    input  logic SEL,
    input  logic Y
);
    // Core mux function: Y equals B when SEL=1, else A.
    check_mux_function: assert property (
        @(posedge CLK) Y == (SEL ? B : A)
    );

    // When SEL is 1, Y must equal B.
    check_sel1_routes_B: assert property (
        @(posedge CLK) SEL |-> (Y == B)
    );

    // When SEL is 0, Y must equal A.
    check_sel0_routes_A: assert property (
        @(posedge CLK) !SEL |-> (Y == A)
    );

    // If A and B are equal, Y must equal that value regardless of SEL.
    check_equal_inputs_passthrough: assert property (
        @(posedge CLK) (A == B) |-> (Y == A)
    );

    // If Y differs from A, then SEL must be 1 and Y must be B.
    check_y_not_a_implies_sel1_b: assert property (
        @(posedge CLK) (Y != A) |-> (SEL && (Y == B))
    );

    // If Y differs from B, then SEL must be 0 and Y must be A.
    check_y_not_b_implies_sel0_a: assert property (
        @(posedge CLK) (Y != B) |-> (!SEL && (Y == A))
    );

    // If Y equals A, then either SEL is 0 or inputs are equal.
    check_y_eq_a_implication: assert property (
        @(posedge CLK) (Y == A) |-> (!SEL || (A == B))
    );

    // If Y equals B, then either SEL is 1 or inputs are equal.
    check_y_eq_b_implication: assert property (
        @(posedge CLK) (Y == B) |-> (SEL || (A == B))
    );
endmodule

verilog_code:
module voltage_level_shifter (
    VPWR,
    VGND,
    VPB,
    VNB,
    VPB_OUT,
    VNB_OUT,
    VPWR_OUT,
    VGND_OUT
);

    input VPWR;
    input VGND;
    input VPB;
    input VNB;
    output VPB_OUT;
    output VNB_OUT;
    output VPWR_OUT;
    output VGND_OUT;

    assign VPWR_OUT = VPWR;
    assign VGND_OUT = VGND;

    assign VPB_OUT = (VPB == 1'b1) ? VPWR : VGND;
    assign VNB_OUT = (VNB == 1'b1) ? VPWR : VGND;

endmodule

sva_code:
module voltage_level_shifter_sva (
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic VPB_OUT,
    input logic VNB_OUT,
    input logic VPWR_OUT,
    input logic VGND_OUT
);
    // No clock/reset in DUT; combinational only. Sample on any edge of DUT inputs.

    // VPWR_OUT must equal VPWR.
    check_vpwr_passthrough: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPWR_OUT == VPWR)
    );

    // VGND_OUT must equal VGND.
    check_vgnd_passthrough: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VGND_OUT == VGND)
    );

    // When VPB is 1, VPB_OUT must equal VPWR.
    check_vpb_selects_vpwr_when_one: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == 1'b1) |-> (VPB_OUT == VPWR)
    );

    // When VPB is 0, VPB_OUT must equal VGND.
    check_vpb_selects_vgnd_when_zero: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == 1'b0) |-> (VPB_OUT == VGND)
    );

    // When VNB is 1, VNB_OUT must equal VPWR.
    check_vnb_selects_vpwr_when_one: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB == 1'b1) |-> (VNB_OUT == VPWR)
    );

    // When VNB is 0, VNB_OUT must equal VGND.
    check_vnb_selects_vgnd_when_zero: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB == 1'b0) |-> (VNB_OUT == VGND)
    );

    // VPB_OUT must be either VPWR or VGND.
    check_vpb_out_is_supply: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB_OUT == VPWR) || (VPB_OUT == VGND)
    );

    // VNB_OUT must be either VPWR or VGND.
    check_vnb_out_is_supply: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VNB_OUT == VPWR) || (VNB_OUT == VGND)
    );

    // If supplies are equal, all outputs must equal that value.
    check_equal_supplies_make_all_outs_equal: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPWR == VGND) |-> ((VPWR_OUT == VGND_OUT) && (VPB_OUT == VPWR) && (VNB_OUT == VPWR) && (VGND_OUT == VPWR))
    );

    // If VPB and VNB are equal, VPB_OUT and VNB_OUT must be equal.
    check_equal_controls_equal_body_outs: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        (VPB == VNB) |-> (VPB_OUT == VNB_OUT)
    );

    // If VPB!=VNB and supplies differ, VPB_OUT and VNB_OUT must differ.
    check_unequal_controls_and_supplies_give_diff_outs: assert property (
        @(posedge VPWR or negedge VPWR or posedge VGND or negedge VGND or posedge VPB or negedge VPB or posedge VNB or negedge VNB)
        ((VPB != VNB) && (VPWR != VGND)) |-> (VPB_OUT != VNB_OUT)
    );

endmodule

