module Freq_Divider#(
  parameter sys_clk = 50000000, // 50 MHz system clock
            clk_out = 1        // 1 Hz clock output
            )
  (Clk_in, Clk_out);

  // input ports
  input wire Clk_in;

  // output ports
  output reg Clk_out;

  // calculate the maximum counter size based on the input and output frequencies
  parameter max = sys_clk / (2*clk_out);

  // calculate the number of bits needed in the counter
  localparam N = $clog2(max);

  // counter
  reg [N-1:0] counter = 0;

  always @(posedge Clk_in) begin
    if (counter == max-1) begin
      counter <= 0;
      Clk_out <= ~Clk_out;
    end else begin
      counter <= counter + 1;
    end
  end

endmodule

sva_code:
module Freq_Divider_sva #(
    parameter int unsigned sys_clk = 50000000,
    parameter int unsigned clk_out = 1,
    parameter int unsigned max = sys_clk / (2*clk_out),
    parameter int unsigned N = $clog2(max)
) (
    input logic Clk_in,
    input logic Clk_out,
    input logic [N-1:0] counter
);
    // Clock: Clk_in (posedge). Reset: none.
    // Sequential counter; on max-1 -> counter=0 and Clk_out toggles; else counter++ and Clk_out holds.

    // When counter hits max-1, next cycle counter becomes 0.
    check_counter_resets_at_max: assert property (
        @(posedge Clk_in) (counter == max-1) |=> (counter == '0)
    );

    // When counter is not max-1, next cycle counter increments by 1.
    check_counter_increments_else: assert property (
        @(posedge Clk_in) (counter != max-1) |=> (counter == $past(counter) + 1'b1)
    );

    // When counter hits max-1, next cycle Clk_out toggles.
    check_clkout_toggles_at_max: assert property (
        @(posedge Clk_in) (counter == max-1) |=> (Clk_out == !$past(Clk_out))
    );

    // When counter is not max-1, next cycle Clk_out holds its value.
    check_clkout_holds_else: assert property (
        @(posedge Clk_in) (counter != max-1) |=> (Clk_out == $past(Clk_out))
    );

    // Any Clk_out change implies previous cycle counter was max-1.
    check_clkout_change_implies_prev_max: assert property (
        @(posedge Clk_in) $changed(Clk_out) |-> ($past(counter) == max-1)
    );

    // Any Clk_out change implies counter is 0 now.
    check_clkout_change_implies_counter_zero: assert property (
        @(posedge Clk_in) $changed(Clk_out) |-> (counter == '0)
    );

    // If Clk_out did not change, previous cycle counter was not max-1.
    check_no_change_implies_prev_not_max: assert property (
        @(posedge Clk_in) !$changed(Clk_out) |-> ($past(counter) != max-1)
    );

    // Counter updates every cycle (never holds its previous value).
    check_counter_always_updates: assert property (
        @(posedge Clk_in) 1'b1 |-> (counter != $past(counter))
    );

    // If counter is within range (< max), it remains within range next cycle.
    check_counter_range_invariant: assert property (
        @(posedge Clk_in) (counter < max) |=> (counter < max)
    );

    // No back-to-back Clk_out changes on consecutive cycles.
    check_no_back_to_back_clkout_change: assert property (
        @(posedge Clk_in) $changed(Clk_out) |=> !$changed(Clk_out)
    );
endmodule

module d_ff_async_reset_sva (
    input logic clk,
    input logic d,
    input logic r,
    input logic q
);
    // If reset is HIGH at a clock edge, q must be 0 on the next clock edge.
    check_reset_clears_next: assert property (
        @(posedge clk) r |-> ##1 (q == 1'b0)
    );

    // While reset is HIGH at consecutive sampled cycles, q is 0 now.
    check_q_zero_while_reset_held: assert property (
        @(posedge clk) (r && $past(r)) |-> (q == 1'b0)
    );

    // On a sampled falling edge of reset, q is 0 in that cycle.
    check_q_zero_on_reset_release_sample: assert property (
        @(posedge clk) $fell(r) |-> (q == 1'b0)
    );
endmodule

verilog_code:
module mbus_wire_ctrl(
	input RESETn,
	input DOUT_FROM_BUS,
	input CLKOUT_FROM_BUS,
	`ifdef POWER_GATING
	input DIN,
	input CLKIN,
	input RELEASE_ISO_FROM_SLEEP_CTRL,
	input EXTERNAL_INT,
	`endif
	output reg DOUT,
	output reg CLKOUT
);

`ifdef POWER_GATING
always @ *
begin
	if (~RESETn)
		CLKOUT <= 1'b1;
	else if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
		CLKOUT <= CLKIN;
	else
		CLKOUT <= CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= 1'b1;
	else if (EXTERNAL_INT)
		DOUT <= 0;
	else
	begin
		if (RELEASE_ISO_FROM_SLEEP_CTRL==`IO_HOLD)
			DOUT <= DIN;
		else
			DOUT <= DOUT_FROM_BUS;
	end
end
`else
always @ *
begin
	if (~RESETn)
		CLKOUT <= 1'b1;
	else
		CLKOUT <= CLKOUT_FROM_BUS;

	if (~RESETn)
		DOUT <= 1'b1;
	else
		DOUT <= DOUT_FROM_BUS;
end
`endif

endmodule

sva_code:
module mbus_wire_ctrl_sva (
    input logic RESETn,
    input logic DOUT_FROM_BUS,
    input logic CLKOUT_FROM_BUS,
`ifdef POWER_GATING
    input logic DIN,
    input logic CLKIN,
    input logic RELEASE_ISO_FROM_SLEEP_CTRL,
    input logic EXTERNAL_INT,
`endif
    input logic DOUT,
    input logic CLKOUT
);
    // During reset, outputs are forced HIGH.
    reset_outputs_high: assert property (
        @(posedge CLKOUT_FROM_BUS) !RESETn |-> (CLKOUT == 1'b1) && (DOUT == 1'b1)
    );

`ifdef POWER_GATING
    // When ISO hold is active, CLKOUT mirrors CLKIN.
    clkout_select_clkin_when_hold: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) |-> (CLKOUT == CLKIN)
    );
    // When not in ISO hold, CLKOUT mirrors CLKOUT_FROM_BUS.
    clkout_select_bus_when_not_hold: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) |-> (CLKOUT == CLKOUT_FROM_BUS)
    );
    // EXTERNAL_INT forces DOUT LOW.
    dout_forced_low_on_external_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        EXTERNAL_INT |-> (DOUT == 1'b0)
    );
    // Without EXTERNAL_INT and in ISO hold, DOUT mirrors DIN.
    dout_select_din_when_hold_no_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (!EXTERNAL_INT && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD)) |-> (DOUT == DIN)
    );
    // Without EXTERNAL_INT and not in ISO hold, DOUT mirrors DOUT_FROM_BUS.
    dout_select_bus_when_not_hold_no_int: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (!EXTERNAL_INT && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD)) |-> (DOUT == DOUT_FROM_BUS)
    );
    // If ISO hold and CLKIN are stable, CLKOUT is stable.
    clkout_stable_when_hold_and_clkin_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) && $stable(CLKIN)) |-> $stable(CLKOUT)
    );
    // If not in ISO hold and bus clock is stable, CLKOUT is stable.
    clkout_stable_when_not_hold_and_busclk_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) && $stable(CLKOUT_FROM_BUS)) |-> $stable(CLKOUT)
    );
    // If EXTERNAL_INT stays HIGH, DOUT stays LOW.
    dout_stable_low_when_extint_stable_high: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && EXTERNAL_INT) |-> ($stable(DOUT) && (DOUT == 1'b0))
    );
    // If no EXTERNAL_INT, ISO hold and DIN are stable, DOUT is stable.
    dout_stable_when_hold_no_int_and_din_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && !EXTERNAL_INT &&
         $stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL == `IO_HOLD) &&
         $stable(DIN)) |-> $stable(DOUT)
    );
    // If no EXTERNAL_INT, not in ISO hold and bus data is stable, DOUT is stable.
    dout_stable_when_not_hold_no_int_and_busdata_stable: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        ($stable(EXTERNAL_INT) && !EXTERNAL_INT &&
         $stable(RELEASE_ISO_FROM_SLEEP_CTRL) && (RELEASE_ISO_FROM_SLEEP_CTRL != `IO_HOLD) &&
         $stable(DOUT_FROM_BUS)) |-> $stable(DOUT)
    );
`else
    // When not in reset, CLKOUT mirrors CLKOUT_FROM_BUS.
    clkout_follows_bus_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (CLKOUT == CLKOUT_FROM_BUS)
    );
    // When not in reset, DOUT mirrors DOUT_FROM_BUS.
    dout_follows_bus_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        (DOUT == DOUT_FROM_BUS)
    );
    // If bus clock is stable, CLKOUT is stable.
    clkout_stable_when_busclk_stable_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        $stable(CLKOUT_FROM_BUS) |-> $stable(CLKOUT)
    );
    // If bus data is stable, DOUT is stable.
    dout_stable_when_busdata_stable_no_pg: assert property (
        @(posedge CLKOUT_FROM_BUS) disable iff (!RESETn)
        $stable(DOUT_FROM_BUS) |-> $stable(DOUT)
    );
`endif
endmodule

module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);
    // Clock: clk (posedge). Reset: rst (active-high, asynchronous). Logic: sequential counter with wrap to 0 at 15.

    // After reset deassertion, count is 0 on that sampled clock edge.
    check_count_zero_on_reset_release: assert property (
        @(posedge clk) disable iff (rst) $fell(rst) |-> (count == 4'd0)
    );

    // When not at max (15), count increments by 1 on the next clock.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != 4'hF) |=> (count == $past(count) + 4'd1)
    );

    // When at max (15), count wraps to 0 on the next clock.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'd0)
    );

    // Every cycle out of reset, the transition is either +1 or wrap-to-0 from 15.
    check_valid_transition_each_cycle: assert property (
        @(posedge clk) disable iff (rst)
            1'b1 |=> ((($past(count) != 4'hF) && (count == $past(count) + 4'd1)) ||
                      (($past(count) == 4'hF) && (count == 4'd0)))
    );

    // From reset release, the counter produces the full 0..15..0 sequence if reset stays low.
    check_full_sequence_from_reset_release: assert property (
        @(posedge clk) disable iff (rst)
            $fell(rst) |-> (count == 4'd0)
                        ##1 (count == 4'd1)
                        ##1 (count == 4'd2)
                        ##1 (count == 4'd3)
                        ##1 (count == 4'd4)
                        ##1 (count == 4'd5)
                        ##1 (count == 4'd6)
                        ##1 (count == 4'd7)
                        ##1 (count == 4'd8)
                        ##1 (count == 4'd9)
                        ##1 (count == 4'd10)
                        ##1 (count == 4'd11)
                        ##1 (count == 4'd12)
                        ##1 (count == 4'd13)
                        ##1 (count == 4'd14)
                        ##1 (count == 4'd15)
                        ##1 (count == 4'd0)
    );

endmodule

