module gray_counter_sva (
    input logic clk,
    input logic reset, // Synchronous active-high reset
    input logic up_down,
    input logic enable,
    input logic [1:0] counter_out,
    input logic [1:0] gray_out
);

    ///// Counter sequencing rules /////
    // On a reset clock edge, counter_out synchronously clears to 0.
    reset_clears_counter: assert property (
        @(posedge clk) reset |-> (counter_out == 2'b00)
    );

    // When enable is LOW, counter_out holds its value to the next cycle.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (counter_out == $past(counter_out))
    );

    // When enable is HIGH and up_down is HIGH, next counter_out increments by 1 (mod 4).
    increment_when_up: assert property (
        @(posedge clk) disable iff (reset) (enable && up_down) |=> (counter_out == $past(counter_out) + 2'b01)
    );

    // When enable is HIGH and up_down is LOW, next counter_out decrements by 1 (mod 4).
    decrement_when_down: assert property (
        @(posedge clk) disable iff (reset) (enable && !up_down) |=> (counter_out == $past(counter_out) - 2'b01)
    );

    // When enable is HIGH, the counter must change value on the next cycle.
    enabled_causes_change: assert property (
        @(posedge clk) disable iff (reset) enable |=> (counter_out != $past(counter_out))
    );

    // For any enabled cycle, the next value matches the selected direction.
    enabled_update_matches_dir: assert property (
        @(posedge clk) disable iff (reset) enable |=> (
            (up_down && (counter_out == $past(counter_out) + 2'b01)) ||
            (!up_down && (counter_out == $past(counter_out) - 2'b01))
        )
    );

    ///// Gray converter mapping (combinational) /////
    // Mapping for counter_out == 2'b00.
    gray_map_00: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b00) |-> (gray_out == 2'b00)
    );

    // Mapping for counter_out == 2'b01.
    gray_map_01: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b01) |-> (gray_out == 2'b01)
    );

    // Mapping for counter_out == 2'b10.
    gray_map_10: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b10) |-> (gray_out == 2'b10)
    );

    // Mapping for counter_out == 2'b11.
    gray_map_11: assert property (
        @(posedge clk) disable iff (reset) (counter_out == 2'b11) |-> (gray_out == 2'b11)
    );

endmodule

verilog_code:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    // Full adder for bit 0
    full_adder fa0(A[0], B[0], Cin, sum[0], carry[0]);

    // Full adder for bit 1
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);

    // Full adder for bit 2
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);

    // Full adder for bit 3
    full_adder fa3(A[3], B[3], carry[2], sum[3], Cout);

    assign S = sum;

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output carry
);

    assign sum = a ^ b ^ cin;
    assign carry = (a & b) | (a & cin) | (b & cin);

endmodule

sva_code:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);
    // Helper carry chain computed from inputs
    logic c0, c1, c2;
    assign c0 = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);
    assign c1 = (A[1] & B[1]) | (A[1] & c0)  | (B[1] & c0);
    assign c2 = (A[2] & B[2]) | (A[2] & c1)  | (B[2] & c1);

    // 5-bit full sum for equivalence checking
    logic [4:0] fullsum;
    assign fullsum = {1'b0, A} + {1'b0, B} + Cin;

    ///// Bit-level full-adder relationships /////
    // LSB sum equals XOR of inputs A[0], B[0], Cin.
    check_sum0_xor: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Bit1 sum equals XOR of A[1], B[1], and carry from bit0.
    check_sum1_xor: assert property (
        @(posedge CLK) S[1] == (A[1] ^ B[1] ^ c0)
    );

    // Bit2 sum equals XOR of A[2], B[2], and carry from bit1.
    check_sum2_xor: assert property (
        @(posedge CLK) S[2] == (A[2] ^ B[2] ^ c1)
    );

    // Bit3 sum equals XOR of A[3], B[3], and carry from bit2.
    check_sum3_xor: assert property (
        @(posedge CLK) S[3] == (A[3] ^ B[3] ^ c2)
    );

    // Carry-out equals majority of A[3], B[3], and carry from bit2.
    check_cout_majority: assert property (
        @(posedge CLK) Cout == ((A[3] & B[3]) | (A[3] & c2) | (B[3] & c2))
    );

    ///// Whole-adder equivalence /////
    // {Cout,S} equals 5-bit sum of A, B, and Cin.
    check_fullsum_concat: assert property (
        @(posedge CLK) {Cout, S} == fullsum
    );

    // S equals lower 4 bits of the 5-bit sum.
    check_s_matches_fullsum_lower: assert property (
        @(posedge CLK) S == fullsum[3:0]
    );

    // Cout equals MSB of the 5-bit sum.
    check_cout_matches_fullsum_msb: assert property (
        @(posedge CLK) Cout == fullsum[4]
    );

    ///// Sanity corner cases /////
    // When A and B are zero, S mirrors Cin on bit0 and Cout is zero.
    check_zero_inputs_behavior: assert property (
        @(posedge CLK) (A == 4'b0000 && B == 4'b0000) |=> (S == {3'b000, Cin}) && (Cout == 1'b0)
    );

    // When A and B are all ones, Cout is one and S depends on Cin.
    check_all_ones_behavior: assert property (
        @(posedge CLK) (A == 4'hF && B == 4'hF) |=> (Cout == 1'b1) && (S == (Cin ? 4'hF : 4'hE))
    );
endmodule

