module counter (
    input clk,
    input rst,
    input [31:0] max_val,
    output reg [31:0] count
);

always @(posedge clk) begin
    if (rst) begin
        count <= 0;
    end else if (count == max_val) begin
        count <= 0;
    end else begin
        count <= count + 1;
    end
end

endmodule

sva_code:
module counter_sva (
    input logic clk,
    input logic rst,
    input logic [31:0] max_val,
    input logic [31:0] count
);
    // Reset drives count to 0 on the next rising edge.
    reset_clears_count_next: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

    // When count equals max_val (no reset), next value is 0.
    wrap_to_zero_on_max: assert property (
        @(posedge clk) disable iff (rst) (count == max_val) |=> (count == 32'd0)
    );

    // When count is not max_val (no reset), next value increments by 1.
    increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst) (count != max_val) |=> (count == $past(count) + 32'd1)
    );

    // Next value function is exactly: (count==max_val) ? 0 : count+1 (no reset).
    deterministic_update: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (count == (($past(count) == $past(max_val)) ? 32'd0 : $past(count) + 32'd1))
    );

    // If not due to reset, a 0 value must come from prior equality to max or overflow.
    zero_implies_prev_eq_max_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> ((count == 32'd0 && !$past(rst)) -> ($past(count) == $past(max_val) || $past(count) == 32'hFFFF_FFFF))
    );

    // If previous count was neither max_val nor 32'hFFFF_FFFF (no reset), next count is not 0.
    no_zero_without_eq_or_overflow: assert property (
        @(posedge clk) disable iff (rst) 1 |=> (($past(count) != $past(max_val) && $past(count) != 32'hFFFF_FFFF) -> (count != 32'd0))
    );
endmodule

verilog_code:
module mux_parity (
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output [3:0] out,
  output parity
);

  wire [3:0] mux_out [0:5];
  wire [2:0] sel_dec [0:7];

  // Generate intermediate signals for each input data
  assign mux_out[0] = (sel_dec[0]) ? data0 : 4'b0;
  assign mux_out[1] = (sel_dec[1]) ? data1 : 4'b0;
  assign mux_out[2] = (sel_dec[2]) ? data2 : 4'b0;
  assign mux_out[3] = (sel_dec[3]) ? data3 : 4'b0;
  assign mux_out[4] = (sel_dec[4]) ? data4 : 4'b0;
  assign mux_out[5] = (sel_dec[5]) ? data5 : 4'b0;

  // Generate select signals using a 3-to-8 decoder
  assign sel_dec[0] = (sel == 3'b000);
  assign sel_dec[1] = (sel == 3'b001);
  assign sel_dec[2] = (sel == 3'b010);
  assign sel_dec[3] = (sel == 3'b011);
  assign sel_dec[4] = (sel == 3'b100);
  assign sel_dec[5] = (sel == 3'b101);
  assign sel_dec[6] = 1'b0;
  assign sel_dec[7] = 1'b0;

  // Select the active input data using an 8-input OR gate
  assign out = mux_out[0] | mux_out[1] | mux_out[2] | mux_out[3] | mux_out[4] | mux_out[5];

  // Generate the parity bit using an XOR gate
  assign parity = out[0] ^ out[1] ^ out[2] ^ out[3];

endmodule

sva_code:
module mux_parity_sva (
  input logic clk,
  input logic [2:0] sel,
  input logic [3:0] data0,
  input logic [3:0] data1,
  input logic [3:0] data2,
  input logic [3:0] data3,
  input logic [3:0] data4,
  input logic [3:0] data5,
  input logic [3:0] out,
  input logic parity
);

  // Mux output equals sum-of-products of data inputs gated by sel
  check_mux_sum_of_products: assert property (
    @(posedge clk)
      out == (
        ((sel == 3'b000) ? data0 : 4'b0) |
        ((sel == 3'b001) ? data1 : 4'b0) |
        ((sel == 3'b010) ? data2 : 4'b0) |
        ((sel == 3'b011) ? data3 : 4'b0) |
        ((sel == 3'b100) ? data4 : 4'b0) |
        ((sel == 3'b101) ? data5 : 4'b0)
      )
  );

  // When sel=000, out equals data0
  check_sel0_route: assert property (
    @(posedge clk) (sel == 3'b000) |-> (out == data0)
  );

  // When sel=001, out equals data1
  check_sel1_route: assert property (
    @(posedge clk) (sel == 3'b001) |-> (out == data1)
  );

  // When sel=010, out equals data2
  check_sel2_route: assert property (
    @(posedge clk) (sel == 3'b010) |-> (out == data2)
  );

  // When sel=011, out equals data3
  check_sel3_route: assert property (
    @(posedge clk) (sel == 3'b011) |-> (out == data3)
  );

  // When sel=100, out equals data4
  check_sel4_route: assert property (
    @(posedge clk) (sel == 3'b100) |-> (out == data4)
  );

  // When sel=101, out equals data5
  check_sel5_route: assert property (
    @(posedge clk) (sel == 3'b101) |-> (out == data5)
  );

  // For invalid sel (110 or 111), out is zero
  check_invalid_sel_out_zero: assert property (
    @(posedge clk) (sel inside {3'b110,3'b111}) |-> (out == 4'b0000)
  );

  // Parity equals XOR of out bits
  check_parity_from_out: assert property (
    @(posedge clk) parity == (out[0] ^ out[1] ^ out[2] ^ out[3])
  );

  // For invalid sel, parity is zero (since out is zero)
  check_invalid_sel_parity_zero: assert property (
    @(posedge clk) (sel inside {3'b110,3'b111}) |-> (parity == 1'b0)
  );

endmodule

