        @(posedge A1 or posedge A2 or posedge B1_N or
          negedge A1 or negedge A2 or negedge B1_N)
        disable iff (1'b0)
        (B1_N == 1'b1) |-> (Y == 1'b1)
    );

    // If B1_N is LOW and A1 is HIGH, Y must be LOW.
    check_b1n_low_a1_high_y_low: assert property (
        @(posedge A1 or posedge A2 or posedge B1_N or
          negedge A1 or negedge A2 or negedge B1_N)
        disable iff (1'b0)
        ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (Y == 1'b0)
