module xor_gate_lut(
    input a,
    input b,
    output reg out_lut
);

    always @(*)
    begin
        case ({a,b})
            2'b00: out_lut = 1'b0;
            2'b01: out_lut = 1'b1;
            2'b10: out_lut = 1'b1;
            2'b11: out_lut = 1'b0;
        endcase
    end

endmodule

sva_code:
module xor_gate_lut_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic out_lut
);
    // Output equals XOR of inputs each cycle.
    check_out_eq_xor: assert property (
        @(posedge CLK) (out_lut == (a ^ b))
    );

    // Truth table: 00 -> 0.
    check_case_00: assert property (
        @(posedge CLK) ({a,b} == 2'b00) |-> (out_lut == 1'b0)
    );
    // Truth table: 01 -> 1.
    check_case_01: assert property (
        @(posedge CLK) ({a,b} == 2'b01) |-> (out_lut == 1'b1)
    );
    // Truth table: 10 -> 1.
    check_case_10: assert property (
        @(posedge CLK) ({a,b} == 2'b10) |-> (out_lut == 1'b1)
    );
    // Truth table: 11 -> 0.
    check_case_11: assert property (
        @(posedge CLK) ({a,b} == 2'b11) |-> (out_lut == 1'b0)
    );

    // When b is 0, output passes a.
    check_b0_passthrough: assert property (
        @(posedge CLK) (b == 1'b0) |-> (out_lut == a)
    );
    // When b is 1, output is inverted a.
    check_b1_invert: assert property (
        @(posedge CLK) (b == 1'b1) |-> (out_lut == ~a)
    );

    // When a is 0, output passes b.
    check_a0_passthrough: assert property (
        @(posedge CLK) (a == 1'b0) |-> (out_lut == b)
    );
    // When a is 1, output is inverted b.
    check_a1_invert: assert property (
        @(posedge CLK) (a == 1'b1) |-> (out_lut == ~b)
    );

    // If inputs are stable between samples, output is stable.
    check_stability: assert property (
        @(posedge CLK) ($stable(a) && $stable(b)) |-> $stable(out_lut)
    );

    // Output change parity equals XOR of input changes between samples.
    check_change_parity: assert property (
        @(posedge CLK) ($changed(out_lut) == ($changed(a) ^ $changed(b)))
    );
endmodule

module combinational_logic_sva (
    input A1,
    input A2,
    input A3,
    input B1,
    input VPB,
    input X,
    input VPWR,
    input VGND,
    input VNB
);
    ///// Combinational function checks (clocked on A1 for sampling) /////
    // X matches the defined boolean function of inputs.
    check_x_function_equivalence: assert property (
        @(posedge A1) X == ((A1 && A2 && A3) || (B1 && VPB))
    );

    // When all A inputs are HIGH, X must be HIGH.
    check_a_term_drives_x: assert property (
        @(posedge A1) (A1 && A2 && A3) |-> (X == 1'b1)
    );

    // When B1 and VPB are HIGH, X must be HIGH.
    check_b_term_drives_x: assert property (
        @(posedge A1) (B1 && VPB) |-> (X == 1'b1)
    );

    // When both product terms are LOW, X must be LOW.
    check_x_zero_when_no_term: assert property (
        @(posedge A1) (!((A1 && A2 && A3) || (B1 && VPB))) |-> (X == 1'b0)
    );

    // If X is HIGH, at least one product term must be HIGH.
    check_x_high_implies_term_true: assert property (
        @(posedge A1) X |-> ((A1 && A2 && A3) || (B1 && VPB))
    );

    // If X is LOW, both product terms must be LOW.
    check_x_low_implies_both_terms_low: assert property (
        @(posedge A1) (!X) |-> (!((A1 && A2 && A3)) && !(B1 && VPB))
    );
endmodule

