    // If A, SLEEP_B, VPWR, and KAGND are all HIGH then X must be HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge CLK) (A && SLEEP_B && VPWR && KAGND) |-> (X == 1'b1)
    );

