module BitShifting_sva (
    input logic CLK,
    input logic [31:0] a,
    input logic [4:0] n,
    input logic [31:0] b
);
    // When n==0, output passes through input a.
    check_passthrough_when_n_zero: assert property (
        @(posedge CLK) (n == 5'd0) |-> (b == a)
    );

    // When n>0, output equals a left-shifted by n.
    check_shift_when_n_positive: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b == (a << n))
    );

    // When n>0, the lower n bits of b are zero after left shift.
    check_lower_bits_zero_after_shift: assert property (
        @(posedge CLK) (n > 5'd0) |-> ((b & (((32'h1 << n) - 32'h1))) == 32'h0)
    );

    // When n>0, bit b[n] equals a[0] after left shift.
    check_bit_n_equals_a0: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[n] == a[0])
    );

    // When n>0, MSB of b equals a[31-n].
    check_msb_matches_source_bit: assert property (
        @(posedge CLK) (n > 5'd0) |-> (b[31] == a[31 - n])
    );

    // If n hypothetically exceeded 31, b would be forced to zero per RTL branch.
    check_large_n_forces_zero: assert property (
        @(posedge CLK) (n > 5'd31) |-> (b == 32'h0)
    );

    // If a is zero, b is zero regardless of n.
    check_zero_input_produces_zero_output: assert property (
        @(posedge CLK) (a == 32'h0) |-> (b == 32'h0)
    );

    // If a is stable and n increments by 1 (and was <31), b shifts left by 1 from prior b.
    check_incremental_n_shifts_output: assert property (
        @(posedge CLK) ($past(a) === a) && ($past(n) < 5'd31) && (n == ($past(n) + 5'd1)) |-> (b == ($past(b) << 1))
    );

    // If a and n are stable, b remains stable (pure combinational function).
    check_stable_inputs_keep_output_stable: assert property (
        @(posedge CLK) $stable(a) && $stable(n) |-> $stable(b)
    );

    // For n==31, b equals {a[0], 31'b0}.
    check_shift_by_31_behavior: assert property (
        @(posedge CLK) (n == 5'd31) |-> (b == {a[0], 31'b0})
    );
endmodule

verilog_code:
module binary_adder (
  input [3:0] A,
  input [3:0] B,
  output [3:0] sum,
  output C_out
);

  wire [3:0] temp_sum;
  wire C1, C2, C3;

  // Full adder for bit 0
  full_adder FA0(A[0], B[0], 1'b0, temp_sum[0], C1);

  // Full adder for bit 1
  full_adder FA1(A[1], B[1], C1, temp_sum[1], C2);

  // Full adder for bit 2
  full_adder FA2(A[2], B[2], C2, temp_sum[2], C3);

  // Full adder for bit 3
  full_adder FA3(A[3], B[3], C3, temp_sum[3], C_out);

  assign sum = temp_sum;

endmodule

module full_adder (
  input A,
  input B,
  input C_in,
  output sum,
  output C_out
);

  assign sum = A ^ B ^ C_in;
  assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva_code:
module binary_adder_sva (
    input  logic        clk,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic [3:0]  sum,
    input  logic        C_out
);

    // Sum and carry-out must match 5-bit addition of A and B.
    check_full_sum: assert property (
        @(posedge clk) {C_out, sum} == ({1'b0, A} + {1'b0, B})
    );

    // Carry-out equals the overflow bit of the 5-bit addition.
    check_cout_overflow_bit: assert property (
        @(posedge clk) C_out == ({1'b0, A} + {1'b0, B})[4]
    );

    // Sum equals the low 4 bits of the 5-bit addition.
    check_sum_low4: assert property (
        @(posedge clk) sum == ({1'b0, A} + {1'b0, B})[3:0]
    );

    // LSB sum bit equals A[0] XOR B[0].
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (A[0] ^ B[0])
    );

    // sum[1] equals A[1] XOR B[1] XOR carry from bit0 (A[0]&B[0]).
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // sum[2] equals A[2] XOR B[2] XOR carry from bit1.
    check_sum_bit2: assert property (
        @(posedge clk)
            sum[2] ==
            ((A[2] ^ B[2]) ^
             ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // sum[3] equals A[3] XOR B[3] XOR carry from bit2.
    check_sum_bit3: assert property (
        @(posedge clk)
            sum[3] ==
            ((A[3] ^ B[3]) ^
             ((A[2] & B[2]) |
              ((A[2] ^ B[2]) & (A[1] & B[1])) |
              ((A[2] ^ B[2]) & (A[1] ^ B[1]) & (A[0] & B[0]))))
    );

    // Carry-out equals ripple-carry expression using generate/propagate.
    check_cout_formula: assert property (
        @(posedge clk)
            C_out ==
            ((A[3] & B[3]) |
             ((A[3] ^ B[3]) & (A[2] & B[2])) |
             ((A[3] ^ B[3]) & (A[2] ^ B[2]) & (A[1] & B[1])) |
             ((A[3] ^ B[3]) & (A[2] ^ B[2]) & (A[1] ^ B[1]) & (A[0] & B[0])))
    );

    // Adding zero on B leaves sum = A and C_out = 0.
    check_add_zero_B: assert property (
        @(posedge clk) (B == 4'b0000) |-> (sum == A) && (C_out == 1'b0)
    );

    // Adding zero on A leaves sum = B and C_out = 0.
    check_add_zero_A: assert property (
        @(posedge clk) (A == 4'b0000) |-> (sum == B) && (C_out == 1'b0)
    );

    // If both MSBs are 0, carry-out must be 0.
    check_no_carry_when_msb00: assert property (
        @(posedge clk) (!A[3] && !B[3]) |-> (C_out == 1'b0)
    );

    // If both MSBs are 1, carry-out must be 1.
    check_carry_when_msb11: assert property (
        @(posedge clk) (A[3] && B[3]) |-> (C_out == 1'b1)
    );

endmodule

module add_sub_8bit_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic sub,
    input logic [7:0] out
);
    // DUT has no clock/reset; pure combinational datapath. Sample properties on external clk.
    // Function: out = (sub ? A - B : A + B).

    // Out matches selected operation for all input combinations.
    check_out_matches_operation: assert property (
        @(posedge clk) out == (sub ? (A - B) : (A + B))
    );

    // With stable inputs, output remains stable (pure combinational function).
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(sub)) |-> $stable(out)
    );

    // In add mode, adding zero passes through A.
    check_add_zero_B: assert property (
        @(posedge clk) (sub == 1'b0 && B == 8'h00) |-> (out == A)
    );

    // In add mode, adding zero-A passes through B.
    check_add_zero_A: assert property (
        @(posedge clk) (sub == 1'b0 && A == 8'h00) |-> (out == B)
    );

    // In sub mode, subtracting zero passes through A.
    check_sub_zero_B: assert property (
        @(posedge clk) (sub == 1'b1 && B == 8'h00) |-> (out == A)
    );

    // In sub mode, subtracting equal operands yields zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (sub == 1'b1 && (A == B)) |-> (out == 8'h00)
    );

    // On sub rising edge with A,B stable, output equals A - B.
    check_out_on_sub_rise: assert property (
        @(posedge clk) ($rose(sub) && $stable(A) && $stable(B)) |-> (out == (A - B))
    );

    // On sub falling edge with A,B stable, output equals A + B.
    check_out_on_sub_fall: assert property (
        @(posedge clk) ($fell(sub) && $stable(A) && $stable(B)) |-> (out == (A + B))
    );

    // In add mode, addition is commutative with respect to A and B.
    check_add_commutative: assert property (
        @(posedge clk) (sub == 1'b0) |-> (out == (B + A))
    );
endmodule

