verilog_code:
module Control(
    input [5:0] opcode,
    input clk,
    output reg reg_dst,
    output reg jump,
    output reg branch,
    output reg ctrl_mem_read,
    output reg mem_to_reg,
    output reg ctrl_mem_write,
    output reg alu_src,
    output reg reg_write,
    output reg [1:0] alu_op
    );

always@(posedge clk)
begin

{reg_dst, alu_src, mem_to_reg, reg_write, ctrl_mem_read, ctrl_mem_write, branch, jump, alu_op} = 10'b0000000000;

if (opcode == 6'b000000) begin
    reg_dst <= 1;
    reg_write <= 1;
    alu_op <= 2'b10;
end


else if (opcode == 6'b100011) begin
    alu_src <= 1;
    mem_to_reg <= 1;
    reg_write <= 1;
    ctrl_mem_read <= 1;
end

else if (opcode == 6'b101011) begin
    alu_src <= 1;
    ctrl_mem_write <= 1;
end

else if (opcode == 6'b000100) begin
    branch <= 1;
    alu_op <= 2'b01;
end

if (opcode == 6'b001000) begin
    alu_src <= 1;
    reg_write <= 1;
    end

else if (opcode == 6'b000010) begin
    jump <= 1;
end

end
endmodule

sva_code:
module Control_sva (
    input logic [5:0] opcode,
    input logic clk,
    input logic reg_dst,
    input logic jump,
    input logic branch,
    input logic ctrl_mem_read,
    input logic mem_to_reg,
    input logic ctrl_mem_write,
    input logic alu_src,
    input logic reg_write,
    input logic [1:0] alu_op
);

    // R-type decode from previous opcode cycle.
    decode_rtype: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b000000)
            |-> (reg_dst == 1'b1 && alu_src == 1'b0 && mem_to_reg == 1'b0 && reg_write == 1'b1 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b0 && branch == 1'b0 && jump == 1'b0 && alu_op == 2'b10)
    );

    // LW decode from previous opcode cycle.
    decode_lw: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b100011)
            |-> (reg_dst == 1'b0 && alu_src == 1'b1 && mem_to_reg == 1'b1 && reg_write == 1'b1 &&
                 ctrl_mem_read == 1'b1 && ctrl_mem_write == 1'b0 && branch == 1'b0 && jump == 1'b0 && alu_op == 2'b00)
    );

    // SW decode from previous opcode cycle.
    decode_sw: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b101011)
            |-> (reg_dst == 1'b0 && alu_src == 1'b1 && mem_to_reg == 1'b0 && reg_write == 1'b0 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b1 && branch == 1'b0 && jump == 1'b0 && alu_op == 2'b00)
    );

    // BEQ decode from previous opcode cycle.
    decode_beq: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b000100)
            |-> (reg_dst == 1'b0 && alu_src == 1'b0 && mem_to_reg == 1'b0 && reg_write == 1'b0 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b0 && branch == 1'b1 && jump == 1'b0 && alu_op == 2'b01)
    );

    // ADDI decode from previous opcode cycle.
    decode_addi: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b001000)
            |-> (reg_dst == 1'b0 && alu_src == 1'b1 && mem_to_reg == 1'b0 && reg_write == 1'b1 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b0 && branch == 1'b0 && jump == 1'b0 && alu_op == 2'b00)
    );

    // JUMP decode from previous opcode cycle.
    decode_jump: assert property (
        @(posedge clk)
            ($past(opcode) == 6'b000010)
            |-> (reg_dst == 1'b0 && alu_src == 1'b0 && mem_to_reg == 1'b0 && reg_write == 1'b0 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b0 && branch == 1'b0 && jump == 1'b1 && alu_op == 2'b00)
    );

    // Unrecognized opcode in previous cycle drives all controls low and ALUop=00.
    decode_default_other: assert property (
        @(posedge clk)
            ($past(opcode) != 6'b000000) && ($past(opcode) != 6'b100011) && ($past(opcode) != 6'b101011) &&
            ($past(opcode) != 6'b000100) && ($past(opcode) != 6'b001000) && ($past(opcode) != 6'b000010)
            |-> (reg_dst == 1'b0 && alu_src == 1'b0 && mem_to_reg == 1'b0 && reg_write == 1'b0 &&
                 ctrl_mem_read == 1'b0 && ctrl_mem_write == 1'b0 && branch == 1'b0 && jump == 1'b0 && alu_op == 2'b00)
    );

    // Read and write to memory are never asserted together.
    check_mem_rw_mutex: assert property (
        @(posedge clk) (!$isunknown({ctrl_mem_read, ctrl_mem_write})) |-> !(ctrl_mem_read && ctrl_mem_write)
    );

    // mem_to_reg matches mem_read behavior (both high only for LW).
    check_mem_to_reg_eq_mem_read: assert property (
        @(posedge clk) (!$isunknown({mem_to_reg, ctrl_mem_read})) |-> (mem_to_reg == ctrl_mem_read)
    );

    // ALU operation is only 00, 01, or 10 (never 11).
    check_alu_op_range: assert property (
        @(posedge clk) (!$isunknown(alu_op)) |-> (alu_op != 2'b11)
    );

endmodule

verilog_code:
module mux4to1_4bit(Y, A, B, C, D, S0, S1);

    input [3:0] A, B, C, D;
    input S0, S1;
    output [3:0] Y;

    wire [3:0] AB, CD, Y_temp;

    assign AB = (S0 & ~S1) ? B : A;
    assign CD = (S0 & S1) ? D : C;
    assign Y_temp = (S0 | S1) ? CD : AB;
    assign Y = Y_temp;

endmodule

sva_code:
module mux4to1_4bit_sva (
    input  logic CLK,
    input  logic [3:0] A,
    input  logic [3:0] B,
    input  logic [3:0] C,
    input  logic [3:0] D,
    input  logic       S0,
    input  logic       S1,
    input  logic [3:0] Y
);
    // Exact functional equivalence to the RTL expression.
    check_function_equivalence: assert property (
        @(posedge CLK) Y == ((S0 | S1) ? ((S0 & S1) ? D : C) : ((S0 & ~S1) ? B : A))
    );

    // When S1=0,S0=0, Y must equal A.
    check_sel_00_to_A: assert property (
        @(posedge CLK) (S1 == 1'b0 && S0 == 1'b0) |-> (Y == A)
    );

    // When S1=0,S0=1, Y must equal C.
    check_sel_01_to_C: assert property (
        @(posedge CLK) (S1 == 1'b0 && S0 == 1'b1) |-> (Y == C)
    );

    // When S1=1,S0=0, Y must equal C.
    check_sel_10_to_C: assert property (
        @(posedge CLK) (S1 == 1'b1 && S0 == 1'b0) |-> (Y == C)
    );

    // When S1=1,S0=1, Y must equal D.
    check_sel_11_to_D: assert property (
        @(posedge CLK) (S1 == 1'b1 && S0 == 1'b1) |-> (Y == D)
    );

    // When exactly one select is HIGH, Y must equal C.
    check_xor_select_to_C: assert property (
        @(posedge CLK) (S0 ^ S1) |-> (Y == C)
    );

    // When any select is HIGH, Y must be C or D per S0&S1.
    check_or_select_rule: assert property (
        @(posedge CLK) (S0 | S1) |-> (Y == ((S0 & S1) ? D : C))
    );

    // When both selects are LOW, Y must equal A.
    check_nor_select_to_A: assert property (
        @(posedge CLK) !(S0 | S1) |-> (Y == A)
    );

    // Changing B alone must not affect Y (B is never selected).
    check_B_irrelevant: assert property (
        @(posedge CLK)
            ($changed(B) && $stable(A) && $stable(C) && $stable(D) && $stable(S0) && $stable(S1)) |-> $stable(Y)
    );

    // With selects pointing to C or D (S0|S1==1), changing A alone must not affect Y.
    check_A_irrelevant_when_or1: assert property (
        @(posedge CLK)
            ((S0 | S1) && $stable(S0) && $stable(S1) && $changed(A) && $stable(B) && $stable(C) && $stable(D)) |-> $stable(Y)
    );

    // With selects at 00, changing C alone must not affect Y (Y=A).
    check_C_irrelevant_when_00: assert property (
        @(posedge CLK)
            ((S1 == 1'b0 && S0 == 1'b0) && $stable(S0) && $stable(S1) && $changed(C) && $stable(A) && $stable(B) && $stable(D)) |-> $stable(Y)
    );

    // Unless selects are 11, changing D alone must not affect Y.
    check_D_irrelevant_when_not_11: assert property (
        @(posedge CLK)
            ((!(S0 && S1)) && $stable(S0) && $stable(S1) && $changed(D) && $stable(A) && $stable(B) && $stable(C)) |-> $stable(Y)
    );
endmodule

module d_ff_reset_sva (
    input logic D,
    input logic CLK,
    input logic RESET_B,
    input logic Q
);
    // Analysis:
    // - Clock: CLK (posedge)
    // - Reset: RESET_B active-low, asynchronous; forces Q=0
    // - Logic: Sequential D flip-flop with async reset; Q captures D on CLK rising edge when RESET_B==1

    ///// Reset behavior /////
    // Reset low forces Q=0 at every clock edge.
    check_reset_low_forces_q0: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

    // Falling edge of RESET_B implies Q=0 at this clock.
    check_reset_fall_forces_q0: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

    // Rising edge of RESET_B keeps Q=0 in this cycle (assignment to D occurs after this edge).
    check_reset_rise_keeps_q0: assert property (
        @(posedge CLK) $rose(RESET_B) |-> (Q == 1'b0)
    );

    // While held in reset across cycles, Q stays stable.
    check_q_stable_while_in_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> $stable(Q)
    );

    // While held in reset across cycles, Q remains 0.
    check_q_zero_while_in_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> (Q == 1'b0)
    );

    ///// Non-reset invariants /////
    // Q=1 implies reset is deasserted.
    check_q1_implies_reset_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) (Q == 1'b1) |-> (RESET_B == 1'b1)
    );

    // No rising edge on Q in the first cycle after reset is deasserted.
    check_no_q_rise_just_after_reset: assert property (
        @(posedge CLK) disable iff (!RESET_B) ($past(RESET_B) == 1'b0) |-> (!$rose(Q))
    );

    // No change on Q between cycles when reset stays asserted.
    check_no_q_change_across_held_reset: assert property (
        @(posedge CLK) ($past(RESET_B) == 1'b0 && RESET_B == 1'b0) |-> (Q == $past(Q))
    );

endmodule

verilog_code:
module multiplier
    # (parameter W = 32) (input wire clk,
    input wire [W-1:0] Data_A_i,
    input wire [W-1:0] Data_B_i,
    output wire [2*W-1:0] Data_S_o
    );

    reg [2*W-1:0] pdt_int;
    assign Data_S_o=pdt_int;always@(posedge clk)
    begin
        pdt_int<= Data_A_i*Data_B_i;
        end

endmodule

sva_code:
module multiplier_sva
    #(parameter int W = 32)
(
    input logic clk,
    input logic [W-1:0] Data_A_i,
    input logic [W-1:0] Data_B_i,
    input logic [2*W-1:0] Data_S_o
);

    // Output equals product of prior-cycle inputs (1-cycle latency).
    check_product_latency: assert property (
        @(posedge clk) $past(1'b1) |-> (Data_S_o == ($past(Data_A_i) * $past(Data_B_i)))
    );

    // If prior A is zero, output must be zero.
    check_zero_if_a_zero: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {W{1'b0}}) |-> (Data_S_o == {2*W{1'b0}})
    );

    // If prior B is zero, output must be zero.
    check_zero_if_b_zero: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {W{1'b0}}) |-> (Data_S_o == {2*W{1'b0}})
    );

    // If prior A is 1, output equals zero-extended prior B.
    check_identity_if_a_one: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {{(W-1){1'b0}},1'b1}) |-> (Data_S_o == {{W{1'b0}}, $past(Data_B_i)})
    );

    // If prior B is 1, output equals zero-extended prior A.
    check_identity_if_b_one: assert property (
        @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {{(W-1){1'b0}},1'b1}) |-> (Data_S_o == {{W{1'b0}}, $past(Data_A_i)})
    );

    // LSB of output equals AND of prior-cycle input LSBs.
    check_lsb_and: assert property (
        @(posedge clk) $past(1'b1) |-> (Data_S_o[0] == ($past(Data_A_i[0]) & $past(Data_B_i[0])))
    );

    // If both prior inputs are odd, output LSB is 1.
    check_lsb_one_if_both_odd: assert property (
        @(posedge clk) $past(1'b1) && $past(Data_A_i[0]) && $past(Data_B_i[0]) |-> (Data_S_o[0] == 1'b1)
    );

    // If either prior input is even, output LSB is 0.
    check_lsb_zero_if_either_even: assert property (
        @(posedge clk) $past(1'b1) && ((!$past(Data_A_i[0])) || (!$past(Data_B_i[0]))) |-> (Data_S_o[0] == 1'b0)
    );

    // If inputs are unchanged across two cycles, output is unchanged across one cycle.
    check_stable_inputs_hold_output: assert property (
        @(posedge clk) $past(1'b1,2) && ($past(Data_A_i,1) == $past(Data_A_i,2)) && ($past(Data_B_i,1) == $past(Data_B_i,2)) |-> (Data_S_o == $past(Data_S_o,1))
    );

    // If prior A == 2, output equals zero-extended prior B shifted left by 1.
    generate if (W >= 2) begin : gen_shift_by1
        check_a_eq2_shift_b: assert property (
            @(posedge clk) $past(1'b1) && ($past(Data_A_i) == {{(W-2){1'b0}}, 2'b10}) |-> (Data_S_o == ({{W{1'b0}}, $past(Data_B_i)} << 1))
        );
        // If prior B == 2, output equals zero-extended prior A shifted left by 1.
        check_b_eq2_shift_a: assert property (
            @(posedge clk) $past(1'b1) && ($past(Data_B_i) == {{(W-2){1'b0}}, 2'b10}) |-> (Data_S_o == ({{W{1'b0}}, $past(Data_A_i)} << 1))
        );
    end endgenerate

endmodule

verilog_code:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] Z
);

    wire [3:0] A_comp, B_comp;
    wire [4:0] sum;
    wire carry;

    assign A_comp = (~A) + 1;
    assign B_comp = (~B) + 1;

    assign sum = A_comp + B_comp + C;

    assign carry = sum[4];

    assign Z = (C) ? (~sum[3:0] + 1) : sum[3:0];

endmodule

sva_code:
module binary_adder_sva (
    input  logic        CLK,
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        C,
    input  logic [3:0]  Z
);
    // Local model mirroring RTL computations
    logic [3:0] A_comp, B_comp;
    logic [4:0] sum5;
    logic [3:0] sum_low;
    logic [3:0] z_expected_c0;
    logic [3:0] z_expected_c1;

    assign A_comp       = (~A) + 4'd1;
    assign B_comp       = (~B) + 4'd1;
    assign sum5         = {1'b0, A_comp} + {1'b0, B_comp} + {4'd0, C};
    assign sum_low      = sum5[3:0];
    assign z_expected_c0 = sum_low;
    assign z_expected_c1 = (~sum_low) + 4'd1;

    // When C=0, Z equals sum_low.
    check_z_when_c0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Z == z_expected_c0)
    );

    // When C=1, Z equals two's complement of sum_low.
    check_z_when_c1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Z == z_expected_c1)
    );

    // If A,B stable and C rises, Z becomes bitwise complement of previous Z.
    check_z_complement_on_c_rise: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(C,1,C) == 1'b0) && (C == 1'b1)) |-> (Z == ~ $past(Z,1,Z))
    );

    // If A,B stable and C falls, Z becomes bitwise complement of previous Z.
    check_z_complement_on_c_fall: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && ($past(C,1,C) == 1'b1) && (C == 1'b0)) |-> (Z == ~ $past(Z,1,Z))
    );

    // If A,B,C are all stable, Z must be stable (purely combinational behavior).
    check_output_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A) && $stable(B) && $stable(C)) |-> $stable(Z)
    );

    // With C=1 and B stable, if A increments by 1 (mod 16), Z increments by 1 (mod 16).
    check_deltaA_inc_when_c1: assert property (
        @(posedge CLK) ($stable(B) && (C == 1'b1) && ($past(C,1,C) == 1'b1) && (A == ($past(A,1,A) + 4'd1))) |-> (Z == ($past(Z,1,Z) + 4'd1))
    );

    // With C=0 and B stable, if A increments by 1 (mod 16), Z decrements by 1 (mod 16).
    check_deltaA_inc_when_c0: assert property (
        @(posedge CLK) ($stable(B) && (C == 1'b0) && ($past(C,1,C) == 1'b0) && (A == ($past(A,1,A) + 4'd1))) |-> (Z == ($past(Z,1,Z) - 4'd1))
    );

    // With C=1 and A stable, if B increments by 1 (mod 16), Z increments by 1 (mod 16).
    check_deltaB_inc_when_c1: assert property (
        @(posedge CLK) ($stable(A) && (C == 1'b1) && ($past(C,1,C) == 1'b1) && (B == ($past(B,1,B) + 4'd1))) |-> (Z == ($past(Z,1,Z) + 4'd1))
    );

    // With C=0 and A stable, if B increments by 1 (mod 16), Z decrements by 1 (mod 16).
    check_deltaB_inc_when_c0: assert property (
        @(posedge CLK) ($stable(A) && (C == 1'b0) && ($past(C,1,C) == 1'b0) && (B == ($past(B,1,B) + 4'd1))) |-> (Z == ($past(Z,1,Z) - 4'd1))
    );

    // Alternative form for C=0: Z equals two's complement of (A+B) modulo 16.
    check_alt_formula_c0: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Z == ((~(({1'b0, A} + {1'b0, B})[3:0])) + 4'd1))
    );

    // Alternative form for C=1: Z equals (A + B - 1) modulo 16.
    check_alt_formula_c1: assert property (
        @(posedge CLK) (C == 1'b1) |-> (Z == (({1'b0, A} + {1'b0, B} + 5'd15)[3:0]))
    );

endmodule

