    // B=3 maps to "3" glyph
    check_decode_b3: assert property (
        @(posedge CLK) (B == 4'h3) |=> (SSEG_L == 7'b0110000)
    );

    // B=4 maps to "4" glyph
    check_decode_b4: assert property (
        @(posedge CLK) (B == 4'h4) |=> (SSEG_L == 7'b0011001)
