    // B=B maps to "b" glyph
    check_decode_bB: assert property (
        @(posedge CLK) (B == 4'hB) |=> (SSEG_L == 7'b0000011)
    );

    // B=C maps to "C" glyph
    check_decode_bC: assert property (
        @(posedge CLK) (B == 4'hC) |=> (SSEG_L == 7'b1000110)
    );

    // B=D maps to "d" glyph
