module twos_complement(
    input [3:0] in,
    output reg [3:0] out
);

always @(*) begin
    out = ~in + 1;
end

endmodule

sva_code:
module twos_complement_sva (
    input logic [3:0] in,
    input logic [3:0] out
);
    ///// Functional equivalence /////
    // out equals bitwise-not of in plus 1 (two's complement).
    check_twos_complement_equivalence: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        out == (~in + 4'd1)
    );

    // The 4-bit sum of in and out wraps to zero (modulo-16).
    check_sum_wraps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in + out) == 4'd0
    );

    // Two's complement is involutive: complement of out == in.
    check_involution: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        ((~out) + 4'd1) == in
    );

    ///// Corner cases /////
    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in == 4'd0) |-> (out == 4'd0)
    );

    // If out is zero, input must have been zero.
    check_only_zero_maps_to_zero: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (out == 4'd0) |-> (in == 4'd0)
    );

    // Minimum 4-bit two's-complement value (8) maps to itself.
    check_min_neg_self_inverse: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (in == 4'h8) |-> (out == 4'h8)
    );

    // out equals in only for fixed points 0 or 8.
    check_only_fixed_points_equal: assert property (
        @(posedge in[0] or negedge in[0] or posedge in[1] or negedge in[1] or posedge in[2] or negedge in[2] or posedge in[3] or negedge in[3])
        (out == in) |-> ((in == 4'h0) || (in == 4'h8))
    );
endmodule

verilog_code:
module clock_divider(
    input clk_in,
    output reg clk_out_1,
    output reg clk_out_2,
    output reg clk_out_3
);

reg [25:0] counter_25;
reg [26:0] counter_12_5;
reg [27:0] counter_6_25;

always @(posedge clk_in) begin
    counter_25 <= counter_25 + 1;
    counter_12_5 <= counter_12_5 + 1;
    counter_6_25 <= counter_6_25 + 1;

    if (counter_25 == 999_999) begin
        counter_25 <= 0;
        clk_out_1 <= ~clk_out_1;
    end

    if (counter_12_5 == 1_999_999) begin
        counter_12_5 <= 0;
        clk_out_2 <= ~clk_out_2;
    end

    if (counter_6_25 == 3_999_999) begin
        counter_6_25 <= 0;
        clk_out_3 <= ~clk_out_3;
    end
end

endmodule

sva_code:
module clock_divider_sva (
    input logic clk_in,
    input logic clk_out_1,
    input logic clk_out_2,
    input logic clk_out_3,
    input logic [25:0] counter_25,
    input logic [26:0] counter_12_5,
    input logic [27:0] counter_6_25
);

    ///// counter_25 behavior /////
    // When not at terminal count, counter_25 increments by 1.
    check_counter25_increment_nonwrap: assert property (
        @(posedge clk_in) ($past(counter_25) != 26'd999999) |-> (counter_25 == $past(counter_25) + 26'd1)
    );
    // When reaching terminal count, counter_25 wraps to 0.
    check_counter25_wrap_to_zero: assert property (
        @(posedge clk_in) ($past(counter_25) == 26'd999999) |-> (counter_25 == 26'd0)
    );

    ///// counter_12_5 behavior /////
    // When not at terminal count, counter_12_5 increments by 1.
    check_counter12_5_increment_nonwrap: assert property (
        @(posedge clk_in) ($past(counter_12_5) != 27'd1999999) |-> (counter_12_5 == $past(counter_12_5) + 27'd1)
    );
    // When reaching terminal count, counter_12_5 wraps to 0.
    check_counter12_5_wrap_to_zero: assert property (
        @(posedge clk_in) ($past(counter_12_5) == 27'd1999999) |-> (counter_12_5 == 27'd0)
    );

    ///// counter_6_25 behavior /////
    // When not at terminal count, counter_6_25 increments by 1.
    check_counter6_25_increment_nonwrap: assert property (
        @(posedge clk_in) ($past(counter_6_25) != 28'd3999999) |-> (counter_6_25 == $past(counter_6_25) + 28'd1)
    );
    // When reaching terminal count, counter_6_25 wraps to 0.
    check_counter6_25_wrap_to_zero: assert property (
        @(posedge clk_in) ($past(counter_6_25) == 28'd3999999) |-> (counter_6_25 == 28'd0)
    );

    ///// clk_out_1 behavior /////
    // clk_out_1 can change only when counter_25 hit terminal count in the previous cycle.
    check_out1_change_requires_counter25_wrap: assert property (
        @(posedge clk_in) $changed(clk_out_1) |-> ($past(counter_25) == 26'd999999)
    );
    // When counter_25 hit terminal count and previous clk_out_1 was known, clk_out_1 toggles.
    check_out1_toggle_on_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_25) == 26'd999999) && (!$isunknown($past(clk_out_1)))) |-> (clk_out_1 == ~$past(clk_out_1))
    );
    // When counter_25 did not hit terminal count and previous clk_out_1 was known, clk_out_1 holds.
    check_out1_stable_when_no_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_25) != 26'd999999) && (!$isunknown($past(clk_out_1)))) |-> (clk_out_1 == $past(clk_out_1))
    );

    ///// clk_out_2 behavior /////
    // clk_out_2 can change only when counter_12_5 hit terminal count in the previous cycle.
    check_out2_change_requires_counter12_5_wrap: assert property (
        @(posedge clk_in) $changed(clk_out_2) |-> ($past(counter_12_5) == 27'd1999999)
    );
    // When counter_12_5 hit terminal count and previous clk_out_2 was known, clk_out_2 toggles.
    check_out2_toggle_on_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_12_5) == 27'd1999999) && (!$isunknown($past(clk_out_2)))) |-> (clk_out_2 == ~$past(clk_out_2))
    );
    // When counter_12_5 did not hit terminal count and previous clk_out_2 was known, clk_out_2 holds.
    check_out2_stable_when_no_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_12_5) != 27'd1999999) && (!$isunknown($past(clk_out_2)))) |-> (clk_out_2 == $past(clk_out_2))
    );

    ///// clk_out_3 behavior /////
    // clk_out_3 can change only when counter_6_25 hit terminal count in the previous cycle.
    check_out3_change_requires_counter6_25_wrap: assert property (
        @(posedge clk_in) $changed(clk_out_3) |-> ($past(counter_6_25) == 28'd3999999)
    );
    // When counter_6_25 hit terminal count and previous clk_out_3 was known, clk_out_3 toggles.
    check_out3_toggle_on_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_6_25) == 28'd3999999) && (!$isunknown($past(clk_out_3)))) |-> (clk_out_3 == ~$past(clk_out_3))
    );
    // When counter_6_25 did not hit terminal count and previous clk_out_3 was known, clk_out_3 holds.
    check_out3_stable_when_no_wrap_when_known: assert property (
        @(posedge clk_in) (($past(counter_6_25) != 28'd3999999) && (!$isunknown($past(clk_out_3)))) |-> (clk_out_3 == $past(clk_out_3))
    );

endmodule

verilog_code:
module simple_calculator(
    input  [7:0] A,
    input  [7:0] B,
    input        OP,
    input        CLK,
    input        RST,
    output [7:0] C
);

    reg [7:0] C_reg;

    always @(posedge CLK) begin
        if (RST) begin
            C_reg <= 8'b0;
        end else if (OP == 1) begin
            C_reg <= A - B;
        end else begin
            C_reg <= A + B;
        end
    end

    assign C = C_reg;

endmodule

sva_code:
module simple_calculator_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic       OP,
    input logic       CLK,
    input logic       RST,
    input logic [7:0] C
);
    // On any reset cycle, C is 0 in the following cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (C == 8'h00)
    );

    // Immediately after a reset cycle, C must be 0.
    post_reset_zero: assert property (
        @(posedge CLK) $past(RST) |-> (C == 8'h00)
    );

    // With OP==1 and not in reset, next C equals previous (A - B) modulo 256.
    update_on_sub_op: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b1) |=> (C == ($past(A) - $past(B))[7:0])
    );

    // With OP==0 and not in reset, next C equals previous (A + B) modulo 256.
    update_on_add_op: assert property (
        @(posedge CLK) disable iff (RST) (OP == 1'b0) |=> (C == ($past(A) + $past(B))[7:0])
    );

    // If previous cycle was not reset, C matches the selected operation from the previous cycle.
    combined_update_rule: assert property (
        @(posedge CLK) disable iff (RST) $past(!RST) |-> (C == ($past(OP) ? ($past(A) - $past(B))[7:0] : ($past(A) + $past(B))[7:0]))
    );

    // If not in reset across two cycles and inputs are unchanged, C must be unchanged.
    hold_when_inputs_stable: assert property (
        @(posedge CLK) disable iff (RST)
            (!$past(RST) && !RST && (A == $past(A)) && (B == $past(B)) && (OP == $past(OP)))
            |-> $stable(C)
    );

    // If C changes (and previous cycle not reset), at least one of A, B, or OP must have changed.
    output_change_implies_input_change: assert property (
        @(posedge CLK) disable iff (RST)
            (!$past(RST) && (C != $past(C))) |-> ((A != $past(A)) || (B != $past(B)) || (OP != $past(OP)))
    );
endmodule

verilog_code:
module bit_converter(
    input [3:0] in,
    output [1:0] out
);

    assign out = (in < 5) ? 2'b00 : (in < 9) ? 2'b01 : (in < 11) ? 2'b10 : 2'b11;

endmodule

sva_code:
module bit_converter_sva (
    input logic CLK,
    input logic [3:0] in,
    input logic [1:0] out
);
    // Out must equal the RTL ternary expression for all inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) out == ((in < 4'd5) ? 2'b00 :
                               (in < 4'd9) ? 2'b01 :
                               (in < 4'd11) ? 2'b10 : 2'b11)
    );

    // For in=0..4, out must be 00.
    check_out_for_in_lt_5: assert property (
        @(posedge CLK) (in < 4'd5) |-> (out == 2'b00)
    );

    // For in=5..8, out must be 01.
    check_out_for_5_to_8: assert property (
        @(posedge CLK) (in >= 4'd5 && in < 4'd9) |-> (out == 2'b01)
    );

    // For in=9..10, out must be 10.
    check_out_for_9_to_10: assert property (
        @(posedge CLK) (in >= 4'd9 && in < 4'd11) |-> (out == 2'b10)
    );

    // For in=11..15, out must be 11.
    check_out_for_11_to_15: assert property (
        @(posedge CLK) (in >= 4'd11) |-> (out == 2'b11)
    );

    // If out is 00, in must be 0..4.
    check_in_range_when_out_00: assert property (
        @(posedge CLK) (out == 2'b00) |-> (in < 4'd5)
    );

    // If out is 01, in must be 5..8.
    check_in_range_when_out_01: assert property (
        @(posedge CLK) (out == 2'b01) |-> (in >= 4'd5 && in < 4'd9)
    );

    // If out is 10, in must be 9..10.
    check_in_range_when_out_10: assert property (
        @(posedge CLK) (out == 2'b10) |-> (in >= 4'd9 && in < 4'd11)
    );

    // If out is 11, in must be 11..15.
    check_in_range_when_out_11: assert property (
        @(posedge CLK) (out == 2'b11) |-> (in >= 4'd11)
    );

    // If input is stable across cycles, output must be stable.
    check_stability: assert property (
        @(posedge CLK) $stable(in) |-> $stable(out)
    );
endmodule

verilog_code:
module prcfg_dac(

  clk,

  control,
  status,

  src_dac_enable,
  src_dac_data,
  src_dac_valid,

  dst_dac_enable,
  dst_dac_data,
  dst_dac_valid
);

  localparam  RP_ID       = 8'hA0;
  parameter   CHANNEL_ID  = 0;

  input             clk;

  input   [31:0]    control;
  output  [31:0]    status;

  output            src_dac_enable;
  input   [15:0]    src_dac_data;
  output            src_dac_valid;

  input             dst_dac_enable;
  output  [15:0]    dst_dac_data;
  input             dst_dac_valid;

  reg               src_dac_enable;
  reg               src_dac_valid;
  reg     [15:0]    dst_dac_data;

  assign status = {24'h0, RP_ID};

  always @(posedge clk) begin
    src_dac_enable  <= dst_dac_enable;
    dst_dac_data    <= src_dac_data;
    src_dac_valid   <= dst_dac_valid;
  end
endmodule

sva_code:
module prcfg_dac_sva(

  input logic             clk,

  input logic [31:0]      control,
  input logic [31:0]      status,

  input logic             src_dac_enable,
  input logic [15:0]      src_dac_data,
  input logic             src_dac_valid,

  input logic             dst_dac_enable,
  input logic [15:0]      dst_dac_data,
  input logic             dst_dac_valid
);

    ///// Constant status /////
    // status is hardwired to 32'h000000A0.
    check_status_constant_value: assert property (
        @(posedge clk) status == 32'h000000A0
    );

    // status remains stable over time.
    check_status_stable_over_time: assert property (
        @(posedge clk) disable iff ($initstate) status == $past(status)
    );

    ///// Registered pass-throughs /////
    // src_dac_enable is the registered copy of dst_dac_enable.
    check_src_enable_registered_from_dst_enable: assert property (
        @(posedge clk) disable iff ($initstate) src_dac_enable == $past(dst_dac_enable)
    );

    // src_dac_valid is the registered copy of dst_dac_valid.
    check_src_valid_registered_from_dst_valid: assert property (
        @(posedge clk) disable iff ($initstate) src_dac_valid == $past(dst_dac_valid)
    );

    // dst_dac_data is the registered copy of src_dac_data.
    check_dst_data_registered_from_src_data: assert property (
        @(posedge clk) disable iff ($initstate) dst_dac_data == $past(src_dac_data)
    );

    ///// Stability propagation /////
    // If dst_dac_enable was stable over the last two cycles, src_dac_enable is stable this cycle.
    check_src_enable_stable_when_dst_enable_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(dst_dac_enable) == $past(dst_dac_enable,2)) |-> (src_dac_enable == $past(src_dac_enable))
    );

    // If dst_dac_valid was stable over the last two cycles, src_dac_valid is stable this cycle.
    check_src_valid_stable_when_dst_valid_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(dst_dac_valid) == $past(dst_dac_valid,2)) |-> (src_dac_valid == $past(src_dac_valid))
    );

    // If src_dac_data was stable over the last two cycles, dst_dac_data is stable this cycle.
    check_dst_data_stable_when_src_data_stable: assert property (
        @(posedge clk) disable iff ($initstate) ($past(src_dac_data) == $past(src_dac_data,2)) |-> (dst_dac_data == $past(dst_dac_data))
    );

endmodule

verilog_code:
module top_module( 
    input [255:0] in,
    input [7:0] sel,
    output out );

    wire [7:0] decoder_out;
    wire [1:0] mux2_out;

    // Decoder
    decoder dec1(
        .in(sel),
        .out(decoder_out)
    );

    // 2-to-1 Mux
    mux2 mux2_1(
        .in0(in[decoder_out]),
        .in1(in[decoder_out + 1]),
        .sel(sel[0]),
        .out(mux2_out)
    );

    // Final Mux
    assign out = mux2_out[sel[0]];

endmodule

// Decoder
module decoder(
    input [7:0] in,
    output reg [7:0] out
);
    always @ (in) begin
        case (in)
            8'b00000001: out = 8'b00000001;
            8'b00000010: out = 8'b00000010;
            8'b00000100: out = 8'b00000100;
            8'b00001000: out = 8'b00001000;
            8'b00010000: out = 8'b00010000;
            8'b00100000: out = 8'b00100000;
            8'b01000000: out = 8'b01000000;
            8'b10000000: out = 8'b10000000;
            default: out = 8'b00000000;
        endcase
    end
endmodule

// 2-to-1 Mux
module mux2(
    input in0,
    input in1,
    input sel,
    output reg [1:0] out
);
    always @ (in0, in1, sel) begin
        case (sel)
            1'b0: out = {in1, in1};
            1'b1: out = {in0, in0};
            default: out = {in0, in0};
        endcase
    end
endmodule

sva_code:
module top_module_sva (
    input logic clk,
    input logic [255:0] in,
    input logic [7:0] sel,
    input logic out,

    // Internal signals from DUT (bind hierarchically)
    input logic [7:0] decoder_out,
    input logic [1:0] mux2_out
);

    ///// Decoder checks /////
    // Decoder outputs sel when sel is one-hot.
    decoder_matches_onehot_sel: assert property (
        @(posedge clk) $onehot(sel) |-> (decoder_out == sel)
    );

    // Decoder outputs 0 when sel is not one-hot.
    decoder_zero_when_not_onehot: assert property (
        @(posedge clk) !$onehot(sel) |-> (decoder_out == 8'b0)
    );

    // Decoder output is always one-hot or zero.
    decoder_out_onehot0: assert property (
        @(posedge clk) $onehot0(decoder_out)
    );

    ///// mux2 checks /////
    // When sel[0]==0, mux2_out replicates in[decoder_out + 1].
    mux2_sel0_replication: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (mux2_out == {in[decoder_out + 1], in[decoder_out + 1]})
    );

    // When sel[0]==1, mux2_out replicates in[decoder_out].
    mux2_sel1_replication: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (mux2_out == {in[decoder_out], in[decoder_out]})
    );

    // mux2_out bits are always identical.
    mux2_bits_identical: assert property (
        @(posedge clk) (mux2_out[1] == mux2_out[0])
    );

    ///// Final mux checks /////
    // Final mux selects mux2_out bit indexed by sel[0].
    final_mux_select: assert property (
        @(posedge clk) (out == mux2_out[sel[0]])
    );

    // End-to-end: out equals selected input bit.
    end_to_end_out_value: assert property (
        @(posedge clk) out == (sel[0] ? in[decoder_out] : in[decoder_out + 1])
    );

    // When sel[0]==0, out equals in[decoder_out + 1].
    end_to_end_sel0: assert property (
        @(posedge clk) (sel[0] == 1'b0) |-> (out == in[decoder_out + 1])
    );

    // When sel[0]==1, out equals in[decoder_out].
    end_to_end_sel1: assert property (
        @(posedge clk) (sel[0] == 1'b1) |-> (out == in[decoder_out])
    );

endmodule

verilog_code:
module mux6to1_pipeline (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;
reg [3:0] stage3_out;

always @(*) begin
    case(sel)
        3'b000: stage1_out = data0;
        3'b001: stage1_out = data1;
        3'b010: stage1_out = data2;
        3'b011: stage1_out = data3;
        3'b100: stage1_out = data4;
        3'b101: stage1_out = data5;
        default: stage1_out = {data5[3], data5[3], data5[3], data5[3]};
    endcase
end

always @(*) begin
    case(sel)
        3'b000: stage2_out = stage1_out;
        3'b001: stage2_out = stage1_out;
        3'b010: stage2_out = stage1_out;
        3'b011: stage2_out = stage1_out;
        3'b100: stage2_out = stage1_out;
        3'b101: stage2_out = stage1_out;
        default: stage2_out = {stage1_out[3], stage1_out[3], stage1_out[3], stage1_out[3]};
    endcase
end

always @(*) begin
    case(sel)
        3'b000: stage3_out = stage2_out;
        3'b001: stage3_out = stage2_out;
        3'b010: stage3_out = stage2_out;
        3'b011: stage3_out = stage2_out;
        3'b100: stage3_out = stage2_out;
        3'b101: stage3_out = stage2_out;
        default: stage3_out = {stage2_out[3], stage2_out[3], stage2_out[3], stage2_out[3]};
    endcase
end

assign out = stage3_out;

endmodule

