module my_module_sva (
    input logic CLK,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);
    // Y equals NOR of B1 and (A1 & A2)
    check_y_equation: assert property (
        @(posedge CLK) Y == ~(B1 | (A1 & A2))
    );

    // B1 high forces Y low
    check_b1_high_forces_y0: assert property (
        @(posedge CLK) (B1 == 1'b1) |-> (Y == 1'b0)
