module and5_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic A4,
    input logic B1,
    input logic X
);
    // Output equals the AND of all five inputs.
    check_output_equals_and_all: assert property (
        @(posedge clk) X == (A1 & A2 & A3 & A4 & B1)
    );

    // If A1 is LOW, X must be LOW.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk) (A1 == 1'b0) |-> (X == 1'b0)
    );

    // If A2 is LOW, X must be LOW.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk) (A2 == 1'b0) |-> (X == 1'b0)
    );

    // If A3 is LOW, X must be LOW.
    check_a3_low_forces_x_low: assert property (
        @(posedge clk) (A3 == 1'b0) |-> (X == 1'b0)
    );

    // If A4 is LOW, X must be LOW.
    check_a4_low_forces_x_low: assert property (
        @(posedge clk) (A4 == 1'b0) |-> (X == 1'b0)
    );

    // If B1 is LOW, X must be LOW.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) (B1 == 1'b0) |-> (X == 1'b0)
    );

    // If all inputs are HIGH, X must be HIGH.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A1 & A2 & A3 & A4 & B1) |-> (X == 1'b1)
    );

    // X can be HIGH only if all inputs are HIGH.
    check_x_high_implies_all_high: assert property (
        @(posedge clk) (X == 1'b1) |-> (A1 & A2 & A3 & A4 & B1)
    );

    // X can only rise when all inputs are HIGH.
    check_x_rise_requires_all_high: assert property (
        @(posedge clk) $rose(X) |-> (A1 & A2 & A3 & A4 & B1)
    );

    // X can only fall when at least one input is LOW.
    check_x_fall_requires_some_low: assert property (
        @(posedge clk) $fell(X) |-> (!A1 || !A2 || !A3 || !A4 || !B1)
    );
endmodule

verilog_code:
module xnor2 (
    Y   ,
    A   ,
    B   ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output Y   ;
    input  A   ;
    input  B   ;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire A_inv, B_inv, A_B, A_inv_B_inv;

    // Invert A and B
    not (A_inv, A);
    not (B_inv, B);

    // AND A and B
    and (A_B, A, B);

    // AND inverted A and inverted B
    and (A_inv_B_inv, A_inv, B_inv);

    // OR the results of the two AND gates
    or (Y, A_B, A_inv_B_inv);

endmodule

sva_code:
module xnor2_sva (
    input logic Y,
    input logic A,
    input logic B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic A_inv,
    input logic B_inv,
    input logic A_B,
    input logic A_inv_B_inv
);
    // Y equals XNOR of A and B (functional definition).
    check_y_eq_xnor: assert property (
        @(posedge A or negedge A or posedge B or negedge B) ##0 (Y == (A ^~ B))
    );

    // A_inv is the inversion of A.
    check_a_inv_is_not_a: assert property (
        @(posedge A or negedge A) ##0 (A_inv == ~A)
    );

    // B_inv is the inversion of B.
    check_b_inv_is_not_b: assert property (
        @(posedge B or negedge B) ##0 (B_inv == ~B)
    );

    // A_B is the AND of A and B.
    check_a_b_and: assert property (
        @(posedge A or negedge A or posedge B or negedge B) ##0 (A_B == (A & B))
    );

    // A_inv_B_inv is the AND of A_inv and B_inv.
    check_a_inv_b_inv_and: assert property (
        @(posedge A_inv or negedge A_inv or posedge B_inv or negedge B_inv or posedge A or negedge A or posedge B or negedge B) ##0
        (A_inv_B_inv == (A_inv & B_inv))
    );

    // A_inv_B_inv equals (~A & ~B).
    check_a_inv_b_inv_matches_inverts: assert property (
        @(posedge A or negedge A or posedge B or negedge B) ##0 (A_inv_B_inv == (~A & ~B))
    );

    // Y is the OR of the two AND terms.
    check_y_or_of_terms: assert property (
        @(posedge A_B or negedge A_B or posedge A_inv_B_inv or negedge A_inv_B_inv or posedge A or negedge A or posedge B or negedge B or posedge Y or negedge Y) ##0
        (Y == (A_B | A_inv_B_inv))
    );

    // When Y rises, inputs must be equal.
    check_y_rise_inputs_equal: assert property (
        @(posedge Y) ##0 (A == B)
    );

    // When Y falls, inputs must be different.
    check_y_fall_inputs_different: assert property (
        @(negedge Y) ##0 (A != B)
    );

    // B_inv does not change when only A toggles and B is stable.
    check_b_inv_independent_of_a: assert property (
        @(posedge A or negedge A) $stable(B) |-> ##0 $stable(B_inv)
    );

    // A_inv does not change when only B toggles and A is stable.
    check_a_inv_independent_of_b: assert property (
        @(posedge B or negedge B) $stable(A) |-> ##0 $stable(A_inv)
    );
endmodule

verilog_code:
module mux_priority_encoder (
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    input [7:0] in,
    output [2:0] pos,
    output reg [3:0] out_sum
);

// 2-to-1 Multiplexer
wire mux_out;
assign mux_out = (sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 0);

// Priority Encoder
reg [2:0] pos_reg;
always @(*) begin
    if (in[0]) pos_reg = 0;
    else if (in[1]) pos_reg = 1;
    else if (in[2]) pos_reg = 2;
    else if (in[3]) pos_reg = 3;
    else if (in[4]) pos_reg = 4;
    else if (in[5]) pos_reg = 5;
    else if (in[6]) pos_reg = 6;
    else if (in[7]) pos_reg = 7;
    else pos_reg = 0;
end
assign pos = pos_reg;

// Functional Module
always @(*) begin
    case (pos_reg)
        0: out_sum = mux_out + 0;
        1: out_sum = mux_out + 1;
        2: out_sum = mux_out + 2;
        3: out_sum = mux_out + 3;
        4: out_sum = mux_out + 4;
        5: out_sum = mux_out + 5;
        6: out_sum = mux_out + 6;
        7: out_sum = mux_out + 7;
        default: out_sum = 0;
    endcase
end

endmodule

sva_code:
module mux_priority_encoder_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic sel_b1,
    input logic sel_b2,
    input logic [7:0] in,
    input logic [2:0] pos,
    input logic [3:0] out_sum
);
    // pos selects index of lowest-order '1' in in (bit 0 has highest priority).
    check_pos_priority_bit0: assert property (
        @(posedge clk) in[0] |-> (pos == 3'd0)
    );
    // pos==1 when in[1] is 1 and no lower bit is set.
    check_pos_priority_bit1: assert property (
        @(posedge clk) (in[1] && !in[0]) |-> (pos == 3'd1)
    );
    // pos==2 when in[2] is 1 and no lower bit is set.
    check_pos_priority_bit2: assert property (
        @(posedge clk) (in[2] && !in[1] && !in[0]) |-> (pos == 3'd2)
    );
    // pos==3 when in[3] is 1 and no lower bit is set.
    check_pos_priority_bit3: assert property (
        @(posedge clk) (in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd3)
    );
    // pos==4 when in[4] is 1 and no lower bit is set.
    check_pos_priority_bit4: assert property (
        @(posedge clk) (in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd4)
    );
    // pos==5 when in[5] is 1 and no lower bit is set.
    check_pos_priority_bit5: assert property (
        @(posedge clk) (in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd5)
    );
    // pos==6 when in[6] is 1 and no lower bit is set.
    check_pos_priority_bit6: assert property (
        @(posedge clk) (in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd6)
    );
    // pos==7 when in[7] is 1 and no lower bit is set.
    check_pos_priority_bit7: assert property (
        @(posedge clk) (in[7] && !in[6] && !in[5] && !in[4] && !in[3] && !in[2] && !in[1] && !in[0]) |-> (pos == 3'd7)
    );
    // When no bits are set, pos is 0.
    check_pos_when_none_set: assert property (
        @(posedge clk) (~|in) |-> (pos == 3'd0)
    );

    // out_sum equals pos plus the selected mux output (b if both sel=1, else a if any sel=1, else 0).
    check_out_sum_matches_equation: assert property (
        @(posedge clk)
        out_sum == ({1'b0, pos} + {3'b0, ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0))})
    );
    // When neither select is asserted, out_sum equals pos (mux_out=0).
    check_out_sum_sel00_no_add: assert property (
        @(posedge clk)
        (!sel_b1 && !sel_b2) |-> (out_sum == {1'b0, pos})
    );
    // When exactly one select is asserted, out_sum equals pos + a.
    check_out_sum_sel_one_add_a: assert property (
        @(posedge clk)
        (sel_b1 ^ sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, a}))
    );
    // When both selects are asserted, out_sum equals pos + b.
    check_out_sum_sel11_add_b: assert property (
        @(posedge clk)
        (sel_b1 && sel_b2) |-> (out_sum == ({1'b0, pos} + {3'b0, b}))
    );
    // The MSB of out_sum is high only when selected mux output is 1 and pos==7.
    check_out_sum_msb_carry: assert property (
        @(posedge clk)
        out_sum[3] == ( ((sel_b1 & sel_b2) ? b : ((sel_b1 | sel_b2) ? a : 1'b0)) & (&pos) )
    );
endmodule

verilog_code:
module shift_register (
    input clk,
    input [3:0] data_in,
    input shift_right,
    input load,
    output [3:0] data_out
);

reg [3:0] stage1, stage2, stage3, stage4;

always @(posedge clk) begin
    if (load) begin
        stage1 <= data_in;
        stage2 <= stage1;
        stage3 <= stage2;
        stage4 <= stage3;
    end else begin
        if (shift_right) begin
            stage1 <= stage4;
            stage2 <= stage1;
            stage3 <= stage2;
            stage4 <= stage3;
        end else begin
            stage1 <= stage2;
            stage2 <= stage3;
            stage3 <= stage4;
            stage4 <= data_in;
        end
    end
end

assign data_out = stage4;

endmodule

sva_code:
module shift_register_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic shift_right,
    input logic load,
    input logic [3:0] data_out,
    input logic [3:0] stage1,
    input logic [3:0] stage2,
    input logic [3:0] stage3,
    input logic [3:0] stage4
);
    // data_out always mirrors stage4.
    check_data_out_mirrors_stage4: assert property (
        @(posedge clk) data_out === stage4
    );

    // On load, next stage1 captures data_in.
    check_load_stage1_from_data_in: assert property (
        @(posedge clk) load |-> (stage1 === $past(data_in))
    );
    // On load, next stage2 captures prior stage1.
    check_load_stage2_from_stage1: assert property (
        @(posedge clk) load |-> (stage2 === $past(stage1))
    );
    // On load, next stage3 captures prior stage2.
    check_load_stage3_from_stage2: assert property (
        @(posedge clk) load |-> (stage3 === $past(stage2))
    );
    // On load, next stage4 captures prior stage3.
    check_load_stage4_from_stage3: assert property (
        @(posedge clk) load |-> (stage4 === $past(stage3))
    );

    // On shift_right (no load), next stage1 captures prior stage4.
    check_shr_stage1_from_stage4: assert property (
        @(posedge clk) (!load && shift_right) |-> (stage1 === $past(stage4))
    );
    // On shift_right (no load), next stage2 captures prior stage1.
    check_shr_stage2_from_stage1: assert property (
        @(posedge clk) (!load && shift_right) |-> (stage2 === $past(stage1))
    );
    // On shift_right (no load), next stage3 captures prior stage2.
    check_shr_stage3_from_stage2: assert property (
        @(posedge clk) (!load && shift_right) |-> (stage3 === $past(stage2))
    );
    // On shift_right (no load), next stage4 captures prior stage3.
    check_shr_stage4_from_stage3: assert property (
        @(posedge clk) (!load && shift_right) |-> (stage4 === $past(stage3))
    );

    // On shift_left path (no load and no shift_right), next stage1 captures prior stage2.
    check_shl_stage1_from_stage2: assert property (
