sva_code:
module ll_axis_bridge_sva #(
    parameter DATA_WIDTH = 8
)(
    input  logic                   clk,
    input  logic                   rst,

    input  logic [DATA_WIDTH-1:0]  ll_data_in,
    input  logic                   ll_sof_in_n,
    input  logic                   ll_eof_in_n,
    input  logic                   ll_src_rdy_in_n,
    input  logic                   ll_dst_rdy_out_n,

    input  logic [DATA_WIDTH-1:0]  axis_tdata,
    input  logic                   axis_tvalid,
    input  logic                   axis_tready,
    input  logic                   axis_tlast
);
    // Clock: clk; Reset: rst (active-high)
    // Logic: purely combinational bridge with direct/inverted mappings
    // Mappings: axis_tdata=ll_data_in; axis_tvalid=~ll_src_rdy_in_n; axis_tlast=~ll_eof_in_n; ll_dst_rdy_out_n=~axis_tready

    // axis_tdata directly reflects ll_data_in each cycle.
    map_data_equiv: assert property (
        @(posedge clk) disable iff (rst) (axis_tdata == ll_data_in)
    );

    // axis_tvalid is the inverse of ll_src_rdy_in_n each cycle.
    map_valid_inversion: assert property (
        @(posedge clk) disable iff (rst) (axis_tvalid == ~ll_src_rdy_in_n)
    );

    // axis_tlast is the inverse of ll_eof_in_n each cycle.
    map_last_inversion: assert property (
        @(posedge clk) disable iff (rst) (axis_tlast == ~ll_eof_in_n)
    );

    // ll_dst_rdy_out_n is the inverse of axis_tready each cycle.
    map_ready_inversion: assert property (
        @(posedge clk) disable iff (rst) (ll_dst_rdy_out_n == ~axis_tready)
    );

    // A rise on ll_src_rdy_in_n causes a fall on axis_tvalid.
    src_rdy_rise_valid_fall: assert property (
        @(posedge clk) disable iff (rst) $rose(ll_src_rdy_in_n) |-> $fell(axis_tvalid)
    );

    // A fall on ll_src_rdy_in_n causes a rise on axis_tvalid.
    src_rdy_fall_valid_rise: assert property (
        @(posedge clk) disable iff (rst) $fell(ll_src_rdy_in_n) |-> $rose(axis_tvalid)
    );

    // A rise on ll_eof_in_n causes a fall on axis_tlast.
    eof_rise_last_fall: assert property (
        @(posedge clk) disable iff (rst) $rose(ll_eof_in_n) |-> $fell(axis_tlast)
    );

    // A fall on ll_eof_in_n causes a rise on axis_tlast.
    eof_fall_last_rise: assert property (
        @(posedge clk) disable iff (rst) $fell(ll_eof_in_n) |-> $rose(axis_tlast)
    );

    // A rise on axis_tready causes a fall on ll_dst_rdy_out_n.
    tready_rise_ll_dst_fall: assert property (
        @(posedge clk) disable iff (rst) $rose(axis_tready) |-> $fell(ll_dst_rdy_out_n)
    );

    // A fall on axis_tready causes a rise on ll_dst_rdy_out_n.
    tready_fall_ll_dst_rise: assert property (
        @(posedge clk) disable iff (rst) $fell(axis_tready) |-> $rose(ll_dst_rdy_out_n)
    );

endmodule

verilog_code:
module basic_Calculator(
    input clk,
    input reset,
    input [7:0] data_in1,
    input [7:0] data_in2,
    input [1:0] ctrl,
    output reg [7:0] result
);

always @(posedge clk) begin
    if(reset) begin
        result <= 8'b0;
    end
    else begin
        case(ctrl)
            2'b00: result <= data_in1 + data_in2;
            2'b01: result <= data_in1 - data_in2;
            2'b10: result <= data_in1 * data_in2;
            2'b11: result <= data_in1 / data_in2;
        endcase
    end
end

endmodule

sva_code:
module basic_Calculator_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] data_in1,
    input logic [7:0] data_in2,
    input logic [1:0] ctrl,
    input logic [7:0] result
);
    // Result is zero during synchronous reset.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |-> (result == 8'h00)
    );

    // Add: next-cycle result equals LSB 8 bits of sum of current inputs.
    check_add_result: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b00) |=> (result == (($past(data_in1) + $past(data_in2))[7:0]))
    );

    // Sub: next-cycle result equals LSB 8 bits of difference of current inputs.
    check_sub_result: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b01) |=> (result == (($past(data_in1) - $past(data_in2))[7:0]))
    );

    // Mul: next-cycle result equals LSB 8 bits of product of current inputs.
    check_mul_result: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b10) |=> (result == (($past(data_in1) * $past(data_in2))[7:0]))
    );

    // Div: next-cycle result equals quotient when divisor != 0.
    check_div_result_no_by_zero: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b11 && (data_in2 != 8'h00)) |=> (result == ($past(data_in1) / $past(data_in2)))
    );

    // Add identity: adding zero on right returns left operand next cycle.
    check_add_identity_rhs_zero: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b00 && (data_in2 == 8'h00)) |=> (result == $past(data_in1))
    );

    // Add identity: adding zero on left returns right operand next cycle.
    check_add_identity_lhs_zero: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b00 && (data_in1 == 8'h00)) |=> (result == $past(data_in2))
    );

    // Sub identity: subtracting zero returns left operand next cycle.
    check_sub_identity_rhs_zero: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b01 && (data_in2 == 8'h00)) |=> (result == $past(data_in1))
    );

    // Sub zero: subtracting equal operands yields zero next cycle.
    check_sub_zero_when_equal: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b01 && (data_in1 == data_in2)) |=> (result == 8'h00)
    );

    // Mul by zero: any zero operand yields zero next cycle.
    check_mul_zero_operand_zero: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b10 && ((data_in1 == 8'h00) || (data_in2 == 8'h00))) |=> (result == 8'h00)
    );

    // Div identity: dividing by one returns numerator next cycle.
    check_div_identity_by_one: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b11 && (data_in2 == 8'h01)) |=> (result == $past(data_in1))
    );

    // Div zero numerator: zero divided by non-zero yields zero next cycle.
    check_div_zero_numerator: assert property (
        @(posedge clk) disable iff (reset)
            (ctrl == 2'b11 && (data_in1 == 8'h00) && (data_in2 != 8'h00)) |=> (result == 8'h00)
    );
endmodule

