module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out
);
    // Output equals logical AND of inputs.
    check_out_is_and: assert property (
        @(posedge clk) out == (a & b)
    );

    // Output HIGH only if both inputs HIGH.
    check_out_high_requires_inputs_high: assert property (
        @(posedge clk) (out == 1'b1) |-> (a && b)
    );

    // If input a is LOW then output must be LOW.
    check_out_low_when_a_low: assert property (
        @(posedge clk) (!a) |-> (out == 1'b0)
    );

    // If input b is LOW then output must be LOW.
    check_out_low_when_b_low: assert property (
        @(posedge clk) (!b) |-> (out == 1'b0)
    );

    // If both inputs are HIGH then output must be HIGH.
    check_out_high_when_both_high: assert property (
        @(posedge clk) (a && b) |-> (out == 1'b1)
    );

    // A rising output implies both inputs are HIGH.
    check_out_rise_requires_inputs_high: assert property (
        @(posedge clk) $rose(out) |-> (a && b)
    );

    // A falling output implies at least one input is LOW.
    check_out_fall_requires_one_low: assert property (
        @(posedge clk) $fell(out) |-> (!a || !b)
    );
endmodule

verilog_code:
module comb_op
(
  input [3:0] in,
  output reg [3:0] out
);

  always @(*)
  begin
    if (in >= 0 && in <= 7) // Range 0 to 7
      out = in << 1;
    else if (in >= 8 && in <= 15) // Range 8 to 15
      out = in >> 1;
    else // Outside range 0 to 15
      out = 0;
  end

endmodule

sva_code:
module comb_op_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [3:0] out
);
    // Out equals left shift for inputs 0..7.
    check_left_shift_range_eq: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out == (in << 1))
    );

    // Out equals right shift for inputs 8..15.
    check_right_shift_range_eq: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out == (in >> 1))
    );

    // Piecewise definition matches MSB: 0 => left shift, 1 => right shift.
    check_piecewise_functionality: assert property (
        @(posedge clk) disable iff (1'b0) out == (in[3] ? (in >> 1) : (in << 1))
    );

    // LSB is zero when left shifting (in <= 7).
    check_left_shift_lsb_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out[0] == 1'b0)
    );

    // MSB is zero when right shifting (in >= 8).
    check_right_shift_msb_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out[3] == 1'b0)
    );

    // Left shift moves bits up by one (out[3:1] = in[2:0]) for in <= 7.
    check_left_shift_bit_move: assert property (
        @(posedge clk) disable iff (1'b0) (in <= 4'd7) |-> (out[3:1] == in[2:0])
    );

    // Right shift moves bits down by one (out[2:0] = in[3:1]) for in >= 8.
    check_right_shift_bit_move: assert property (
        @(posedge clk) disable iff (1'b0) (in >= 4'd8) |-> (out[2:0] == in[3:1])
    );

    // Zero maps to zero.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in == 4'd0) |-> (out == 4'd0)
    );

    // Maximum value 15 maps to 7 (15 >> 1).
    check_fifteen_maps_to_seven: assert property (
        @(posedge clk) disable iff (1'b0) (in == 4'd15) |-> (out == 4'd7)
    );
endmodule

verilog_code:
module demux4x1 (Q0, Q1, Q2, Q3, D, S1, S0);
  output Q0, Q1, Q2, Q3;
  input D, S1, S0;

  assign Q0 = (!S1 & !S0) ? D : 0;
  assign Q1 = (!S1 & S0) ? D : 0;
  assign Q2 = (S1 & !S0) ? D : 0;
  assign Q3 = (S1 & S0) ? D : 0;
endmodule

sva_code:
module demux4x1_sva (
    input  logic CLK,
    input  logic Q0,
    input  logic Q1,
    input  logic Q2,
    input  logic Q3,
    input  logic D,
    input  logic S1,
    input  logic S0
);
    // When S1S0==00, Q0==D and others are 0.
    sel00_routes_d_to_q0: assert property (
        @(posedge CLK) (!S1 && !S0) |-> (Q0 == D && (Q1 == 1'b0) && (Q2 == 1'b0) && (Q3 == 1'b0))
    );

    // When S1S0==01, Q1==D and others are 0.
    sel01_routes_d_to_q1: assert property (
        @(posedge CLK) (!S1 &&  S0) |-> (Q1 == D && (Q0 == 1'b0) && (Q2 == 1'b0) && (Q3 == 1'b0))
    );

    // When S1S0==10, Q2==D and others are 0.
    sel10_routes_d_to_q2: assert property (
        @(posedge CLK) ( S1 && !S0) |-> (Q2 == D && (Q0 == 1'b0) && (Q1 == 1'b0) && (Q3 == 1'b0))
    );

    // When S1S0==11, Q3==D and others are 0.
    sel11_routes_d_to_q3: assert property (
        @(posedge CLK) ( S1 &&  S0) |-> (Q3 == D && (Q0 == 1'b0) && (Q1 == 1'b0) && (Q2 == 1'b0))
    );

    // If Q0 is HIGH, then D=1 and S1S0==00.
    q0_high_implies_sel00_and_d: assert property (
        @(posedge CLK) (Q0 == 1'b1) |-> (D == 1'b1 && !S1 && !S0)
    );

    // If Q1 is HIGH, then D=1 and S1S0==01.
    q1_high_implies_sel01_and_d: assert property (
        @(posedge CLK) (Q1 == 1'b1) |-> (D == 1'b1 && !S1 &&  S0)
    );

    // If Q2 is HIGH, then D=1 and S1S0==10.
    q2_high_implies_sel10_and_d: assert property (
        @(posedge CLK) (Q2 == 1'b1) |-> (D == 1'b1 &&  S1 && !S0)
    );

    // If Q3 is HIGH, then D=1 and S1S0==11.
    q3_high_implies_sel11_and_d: assert property (
        @(posedge CLK) (Q3 == 1'b1) |-> (D == 1'b1 &&  S1 &&  S0)
    );

    // Outputs are at most one-hot at all times.
    outputs_onehot0: assert property (
        @(posedge CLK) $onehot0({Q3, Q2, Q1, Q0})
    );

    // OR of all outputs equals D.
    or_of_outputs_matches_d: assert property (
        @(posedge CLK) ((Q0 | Q1 | Q2 | Q3) == D)
    );
endmodule

module four_to_two_sva (
    input  logic        clk,   // verification clock (DUT has no clock/reset)
    input  logic [3:0]  in,
    input  logic [1:0]  out
);
    // LSB is odd parity of input bits.
    check_lsb_parity: assert property (
        @(posedge clk) out[0] == (^in)
    );

    // MSB is 1 iff exactly 2 or 3 ones (not all four).
    check_msb_two_or_three: assert property (
        @(posedge clk)
            out[1] == ( ((in[0]&in[1]) | (in[0]&in[2]) | (in[0]&in[3]) | (in[1]&in[2]) | (in[1]&in[3]) | (in[2]&in[3])) & ~(&in) )
    );

    // 0000 maps to 00.
    check_map_0000: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

    // 0001 maps to 01.
    check_map_0001: assert property (
        @(posedge clk) (in == 4'b0001) |-> (out == 2'b01)
    );

    // 0010 maps to 01.
    check_map_0010: assert property (
        @(posedge clk) (in == 4'b0010) |-> (out == 2'b01)
    );

