module up_down_counter (
    input clk,
    input up_down,
    input load,
    input [3:0] binary,
    output reg [3:0] count
);

always @(posedge clk) begin
    if (load) begin
        count <= binary;
    end else if (up_down) begin
        count <= count + 1;
    end else begin
        count <= count - 1;
    end
end

endmodule

