    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

    // LSB sum is XOR of A[0], B[0], and Cin.
    check_s0_is_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

    // When A[1]==B[1], S[1] equals carry out from bit0.
    check_s1_matches_c1_when_a1_eq_b1: assert property (
        @(posedge clk)
        (A[1] == B[1]) |-> (S[1] == ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // When A[1]!=B[1], S[1] is inverse of carry out from bit0.
    check_s1_inverts_c1_when_a1_ne_b1: assert property (
        @(posedge clk)
        (A[1] ^ B[1]) |-> (S[1] == ~((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

    // No overflow implies Cout is 0.
    check_cout_zero_when_no_overflow: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) < 5'd16) |-> (Cout == 1'b0)
    );

    // Overflow implies Cout is 1.
    check_cout_one_when_overflow: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

    // Adding zero B and zero Cin passes A through and no carry.
    check_add_zero_B_yields_A: assert property (
        @(posedge clk) ((B == 4'b0) && (Cin == 1'b0)) |-> ((S == A) && (Cout == 1'b0))
    );

    // Adding zero A and zero Cin passes B through and no carry.
    check_add_zero_A_yields_B: assert property (
        @(posedge clk) ((A == 4'b0) && (Cin == 1'b0)) |-> ((S == B) && (Cout == 1'b0))
    );

    // B is bitwise complement of A with Cin=0 yields S=0xF and no carry.
    check_complement_sum_all_ones: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b0)) |-> ((S == 4'hF) && (Cout == 1'b0))
    );

    // B is bitwise complement of A with Cin=1 yields S=0x0 and carry out.
    check_complement_with_cin_carryout: assert property (
        @(posedge clk) ((B == ~A) && (Cin == 1'b1)) |-> ((S == 4'h0) && (Cout == 1'b1))
    );

    // Outputs do not change when inputs hold constant.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(Cin)) |-> ($stable(S) && $stable(Cout))
    );
endmodule

module counter_3bit_sva (
    input logic clk,
    input logic rst,
    input logic enable,
    input logic load,
    input logic [2:0] data_in,
    input logic [2:0] count
);
    // While reset is asserted low, count must be 0.
    reset_drives_zero: assert property (
        @(posedge clk) !rst |-> (count == 3'b000)
    );

    // When enable is LOW, count holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && !enable) |=> (count == $past(count))
    );

    // When enable and load are HIGH, next count equals data_in.
    load_updates_count: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && load) |=> (count == $past(data_in))
    );

    // When enable is HIGH and load is LOW, next count increments by 1 (mod 8).
    increment_updates_count: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load) |=> (count == ($past(count) + 3'd1))
    );

    // Any change to count requires enable to have been HIGH in the previous cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && $changed(count)) |-> $past(enable)
    );

    // If load is HIGH but enable is LOW, count does not change.
    load_ignored_without_enable: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && !enable && load) |=> (count == $past(count))
    );

    // Increment wraps from 7 to 0 when enable is HIGH and load is LOW.
    wrap_on_increment_from_7: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load && ($past(count) == 3'd7)) |=> (count == 3'd0)
    );

    // Increment does not produce 0 unless previous value was 7.
    no_zero_after_increment_unless_from_7: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load && ($past(count) != 3'd7)) |=> (count != 3'd0)
    );

    // Increment always changes count (no self-loop when adding 1 mod 8).
    increment_always_changes_value: assert property (
        @(posedge clk) disable iff (!rst) ($past(rst) && enable && !load) |=> (count != $past(count))
    );

    // Two consecutive increments add 2 (mod 8).
    two_step_increment_sequence: assert property (
        @(posedge clk) disable iff (!rst)
            (enable && !load) ##1 (enable && !load) |=> (count == ($past(count,2) + 3'd2))
    );
endmodule

