module omsp_sync_cell (

// OUTPUTs
    data_out,                      // Synchronized data output

// INPUTs
    clk,                           // Receiving clock
    data_in,                       // Asynchronous data input
    rst                            // Receiving reset (active high)
);

output              data_out;      // Synchronized data output

input               clk;          // Receiving clock
input               data_in;      // Asynchronous data input
input               rst;          // Receiving reset (active high)



reg  [1:0] data_sync;

always @(posedge clk or posedge rst)
  if (rst) data_sync <=  2'b00;
  else     data_sync <=  {data_sync[0], data_in};

assign     data_out   =   data_sync[1];


endmodule

sva_code:
module omsp_sync_cell_sva (
    input  logic clk,
    input  logic rst,        // active high
    input  logic data_in,
    input  logic data_out,
    input  logic [1:0] data_sync
);
    // Reset forces internal state low.
    reset_clears_data_sync: assert property (
        @(posedge clk) rst |-> (data_sync == 2'b00)
    );

    // Reset drives output low.
    reset_drives_data_out_low: assert property (
        @(posedge clk) rst |-> (data_out == 1'b0)
    );

    // Output mirrors MSB of synchronizer.
    connect_data_out_to_msb: assert property (
        @(posedge clk) disable iff (rst) (data_out == data_sync[1])
    );

    // On each clock (no reset), LSB captures input (post-update check).
    lsb_captures_input_postupdate: assert property (
        @(posedge clk) disable iff (rst) ##0 (data_sync[0] == data_in)
    );

    // On each clock (no reset), MSB shifts from previous LSB (post-update check).
    msb_shifts_from_prev_lsb_postupdate: assert property (
        @(posedge clk) disable iff (rst) ##0 (data_sync[1] == $past(data_sync[0]))
    );

    // Combined post-update check: {out, lsb} matches {prev lsb, in}.
    pair_update_consistency: assert property (
        @(posedge clk) disable iff (rst) ##0 ({data_out, data_sync[0]} == {$past(data_sync[0]), data_in})
    );

    // With no reset on current and previous cycle, output equals last cycle's input.
    one_cycle_input_to_output_delay: assert property (
        @(posedge clk) disable iff (rst) (!$initstate && !$past(rst)) |-> (data_out == $past(data_in))
    );

    // On reset deassertion edge, output is driven low that cycle.
    output_low_on_reset_fall: assert property (
        @(posedge clk) $fell(rst) |-> (data_out == 1'b0)
    );

    // While reset is held, state and output remain zero.
    hold_zeros_while_reset: assert property (
        @(posedge clk) (rst && $past(rst)) |-> (data_sync == 2'b00) && (data_out == 1'b0)
    );
endmodule

verilog_code:
module reset_stretch #(
    parameter N = 4
)(
    input  wire clk,
    input  wire rst_in,
    output wire rst_out
);

reg reset_reg = 1;
reg [N-1:0] count_reg = 0;

assign rst_out = reset_reg;

always @(posedge clk or posedge rst_in) begin
    if (rst_in) begin
        count_reg <= 0;
        reset_reg <= 1;
    end else begin
        if (&count_reg) begin
            reset_reg <= 0;
        end else begin
            reset_reg <= 1;
            count_reg <= count_reg + 1;
        end
    end
end

endmodule

sva_code:
module reset_stretch_sva #(
    parameter int N = 4
)(
    input  logic             clk,
    input  logic             rst_in,
    input  logic             rst_out,
    // Internal signals from DUT (use hierarchical bind to connect)
    input  logic             reset_reg,
    input  logic [N-1:0]     count_reg
);
    // Clock: clk (posedge). Reset: rst_in (active-high, asynchronous). Logic: sequential counter with async reset and stretched deassert.

    // rst_out must mirror internal reset_reg.
    check_rst_out_mapping: assert property (
        @(posedge clk) rst_out == reset_reg
    );

    // When rst_in is asserted, next cycle count_reg is 0 and rst_out is 1.
    check_async_reset_values_next: assert property (
        @(posedge clk) rst_in |=> (count_reg == '0) && (rst_out == 1'b1)
    );

    // If rst_in stays asserted across cycles, count_reg remains 0 and rst_out remains 1.
    check_hold_while_reset: assert property (
        @(posedge clk) (rst_in && $past(rst_in)) |-> (count_reg == '0) && (rst_out == 1'b1)
    );

    // When not in reset and not saturated, count increments by 1 on the next cycle.
    check_count_increment_until_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (!(&count_reg)) |=> (count_reg == $past(count_reg) + 1'b1)
    );

    // When not in reset and not saturated, rst_out is 1 on the next cycle.
    check_out_high_until_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (!(&count_reg)) |=> (rst_out == 1'b1)
    );

    // When not in reset and saturated, rst_out is 0 on the next cycle.
    check_out_low_when_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (&count_reg) |=> (rst_out == 1'b0)
    );

    // When saturated (and not in reset), count_reg holds its value.
    check_count_stable_when_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (&count_reg) |=> (count_reg == $past(count_reg))
    );

    // In normal operation, low rst_out implies counter is saturated.
    check_out_low_implies_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (rst_out == 1'b0) |-> (&count_reg)
    );

    // In normal operation, high rst_out implies counter is not saturated.
    check_out_high_implies_not_saturated: assert property (
        @(posedge clk) disable iff (rst_in) (rst_out == 1'b1) |-> (!(&count_reg))
    );

    // On the first cycle that saturation occurs, rst_out falls.
    check_fall_on_saturation_edge: assert property (
        @(posedge clk) disable iff (rst_in) (!$past(&count_reg) && &count_reg) |-> $fell(rst_out)
    );

endmodule

