module data_modifier(
    input clk,
    input [15:0] data_in,
    input [1:0] control,
    output reg [15:0] data_out
);

always @(posedge clk) begin
    case (control)
        2'b00: data_out <= data_in;
        2'b01: data_out <= ~data_in;
        2'b10: data_out <= {data_in[14:0], 1'b0};
        2'b11: data_out <= {1'b0, data_in[15:1]};
    endcase
end

endmodule

sva_code:
module data_modifier_sva (
    input logic clk,
    input logic [15:0] data_in,
    input logic [1:0] control,
    input logic [15:0] data_out
);
    // Next cycle output equals input when control==00.
    check_passthrough: assert property (
        @(posedge clk) (control == 2'b00) |=> (data_out == $past(data_in))
    );

    // Next cycle output equals bitwise NOT of input when control==01.
    check_invert: assert property (
        @(posedge clk) (control == 2'b01) |=> (data_out == ~$past(data_in))
    );

    // Next cycle output equals left shift by 1 with zero LSB when control==10.
    check_shift_left_value: assert property (
        @(posedge clk) (control == 2'b10) |=> (data_out == {$past(data_in)[14:0], 1'b0})
    );

    // Next cycle output equals right shift by 1 with zero MSB when control==11.
    check_shift_right_value: assert property (
        @(posedge clk) (control == 2'b11) |=> (data_out == {1'b0, $past(data_in)[15:1]})
    );

    // On left shift, next LSB is 0.
    check_shift_left_lsb_zero: assert property (
        @(posedge clk) (control == 2'b10) |=> (data_out[0] == 1'b0)
    );

    // On right shift, next MSB is 0.
    check_shift_right_msb_zero: assert property (
        @(posedge clk) (control == 2'b11) |=> (data_out[15] == 1'b0)
    );

    // On left shift, next upper bits track prior input [14:0].
    check_shift_left_bit_propagation: assert property (
        @(posedge clk) (control == 2'b10) |=> (data_out[15:1] == $past(data_in)[14:0])
    );

    // On right shift, next lower bits track prior input [15:1].
    check_shift_right_bit_propagation: assert property (
        @(posedge clk) (control == 2'b11) |=> (data_out[14:0] == $past(data_in)[15:1])
    );

    // One-cycle-late functional mapping matches the case statement for all control values.
    check_combined_map: assert property (
        @(posedge clk) 1'b1 |=> (
            data_out ==
                (($past(control) == 2'b00) ? $past(data_in) :
                 ($past(control) == 2'b01) ? ~$past(data_in) :
                 ($past(control) == 2'b10) ? {$past(data_in)[14:0], 1'b0} :
                                             {1'b0, $past(data_in)[15:1]})
        )
    );

    // On invert, next output XOR prior input is all ones.
    check_invert_xor_ones: assert property (
        @(posedge clk) (control == 2'b01) |=> ((data_out ^ $past(data_in)) == 16'hFFFF)
    );
endmodule

verilog_code:
module uart_sync_flops
(
  rst_i,
  clk_i,
  stage1_rst_i,
  stage1_clk_en_i,
  async_dat_i,
  sync_dat_o
);

parameter width         = 1;
parameter init_value    = 1'b0;

input                           rst_i;                  input                           clk_i;                  input                           stage1_rst_i;           input                           stage1_clk_en_i;        input   [width-1:0]             async_dat_i;            output  [width-1:0]             sync_dat_o;             reg     [width-1:0]             sync_dat_o;
reg     [width-1:0]             flop_0;


always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        flop_0 <= {width{init_value}};
    else
        flop_0 <= async_dat_i;    
end

always @ (posedge clk_i or posedge rst_i)
begin
    if (rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_rst_i)
        sync_dat_o <= {width{init_value}};
    else if (stage1_clk_en_i)
        sync_dat_o <= flop_0;       
end

endmodule

sva_code:
module uart_sync_flops_sva #(
    parameter width      = 1,
    parameter init_value = 1'b0
) (
    input  logic                  rst_i,
    input  logic                  clk_i,
    input  logic                  stage1_rst_i,
    input  logic                  stage1_clk_en_i,
    input  logic [width-1:0]      async_dat_i,
    input  logic [width-1:0]      sync_dat_o
);
    localparam logic [width-1:0] INIT = {width{init_value}};

    ///// Reset behavior /////
    // While global reset is asserted, sync_dat_o must be INIT.
    check_sync_init_while_rst: assert property (
        @(posedge clk_i) rst_i |-> (sync_dat_o == INIT)
    );

    ///// Stage1 reset behavior /////
    // stage1_rst_i sets sync_dat_o to INIT on the next cycle.
    check_stage1_reset_sets_init: assert property (
        @(posedge clk_i) disable iff (rst_i) stage1_rst_i |-> ##1 (sync_dat_o == INIT)
    );

    // stage1_rst_i has priority over enable when both are HIGH.
    check_stage1_reset_priority_over_enable: assert property (
        @(posedge clk_i) disable iff (rst_i) (stage1_rst_i && stage1_clk_en_i) |-> ##1 (sync_dat_o == INIT)
    );

    ///// Enable/hold behavior /////
    // With no resets and enable LOW, sync_dat_o holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk_i) disable iff (rst_i) (!stage1_rst_i && !stage1_clk_en_i) |-> ##1 (sync_dat_o == $past(sync_dat_o))
    );

    // If sync_dat_o changes without global reset, prior enable or stage1 reset must be the cause.
    check_change_requires_enable_or_stage1_reset: assert property (
        @(posedge clk_i) disable iff (rst_i) ($changed(sync_dat_o) && !$past(rst_i)) |-> ($past(stage1_clk_en_i) || $past(stage1_rst_i))
    );

    ///// Dataflow through the two-stage synchronizer /////
    // With no resets now and previously, enable updates sync_dat_o from prior async_dat_i.
    check_enable_updates_from_prev_input: assert property (
        @(posedge clk_i) disable iff (rst_i)
            (stage1_clk_en_i && !stage1_rst_i && !$past(rst_i)) |-> ##1 (sync_dat_o == $past(async_dat_i))
    );

    // If previous cycle was under global reset, enable updates sync_dat_o to INIT.
    check_enable_updates_to_init_after_prev_reset: assert property (
        @(posedge clk_i) disable iff (rst_i)
            (stage1_clk_en_i && !stage1_rst_i && $past(rst_i)) |-> ##1 (sync_dat_o == INIT)
    );
endmodule

