module nand3_gate(input A, input B, input C, output Y);

    // Inputs are registered
    reg A_reg;
    reg B_reg;
    reg C_reg;

    // Outputs are wires
    wire Y_and;

    // Connect to power and ground
    supply1 VDD;
    supply0 VSS;

    // Instantiate buffers
    buf A_buf (A, A_reg);
    buf B_buf (B, B_reg);
    buf C_buf (C, C_reg);
    buf Y_buf (Y_and, Y);

    // Instantiate NAND gates
    nand (Y_and, A_reg, B_reg, C_reg); // 3-input NAND gate

endmodule

sva_code:
module nand3_gate_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic Y
);
    ///// Combinational NAND behavior sampled on A's posedge /////
    // Y equals the 3-input NAND of A, B, and C.
    check_nand_function: assert property (
        @(posedge A) Y == ~(A & B & C)
    );

    // If any input is 0, Y must be 1.
    check_any_input_low_implies_y_high: assert property (
        @(posedge A) (!A || !B || !C) |-> (Y == 1'b1)
    );

    // Y can be 0 only when all inputs are 1.
    check_y_low_only_when_all_inputs_high: assert property (
        @(posedge A) (Y == 1'b0) |-> (A && B && C)
    );

    // When B and C are 1 and Y was 1, a rising A causes Y to fall.
    check_y_falls_when_a_rises_with_bc_high: assert property (
        @(posedge A) (B && C && $past(Y) == 1'b1) |-> $fell(Y)
    );

    // When either B or C is 0, a rising A leaves Y high.
    check_y_stays_high_when_bc_not_both_high_on_a_rise: assert property (
        @(posedge A) ((!B || !C)) |-> (Y == 1'b1)
    );
endmodule

verilog_code:
module twos_complement(
    input [3:0] in,
    output [3:0] out
);

wire [3:0] inv;
wire [3:0] add_one;

// invert all bits of input
assign inv = ~in;

// add 1 to inverted input
assign add_one = inv + 4'b0001;

// assign result to output
assign out = add_one;

endmodule

sva_code:
module twos_complement_sva (
    input  logic        clk,   // No clock/reset in DUT; use external clk for sampling
    input  logic [3:0]  in,
    input  logic [3:0]  out
);
    // out implements two's complement of in (4-bit wrap)
    check_twos_complement_equation: assert property (
        @(posedge clk) out == ((~in) + 4'd1)
    );

    // in + out wraps to zero modulo 16
    check_additive_inverse_mod16: assert property (
        @(posedge clk) (in + out) == 4'd0
    );

    // 0 maps to 0
    check_zero_maps_to_zero: assert property (
        @(posedge clk) (in == 4'd0) |-> (out == 4'd0)
    );

    // 1 maps to 0xF
    check_one_maps_to_all_ones: assert property (
        @(posedge clk) (in == 4'd1) |-> (out == 4'hF)
    );

    // 0xF maps to 1
    check_all_ones_maps_to_one: assert property (
        @(posedge clk) (in == 4'hF) |-> (out == 4'd1)
    );

    // Two's complement equals (0 - in) modulo 16
    check_subtraction_form: assert property (
        @(posedge clk) out == (4'd0 - in)
    );

    // Double two's complement returns original value
    check_double_complement_is_identity: assert property (
        @(posedge clk) ((~out) + 4'd1) == in
    );

    // Bitwise NOT of out equals (in - 1) modulo 16
    check_not_out_equals_in_minus_one: assert property (
        @(posedge clk) (~out) == (in - 4'd1)
    );

    // LSB is preserved by two's complement
    check_lsb_preserved: assert property (
        @(posedge clk) out[0] == in[0]
    );

    // Minimum 4-bit value (8) maps to itself
    check_min_int_maps_to_itself: assert property (
        @(posedge clk) (in == 4'd8) |-> (out == 4'd8)
    );
endmodule

verilog_code:
module right_barrel_shifter(
	input [7:0] d_in,
	input [2:0] shift_amount,
	output reg [7:0] d_out
);

always @* begin
	case (shift_amount)
		0 : d_out = d_in;
		1 : d_out = {d_in[0], d_in[7:1]}; 2 : d_out = {d_in[1:0], d_in[7:2]};
		3 : d_out = {d_in[2:0], d_in[7:3]};
		4 : d_out = {d_in[3:0], d_in[7:4]};
		5 : d_out = {d_in[4:0], d_in[7:5]};
		6 : d_out = {d_in[5:0], d_in[7:6]};
		7 : d_out = 0;
	endcase
end 

endmodule

sva_code:
module right_barrel_shifter_sva (
    input logic CLK,
    input logic [7:0] d_in,
    input logic [2:0] shift_amount,
    input logic [7:0] d_out
);
    // d_out must equal input when shift_amount == 0.
    check_shift0_identity: assert property (
        @(posedge CLK) (shift_amount == 3'd0) |=> (d_out == d_in)
    );

    // d_out must be a right rotate by 1 when shift_amount == 1.
    check_shift1_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd1) |=> (d_out == {d_in[0], d_in[7:1]})
    );

    // d_out must be a right rotate by 2 when shift_amount == 2.
    check_shift2_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd2) |=> (d_out == {d_in[1:0], d_in[7:2]})
    );

    // d_out must be a right rotate by 3 when shift_amount == 3.
    check_shift3_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd3) |=> (d_out == {d_in[2:0], d_in[7:3]})
    );

    // d_out must be a right rotate by 4 when shift_amount == 4.
    check_shift4_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd4) |=> (d_out == {d_in[3:0], d_in[7:4]})
    );

    // d_out must be a right rotate by 5 when shift_amount == 5.
    check_shift5_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd5) |=> (d_out == {d_in[4:0], d_in[7:5]})
    );

    // d_out must be a right rotate by 6 when shift_amount == 6.
    check_shift6_rotate: assert property (
        @(posedge CLK) (shift_amount == 3'd6) |=> (d_out == {d_in[5:0], d_in[7:6]})
    );

    // d_out must be zero when shift_amount == 7.
    check_shift7_zero: assert property (
        @(posedge CLK) (shift_amount == 3'd7) |=> (d_out == 8'h00)
    );

    // d_out must always match the full case mapping of the RTL.
    check_full_mapping: assert property (
        @(posedge CLK)
            1'b1 |=> (
                d_out == (
                    (shift_amount == 3'd0) ? d_in :
                    (shift_amount == 3'd1) ? {d_in[0],     d_in[7:1]} :
                    (shift_amount == 3'd2) ? {d_in[1:0],   d_in[7:2]} :
                    (shift_amount == 3'd3) ? {d_in[2:0],   d_in[7:3]} :
                    (shift_amount == 3'd4) ? {d_in[3:0],   d_in[7:4]} :
                    (shift_amount == 3'd5) ? {d_in[4:0],   d_in[7:5]} :
                    (shift_amount == 3'd6) ? {d_in[5:0],   d_in[7:6]} :
                                              8'h00
                )
            )
    );
endmodule

verilog_code:
module addsub_4bit (
    input [3:0] O,
    input [3:0] A,
    input C,
    output reg [3:0] S,
    output reg [3:0] D,
    output reg B
);

always @(*) begin
    if (C == 1'b1) begin
        S = O + A;
        D = 4'b0;
        B = 1'b0;
    end else begin
        S = 4'b0;
        if (O < A) begin
            D = (O + 16) - A;
            B = 1'b1;
        end else begin
            D = O - A;
            B = 1'b0;
        end
    end
end

endmodule

sva_code:
module addsub_4bit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [3:0] O,
    input logic [3:0] A,
    input logic C,
    input logic [3:0] S,
    input logic [3:0] D,
    input logic B
);
    // Addition mode: S is O + A (4-bit).
    check_add_sum: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (S == ((O + A) & 4'hF))
    );

    // Addition mode: D is zero.
    check_add_d_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (D == 4'b0)
    );

    // Addition mode: B is zero.
    check_add_b_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b1) |-> (B == 1'b0)
    );

    // Subtraction mode: S is zero.
    check_sub_s_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (S == 4'b0)
    );

    // Subtraction no-borrow path: D = (O - A) (4-bit).
    check_sub_no_borrow_d: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && !(O < A)) |-> (D == ((O - A) & 4'hF))
    );

    // Subtraction no-borrow path: B = 0.
    check_sub_no_borrow_b: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && !(O < A)) |-> (B == 1'b0)
    );

    // Subtraction borrow path: D = (O + 16) - A (low 4 bits).
    check_sub_borrow_d: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O < A)) |-> (D == (((O + 5'd16) - A) & 4'hF))
    );

    // Subtraction borrow path: B = 1.
    check_sub_borrow_b: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O < A)) |-> (B == 1'b1)
    );

    // In subtraction mode, B matches (O < A).
    check_sub_b_matches_comparison: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (B == (O < A))
    );

    // In subtraction mode, D equals (O - A) modulo 16.
    check_sub_d_modulo: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0) |-> (D == ((O - A) & 4'hF))
    );

    // Special case: O == A in subtraction yields D=0 and B=0.
    check_sub_equal_inputs: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (C == 1'b0 && (O == A)) |-> (D == 4'b0 && B == 1'b0)
    );
endmodule

verilog_code:
module signal_converter(
    input [3:0] in_signal,
    output reg [2:0] out_signal
);

always @(*) begin
    if (in_signal < 4) begin
        out_signal = in_signal;
    end else if (in_signal < 8) begin
        out_signal = in_signal - 1;
    end else begin
        out_signal = in_signal - 2;
    end
end

endmodule

sva_code:
module signal_converter_sva (
    input logic clk,
    input logic [3:0] in_signal,
    input logic [2:0] out_signal
);

    // For in_signal < 4, out_signal equals in_signal.
    check_map_lt4: assert property (
        @(posedge clk) (in_signal < 4'd4) |-> (out_signal == in_signal[2:0])
    );

    // For 4 <= in_signal < 8, out_signal equals in_signal - 1.
    check_map_4_to_7: assert property (
        @(posedge clk) ((in_signal >= 4'd4) && (in_signal < 4'd8)) |-> (out_signal == (in_signal - 4'd1)[2:0])
    );

    // For in_signal >= 8, out_signal equals in_signal - 2 (truncated to 3 bits).
    check_map_ge8: assert property (
        @(posedge clk) (in_signal >= 4'd8) |-> (out_signal == (in_signal - 4'd2)[2:0])
    );

    // Boundary: in_signal == 0 => out_signal == 0.
    check_in0: assert property (
        @(posedge clk) (in_signal == 4'd0) |-> (out_signal == 3'd0)
    );

    // Boundary: in_signal == 3 => out_signal == 3.
    check_in3: assert property (
        @(posedge clk) (in_signal == 4'd3) |-> (out_signal == 3'd3)
    );

    // Boundary: in_signal == 4 => out_signal == 3 (start of middle range).
    check_in4: assert property (
        @(posedge clk) (in_signal == 4'd4) |-> (out_signal == 3'd3)
    );

    // Boundary: in_signal == 7 => out_signal == 6 (end of middle range).
    check_in7: assert property (
        @(posedge clk) (in_signal == 4'd7) |-> (out_signal == 3'd6)
    );

    // Boundary: in_signal == 8 => out_signal == 6 (start of upper range).
    check_in8: assert property (
        @(posedge clk) (in_signal == 4'd8) |-> (out_signal == 3'd6)
    );

    // Wrap example: in_signal == 10 => out_signal == 0 ((10-2)=8 -> 3'b000).
    check_in10_wrap0: assert property (
        @(posedge clk) (in_signal == 4'd10) |-> (out_signal == 3'd0)
    );

    // Boundary: in_signal == 15 => out_signal == 5 ((15-2)=13 -> 3'b101).
    check_in15: assert property (
        @(posedge clk) (in_signal == 4'd15) |-> (out_signal == 3'd5)
    );

endmodule

verilog_code:
module byte_reverse (
    input [31:0] in,
    output [31:0] out
);
    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};
endmodule
module xor_gate (
    input [31:0] a,
    input [31:0] b,
    output [31:0] out
);
    assign out = a ^ b;
endmodule
module functional_module (
    input [31:0] byte_reverse_out,
    input [31:0] xor_gate_out,
    output [31:0] out
);
    assign out = byte_reverse_out ^ xor_gate_out;
endmodule
module output_select (
    input [31:0] byte_reverse_in,
    input [31:0] xor_gate_in,
    input select,
    output [31:0] out
);
    wire [31:0] byte_reverse_out;
    wire [31:0] xor_gate_out;

    byte_reverse byte_reverse_inst (
        .in(byte_reverse_in),
        .out(byte_reverse_out)
    );

    xor_gate xor_gate_inst (
        .a(xor_gate_in),
        .b(xor_gate_in),
        .out(xor_gate_out)
    );

    assign out = select ? byte_reverse_out : xor_gate_out;
endmodule
module top_module (
    input [31:0] in,
    input select,
    output [31:0] out
);
    wire [31:0] byte_reverse_out;
    wire [31:0] xor_gate_out;

    byte_reverse byte_reverse_inst (
        .in(in),
        .out(byte_reverse_out)
    );

    xor_gate xor_gate_inst (
        .a(in),
        .b(in),
        .out(xor_gate_out)
    );

    output_select output_select_inst (
        .byte_reverse_in(byte_reverse_out),
        .xor_gate_in(xor_gate_out),
        .select(select),
        .out(out)
    );
endmodule

sva_code:
module top_module_sva (
    input logic [31:0] in,
    input logic        select,
    input logic [31:0] out
);
    // On select rising edge, out must equal in.
    check_out_eq_in_on_select_rise: assert property (
        @(posedge select) out == in
    );

    // On select falling edge, out must be all zeros.
    check_out_zero_on_select_fall: assert property (
        @(negedge select) out == 32'h0
    );

    // Out equals masked form {32{select}} & in on in[0] rising edge.
    check_mask_equivalence_pos_in0: assert property (
        @(posedge in[0]) out == ({32{select}} & in)
    );

    // Out equals masked form {32{select}} & in on in[0] falling edge.
    check_mask_equivalence_neg_in0: assert property (
        @(negedge in[0]) out == ({32{select}} & in)
    );

    // Out has no bits set outside of in (subset) on in[1] rising edge.
    check_out_subset_of_in: assert property (
        @(posedge in[1]) (out & ~in) == 32'h0
    );

    // OR with in returns in on in[2] rising edge.
    check_out_or_in_equals_in: assert property (
        @(posedge in[2]) (out | in) == in
    );

    // XOR relation: out ^ in equals (~select) mask of in on in[3] rising edge.
    check_xor_relation: assert property (
        @(posedge in[3]) (out ^ in) == ({32{~select}} & in)
    );

    // Nonzero out implies select is HIGH on in[4] rising edge.
    check_nonzero_out_implies_select: assert property (
        @(posedge in[4]) (|out) |-> (select == 1'b1)
    );

    // When select is LOW, out must be zero on in[5] rising edge.
    check_select_low_implies_zero_pos_in5: assert property (
        @(posedge in[5]) (select == 1'b0) |-> (out == 32'h0)
    );

    // When select is LOW, out must be zero on in[5] falling edge.
    check_select_low_implies_zero_neg_in5: assert property (
        @(negedge in[5]) (select == 1'b0) |-> (out == 32'h0)
    );

    // When select is HIGH, out equals in on in[6] rising edge.
    check_select_high_implies_out_eq_in: assert property (
        @(posedge in[6]) (select == 1'b1) |-> (out == in)
    );

    // Out is idempotent with in: (out & in) == out on in[7] rising edge.
    check_out_idempotent_with_in: assert property (
        @(posedge in[7]) (out & in) == out
    );
endmodule

verilog_code:
module mux_4to1(
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [1:0] sel,
    output [3:0] result
);

wire [3:0] sel_0, sel_1, sel_2, sel_3;

assign sel_0 = (sel == 2'b00) ? data0 : 4'b0000;
assign sel_1 = (sel == 2'b01) ? data1 : 4'b0000;
assign sel_2 = (sel == 2'b10) ? data2 : 4'b0000;
assign sel_3 = (sel == 2'b11) ? data3 : 4'b0000;

assign result = sel_0 | sel_1 | sel_2 | sel_3;

endmodule

sva_code:
module mux_4to1_sva (
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [1:0] sel,
    input logic [3:0] result
);
    // Analysis: no clock/reset in RTL; pure combinational 4:1 mux; assertions clocked on $global_clock.

    // Result equals masked-OR of inputs per select.
    check_mux_masked_or_equivalence: assert property (
        @(posedge $global_clock)
        result == ( ({4{(sel == 2'b00)}} & data0)
                  | ({4{(sel == 2'b01)}} & data1)
                  | ({4{(sel == 2'b10)}} & data2)
                  | ({4{(sel == 2'b11)}} & data3) )
    );

    // When sel==00, result equals data0.
    check_sel00_routing: assert property (
        @(posedge $global_clock) (sel == 2'b00) |-> (result == data0)
    );

    // When sel==01, result equals data1.
    check_sel01_routing: assert property (
        @(posedge $global_clock) (sel == 2'b01) |-> (result == data1)
    );

    // When sel==10, result equals data2.
    check_sel10_routing: assert property (
        @(posedge $global_clock) (sel == 2'b10) |-> (result == data2)
    );

    // When sel==11, result equals data3.
    check_sel11_routing: assert property (
        @(posedge $global_clock) (sel == 2'b11) |-> (result == data3)
    );

    // If sel==00 and sel/data0 are stable, result remains stable.
    check_stable_sel00: assert property (
        @(posedge $global_clock) (sel == 2'b00) && $stable(sel) && $stable(data0) |-> $stable(result)
    );

    // If sel==01 and sel/data1 are stable, result remains stable.
    check_stable_sel01: assert property (
        @(posedge $global_clock) (sel == 2'b01) && $stable(sel) && $stable(data1) |-> $stable(result)
    );

    // If sel==10 and sel/data2 are stable, result remains stable.
    check_stable_sel10: assert property (
        @(posedge $global_clock) (sel == 2'b10) && $stable(sel) && $stable(data2) |-> $stable(result)
    );

    // If sel==11 and sel/data3 are stable, result remains stable.
    check_stable_sel11: assert property (
        @(posedge $global_clock) (sel == 2'b11) && $stable(sel) && $stable(data3) |-> $stable(result)
    );

    // If all inputs are equal, result equals that common value.
    check_all_inputs_equal_output: assert property (
        @(posedge $global_clock) ((data0 == data1) && (data1 == data2) && (data2 == data3)) |-> (result == data0)
    );

endmodule

