sva_code:
module binary_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S
);
    // S equals (A+B) modulo 16.
    check_sum_mod16: assert property (
        @(posedge clk) S == ((A + B) & 4'hF)
    );

    // If inputs hold their values, S holds as well.
    check_stable_if_inputs_hold: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> $stable(S)
    );

    // Adding zero on B leaves S equal to A.
    check_identity_B_zero: assert property (
        @(posedge clk) (B == 4'd0) |-> (S == A)
    );

    // Adding zero on A leaves S equal to B.
    check_identity_A_zero: assert property (
        @(posedge clk) (A == 4'd0) |-> (S == B)
    );

    // Both inputs zero results in zero sum.
    check_zero_plus_zero: assert property (
        @(posedge clk) (A == 4'd0 && B == 4'd0) |-> (S == 4'd0)
    );

    // If A is stable and B increments by 1 (mod 16), S increments by 1 (mod 16).
    check_increment_B: assert property (
        @(posedge clk) ($stable(A) && (B == $past(B) + 4'd1)) |-> (S == $past(S) + 4'd1)
    );

    // If A is stable and B decrements by 1 (mod 16), S decrements by 1 (mod 16).
    check_decrement_B: assert property (
        @(posedge clk) ($stable(A) && (B == $past(B) - 4'd1)) |-> (S == $past(S) - 4'd1)
    );

    // If B is stable and A increments by 1 (mod 16), S increments by 1 (mod 16).
    check_increment_A: assert property (
        @(posedge clk) ($stable(B) && (A == $past(A) + 4'd1)) |-> (S == $past(S) + 4'd1)
    );

    // If B is stable and A decrements by 1 (mod 16), S decrements by 1 (mod 16).
    check_decrement_A: assert property (
        @(posedge clk) ($stable(B) && (A == $past(A) - 4'd1)) |-> (S == $past(S) - 4'd1)
    );

    // Swapping A and B across cycles leaves S unchanged (commutativity).
    check_swap_commutativity: assert property (
        @(posedge clk) (A == $past(B) && B == $past(A)) |-> (S == $past(S))
    );
endmodule

module simple_calculator_sva (
    input logic [15:0] operand_a,
    input logic [15:0] operand_b,
    input logic [1:0]  operation,
    input logic [15:0] result
);
    // No clock/reset in RTL; pure combinational. Use $global_clock for assertions.

    // Addition result matches lower 16 bits of sum when operation == 00.
    check_addition_result: assert property (
        @(posedge $global_clock) (operation == 2'b00) |-> (result == (operand_a + operand_b)[15:0])
    );

    // Subtraction result matches lower 16 bits of difference when operation == 01.
    check_subtraction_result: assert property (
        @(posedge $global_clock) (operation == 2'b01) |-> (result == (operand_a - operand_b)[15:0])
    );

    // Multiplication result matches lower 16 bits of product when operation == 10.
    check_multiplication_result: assert property (
        @(posedge $global_clock) (operation == 2'b10) |-> (result == (operand_a * operand_b)[15:0])
    );

    // Division result matches quotient when operation == 11 and divisor != 0.
    check_division_result_nonzero: assert property (
        @(posedge $global_clock) (operation == 2'b11 && (operand_b != 16'h0000)) |-> (result == (operand_a / operand_b)[15:0])
    );

    // Addition by zero returns operand_a.
    check_add_zero_identity: assert property (
        @(posedge $global_clock) (operation == 2'b00 && operand_b == 16'h0000) |-> (result == operand_a)
    );

    // Subtraction by zero returns operand_a.
    check_sub_zero_identity: assert property (
        @(posedge $global_clock) (operation == 2'b01 && operand_b == 16'h0000) |-> (result == operand_a)
    );

    // Subtraction of equal operands yields zero.
    check_sub_self_zero: assert property (
        @(posedge $global_clock) (operation == 2'b01 && operand_a == operand_b) |-> (result == 16'h0000)
    );

    // Multiplication by zero yields zero.
    check_mul_zero_annihilator: assert property (
        @(posedge $global_clock) (operation == 2'b10 && (operand_a == 16'h0000 || operand_b == 16'h0000)) |-> (result == 16'h0000)
    );

    // Multiplication by one returns operand_a.
    check_mul_one_identity: assert property (
        @(posedge $global_clock) (operation == 2'b10 && operand_b == 16'h0001) |-> (result == operand_a)
    );

    // Division by one returns operand_a.
    check_div_one_identity: assert property (
        @(posedge $global_clock) (operation == 2'b11 && operand_b == 16'h0001) |-> (result == operand_a)
    );
endmodule

module up_counter_sva (
    input logic CLK,
    input logic RST,
    input logic EN,
    input logic [3:0] Q
);

    // On reset, Q becomes zero on the next cycle.
    reset_drives_zero_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'd0)
    );

    // Reset overrides EN when both are asserted.
    reset_overrides_enable: assert property (
        @(posedge CLK) (RST && EN) |=> (Q == 4'd0)
    );

    // When EN=0 and not in reset, Q holds its value.
    hold_when_en_low: assert property (
        @(posedge CLK) disable iff (RST) (!EN) |=> $stable(Q)
    );

    // When EN=1 and not in reset, Q increments by 1 modulo 16.
    increment_when_en_high: assert property (
        @(posedge CLK) disable iff (RST) EN |=> (Q == $past(Q) + 4'd1)
    );

    // If previous Q was 0xF with EN=1, next Q wraps to 0.
    wrap_from_max_on_enable: assert property (
        @(posedge CLK) disable iff (RST) (EN && ($past(Q) == 4'hF)) |=> (Q == 4'd0)
    );

    // Q changes only if EN or RST was asserted in the prior cycle.
    change_only_on_en_or_rst_prev: assert property (
        @(posedge CLK) disable iff (RST) $changed(Q) |-> $past(RST || EN)
    );

    // Without reset in prior cycle, Q either holds or increments by 1.
    at_most_one_step_no_reset: assert property (
        @(posedge CLK) disable iff (RST) $past(!RST) |-> ((Q == $past(Q)) || (Q == $past(Q) + 4'd1))
    );

endmodule

