module sky130_fd_sc_hd__o2bb2a (
    input  A1_N,
    input  A2_N,
    input  B1  ,
    input  B2  ,
    output X
);

    // Implement the logic for the module
    assign X = (A1_N == 1) && (A2_N == 0) && (B1 == 1) && (B2 == 0);

endmodule

sva_code:
module sky130_fd_sc_hd__o2bb2a_sva (
    input  logic CLK,   // external sample clock for assertions
    input  logic A1_N,
    input  logic A2_N,
    input  logic B1,
    input  logic B2,
    input  logic X
);
    // X implements A1_N & ~A2_N & B1 & ~B2.
    check_functional_equivalence: assert property (
        @(posedge CLK) X == (A1_N && !A2_N && B1 && !B2)
    );

    // X can be 1 only when the input pattern holds.
    check_x_high_requires_pattern: assert property (
        @(posedge CLK) X |-> (A1_N && !A2_N && B1 && !B2)
    );

    // When the input pattern holds, X must be 1.
    check_pattern_implies_x_high: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) |-> X
    );

    // A1_N low forces X low.
    check_a1n_zero_forces_x_zero: assert property (
        @(posedge CLK) !A1_N |-> !X
    );

    // A2_N high forces X low.
    check_a2n_one_forces_x_zero: assert property (
        @(posedge CLK) A2_N |-> !X
    );

    // B1 low forces X low.
    check_b1_zero_forces_x_zero: assert property (
        @(posedge CLK) !B1 |-> !X
    );

    // B2 high forces X low.
    check_b2_one_forces_x_zero: assert property (
        @(posedge CLK) B2 |-> !X
    );

    // If inputs are stable, X is stable.
    check_x_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(A1_N) && $stable(A2_N) && $stable(B1) && $stable(B2)) |-> $stable(X)
    );

    // Leaving the pattern via A1_N going low makes X low next cycle.
    check_leave_pattern_via_a1n_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!A1_N) |-> !X
    );

    // Leaving the pattern via A2_N going high makes X low next cycle.
    check_leave_pattern_via_a2n_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (A2_N) |-> !X
    );

    // Leaving the pattern via B1 going low makes X low next cycle.
    check_leave_pattern_via_b1_drop: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (!B1) |-> !X
    );

    // Leaving the pattern via B2 going high makes X low next cycle.
    check_leave_pattern_via_b2_rise: assert property (
        @(posedge CLK) (A1_N && !A2_N && B1 && !B2) ##1 (B2) |-> !X
    );
endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic load,
    input logic [3:0] data,
    input logic [1:0] shift,
    input logic [3:0] result
);
    // Clock: clk (posedge). No reset in RTL.
    // Sequential: result updates on clk; load has priority; else shift by shift.

    // When load was HIGH last cycle, result now equals last cycle's data.
    load_captures_data: assert property (
        @(posedge clk) $past(load) |-> (result == $past(data))
    );

    // With no load and shift==00 last cycle, result holds its previous value.
    no_shift_holds: assert property (
        @(posedge clk) $past(!load && (shift == 2'b00)) |-> (result == $past(result))
    );

    // With no load and shift==01 last cycle, result = {old result[2:0], old data[3]}.
    shift_left_by_1: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result == {$past(result[2:0]), $past(data[3])})
    );

    // With no load and shift==10 last cycle, result = {old data[0], old result[3:1]}.
    shift_right_by_1: assert property (
        @(posedge clk) $past(!load && (shift == 2'b10)) |-> (result == {$past(data[0]), $past(result[3:1])})
    );

    // With no load and shift==11 last cycle, result = {old data[1:0], old result[3:2]}.
    shift_right_by_2: assert property (
        @(posedge clk) $past(!load && (shift == 2'b11)) |-> (result == {$past(data[1:0]), $past(result[3:2])})
    );

    // Bit check for shift==01: upper three bits move down by one.
    shift_left_by_1_upper_bits: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result[3:1] == $past(result[2:0]))
    );

    // Bit check for shift==01: LSB comes from data[3].
    shift_left_by_1_lsb_from_data3: assert property (
        @(posedge clk) $past(!load && (shift == 2'b01)) |-> (result[0] == $past(data[3]))
    );

    // Bit check for shift==10: MSB comes from data[0].
    shift_right_by_1_msb_from_data0: assert property (
        @(posedge clk) $past(!load && (shift == 2'b10)) |-> (result[3] == $past(data[0]))
    );

    // Bit check for shift==11: top two bits come from data[1:0].
    shift_right_by_2_top_from_data10: assert property (
        @(posedge clk) $past(!load && (shift == 2'b11)) |-> (result[3:2] == $past(data[1:0]))
    );
endmodule

