module full_adder (
    input A,
    input B,
    input CIN,
    output COUT,
    output SUM
);
    assign SUM = A ^ B ^ CIN; // XOR gate for sum
    assign COUT = (A & B) | (B & CIN) | (A & CIN); // OR gate for carry
