    check_left_shift1_eq: assert property (
        @(posedge CLK) disable iff (!RESETn) (control == 2'b00) |-> (out == (in << 1))
    );
    // For control 01, output equals input shifted left by 2.
    check_left_shift2_eq: assert property (
