    ///// Functional correctness /////
    // {Cout,S} equals the 5-bit sum of A and B.
    check_result_matches_addition: assert property (
        @(posedge clk) {Cout, S} == (A + B)
    );

    // S is the low 4 bits of A+B.
    check_S_is_low4_of_sum: assert property (
        @(posedge clk) S == (A + B)[3:0]
    );

    // Cout is the MSB (carry-out) of A+B.
    check_Cout_is_carry_of_sum: assert property (
        @(posedge clk) Cout == (A + B)[4]
    );

    ///// Ripple-carry structure equivalence /////
    // Bit 0 sum: no carry-in.
    check_s0_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum uses carry from bit 0.
    check_s1_rca: assert property (
        @(posedge clk) S[1] == ((A[1] ^ B[1]) ^ (A[0] & B[0]))
    );

    // Bit 2 sum uses carry from bit 1.
    check_s2_rca: assert property (
        @(posedge clk) S[2] == ((A[2] ^ B[2]) ^ (((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))
    );

    // Bit 3 sum uses carry from bit 2.
    check_s3_rca: assert property (
        @(posedge clk) S[3] == ((A[3] ^ B[3]) ^ (((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );

    // Final carry-out from bit 3.
    check_cout_rca: assert property (
        @(posedge clk) Cout == ((A[3] & B[3]) | ((A[3] ^ B[3]) & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );

    ///// Overflow/carry equivalence /////
    // If sum exceeds 4 bits, Cout must be 1.
    check_overflow_sets_cout: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B}) > 5'd15) |-> (Cout == 1'b1)
    );

    // Cout high implies sum exceeds 4 bits.
    check_cout_implies_overflow: assert property (
        @(posedge clk) Cout |-> (({1'b0, A} + {1'b0, B}) > 5'd15)
    );

    ///// Determinism /////
    // If inputs are stable cycle-to-cycle, outputs remain stable.
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A, B}) |-> $stable({S, Cout})
    );

endmodule

module bitwise_full_adder_sva (
    input logic A,
    input logic B,
    input logic CIN,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB,
    input logic COUT,
    input logic SUM
);

    ///// Combinational full-adder function /////
    // SUM equals XOR of inputs.
    check_sum_definition: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            SUM == (A ^ B) ^ CIN
    );

    // COUT equals carry function (A&B) | (CIN & (A^B)).
    check_cout_definition_impl: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            COUT == ((A & B) | (CIN & (A ^ B)))
    );

    // COUT equals majority of inputs.
    check_cout_majority_equiv: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            COUT == ((A & B) | (A & CIN) | (B & CIN))
    );

    ///// Truth-table spot checks /////
    // 0+0+0 -> SUM=0, COUT=0.
    check_case_000: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (!A && !B && !CIN) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

    // Exactly one '1' -> SUM=1, COUT=0.
    check_case_popcount1: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            ((A + B + CIN) == 1) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

    // Exactly two '1's -> SUM=0, COUT=1.
    check_case_popcount2: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            ((A + B + CIN) == 2) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

    // 1+1+1 -> SUM=1, COUT=1.
    check_case_111: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && B && CIN) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

    ///// Simple carry implications /////
    // If A&B then COUT must be 1.
    check_carry_when_ab: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && B) |-> (COUT == 1'b1)
    );

    // If A&CIN then COUT must be 1.
    check_carry_when_acin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A && CIN) |-> (COUT == 1'b1)
    );

    // If B&CIN then COUT must be 1.
    check_carry_when_bcin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (B && CIN) |-> (COUT == 1'b1)
    );

    ///// XOR identities for SUM /////
    // If B==CIN then SUM==A.
    check_sum_when_b_eq_cin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (B == CIN) |-> (SUM == A)
    );

    // If A==B then SUM==CIN.
    check_sum_when_a_eq_b: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A == B) |-> (SUM == CIN)
    );

    // If A==CIN then SUM==B.
    check_sum_when_a_eq_cin: assert property (
        @(posedge A or posedge B or posedge CIN) disable iff (1'b0)
            (A == CIN) |-> (SUM == B)
    );

endmodule

