verilog_code:
module ADD32
  (output reg signed [31:0] S,
   input signed [31:0] A,
   input signed [31:0] B,
   input C,    // Clock
   input CE,   // Clock Enable
   input R     // Synchronous Reset
   );

   always @(posedge C)
     if(R)
       S <= 32'sd0;
     else if(CE)
       S <= A + B;

endmodule

sva_code:
module ADD32_sva
  (input  logic signed [31:0] S,
   input  logic signed [31:0] A,
   input  logic signed [31:0] B,
   input  logic               C,   // Clock
   input  logic               CE,  // Clock Enable
   input  logic               R    // Synchronous Reset (active-high)
   );

    // Next-state function matches RTL: reset has priority, else CE updates sum, else hold.
    check_next_state_function: assert property (
        @(posedge C) 1'b1 |=> ( S == ( $past(R) ? 32'sd0 : ($past(CE) ? ($past(A) + $past(B)) : $past(S)) ) )
    );

    // On any cycle with reset asserted, S becomes 0 on the next cycle.
    check_sync_reset_clears_S: assert property (
        @(posedge C) R |=> (S == 32'sd0)
    );

    // With CE high and not in reset, S updates to A+B on the next cycle.
    check_update_when_CE_high: assert property (
        @(posedge C) disable iff (R) CE |=> (S == $past(A) + $past(B))
    );

    // With CE low and not in reset, S holds its previous value on the next cycle.
    check_hold_when_CE_low: assert property (
        @(posedge C) disable iff (R) !CE |=> (S == $past(S))
    );

    // Reset has priority over CE when both are asserted.
    check_reset_priority_over_CE: assert property (
        @(posedge C) (R && CE) |=> (S == 32'sd0)
    );

    // If CE is high and A+B is zero (not in reset), next S is zero.
    check_sum_zero_case: assert property (
        @(posedge C) disable iff (R) (CE && ((A + B) == 32'sd0)) |=> (S == 32'sd0)
    );

    // If CE is high and A+B equals current S (not in reset), S remains unchanged next cycle.
    check_idempotent_update_when_sum_equals_S: assert property (
        @(posedge C) disable iff (R) (CE && ((A + B) == S)) |=> (S == $past(S))
    );

    // If CE stays low for two consecutive cycles (not in reset), S is unchanged across them.
    check_hold_two_cycles_when_CE_low: assert property (
        @(posedge C) disable iff (R) (!CE ##1 !CE) |-> (S == $past(S))
    );

endmodule

verilog_code:
module bus_fsm (
	output reg gnt,
	output reg [1:0] state,
	input dly,
	input done,
	input req,
	input clk,
	input rst_n
);

	// Define the states of the FSM
	parameter [1:0] IDLE = 2'b00,
					BBUSY = 2'b01,
					BWAIT = 2'b10,
					BFREE = 2'b11;

	// Declare the state and next state variables
	reg [1:0] state, next_state;

	// Initialize the state and next state variables
	initial begin
		state <= IDLE;
		next_state <= IDLE;
	end

	// Assign the next state to the current state on the positive clock edge
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= IDLE;
		end
		else begin
			state <= next_state;
		end
	end

	// Implement the FSM logic using a case statement
	always @(*) begin
		case (state)
			IDLE: if (req) next_state = BBUSY; else next_state = IDLE;
			BBUSY: if (!done) next_state = BBUSY; else if (dly) next_state = BWAIT; else next_state = BFREE;
			BWAIT: if (!dly) next_state = BFREE; else next_state = BWAIT;
			BFREE: if (req) next_state = BBUSY; else next_state = IDLE;
			default: next_state = IDLE;
		endcase
		gnt = (state == BBUSY) | (state == BWAIT);
	end
endmodule

sva_code:
module bus_fsm_sva (
    input logic gnt,
    input logic [1:0] state,
    input logic dly,
    input logic done,
    input logic req,
    input logic clk,
    input logic rst_n
);
    // State encodings (match RTL)
    localparam [1:0] IDLE  = 2'b00;
    localparam [1:0] BBUSY = 2'b01;
    localparam [1:0] BWAIT = 2'b10;
    localparam [1:0] BFREE = 2'b11;

    ///// Reset behavior /////
    // While reset is asserted, state is IDLE and gnt is 0.
    check_reset_idle_gnt0: assert property (
        @(posedge clk) !rst_n |-> (state == IDLE) && (gnt == 1'b0)
    );
    // On the first cycle after reset deasserts, state is IDLE and gnt is 0.
    check_first_cycle_after_reset_idle: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> (state == IDLE) && (gnt == 1'b0)
    );

    ///// Next-state function /////
    // From IDLE: next = (req ? BBUSY : IDLE).
    check_state_trans_from_idle: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == IDLE) |-> state == ($past(req) ? BBUSY : IDLE)
    );
    // From BBUSY: next = (!done ? BBUSY : (dly ? BWAIT : BFREE)).
    check_state_trans_from_bbusy: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BBUSY) |-> state == ( !$past(done) ? BBUSY : ($past(dly) ? BWAIT : BFREE) )
    );
    // From BWAIT: next = (dly ? BWAIT : BFREE).
    check_state_trans_from_bwait: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BWAIT) |-> state == ( $past(dly) ? BWAIT : BFREE )
    );
    // From BFREE: next = (req ? BBUSY : IDLE).
    check_state_trans_from_bfree: assert property (
        @(posedge clk) disable iff (!rst_n)
        $past(rst_n) && ($past(state) == BFREE) |-> state == ($past(req) ? BBUSY : IDLE)
    );

    ///// gnt definition /////
    // gnt is asserted iff state is BBUSY or BWAIT (matches RTL combinational definition).
    check_gnt_definition: assert property (
        @(posedge clk) disable iff (!rst_n) gnt == ((state == BBUSY) | (state == BWAIT))
    );
    // In IDLE, gnt must be 0.
    check_gnt_low_in_idle: assert property (
        @(posedge clk) disable iff (!rst_n) (state == IDLE) |-> (gnt == 1'b0)
    );
    // In BFREE, gnt must be 0.
    check_gnt_low_in_bfree: assert property (
        @(posedge clk) disable iff (!rst_n) (state == BFREE) |-> (gnt == 1'b0)
    );
    // A rising gnt implies we entered BBUSY or BWAIT this cycle.
    check_gnt_rise_targets_busy_or_wait: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(gnt) |-> ((state == BBUSY) || (state == BWAIT))
    );
    // A falling gnt implies we entered IDLE or BFREE this cycle.
    check_gnt_fall_targets_idle_or_free: assert property (
        @(posedge clk) disable iff (!rst_n) $fell(gnt) |-> ((state == IDLE) || (state == BFREE))
    );
endmodule

module mux_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic invert,
    input logic out
);
    // out equals (C ? B : A) XOR invert.
    check_mux_function: assert property (
        @(posedge clk) out == ((C ? B : A) ^ invert)
    );

    // When C==0, out equals A XOR invert.
    check_C0_path: assert property (
        @(posedge clk) (C == 1'b0) |-> (out == (A ^ invert))
    );

    // When C==1, out equals B XOR invert.
    check_C1_path: assert property (
        @(posedge clk) (C == 1'b1) |-> (out == (B ^ invert))
    );

    // When invert==0, out equals selected input.
    check_invert0_behavior: assert property (
        @(posedge clk) (invert == 1'b0) |-> (out == (C ? B : A))
    );

    // When invert==1, out equals inverse of selected input.
    check_invert1_behavior: assert property (
        @(posedge clk) (invert == 1'b1) |-> (out == ~(C ? B : A))
    );

    // If inputs are stable, out remains stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B) && $stable(C) && $stable(invert)) |-> $stable(out)
    );

    // If only invert changes (others stable), out toggles.
    check_out_toggles_on_invert_change: assert property (
        @(posedge clk) $past(1'b1) && $stable(A) && $stable(B) && $stable(C) && $changed(invert) |-> (out == ~$past(out))
    );

    // With C==0 and others stable, A change causes out to change to A^invert.
    check_A_influence_when_C0: assert property (
        @(posedge clk) $past(1'b1) && (C == 1'b0) && $stable(B) && $stable(C) && $stable(invert) && $changed(A) |-> ($changed(out) && (out == (A ^ invert)))
    );

    // With C==1 and others stable, B change causes out to change to B^invert.
    check_B_influence_when_C1: assert property (
        @(posedge clk) $past(1'b1) && (C == 1'b1) && $stable(A) && $stable(C) && $stable(invert) && $changed(B) |-> ($changed(out) && (out == (B ^ invert)))
    );

    // With C==1 and others stable, A change does not affect out.
    check_A_no_influence_when_C1: assert property (
        @(posedge clk) $past(1'b1) && (C == 1'b1) && $stable(B) && $stable(C) && $stable(invert) && $changed(A) |-> !$changed(out)
    );

    // With C==0 and others stable, B change does not affect out.
    check_B_no_influence_when_C0: assert property (
        @(posedge clk) $past(1'b1) && (C == 1'b0) && $stable(A) && $stable(C) && $stable(invert) && $changed(B) |-> !$changed(out)
    );
endmodule

