module edge_detection (
    input clk,
    input [7:0] in,
    output reg [7:0] out
);
    reg [7:0] prev_in;

    always @(posedge clk) begin
        if (in != prev_in) begin
            out <= {1'b0, in[7:1]};
        end else begin
            out <= {1'b0, 7'b0};
        end
        prev_in <= in;
    end
endmodule

sva_code:
module edge_detection_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [7:0] out
);
    // MSB of out is always 0.
    check_out_msb_zero: assert property (
        @(posedge clk) out[7] == 1'b0
    );

    // Out is always either zero or {0,in[7:1]}.
    check_out_two_values_only: assert property (
        @(posedge clk) (out == 8'h00) || (out == {1'b0, in[7:1]})
    );

    // If input changes since last cycle, out equals {0,in[7:1]}.
    check_shift_on_change: assert property (
        @(posedge clk) (in != $past(in)) |-> (out == {1'b0, in[7:1]})
    );

    // If input is unchanged since last cycle, out is zero.
    check_zero_on_no_change: assert property (
        @(posedge clk) (in == $past(in)) |-> (out == 8'h00)
    );

    // If out is non-zero, input must have changed.
    check_nonzero_out_implies_change: assert property (
        @(posedge clk) (out[6:0] != 7'b0) |-> (in != $past(in))
    );

    // On change, out[0] equals in[1].
    check_bit0_on_change: assert property (
        @(posedge clk) (in != $past(in)) |-> (out[0] == in[1])
    );

    // On change, out[6] equals in[7].
    check_bit6_on_change: assert property (
        @(posedge clk) (in != $past(in)) |-> (out[6] == in[7])
    );

    // Out never sets bits outside of {0,in[7:1]}.
    check_out_subset_of_shifted: assert property (
        @(posedge clk) ((out & ~{1'b0, in[7:1]}) == 8'h00)
    );

    // When no change, out[6:0] are zero.
    check_lowbits_zero_on_no_change: assert property (
        @(posedge clk) (in == $past(in)) |-> (out[6:0] == 7'b0)
    );

endmodule

module shift_register_left_sva (
    input logic clk,
    input logic areset_n,  // async active-low reset
    input logic load,
    input logic ena,
    input logic [3:0] data,
    input logic [3:0] q
);
    // Clock: posedge clk. Reset: areset_n active-low, asynchronous.
    // Logic: sequential with async reset; load has priority over shift; else hold.

    ///// Reset behavior /////
    // When reset is asserted at the clock edge, q is zero.
    check_reset_clears_q: assert property (
        @(posedge clk) (!areset_n) |-> (q == 4'b0000)
    );

    ///// Load behavior /////
    // On load, q updates with data on the next cycle.
    check_load_updates_q: assert property (
        @(posedge clk) disable iff (!areset_n) load |=> (q == $past(data))
    );

    // Load has priority over ena when both are asserted.
    check_priority_load_over_ena: assert property (
        @(posedge clk) disable iff (!areset_n) (load && ena) |=> (q == $past(data))
    );

    ///// Shift behavior /////
    // On ena without load, q shifts left by one with zero fill.
    check_shift_left_when_ena_only: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q == {$past(q[2:0]), 1'b0})
    );

    // On shift, LSB becomes zero.
    check_shift_lsb_zero: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[0] == 1'b0)
    );

    // On shift, MSB takes previous bit2.
    check_shift_msb_from_bit2: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[3] == $past(q[2]))
    );

    // On shift, bit2 takes previous bit1.
    check_shift_bit2_from_bit1: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[2] == $past(q[1]))
    );

    // On shift, bit1 takes previous bit0.
    check_shift_bit1_from_bit0: assert property (
        @(posedge clk) disable iff (!areset_n) (ena && !load) |=> (q[1] == $past(q[0]))
    );

    ///// Hold behavior /////
    // When neither load nor ena is asserted, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset_n) (!load && !ena) |=> (q == $past(q))
    );
endmodule

