    // At B1 falling edge, if A1..A4 are stable, Y must be stable.
    check_b1_negedge_no_effect: assert property (
        @(negedge B1) ((A1 == $past(A1)) && (A2 == $past(A2)) && (A3 == $past(A3)) && (A4 == $past(A4))) |-> (Y == $past(Y))
    );

