module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    assign {Cout, Sum} = A + B + Cin;

endmodule

module decoder_4to16 (
    input [1:0] A,
    output reg [15:0] O
);

    always @(*) begin
        case (A)
            2'b00: O = 16'b0000000000000001;
            2'b01: O = 16'b0000000000000010;
            2'b10: O = 16'b0000000000000100;
            2'b11: O = 16'b0000000000001000;
        endcase
    end

endmodule

module ripple_decoder_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout,
    output [15:0] O
);

    wire [3:0] adder_sum;
    wire adder_cout;
    wire [1:0] decoder_input;

    ripple_carry_adder adder(  // Assuming ripple_carry_adder is a separate module
        .A(A),
        .B(B),
        .Cin(Cin),
        .Sum(adder_sum),
        .Cout(adder_cout)
    );

    assign decoder_input = adder_sum[3:2];

    decoder_4to16 decoder(   // Assuming decoder_4to16 is a separate module
        .A(decoder_input),
        .O(O)
    );

    assign Sum = adder_sum;
    assign Cout = adder_cout;

endmodule

sva_code:
module ripple_decoder_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout,
    input logic [15:0] O
);
    // Adder outputs equal A + B + Cin (sum and carry)
    check_adder_sum_and_carry: assert property (
        @(posedge clk) {Cout, Sum} == (A + B + Cin)
    );

    // LSB sum bit is XOR of A[0], B[0], and Cin
    check_sum0_xor: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

    // Carry-out equals overflow of 4-bit addition
    check_cout_overflow: assert property (
        @(posedge clk) Cout == ((A + B + Cin) > 5'd15)
    );

    // Decoder output equals 1 shifted by Sum[3:2]
    check_decoder_mapping_shift: assert property (
        @(posedge clk) O == (16'h0001 << Sum[3:2])
    );

    // Decoder output is exactly one-hot
    check_decoder_onehot: assert property (
        @(posedge clk) $onehot(O)
    );

    // Upper decoder bits are zero
    check_decoder_upper_zero: assert property (
        @(posedge clk) O[15:4] == 12'h000
    );

    // If primary inputs hold, outputs hold (combinational behavior)
    check_outputs_hold_when_inputs_hold: assert property (
        @(posedge clk) $past(1'b1) && $stable({A,B,Cin}) |-> $stable({Sum,Cout,O})
    );

    // If Sum[3:2] holds, O holds (direct decode of Sum[3:2])
    check_o_stable_when_sum_msb_stable: assert property (
        @(posedge clk) $past(1'b1) && $stable(Sum[3:2]) |-> $stable(O)
    );

    // If Sum[3:2] changes, O changes accordingly
    check_o_changes_with_sum_msb_change: assert property (
        @(posedge clk) $past(1'b1) && (Sum[3:2] != $past(Sum[3:2])) |-> (O != $past(O))
    );
endmodule

verilog_code:
module add_sub_carry_out(
    output [3:0] S,
    input  [30:0] Q_reg,
    input  [6:0] Q,
    input  FSM_exp_operation_A_S,
    input  [1:0] FSM_selector_B,
    input  DI
);

  wire [31:0] A;
  wire [31:0] B;
  wire [32:0] C;
  wire carry_out;
  reg [30:0] Q_reg_temp;

  assign A = {1'b0, Q_reg};
  assign B = {1'b0, Q};

  // Perform addition or subtraction based on FSM_exp_operation_A_S
  assign C = FSM_exp_operation_A_S ? A + B : A - B;

  // Register the carry out value
  assign carry_out = C[31];

  // Store the carry out in the most significant bit of Q_reg
  always @(*)
  begin
    Q_reg_temp = Q_reg;
    Q_reg_temp[30] = carry_out;
  end

  // Select the appropriate bits of C for the output
  assign S = C[3:0];

endmodule

sva_code:
module add_sub_carry_out_sva (
    input logic CLK,
    input logic [3:0] S,
    input logic [30:0] Q_reg,
    input logic [6:0] Q,
    input logic FSM_exp_operation_A_S,
    input logic [1:0] FSM_selector_B,
    input logic DI
);

    // S equals low 4 bits of ({1'b0,Q_reg} + {1'b0,Q}) when add is selected.
    add_low_nibble_matches_full_add: assert property (
        @(posedge CLK) FSM_exp_operation_A_S |-> ( S == ( ({1'b0, Q_reg} + {1'b0, Q})[3:0] ) )
    );

    // S equals low 4 bits of ({1'b0,Q_reg} - {1'b0,Q}) when subtract is selected.
    sub_low_nibble_matches_full_sub: assert property (
        @(posedge CLK) !FSM_exp_operation_A_S |-> ( S == ( ({1'b0, Q_reg} - {1'b0, Q})[3:0] ) )
    );

    // DI has no effect on S when other relevant inputs are stable.
    s_independent_of_DI_changes: assert property (
        @(posedge CLK) ($stable(Q) && $stable(Q_reg) && $stable(FSM_exp_operation_A_S) && !$stable(DI)) |-> $stable(S)
    );

    // FSM_selector_B has no effect on S when other relevant inputs are stable.
    s_independent_of_selectorB_changes: assert property (
        @(posedge CLK) ($stable(Q) && $stable(Q_reg) && $stable(FSM_exp_operation_A_S) && !$stable(FSM_selector_B)) |-> $stable(S)
    );

    // Changes to Q[6:4] do not affect S when other relevant inputs are stable.
    s_independent_of_Q_upper_bits: assert property (
        @(posedge CLK) ($stable(Q_reg) && $stable(FSM_exp_operation_A_S) && $stable(Q[3:0]) && !$stable(Q[6:4])) |-> $stable(S)
    );

    // Changes to Q_reg[30:4] do not affect S when other relevant inputs are stable.
    s_independent_of_Qreg_upper_bits: assert property (
        @(posedge CLK) ($stable(Q) && $stable(FSM_exp_operation_A_S) && $stable(Q_reg[3:0]) && !$stable(Q_reg[30:4])) |-> $stable(S)
    );

    // When Q is zero, S equals Q_reg[3:0] for both add and subtract.
    s_passthrough_when_Q_zero: assert property (
        @(posedge CLK) (Q == 7'h00) |-> (S == Q_reg[3:0])
    );

    // When low nibbles of Q_reg and Q are zero, S is zero for both operations.
    s_zero_when_both_low_nibbles_zero: assert property (
        @(posedge CLK) (Q_reg[3:0] == 4'h0 && Q[3:0] == 4'h0) |-> (S == 4'h0)
    );

    // For add: S equals (Q_reg[3:0] + Q[3:0]) modulo 16.
    add_low_nibble_depends_only_on_low_nibbles: assert property (
        @(posedge CLK) FSM_exp_operation_A_S |-> ( S == ((Q_reg[3:0] + Q[3:0]) & 4'hF) )
    );

    // For subtract: S equals (Q_reg[3:0] - Q[3:0]) modulo 16.
    sub_low_nibble_depends_only_on_low_nibbles: assert property (
        @(posedge CLK) !FSM_exp_operation_A_S |-> ( S == ((Q_reg[3:0] - Q[3:0]) & 4'hF) )
    );

endmodule

