module slower_sva (
    input logic CLK,
    input logic SLOWCLK,
    input logic RESET,
    input logic EN_OUT
);
    // Clock: CLK posedge; Reset: RESET synchronous active-high.
    // Behavior: EN_OUT=1 iff SLOWCLK is unchanged from previous CLK; else EN_OUT=0.

    // During RESET, EN_OUT must be driven LOW.
    reset_drives_en_low: assert property (
        @(posedge CLK) RESET |-> (EN_OUT == 1'b0)
    );

    // If SLOWCLK is stable since last CLK, EN_OUT must be 1.
    en_high_on_slowclk_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($stable(SLOWCLK) && !$past(RESET)) |-> (EN_OUT == 1'b1)
    );

    // If SLOWCLK changed since last CLK, EN_OUT must be 0.
    en_low_on_slowclk_change: assert property (
        @(posedge CLK) disable iff (RESET)
            ($changed(SLOWCLK) && !$past(RESET)) |-> (EN_OUT == 1'b0)
    );

    // EN_OUT high implies SLOWCLK was stable since last CLK.
    en_high_implies_slowclk_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            (EN_OUT && !$past(RESET)) |-> $stable(SLOWCLK)
    );

    // EN_OUT low implies SLOWCLK changed since last CLK.
    en_low_implies_slowclk_changed: assert property (
        @(posedge CLK) disable iff (RESET)
            ((!EN_OUT) && !$past(RESET)) |-> $changed(SLOWCLK)
    );

    // After a SLOWCLK change, if next cycle SLOWCLK is stable then EN_OUT must be 1.
    en_recovers_high_after_change_and_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($changed(SLOWCLK) && !$past(RESET)) ##1 ($stable(SLOWCLK) && !RESET) |-> (EN_OUT == 1'b1)
    );

    // On RESET deassertion, if SLOWCLK is 0 then EN_OUT must be 1 in that cycle.
    release_en_out_when_slowclk_zero: assert property (
        @(posedge CLK) $fell(RESET) && (SLOWCLK == 1'b0) |-> (EN_OUT == 1'b1)
    );

    // On RESET deassertion, if SLOWCLK is 1 then EN_OUT must be 0 in that cycle.
    release_en_out_when_slowclk_one: assert property (
        @(posedge CLK) $fell(RESET) && (SLOWCLK == 1'b1) |-> (EN_OUT == 1'b0)
    );

    // A falling edge on EN_OUT (1->0) occurs only when SLOWCLK changed.
    en_out_fall_only_on_slowclk_change: assert property (
        @(posedge CLK) disable iff (RESET)
            ($fell(EN_OUT) && !$past(RESET)) |-> $changed(SLOWCLK)
    );

    // A rising edge on EN_OUT (0->1) requires last cycle change and current stability of SLOWCLK.
    en_out_rise_requires_prev_change_and_now_stable: assert property (
        @(posedge CLK) disable iff (RESET)
            ($rose(EN_OUT) && !$past(RESET)) |-> (!$changed(SLOWCLK) && $past($changed(SLOWCLK)))
    );

endmodule

verilog_code:
module d_ff_reset (
    input D,
    input RESET_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    input CLK_N,
    output reg Q
);

    wire D_valid;
    wire RESET_B_valid;
    wire VPWR_valid;
    wire VGND_valid;
    wire VPB_valid;
    wire VNB_valid;

    assign D_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign RESET_B_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VPWR_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VGND_valid = (VPWR == 1'b1) && (VGND == 1'b0);
    assign VPB_valid = (VPB == 1'b1) && (VNB == 32'b11111111111111111111111111111111);
    assign VNB_valid = (VPB == 1'b1) && (VNB == 32'b11111111111111111111111111111111);

    always @(posedge CLK_N) begin
        if (RESET_B_valid && !RESET_B) begin
            Q <= 1'b0;
        end else if (D_valid) begin
            Q <= D;
        end
    end

endmodule

sva_code:
module d_ff_reset_sva (
    input logic D,
    input logic RESET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic CLK_N,
    input logic Q
);
    ///// Reset behavior /////
    // Active-low reset with valid power drives Q to 0 on the next clock.
    reset_low_forces_q0: assert property (
        @(posedge CLK_N) ((VPWR == 1'b1) && (VGND == 1'b0) && (!RESET_B)) |=> (Q == 1'b0)
    );

    // Reset low without valid power has no effect on Q (no assignment occurs).
    reset_low_without_power_no_effect: assert property (
        @(posedge CLK_N) ((!((VPWR == 1'b1) && (VGND == 1'b0))) && (!RESET_B)) |=> (Q == $past(Q))
    );

    ///// Data capture behavior /////
    // With valid power and reset deasserted, Q captures D on the next clock.
    capture_d_when_powered: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1)) |=> (Q == D)
    );

    // If D equals previous Q when capturing, Q remains unchanged.
    no_change_when_d_equals_prev_q: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1) && (D == $past(Q))) |=> (Q == $past(Q))
    );

    // If D differs from previous Q when capturing, Q must change.
    q_changes_when_d_differs_from_prev_q: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) ((VPWR == 1'b1) && (VGND == 1'b0) && (RESET_B == 1'b1) && (D != $past(Q))) |=> (Q != $past(Q))
    );

    ///// Hold behavior /////
    // With invalid power rails, Q holds its value across the clock.
    hold_when_power_invalid: assert property (
        @(posedge CLK_N) disable iff (!RESET_B) (!((VPWR == 1'b1) && (VGND == 1'b0))) |=> (Q == $past(Q))
    );

    ///// Change qualification /////
    // Any change on Q must be preceded by valid power rails.
    q_change_requires_valid_power: assert property (
