verilog_code:
module arithmetic_operations(
    input [15:0] A_in,
    input [15:0] B_in,
    output reg [15:0] sum_out,
    output reg [15:0] diff_out,
    output reg [15:0] abs_diff_out,
    output reg [15:0] and_out,
    output reg [15:0] or_out,
    output reg [15:0] xor_out
);

    always @(*) begin
        // Sum
        sum_out = A_in + B_in;

        // Difference
        diff_out = A_in - B_in;

        // Absolute difference
        if (A_in > B_in) begin
            abs_diff_out = A_in - B_in;
        end else begin
            abs_diff_out = B_in - A_in;
        end

        // Bitwise AND
        and_out = A_in & B_in;

        // Bitwise OR
        or_out = A_in | B_in;

        // Bitwise XOR
        xor_out = A_in ^ B_in;
    end

endmodule

sva_code:
module arithmetic_operations_sva (
    // DUT ports as inputs
    input logic [15:0] A_in,
    input logic [15:0] B_in,
    input logic [15:0] sum_out,
    input logic [15:0] diff_out,
    input logic [15:0] abs_diff_out,
    input logic [15:0] and_out,
    input logic [15:0] or_out,
    input logic [15:0] xor_out,
    // External sampling clock for SVA (RTL is combinational; no reset present)
    input logic CLK
);
    // Combinational RTL (no clock/reset). Assertions sample on CLK.
    // Behaviors: sum=A+B (16-bit wrap), diff=A-B (16-bit wrap), abs_diff per unsigned compare, bitwise AND/OR/XOR.

    // Sum equals lower 16 bits of A_in + B_in.
    check_sum_functional: assert property (
        @(posedge CLK) sum_out == (A_in + B_in)[15:0]
    );

    // Difference equals lower 16 bits of A_in - B_in.
    check_diff_functional: assert property (
        @(posedge CLK) diff_out == (A_in - B_in)[15:0]
    );

    // Absolute difference when A_in > B_in equals A_in - B_in.
    check_absdiff_when_gt: assert property (
        @(posedge CLK) (A_in > B_in) |-> (abs_diff_out == (A_in - B_in)[15:0])
    );

    // Absolute difference when A_in <= B_in equals B_in - A_in.
    check_absdiff_when_le: assert property (
        @(posedge CLK) (A_in <= B_in) |-> (abs_diff_out == (B_in - A_in)[15:0])
    );

    // Bitwise AND correctness.
    check_and_functional: assert property (
        @(posedge CLK) and_out == (A_in & B_in)
    );

    // Bitwise OR correctness.
    check_or_functional: assert property (
        @(posedge CLK) or_out == (A_in | B_in)
    );

    // Bitwise XOR correctness.
    check_xor_functional: assert property (
        @(posedge CLK) xor_out == (A_in ^ B_in)
    );

    // XOR equals (OR & ~AND).
    check_xor_or_and_identity: assert property (
        @(posedge CLK) xor_out == (or_out & ~and_out)
    );

    // OR equals XOR | AND.
    check_or_decomposition: assert property (
        @(posedge CLK) or_out == (xor_out | and_out)
    );

    // AND is a subset of OR (no bit can be 1 in AND while 0 in OR).
    check_and_subset_or: assert property (
        @(posedge CLK) (and_out & ~or_out) == 16'h0000
    );

    // When inputs are equal, diff/xor/abs_diff are zero.
    check_equal_inputs_zeroes: assert property (
        @(posedge CLK) (A_in == B_in) |-> (diff_out == 16'h0000) && (abs_diff_out == 16'h0000) && (xor_out == 16'h0000)
    );

endmodule

verilog_code:
module d_flip_flop_mux (
    input clk,
    input [7:0] d1,
    input [7:0] d2,
    input sel,
    output [7:0] q
);

reg [7:0] q_reg;
wire [7:0] d_in;

assign d_in = sel ? d2 : d1;

always @(negedge clk) begin
    q_reg <= d_in;
end

assign q = q_reg;

endmodule

sva_code:
module d_flip_flop_mux_sva (
    input logic clk,
    input logic [7:0] d1,
    input logic [7:0] d2,
    input logic sel,
    input logic [7:0] q
);
    // Q updates one negedge later to the sampled muxed input.
    property p_q_updates_to_prev_selected;
        logic [7:0] din;
        @(negedge clk) (din = (sel ? d2 : d1), 1'b1) |=> (q == din);
    endproperty
    check_q_updates_to_prev_selected: assert property (p_q_updates_to_prev_selected);

    // When sel==0 at capture, next q equals sampled d1.
    property p_capture_d1_when_sel0;
        logic [7:0] d1s;
        @(negedge clk) ((sel == 1'b0) ##0 (d1s = d1, 1'b1)) |=> (q == d1s);
    endproperty
    check_capture_d1_when_sel0: assert property (p_capture_d1_when_sel0);

    // When sel==1 at capture, next q equals sampled d2.
    property p_capture_d2_when_sel1;
        logic [7:0] d2s;
        @(negedge clk) ((sel == 1'b1) ##0 (d2s = d2, 1'b1)) |=> (q == d2s);
    endproperty
    check_capture_d2_when_sel1: assert property (p_capture_d2_when_sel1);

    // Next q equals either previously sampled d1 or d2.
    property p_q_equals_prev_d1_or_d2;
        logic [7:0] d1s, d2s;
        @(negedge clk) ((d1s = d1, 1'b1) ##0 (d2s = d2, 1'b1)) |=> ((q == d1s) || (q == d2s));
    endproperty
    check_q_equals_prev_d1_or_d2: assert property (p_q_equals_prev_d1_or_d2);

    // If selected input is unchanged across two captures, q holds its value.
    property p_q_stable_if_selected_stable;
        logic [7:0] din0, din1, q1;
        @(negedge clk)
            (din0 = (sel ? d2 : d1), 1'b1) ##1
            (din1 = (sel ? d2 : d1), q1 = q, 1'b1) |=> ((din1 == din0) |-> (q == q1));
    endproperty
    check_q_stable_if_selected_stable: assert property (p_q_stable_if_selected_stable);

    // If selected input changes across two captures, q must change next.
    property p_q_changes_if_selected_changes;
        logic [7:0] din0, din1, q1;
        @(negedge clk)
            (din0 = (sel ? d2 : d1), 1'b1) ##1
            (din1 = (sel ? d2 : d1), q1 = q, 1'b1) |=> ((din1 != din0) |-> (q != q1));
    endproperty
    check_q_changes_if_selected_changes: assert property (p_q_changes_if_selected_changes);

    // If d1==d2 at capture, next q equals that common value.
    property p_q_equals_common_input_when_equal;
        logic [7:0] v;
        @(negedge clk) ((d1 == d2) ##0 (v = d1, 1'b1)) |=> (q == v);
    endproperty
    check_q_equals_common_input_when_equal: assert property (p_q_equals_common_input_when_equal);

    // With sel held HIGH and d2 stable across captures, q holds steady.
    property p_unselected_d1_ignored_sel_high;
        logic s0, s1;
        logic [7:0] d20, d21, q1;
        @(negedge clk)
            (s0 = sel, d20 = d2, 1'b1) ##1
            (s1 = sel, d21 = d2, q1 = q, 1'b1) |=> (((s0 == 1'b1) && (s1 == 1'b1) && (d21 == d20)) |-> (q == q1));
    endproperty
    check_unselected_d1_ignored_sel_high: assert property (p_unselected_d1_ignored_sel_high);

    // With sel held LOW and d1 stable across captures, q holds steady.
    property p_unselected_d2_ignored_sel_low;
        logic s0, s1;
        logic [7:0] d10, d11, q1;
        @(negedge clk)
            (s0 = sel, d10 = d1, 1'b1) ##1
            (s1 = sel, d11 = d1, q1 = q, 1'b1) |=> (((s0 == 1'b0) && (s1 == 1'b0) && (d11 == d10)) |-> (q == q1));
    endproperty
    check_unselected_d2_ignored_sel_low: assert property (p_unselected_d2_ignored_sel_low);

endmodule

