module counterB (
    output reg [3:0] cntB_reg, // Registered version of cntA
    input decrementB, // 0=Up-counting, 1=down-counting
    input dual_countB, // Advance counter by 2 steps at a time
    input cntB_en, // Enable counter B
    input clk, // Clock
    input rst // Synchronous reset
);

    // Counter B - tried to write sequential only, but ended up without
    // SystemVerilog.

    always @(posedge clk) begin
        if (rst)
            cntB_reg <= 4'b0000;
        else if (cntB_en) begin
            if (decrementB) begin
                if (dual_countB)
                    cntB_reg <= cntB_reg - 2;
                else
                    cntB_reg <= cntB_reg - 1;
            end
            else begin
                if (dual_countB)
                    cntB_reg <= cntB_reg + 2;
                else
                    cntB_reg <= cntB_reg + 1;
            end
        end
    end // always @

endmodule

sva_code:
module counterB_sva (
    input logic [3:0] cntB_reg,
    input logic decrementB,
    input logic dual_countB,
    input logic cntB_en,
    input logic clk,
    input logic rst
);
    // Synchronous reset drives cntB_reg to zero.
    reset_clears_cntB: assert property (
        @(posedge clk) rst |-> (cntB_reg == 4'b0000)
    );

    // When disabled, cntB_reg holds its previous value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) (!cntB_en) |-> (cntB_reg == $past(cntB_reg))
    );

    // Any state change requires enable to be high.
    update_requires_enable: assert property (
        @(posedge clk) disable iff (rst) (cntB_reg != $past(cntB_reg)) |-> cntB_en
    );

    // Enabled up-count single-step: +1 modulo 16.
    inc_by1_when_enabled_up_single: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && !dual_countB) |-> (cntB_reg == ($past(cntB_reg) + 4'd1))
    );

    // Enabled up-count dual-step: +2 modulo 16.
    inc_by2_when_enabled_up_dual: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && dual_countB) |-> (cntB_reg == ($past(cntB_reg) + 4'd2))
    );

    // Enabled down-count single-step: -1 modulo 16.
    dec_by1_when_enabled_down_single: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && !dual_countB) |-> (cntB_reg == ($past(cntB_reg) - 4'd1))
    );

    // Enabled down-count dual-step: -2 modulo 16.
    dec_by2_when_enabled_down_dual: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB) |-> (cntB_reg == ($past(cntB_reg) - 4'd2))
    );

    // Wrap: up-count single-step from 0xF goes to 0x0.
    wrap_up_single_from_F: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && !dual_countB && ($past(cntB_reg) == 4'hF)) |-> (cntB_reg == 4'h0)
    );

    // Wrap: up-count dual-step from 0xE goes to 0x0.
    wrap_up_dual_from_E: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && !decrementB && dual_countB && ($past(cntB_reg) == 4'hE)) |-> (cntB_reg == 4'h0)
    );

    // Wrap: down-count single-step from 0x0 goes to 0xF.
    wrap_down_single_from_0: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && !dual_countB && ($past(cntB_reg) == 4'h0)) |-> (cntB_reg == 4'hF)
    );

    // Wrap: down-count dual-step from 0x0 goes to 0xE.
    wrap_down_dual_from_0: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB && ($past(cntB_reg) == 4'h0)) |-> (cntB_reg == 4'hE)
    );

    // Wrap: down-count dual-step from 0x1 goes to 0xF.
    wrap_down_dual_from_1: assert property (
        @(posedge clk) disable iff (rst)
            (cntB_en && decrementB && dual_countB && ($past(cntB_reg) == 4'h1)) |-> (cntB_reg == 4'hF)
    );
endmodule

module ShiftRegister_sva (
    input  logic D,
    input  logic LOAD,
    input  logic CLK,
    input  logic [5:0] Q
);

    // If LOAD was 1 last cycle, Q loads all bits from D.
    check_load_writes_all_bits: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && $past(LOAD,1,1'b0) |-> (Q == {6{$past(D,1,1'b0)}})
    );

    // If LOAD was 0 last cycle, Q shifts left with D entering bit 0.
    check_shift_nextstate_vector: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q == {$past(Q,1,6'b0)[4:0], $past(D,1,1'b0)})
    );

    // On shift (LOAD was 0), MSB gets previous bit 4.
    check_shift_msb_propagate: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q[5] == $past(Q,1,6'b0)[4])
    );

    // On shift (LOAD was 0), LSB gets previous D.
    check_shift_lsb_from_D: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && !$past(LOAD,1,1'b0) |-> (Q[0] == $past(D,1,1'b0))
    );

    // If LOAD was 1 last cycle, both MSB and LSB equal D.
    check_load_sets_end_bits: assert property (
        @(posedge CLK) $past(1'b1,1,1'b0) && $past(LOAD,1,1'b0) |-> (Q[5] == $past(D,1,1'b0)) && (Q[0] == $past(D,1,1'b0))
    );

endmodule

verilog_code:
module binary_counter (
    input clk,
    input reset,
    input enable,
    output [3:0] Q
);

reg [3:0] Q_reg;
reg [3:0] Q_next;

always @(posedge clk) begin
    if (reset) begin
        Q_reg <= 4'b0;
    end
    else if (enable) begin
        Q_reg <= Q_next;
    end
end

always @* begin
    if (Q_reg == 4'b1111) begin
        Q_next = 4'b0000;
    end
    else begin
        Q_next = Q_reg + 1;
    end
end

assign Q = Q_reg;

endmodule

sva_code:
module binary_counter_sva (
    input logic clk,
    input logic reset,      // active-high synchronous reset
    input logic enable,
    input logic [3:0] Q
);

    // Q must be 0 on any clock where reset is asserted.
    reset_clears_Q: assert property (
        @(posedge clk) reset |-> (Q == 4'b0000)
    );

    // When enable is LOW, Q holds its previous value.
    hold_when_enable_low: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> (Q == $past(Q))
    );

    // When enable is HIGH and previous Q != 15, Q increments by 1.
    increment_when_enable_high_no_wrap: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) != 4'hF)) |-> (Q == $past(Q) + 4'd1)
    );

    // When enable is HIGH and previous Q == 15, Q wraps to 0.
    wrap_when_enable_high_from_fifteen: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) == 4'hF)) |-> (Q == 4'h0)
    );

    // Q only changes on a clock when enable is HIGH (reset cycles disabled).
    change_requires_enable: assert property (
        @(posedge clk) disable iff (reset) $changed(Q) |-> enable
    );

    // If Q is 0 on a cycle with enable HIGH (and previous cycle not in reset), previous Q was 15.
    zero_with_enable_implies_prev_fifteen: assert property (
        @(posedge clk) disable iff (reset) (enable && (Q == 4'h0) && $past(!reset)) |-> ($past(Q) == 4'hF)
    );

    // Immediately after reset deasserts, if enable is HIGH, Q becomes 1.
    next_is_one_after_reset_then_enable: assert property (
        @(posedge clk) disable iff (reset) (!reset && $past(reset) && enable) |-> (Q == 4'd1)
    );

    // Immediately after reset deasserts, if enable is LOW, Q stays at 0.
    next_is_zero_after_reset_then_disable: assert property (
        @(posedge clk) disable iff (reset) (!reset && $past(reset) && !enable) |-> (Q == 4'd0)
    );

    // From previous Q == 15, next Q is either 0 if enable HIGH, or holds at 15 if enable LOW.
    next_from_fifteen_cases: assert property (
        @(posedge clk) disable iff (reset) ($past(Q) == 4'hF) |-> ((enable && (Q == 4'h0)) || (!enable && (Q == 4'hF)))
    );

    // When enabled and previous Q was 0, Q increments to 1.
    increment_from_zero_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable && ($past(Q) == 4'h0)) |-> (Q == 4'h1)
    );

endmodule

