module MX2X4A12TR_sva (
    input logic clk,   // external clock for sampling
    input logic A,
    input logic B,
    input logic S0,
    input logic Y
);
    // Y must equal B | S0 (4-state aware).
    check_y_equals_b_or_s0: assert property (
        @(posedge clk) disable iff (1'b0) (Y === (B | S0))
    );

    // When both B and S0 are 0, Y must be 0.
    check_y_zero_when_both_zero: assert property (
        @(posedge clk) disable iff (1'b0) ((B === 1'b0) && (S0 === 1'b0)) |-> (Y === 1'b0)
    );

    // When B is 1, Y must be 1.
    check_y_one_when_b_one: assert property (
        @(posedge clk) disable iff (1'b0) (B === 1'b1) |-> (Y === 1'b1)
    );

    // When S0 is 1, Y must be 1.
    check_y_one_when_s0_one: assert property (
        @(posedge clk) disable iff (1'b0) (S0 === 1'b1) |-> (Y === 1'b1)
    );

    // If Y is 0, then both B and S0 must be 0.
    check_y_zero_implies_inputs_zero: assert property (
        @(posedge clk) disable iff (1'b0) (Y === 1'b0) |-> ((B === 1'b0) && (S0 === 1'b0))
    );

    // If Y is 1, then at least one of B or S0 must be 1.
    check_y_one_implies_any_input_one: assert property (
        @(posedge clk) disable iff (1'b0) (Y === 1'b1) |-> ((B === 1'b1) || (S0 === 1'b1))
    );

    // When S0 is 0, Y must equal B.
    check_y_eq_b_when_s0_zero: assert property (
        @(posedge clk) disable iff (1'b0) (S0 === 1'b0) |-> (Y === B)
    );

    // When B is 0, Y must equal S0.
    check_y_eq_s0_when_b_zero: assert property (
        @(posedge clk) disable iff (1'b0) (B === 1'b0) |-> (Y === S0)
    );

    // Y must remain stable when B and S0 are stable.
    check_y_stable_when_b_s0_stable: assert property (
        @(posedge clk) disable iff (1'b0) ($stable(B) && $stable(S0)) |-> $stable(Y)
    );

    // Y must be independent of A; A changes with B and S0 stable must not change Y.
    check_independence_from_a: assert property (
        @(posedge clk) disable iff (1'b0) ($changed(A) && $stable(B) && $stable(S0)) |-> $stable(Y)
    );
endmodule

verilog_code:
module xor_shift_registers_fixed (
  input clk,
  input reset,
  input d,
  output q
);

  reg [3:0] sr1;
  reg [1:0] sr2;

  always @(posedge clk) begin
    if (reset) begin
      sr1 <= 4'b0000;
      sr2 <= 2'b00;
    end else begin
      sr1 <= {sr1[2:0], sr1[3]};
      sr2 <= {sr2[0], d};
    end
  end

  assign q = sr1[0] ^ sr2[1];

endmodule

sva_code:
module xor_shift_registers_fixed_sva (
  input logic clk,
  input logic reset,
  input logic d,
  input logic q,
  input logic [3:0] sr1,
  input logic [1:0] sr2
);
  // Clock: clk (posedge). Reset: reset (active-high, synchronous).
  // Logic: sequential sr1/sr2 updates; combinational q = sr1[0] ^ sr2[1].

  // Synchronous reset clears both shift registers to zero.
  reset_clears_registers: assert property (
    @(posedge clk) reset |-> (sr1 == 4'b0000) && (sr2 == 2'b00)
  );

  // During reset, q is LOW (XOR of cleared bits).
  reset_q_low: assert property (
    @(posedge clk) reset |-> (q == 1'b0)
  );

  // When not reset, sr1 rotates left by one bit.
  check_sr1_rotates_left: assert property (
    @(posedge clk) disable iff (reset) sr1 == { $past(sr1)[2:0], $past(sr1)[3] }
  );

  // sr1[0] takes previous sr1[3] when not reset.
  check_sr1_bit0_from_prev_bit3: assert property (
    @(posedge clk) disable iff (reset) sr1[0] == $past(sr1[3])
  );

  // sr1[1] takes previous sr1[0] when not reset.
  check_sr1_bit1_from_prev_bit0: assert property (
    @(posedge clk) disable iff (reset) sr1[1] == $past(sr1[0])
  );

  // sr2[0] loads current d when not reset.
  check_sr2_bit0_loads_d: assert property (
    @(posedge clk) disable iff (reset) sr2[0] == d
  );

  // sr2[1] takes previous sr2[0] when not reset.
  check_sr2_bit1_from_prev_bit0: assert property (
    @(posedge clk) disable iff (reset) sr2[1] == $past(sr2[0])
  );

  // If previous cycle was not reset, sr2[1] equals previous d.
  check_sr2_bit1_is_prev_d: assert property (
    @(posedge clk) disable iff (reset) (!$past(reset)) |-> (sr2[1] == $past(d))
  );

  // q matches XOR of sr1[0] and sr2[1] when not reset.
  check_q_equals_xor: assert property (
    @(posedge clk) disable iff (reset) q == (sr1[0] ^ sr2[1])
  );

  // Once zero (outside reset), sr1 stays zero due to rotation.
  check_sr1_zero_sticky: assert property (
    @(posedge clk) disable iff (reset) (sr1 == 4'b0000) |=> (sr1 == 4'b0000)
  );

endmodule

