verilog_code:
module mux4to1 (
    sel,
    in0,
    in1,
    in2,
    in3,
    out
);

    // Module ports
    input [1:0] sel;
    input in0, in1, in2, in3;
    output out;

    // Local signals
    reg mux_out;

    // Implement the multiplexer using an always block
    always @ (sel, in0, in1, in2, in3) begin
        case (sel)
            2'b00: mux_out = in0;
            2'b01: mux_out = in1;
            2'b10: mux_out = in2;
            2'b11: mux_out = in3;
        endcase
    end

    // Assign the output signal to the selected input signal
    assign out = mux_out;

endmodule

sva_code:
module mux4to1_sva (
    input logic [1:0] sel,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic out
);

    // Helper: compute the expected mux output from sel and inputs.
    function automatic logic selected_input_value (
        input logic [1:0] s,
        input logic i0, i1, i2, i3
    );
        case (s)
            2'b00: selected_input_value = i0;
            2'b01: selected_input_value = i1;
            2'b10: selected_input_value = i2;
            default: selected_input_value = i3;
        endcase
    endfunction

    ///// Functional correctness checks /////

    // Output equals selected input when sel[0] rises.
    check_out_matches_sel_on_sel0_posedge: assert property (
        @(posedge sel[0]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when sel[1] rises.
    check_out_matches_sel_on_sel1_posedge: assert property (
        @(posedge sel[1]) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in0 rises.
    check_out_matches_sel_on_in0_posedge: assert property (
        @(posedge in0) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in1 rises.
    check_out_matches_sel_on_in1_posedge: assert property (
        @(posedge in1) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in2 rises.
    check_out_matches_sel_on_in2_posedge: assert property (
        @(posedge in2) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // Output equals selected input when in3 rises.
    check_out_matches_sel_on_in3_posedge: assert property (
        @(posedge in3) out == selected_input_value(sel, in0, in1, in2, in3)
    );

    // When sel==00, out mirrors in0 on in0 rising edges.
    check_route_in0_when_sel00: assert property (
        @(posedge in0) (sel == 2'b00) |-> (out == in0)
    );

    // When sel==01, out mirrors in1 on in1 rising edges.
    check_route_in1_when_sel01: assert property (
        @(posedge in1) (sel == 2'b01) |-> (out == in1)
    );

    // When sel==10, out mirrors in2 on in2 rising edges.
    check_route_in2_when_sel10: assert property (
        @(posedge in2) (sel == 2'b10) |-> (out == in2)
    );

    // When sel==11, out mirrors in3 on in3 rising edges.
    check_route_in3_when_sel11: assert property (
        @(posedge in3) (sel == 2'b11) |-> (out == in3)
    );

    // When out rises, it equals the value of the currently selected input.
    check_out_posedge_matches_selected: assert property (
        @(posedge out) out == selected_input_value(sel, in0, in1, in2, in3)
    );

endmodule

verilog_code:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CI,
    output [3:0] SUM,
    output CO
);

    wire C1, C2, C3;

    // Instantiate 4-bit full adder cells
    full_adder FA0(A[0], B[0], CI, SUM[0], C1);
    full_adder FA1(A[1], B[1], C1, SUM[1], C2);
    full_adder FA2(A[2], B[2], C2, SUM[2], C3);
    full_adder FA3(A[3], B[3], C3, SUM[3], CO);

endmodule

module full_adder (
    input A,
    input B,
    input CI,
    output SUM,
    output CO
);

    // Assign Sum and Carry Out using XOR and AND gates
    assign SUM = A ^ B ^ CI;
    assign CO = (A & B) | (B & CI) | (A & CI);

endmodule

sva_code:
module four_bit_adder_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic [3:0] SUM,
    input logic CO
);
    // Combinational 4-bit adder; no reset in RTL; use CLK only for sampling.

    // SUM and CO together equal the 5-bit arithmetic sum of A+B+CI.
    check_sum_and_carry_are_arithmetic: assert property (
        @(posedge CLK) {CO, SUM} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // CO equals the MSB of the 5-bit sum.
    check_carry_equals_sum_msb: assert property (
        @(posedge CLK) CO == ({1'b0, A} + {1'b0, B} + CI)[4]
    );

    // No carry-out when both MSBs are 0.
    check_no_carry_when_both_msb_zero: assert property (
        @(posedge CLK) (A[3] == 1'b0 && B[3] == 1'b0) |-> (CO == 1'b0)
    );

    // Carry-out must be 1 when both MSBs are 1.
    check_carry_when_both_msb_one: assert property (
        @(posedge CLK) (A[3] == 1'b1 && B[3] == 1'b1) |-> (CO == 1'b1)
    );

    // LSB sum bit is XOR of A[0], B[0], and CI.
    check_lsb_sum_xor: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ CI)
    );

    // Adding B=0 with CI=0 yields SUM=A and CO=0.
    check_identity_b_zero_no_ci: assert property (
        @(posedge CLK) ((B == 4'b0000) && (CI == 1'b0)) |-> ((SUM == A) && (CO == 1'b0))
    );

    // Adding A=0 with CI=0 yields SUM=B and CO=0.
    check_identity_a_zero_no_ci: assert property (
        @(posedge CLK) ((A == 4'b0000) && (CI == 1'b0)) |-> ((SUM == B) && (CO == 1'b0))
    );

    // With A=0 and B=0, output equals CI (no carry-out).
    check_zero_plus_zero_ci_only: assert property (
        @(posedge CLK) ((A == 4'b0000) && (B == 4'b0000)) |-> ((CO == 1'b0) && (SUM == {3'b000, CI}))
    );

    // A + (~A) + 1 produces SUM=0 and CO=1.
    check_ones_complement_plus_one: assert property (
        @(posedge CLK) ((B == ~A) && (CI == 1'b1)) |-> ((SUM == 4'b0000) && (CO == 1'b1))
    );

    // When A==B and CI==0, result is A shifted left by 1 with carry=MSB of A.
    check_double_when_equal_no_ci: assert property (
        @(posedge CLK) ((A == B) && (CI == 1'b0)) |-> ({CO, SUM} == {A[3], {A[2:0], 1'b0}})
    );

    // Adding 0xF with CI=1 yields {1, A}.
    check_add_f_with_ci_one: assert property (
        @(posedge CLK) ((B == 4'hF) && (CI == 1'b1)) |-> ({CO, SUM} == {1'b1, A})
    );

    // A + (~A) with CI=0 produces SUM=0xF and CO=0.
    check_ones_complement_no_ci: assert property (
        @(posedge CLK) ((B == ~A) && (CI == 1'b0)) |-> ((SUM == 4'hF) && (CO == 1'b0))
    );
endmodule

