module signed_mag_to_twos_comp (
    input signed [15:0] signed_mag,
    output reg signed [15:0] twos_comp
);

    always @(*) begin
        if (signed_mag >= 0) begin
            twos_comp = signed_mag;
        end else begin
            twos_comp = -signed_mag;
            twos_comp = ~twos_comp + 1;
        end
    end

endmodule

sva_code:
module signed_mag_to_twos_comp_sva (
    input logic clk,
    input  signed [15:0] signed_mag,
    input  signed [15:0] twos_comp
);
    // Output equals input (combinational pass-through).
    check_output_equals_input: assert property (
        @(posedge clk) (twos_comp == signed_mag)
    );

    // Sign bits match between input and output.
    check_sign_bit_match: assert property (
        @(posedge clk) (twos_comp[15] == signed_mag[15])
    );

    // If input is non-negative, output equals input.
    check_nonneg_passthrough: assert property (
        @(posedge clk) (signed_mag >= 0) |-> (twos_comp == signed_mag)
    );

    // If input is negative, output equals input.
    check_neg_passthrough: assert property (
        @(posedge clk) (signed_mag < 0) |-> (twos_comp == signed_mag)
    );

    // Stable input across cycles implies stable output.
    check_stable_propagation: assert property (
        @(posedge clk) $stable(signed_mag) |-> $stable(twos_comp)
    );

    // Any input change across cycles implies output changes.
    check_change_propagation: assert property (
        @(posedge clk) $changed(signed_mag) |-> $changed(twos_comp)
    );

    // Zero input passes through as zero.
    check_zero_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sd0) |-> (twos_comp == 16'sd0)
    );

    // Minimum value (0x8000) passes through unchanged.
    check_min_int_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sh8000) |-> (twos_comp == 16'sh8000)
    );

    // Maximum value (0x7FFF) passes through unchanged.
    check_max_int_passthrough: assert property (
        @(posedge clk) (signed_mag == 16'sh7FFF) |-> (twos_comp == 16'sh7FFF)
    );

    // Output bits match input bits (bitwise equality).
    check_bitwise_equality: assert property (
        @(posedge clk) (twos_comp ^ signed_mag) == 16'sd0
    );
endmodule

module my_mac_sva (
    input logic clk,
    input logic reset,     // active-high synchronous reset
    input logic ce,
    input logic [31:0] din0,
    input logic [31:0] din1,
    input logic [31:0] dout
);
    // Reset sets dout to 0 on the next cycle.
    reset_clears_dout_next: assert property (
        @(posedge clk) reset |-> (dout == 32'd0)
    );

    // While reset stays asserted (2+ cycles), dout is 0.
    reset_holds_zero_while_asserted: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (dout == 32'd0)
    );

    // When ce is LOW and prior cycle was not reset, dout holds its value.
    hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset) (!ce && !$past(reset)) |-> (dout == $past(dout))
    );

    // When ce is HIGH, dout accumulates din0*din1 modulo 2^32 on the next cycle.
    accumulates_on_ce: assert property (
        @(posedge clk) disable iff (reset) ce |-> (dout == (($past(dout) + ($past(din0) * $past(din1)))[31:0]))
    );

    // Any change in dout (not due to reset) implies ce was HIGH in the previous cycle.
    change_requires_ce_prev: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (dout != $past(dout))) |-> $past(ce)
    );

    // If ce is HIGH and either operand is zero, dout does not change next cycle.
    zero_operand_no_change: assert property (
        @(posedge clk) disable iff (reset) (ce && ((din0 == 32'd0) || (din1 == 32'd0))) |-> (dout == $past(dout))
    );

    // If ce is HIGH and previous dout was zero, next dout equals product LSBs.
    accumulate_from_zero: assert property (
        @(posedge clk) disable iff (reset) (ce && ($past(dout) == 32'd0)) |-> (dout == (($past(din0) * $past(din1))[31:0]))
    );

    // Two consecutive ce cycles accumulate two products modulo 2^32.
    two_cycle_accumulate: assert property (
        @(posedge clk) disable iff (reset)
            (ce && $past(ce,1) && !$past(reset,1) && !$past(reset,2)) |->
            (dout == (($past(dout,2) +
                       ($past(din0,2) * $past(din1,2)) +
                       ($past(din0,1) * $past(din1,1)))[31:0]))
    );

    // If ce is HIGH and din0 is 1, next dout increments by din1 modulo 2^32.
    unit_din0_increments_by_din1: assert property (
        @(posedge clk) disable iff (reset) (ce && (din0 == 32'd1)) |-> (dout == (($past(dout) + $past(din1))[31:0]))
    );

    // If ce is HIGH and din1 is 1, next dout increments by din0 modulo 2^32.
    unit_din1_increments_by_din0: assert property (
        @(posedge clk) disable iff (reset) (ce && (din1 == 32'd1)) |-> (dout == (($past(dout) + $past(din0))[31:0]))
    );
endmodule

verilog_code:
module priority_encoder_4to2 (
    input a,
    input b,
    input c,
    input d,
    output x,
    output y
);

    assign x = (a) ? 2'b00 : (b) ? 2'b01 : (c) ? 2'b10 : (d) ? 2'b11 : 2'b00;
    assign y = (a) ? 2'b00 : (b) ? 2'b00 : (c) ? 2'b01 : (d) ? 2'b01 : 2'b00;

endmodule

sva_code:
module priority_encoder_4to2_sva (
    input logic CLK,
    input logic a,
    input logic b,
    input logic c,
    input logic d,
    input logic x,
    input logic y
);
    // When a is high, output is 00 regardless of others.
    check_a_selects_00: assert property (
        @(posedge CLK) a |-> (x == 1'b0) && (y == 1'b0)
    );

    // When a is low and b is high, output is 10.
    check_b_selects_10: assert property (
        @(posedge CLK) (!a && b) |-> (x == 1'b1) && (y == 1'b0)
    );

    // When a and b are low and c is high, output is 01.
    check_c_selects_01: assert property (
        @(posedge CLK) (!a && !b && c) |-> (x == 1'b0) && (y == 1'b1)
    );

    // When a,b,c are low and d is high, output is 11.
    check_d_selects_11: assert property (
        @(posedge CLK) (!a && !b && !c && d) |-> (x == 1'b1) && (y == 1'b1)
    );

    // When all inputs are low, output is 00.
    check_none_selects_00: assert property (
        @(posedge CLK) (!a && !b && !c && !d) |-> (x == 1'b0) && (y == 1'b0)
    );

    // b has priority over c when a is low.
    check_b_overrides_c: assert property (
        @(posedge CLK) (!a && b && c) |-> (x == 1'b1) && (y == 1'b0)
    );

    // c has priority over d when a and b are low.
    check_c_overrides_d: assert property (
        @(posedge CLK) (!a && !b && c && d) |-> (x == 1'b0) && (y == 1'b1)
    );

    // x matches the RTL's LSB mapping.
    check_x_functional_equiv: assert property (
        @(posedge CLK) x == (a ? 1'b0 : b ? 1'b1 : c ? 1'b0 : d ? 1'b1 : 1'b0)
    );

    // y matches the RTL's mapping.
    check_y_functional_equiv: assert property (
        @(posedge CLK) y == (a ? 1'b0 : b ? 1'b0 : c ? 1'b1 : d ? 1'b1 : 1'b0)
    );

    // If y is 1, either c is selected or d is selected with higher-priority inputs low.
    check_y_one_implies_c_or_d: assert property (
        @(posedge CLK) y |-> ((!a && !b && c) || (!a && !b && !c && d))
    );
endmodule

