    // Next-cycle read_0 equals prior cycle's mux of (EN_write_0 ? write_0 : read_0).
    check_next_value_function: assert property (
        @(posedge CLK) 1'b1 |=> (read_0 == ($past(EN_write_0) ? $past(write_0) : $past(read_0)))
