);

reg [1:0] ff;

always @(posedge clk or negedge in_rst_n) begin
    if(!in_rst_n) begin
        ff[1] <= 1'b0;
        ff[0] <= 1'b0;
    end
    else begin
        ff[1] <= 1'b1;
        ff[0] <= ff[1];
    end
