module servo
#(
    parameter WIDTH = 16, parameter NUM = 1     ) (
    input clk50Mhz,                   input rst,                        input [(WIDTH*NUM)-1:0] posArray, output reg [NUM-1:0] pwm          );

wire [WIDTH-1:0] posArrayInternal[NUM-1:0];

reg [19:0] counter;

integer i;
genvar j;

generate
begin
