module Mealy #(
  parameter n = 4, // number of input signals
  parameter m = 2, // number of output signals
  parameter s = 4 // number of states in the state machine
)(
  input [n-1:0] in,
  input clk,
  output reg [m-1:0] out
);

reg [s-1:0] state; // current state of the state machine

// define the state transition rules and output values for each state
always @ (posedge clk) begin
  case (state)
    0: begin // state 0
         if (in[0] && in[1]) begin
           state <= 1;
           out <= 2'b11;
         end else begin
           state <= 0;
           out <= 2'b00;
         end
       end
    1: begin // state 1
         if (in[0] || in[1]) begin
           state <= 2;
           out <= 2'b10;
         end else begin
           state <= 1;
           out <= 2'b01;
         end
       end
    2: begin // state 2
         if (in[2]) begin
           state <= 3;
           out <= 2'b01;
         end else begin
           state <= 2;
           out <= 2'b10;
         end
       end
    3: begin // state 3
         if (in[3]) begin
           state <= 0;
           out <= 2'b10;
         end else begin
           state <= 3;
           out <= 2'b01;
         end
       end
  endcase
end

endmodule

