module top_module(
    input signed [31:0] a,
    input signed [31:0] b,
    output signed [63:0] product
);

    wire signed [15:0] stage1_out;
    wire signed [15:0] stage2_out;
    wire signed [15:0] stage3_out;
    wire signed [15:0] stage4_out;

