module sky130_fd_sc_lp__fahcin_sva (
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CIN
);
    // Combinational DUT with no clock/reset; sample properties on $global_clock.
    default clocking cb @(posedge $global_clock); endclocking

    ///// Functional equivalence to gate-level logic /////
    // SUM equals A ^ B ^ ~CIN.
    check_sum_functional: assert property ( SUM == (A ^ B ^ ~CIN) );

    // COUT equals (A&B) | (A&~CIN) | (B&~CIN).
    check_cout_functional: assert property ( COUT == ((A & B) | (A & ~CIN) | (B & ~CIN)) );

    ///// Behavior conditioned on CIN /////
    // When CIN is 0, SUM is bitwise NOT of A^B.
    check_sum_when_cin0: assert property ( (CIN == 1'b0) |-> (SUM == ~(A ^ B)) );

    // When CIN is 1, SUM equals A^B.
    check_sum_when_cin1: assert property ( (CIN == 1'b1) |-> (SUM == (A ^ B)) );

    // When CIN is 0, COUT equals A|B.
    check_cout_when_cin0: assert property ( (CIN == 1'b0) |-> (COUT == (A | B)) );

    // When CIN is 1, COUT equals A&B.
    check_cout_when_cin1: assert property ( (CIN == 1'b1) |-> (COUT == (A & B)) );

    ///// Behavior conditioned on A/B relation /////
    // When A equals B, SUM equals ~CIN.
    check_sum_when_a_eq_b: assert property ( (A == B) |-> (SUM == ~CIN) );

    // When A differs from B, SUM equals CIN.
    check_sum_when_a_neq_b: assert property ( (A ^ B) |-> (SUM == CIN) );

    // When A equals B, COUT equals A.
    check_cout_when_a_eq_b: assert property ( (A == B) |-> (COUT == A) );

    // When A differs from B, COUT equals ~CIN.
    check_cout_when_a_neq_b: assert property ( (A ^ B) |-> (COUT == ~CIN) );

endmodule

module up_counter_4bit_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic [3:0] count
);

    ///// Reset behavior /////
    // When rst is LOW at a clock edge, count must be 0 in the same cycle.
    check_reset_clears_now: assert property (
        @(posedge clk) (rst == 1'b0) |-> (count == 4'b0000)
    );

    // When rst is LOW at a clock edge, count must be 0 at the next clock edge.
    check_reset_clears_next: assert property (
        @(posedge clk) (rst == 1'b0) |=> (count == 4'b0000)
    );

    // On a sampled rising edge of rst, count is 0 at that cycle.
    check_reset_release_sample_zero: assert property (
        @(posedge clk) $rose(rst) |-> (count == 4'b0000)
    );

    ///// Enable/Count behavior (active when rst is HIGH) /////
    // When enabled, count increments by 1 modulo 16 on the next cycle.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b1) |=> (count == ($past(count) + 4'h1))
    );

    // When enabled, count must change on the next cycle.
    check_change_when_enabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b1) |=> (count != $past(count))
    );

    // When not enabled, count holds its value on the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst == 1'b0) (en == 1'b0) |=> (count == $past(count))
    );

    // When enabled at 0xF, the next value wraps to 0x0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (rst == 1'b0) ((count == 4'hF) && (en == 1'b1)) |=> (count == 4'h0)
    );

endmodule

