module bitwise_operators #(
  parameter n = 4 // number of bits in A and B
) (
  input [n-1:0] A,
  input [n-1:0] B,
  output [n-1:0] and_res,
  output [n-1:0] or_res,
  output [n-1:0] xor_res,
  output [n-1:0] not_res
);


assign and_res = A & B;
assign or_res = A | B;
assign xor_res = A ^ B;
assign not_res = ~A;

endmodule

sva_code:
module bitwise_operators_sva #(
  parameter int n = 4
) (
  input  logic                 CLK,
  input  logic                 RESETn,
  input  logic [n-1:0]         A,
  input  logic [n-1:0]         B,
  input  logic [n-1:0]         and_res,
  input  logic [n-1:0]         or_res,
  input  logic [n-1:0]         xor_res,
  input  logic [n-1:0]         not_res
);

  // and_res equals bitwise AND of A and B.
  check_and_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) and_res == (A & B)
  );

  // or_res equals bitwise OR of A and B.
  check_or_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) or_res == (A | B)
  );

  // xor_res equals bitwise XOR of A and B.
  check_xor_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) xor_res == (A ^ B)
  );

  // not_res equals bitwise NOT of A.
  check_not_definition: assert property (
    @(posedge CLK) disable iff (!RESETn) not_res == (~A)
  );

  // OR equals XOR OR AND.
  check_or_is_xor_or_and: assert property (
    @(posedge CLK) disable iff (!RESETn) or_res == (xor_res | and_res)
  );

  // XOR equals OR masked by NOT AND.
  check_xor_is_or_andmask: assert property (
    @(posedge CLK) disable iff (!RESETn) xor_res == (or_res & ~and_res)
  );

  // AND and XOR are disjoint (no overlapping 1s).
  check_and_xor_disjoint_zero: assert property (
    @(posedge CLK) disable iff (!RESETn) ((and_res & xor_res) == '0)
  );

  // NOT(A) AND A is always zero.
  check_not_and_zero: assert property (
    @(posedge CLK) disable iff (!RESETn) ((not_res & A) == '0)
  );

  // NOT(A) OR A is all ones.
  check_not_or_ones: assert property (
    @(posedge CLK) disable iff (!RESETn) ((not_res | A) == '1)
  );

  // OR covers all 1s present in A.
  check_or_covers_A: assert property (
    @(posedge CLK) disable iff (!RESETn) ((~or_res & A) == '0)
  );

endmodule

module mux4_ctrl_sva (
    input  logic        CLK,   // external verification clock (RTL has no clock/reset)
    input  logic [7:0]  A,
    input  logic [7:0]  B,
    input  logic [7:0]  C,
    input  logic [7:0]  D,
    input  logic        ctrl,
    input  logic [7:0]  out
);
    // RTL is purely combinational: ctrl=0 selects A, ctrl=1 selects D, otherwise out=0.

    // When ctrl==0, out equals A.
    check_ctrl0_selects_A: assert property (
        @(posedge CLK) (ctrl == 1'b0) |-> (out == A)
    );

    // When ctrl==1, out equals D.
    check_ctrl1_selects_D: assert property (
        @(posedge CLK) (ctrl == 1'b1) |-> (out == D)
    );

    // If ctrl is X/Z, out must be 0.
    check_default_zero_on_unknown_ctrl: assert property (
        @(posedge CLK) (ctrl !== 1'b0 && ctrl !== 1'b1) |-> (out == 8'h00)
    );

    // With ctrl held 0 and A stable, out stays stable.
    check_stable_out_when_ctrl0_A_stable: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $stable(A) |-> $stable(out)
    );

    // With ctrl held 1 and D stable, out stays stable.
    check_stable_out_when_ctrl1_D_stable: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $stable(D) |-> $stable(out)
    );

    // With ctrl held 0, a change on A causes a change on out.
    check_A_change_propagates_when_ctrl0: assert property (
        @(posedge CLK) (ctrl == 1'b0) && $stable(ctrl) && $changed(A) |-> $changed(out)
    );

    // With ctrl held 1, a change on D causes a change on out.
    check_D_change_propagates_when_ctrl1: assert property (
        @(posedge CLK) (ctrl == 1'b1) && $stable(ctrl) && $changed(D) |-> $changed(out)
    );

    // On ctrl rising edge, out reflects D.
    check_out_on_ctrl_rise: assert property (
        @(posedge CLK) $rose(ctrl) |-> (out == D)
    );

    // On ctrl falling edge, out reflects A.
    check_out_on_ctrl_fall: assert property (
        @(posedge CLK) $fell(ctrl) |-> (out == A)
    );
endmodule

verilog_code:
module adder_16bit(
    input [15:0] a,
    input [15:0] b,
    input sub,
    output [15:0] out
);

    assign out = sub ? a - b : a + b;

endmodule
module byte_reversal(
    input [31:0] in,
    output [31:0] out
);

    assign out = {in[7:0], in[15:8], in[23:16], in[31:24]};

endmodule
module bitwise_or(
    input [31:0] in1,
    input [31:0] in2,
    output [31:0] out
);

    assign out = in1 | in2;

endmodule
module top_module(
    input [31:0] a,
    input [31:0] b,
    input sub,
    input [31:0] in,
    output [31:0] out
);

    wire [15:0] adder_out;
    wire [31:0] byte_reversal_out;

    adder_16bit adder_inst(
        .a(a[15:0]),
        .b(b[15:0]),
        .sub(sub),
        .out(adder_out)
    );

    byte_reversal byte_reversal_inst(
        .in(in),
        .out(byte_reversal_out)
    );

    bitwise_or bitwise_or_inst(
        .in1({16'b0,adder_out}),
        .in2(byte_reversal_out),
        .out(out)
    );

endmodule

