);

  ///// Reset behavior /////
  // While reset is asserted low, outputs are cleared.
  reset_outputs_cleared: assert property (
    @(posedge clk) !reset |-> (out == 2'b00) && (valid == 1'b0)
  );

  ///// Encoding from inputs (uses previous cycle inputs due to registered outputs) /////
  // If in[3] was 1, out must be 3 and valid 1.
  encode_in3_maps_to_3: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && $past(in[3])) |-> (out == 2'b11) && (valid == 1'b1)
  );
  // If in[2] was 1 and in[3] was 0, out must be 2 and valid 1.
  encode_in2_maps_to_2: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && $past(in[2])) |-> (out == 2'b10) && (valid == 1'b1)
  );
  // If in[1] was 1 and in[3:2] were 0, out must be 1 and valid 1.
  encode_in1_maps_to_1: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && !$past(in[2]) && $past(in[1])) |-> (out == 2'b01) && (valid == 1'b1)
  );
  // If only in[0] was 1 among higher bits 3:1=0, out must be 0 and valid 1.
  encode_in0_maps_to_0: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && !$past(in[3]) && !$past(in[2]) && !$past(in[1]) && $past(in[0])) |-> (out == 2'b00) && (valid == 1'b1)
  );
  // If no inputs were 1, out must be 0 and valid 0.
  encode_none_maps_to_none: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && ($past(in) == 4'b0000)) |-> (out == 2'b00) && (valid == 1'b0)
  );

  ///// Valid flag semantics /////
  // valid equals OR-reduction of previous cycle inputs.
  valid_equals_or_prev_in: assert property (
    @(posedge clk) disable iff (!reset) $past(reset) |-> (valid == (|$past(in)))
  );
  // When valid is 0, out must be 0.
  valid_zero_implies_out_zero: assert property (
    @(posedge clk) disable iff (!reset) (valid == 1'b0) |-> (out == 2'b00)
  );

  ///// Reverse mapping checks (outputs imply prior inputs) /////
  // out==3 implies prior in[3]==1.
  out3_implies_prev_in3: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b11)) |-> $past(in[3])
  );
  // out==2 implies prior in[3]==0 and in[2]==1.
  out2_implies_prev_in2_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b10)) |-> (!$past(in[3]) && $past(in[2]))
  );
  // out==1 implies prior in[3:2]==0 and in[1]==1.
  out1_implies_prev_in1_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b01)) |-> (!$past(in[3]) && !$past(in[2]) && $past(in[1]))
  );
  // out==0 with valid==1 implies prior in[3:1]==0 and in[0]==1.
  out0_valid1_implies_prev_in0_only: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b00) && (valid == 1'b1)) |-> (!$past(in[3]) && !$past(in[2]) && !$past(in[1]) && $past(in[0]))
  );
  // out==0 with valid==0 implies prior inputs were all zero.
  out0_valid0_implies_prev_none: assert property (
    @(posedge clk) disable iff (!reset) ($past(reset) && (out == 2'b00) && (valid == 1'b0)) |-> ($past(in) == 4'b0000)
  );

endmodule

module bitwise_sva #(
    parameter int op = 0 // Mirror DUT parameter: 0=AND, 1=OR, 2=XOR, others=NOT
) (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic out
);
    generate
        if (op == 0) begin : GEN_AND
            // out equals in1 AND in2.
            check_and_functional: assert property (@(posedge clk) out == (in1 & in2));
            // If out is 1 then both inputs are 1.
            check_and_out_one_implies_inputs_one: assert property (@(posedge clk) out |-> (in1 && in2));
            // If any input is 0 then out is 0.
            check_and_input_zero_implies_out_zero: assert property (@(posedge clk) (!in1 || !in2) |-> !out);
            // Commutativity holds for AND.
            check_and_commutative: assert property (@(posedge clk) out == (in2 & in1));
        end else if (op == 1) begin : GEN_OR
            // out equals in1 OR in2.
            check_or_functional: assert property (@(posedge clk) out == (in1 | in2));
            // If any input is 1 then out is 1.
            check_or_input_one_implies_out_one: assert property (@(posedge clk) (in1 || in2) |-> out);
            // If out is 0 then both inputs are 0.
            check_or_out_zero_implies_inputs_zero: assert property (@(posedge clk) !out |-> (!in1 && !in2));
            // Commutativity holds for OR.
            check_or_commutative: assert property (@(posedge clk) out == (in2 | in1));
        end else if (op == 2) begin : GEN_XOR
            // out equals in1 XOR in2.
            check_xor_functional: assert property (@(posedge clk) out == (in1 ^ in2));
            // Equal inputs produce 0.
            check_xor_equal_inputs_zero: assert property (@(posedge clk) (in1 == in2) |-> (out == 1'b0));
            // Different inputs produce 1.
            check_xor_inequal_inputs_one: assert property (@(posedge clk) (in1 != in2) |-> (out == 1'b1));
            // Commutativity holds for XOR.
            check_xor_commutative: assert property (@(posedge clk) out == (in2 ^ in1));
        end else begin : GEN_NOT
            // out equals NOT of in1 (in2 is ignored).
            check_not_functional: assert property (@(posedge clk) out == (~in1));
            // If in1 is 0 then out is 1.
            check_not_in1_zero_out_one: assert property (@(posedge clk) (in1 == 1'b0) |-> (out == 1'b1));
            // If in1 is 1 then out is 0.
            check_not_in1_one_out_zero: assert property (@(posedge clk) (in1 == 1'b1) |-> (out == 1'b0));
        end
    endgenerate
endmodule

module up_counter_sva (
    input logic clk,
    input logic load,
    input logic [3:0] load_value,
    input logic [3:0] count
);
    // If load is high, next-cycle sampled count equals that cycle's load_value.
    check_load_updates_count_next_cycle: assert property (
        @(posedge clk) load |=> (count == $past(load_value))
    );

    // If load is low, next-cycle sampled count equals previous count + 1 (mod 16).
    check_increment_on_no_load: assert property (
        @(posedge clk) !load |=> (count == ($past(count) + 4'd1))
    );

    // Next-cycle sampled count always equals either prior load_value or prior count + 1.
    check_next_count_comes_from_load_or_increment: assert property (
        @(posedge clk) 1'b1 |=> (count == ($past(load) ? $past(load_value) : ($past(count) + 4'd1)))
    );

    // With no load and count at max, next-cycle sampled count wraps to 0.
    check_wrap_from_max_on_increment: assert property (
        @(posedge clk) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

    // With no load and count at 0, next-cycle sampled count becomes 1.
    check_increment_from_zero: assert property (
        @(posedge clk) (!load && (count == 4'h0)) |=> (count == 4'h1)
    );

    // If load assigns the same value as current count, next-cycle sampled count holds.
    check_stable_when_load_assigns_same: assert property (
        @(posedge clk) (load && (load_value == count)) |=> (count == $past(count))
    );

    // Two consecutive cycles of no load advance count by two.
    check_two_cycle_increment_when_no_load: assert property (
        @(posedge clk) (!load ##1 !load) |=> (count == ($past(count, 2) + 4'd2))
    );

    // Three consecutive cycles of no load advance count by three.
    check_three_cycle_increment_when_no_load: assert property (
        @(posedge clk) (!load ##1 !load ##1 !load) |=> (count == ($past(count, 3) + 4'd3))
    );

    // A load followed by no-load causes one increment from the loaded value.
    check_load_then_no_load_results_in_loaded_plus_one: assert property (
        @(posedge clk) (load ##1 !load) |=> (count == ($past(load_value, 2) + 4'd1))
    );

    // Two consecutive loads make the next-cycle sampled count equal the second load_value.
    check_two_consecutive_loads_results_in_second_value: assert property (
        @(posedge clk) (load ##1 load) |=> (count == $past(load_value))
    );
endmodule

module Sumador_sva (
    input logic CLK,               // Sampling clock for assertions (DUT is combinational; no reset)
    input logic [31:0] a,
    input logic [31:0] b,
    input logic [31:0] Z,
    input logic ovf
);

    // 32-bit zero-extended sum of 31-bit magnitudes
    function automatic [31:0] sum31(input logic [30:0] x, input logic [30:0] y);
        sum31 = {1'b0, x} + {1'b0, y};
    endfunction

    // 31-bit absolute difference of magnitudes
    function automatic [30:0] absdiff31(input logic [30:0] x, input logic [30:0] y);
        absdiff31 = (x >= y) ? (x - y) : (y - x);
    endfunction

    ///// Equal-sign path /////
    // When signs match, {ovf,Z[30:0]} equals zero-extended sum of magnitudes.
    check_eqsign_sum: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] == b[31]) |-> ({ovf, Z[30:0]} == sum31(a[30:0], b[30:0]))
    );

    // When signs match, Z's sign equals the inputs' sign.
    check_eqsign_signbit: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] == b[31]) |-> (Z[31] == a[31])
    );

    // When signs match and one magnitude is zero, output passes through the other with no overflow.
    check_eqsign_b_zero_passthru: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] == b[31] && (b[30:0] == 31'd0)) |-> (Z[30:0] == a[30:0] && Z[31] == a[31] && ovf == 1'b0)
    );

    // Symmetric passthrough when a's magnitude is zero.
    check_eqsign_a_zero_passthru: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] == b[31] && (a[30:0] == 31'd0)) |-> (Z[30:0] == b[30:0] && Z[31] == b[31] && ovf == 1'b0)
    );

    ///// Different-sign path /////
    // When signs differ, overflow is always zero.
    check_diffsign_ovf_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31]) |-> (ovf == 1'b0)
    );

    // When signs differ, Z's magnitude is the absolute difference of magnitudes.
    check_diffsign_absdiff: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31]) |-> (Z[30:0] == absdiff31(a[30:0], b[30:0]))
    );

    // When signs differ and magnitudes are equal, result is exactly zero.
    check_diffsign_equal_mags_zero: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && a[30:0] == b[30:0]) |-> (Z == 32'd0)
    );

    // When signs differ and |a| > |b|, Z's sign equals a's sign.
    check_diffsign_sign_from_a: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && a[30:0] > b[30:0]) |-> (Z[31] == a[31])
    );

    // When signs differ and |b| > |a|, Z's sign equals b's sign.
    check_diffsign_sign_from_b: assert property (
        @(posedge CLK) disable iff (1'b0) (a[31] != b[31] && b[30:0] > a[30:0]) |-> (Z[31] == b[31])
    );

    ///// General consistency /////
    // ovf can only be high when input signs match.
    check_ovf_only_on_eqsign: assert property (
        @(posedge CLK) disable iff (1'b0) ovf |-> (a[31] == b[31])
    );

    // Pure combinational behavior: if inputs are stable, outputs remain stable.
    check_pure_comb: assert property (
        @(posedge CLK) disable iff (1'b0) ($stable(a) && $stable(b)) |-> ($stable(Z) && $stable(ovf))
    );

endmodule

