    // When D0 falls and ctrl selects 0, S equals D0.
    follow_d0_on_fall_when_sel0: assert property (
        @(negedge D0[0]) (ctrl === 1'b0) |-> (S == D0)
    );

    // When D1 rises and ctrl selects 1, S equals D1.
    follow_d1_on_rise_when_sel1: assert property (
        @(posedge D1[0]) (ctrl === 1'b1) |-> (S == D1)
    );

    // When D1 falls and ctrl selects 1, S equals D1.
    follow_d1_on_fall_when_sel1: assert property (
        @(negedge D1[0]) (ctrl === 1'b1) |-> (S == D1)
    );

    // If ctrl is 0 (known), S equals D0 on any relevant edge.
    ctrl0_implies_out_eq_d0: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0[0] or negedge D0[0] or posedge D1[0] or negedge D1[0] or posedge S[0] or negedge S[0])
            (ctrl === 1'b0) |-> (S == D0)
    );

    // If ctrl is 1 (known), S equals D1 on any relevant edge.
    ctrl1_implies_out_eq_d1: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0[0] or negedge D0[0] or posedge D1[0] or negedge D1[0] or posedge S[0] or negedge S[0])
            (ctrl === 1'b1) |-> (S == D1)
    );

    // Output equals the mux equation at edges of inputs or output.
    check_mux_equation_on_any_edge: assert property (
        @(posedge ctrl or negedge ctrl or posedge D0[0] or negedge D0[0] or posedge D1[0] or negedge D1[0] or posedge S[0] or negedge S[0])
            (S == ((ctrl == 1'b0) ? D0 : D1))
    );

    // When inputs are equal, toggling ctrl still yields that value.
    equal_inputs_ctrl_edge_value: assert property (
        @(posedge ctrl or negedge ctrl) (D0 == D1) |-> (S == D0)
    );
endmodule

verilog_code:
module magnitude_comparator_selector (
    input [2:0] a, b,
    input [1:0] select,
    output reg [2:0] comparison_result,
    output reg [1:0] input_selected
);

    always @* begin
        if (a > b) begin
            comparison_result = a;
            input_selected = 2'b00;
        end
        else if (b > a) begin
            comparison_result = b;
            input_selected = 2'b01;
        end
        else begin
            comparison_result = a;
            input_selected = select;
        end
    end

endmodule

sva_code:
module magnitude_comparator_selector_sva (
    input logic CLK, // sampling clock for formal
    input logic [2:0] a,
    input logic [2:0] b,
    input logic [1:0] select,
    input logic [2:0] comparison_result,
    input logic [1:0] input_selected
);

    // If a > b, drive result=a and select=00.
    check_a_gt_b_drives_a_and_sel00: assert property (
        @(posedge CLK) (a > b) |-> (comparison_result == a) && (input_selected == 2'b00)
    );

    // If b > a, drive result=b and select=01.
    check_b_gt_a_drives_b_and_sel01: assert property (
        @(posedge CLK) (b > a) |-> (comparison_result == b) && (input_selected == 2'b01)
    );

    // If a == b, drive result=a and pass through select.
    check_equal_drives_a_and_sel_passthrough: assert property (
        @(posedge CLK) (a == b) |-> (comparison_result == a) && (input_selected == select)
    );

    // Result is always either a or b.
    check_result_is_either_a_or_b: assert property (
        @(posedge CLK) (comparison_result == a) || (comparison_result == b)
    );

    // MSB of input_selected is 1 only when a == b (values 2 or 3 only on equality).
    check_sel_msb_one_only_when_equal: assert property (
        @(posedge CLK) (input_selected[1] == 1'b1) |-> (a == b)
    );

    // When a != b, MSB of input_selected must be 0 (only 00 or 01 allowed).
    check_not_equal_forces_sel_msb_zero: assert property (
        @(posedge CLK) (a != b) |-> (input_selected[1] == 1'b0)
    );

    // If result==b, then b > a and select must be 01.
    check_result_b_implies_b_gt_a_and_sel01: assert property (
        @(posedge CLK) (comparison_result == b) |-> (b > a) && (input_selected == 2'b01)
    );

    // If result==a, then a >= b.
    check_result_a_implies_a_ge_b: assert property (
        @(posedge CLK) (comparison_result == a) |-> (a >= b)
    );

    // When a != b and only select changes, outputs must not change.
    check_select_irrelevant_when_not_equal: assert property (
        @(posedge CLK) (a != b) && $stable(a) && $stable(b) && !$stable(select)
        |-> $stable(comparison_result) && $stable(input_selected)
    );

    // When a == b and only select changes, result stays and input_selected follows select.
    check_select_passthrough_when_equal_changes: assert property (
        @(posedge CLK) (a == b) && $stable(a) && $stable(b) && !$stable(select)
        |-> $stable(comparison_result) && !$stable(input_selected)
    );

endmodule

verilog_code:
module mux_min (
    input wire [2:0] vec, // 3-bit input for the multiplexer
    input wire select, // Select input for the multiplexer
    input [7:0] a, b, c, d, // 4 unsigned 8-bit input values for the functional module
    output wire [2:0] outv, // 3 output ports for the selected bit from the multiplexer
    output wire o2,
    output wire o1,
    output wire o0,
    output wire [7:0] min // 8-bit output representing the minimum value among the four input values
);

// Multiplexer
assign outv = {vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0], vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0], vec[2] ? vec[2] : vec[1] ? vec[1] : vec[0]};
assign o2 = outv[2];
assign o1 = outv[1];
assign o0 = outv[0];

// Comparator and Multiplexer for minimum value
wire [7:0] min1, min2, min3;
assign min1 = a < b ? a : b;
assign min2 = c < d ? c : d;
assign min3 = min1 < min2 ? min1 : min2;
assign min = min3;

endmodule

sva_code:
module mux_min_sva (
    input logic clk,
    input logic [2:0] vec,
    input logic select,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [7:0] c,
    input logic [7:0] d,
    input logic [2:0] outv,
    input logic o2,
    input logic o1,
    input logic o0,
    input logic [7:0] min
);

    ///// Multiplexer (outv/o2/o1/o0) /////
    // outv must be three copies of (vec[2] | vec[1] | vec[0]).
    check_outv_replication: assert property (
        @(posedge clk) outv == {3{|vec}}
    );

    // o2 equals outv[2].
    check_o2_matches_outv2: assert property (
        @(posedge clk) o2 == outv[2]
    );

    // o1 equals outv[1].
    check_o1_matches_outv1: assert property (
        @(posedge clk) o1 == outv[1]
    );

    // o0 equals outv[0].
    check_o0_matches_outv0: assert property (
        @(posedge clk) o0 == outv[0]
    );

    // If all vec bits are 0 then outv is 3'b000.
    check_outv_all_zero_when_vec_zero: assert property (
        @(posedge clk) (~|vec) |-> (outv == 3'b000)
    );

    // If any vec bit is 1 then outv is 3'b111.
    check_outv_all_one_when_any_vec_high: assert property (
        @(posedge clk) (|vec) |-> (outv == 3'b111)
    );

    // Changing only 'select' does not change outputs (select is unused).
    check_outputs_independent_of_select: assert property (
        @(posedge clk)
            $changed(select) && $stable(vec) && $stable(a) && $stable(b) && $stable(c) && $stable(d)
        |-> $stable(outv) && $stable(o2) && $stable(o1) && $stable(o0) && $stable(min)
    );

    ///// Minimum-of-four (min) /////
    // min is less than or equal to a.
    check_min_le_a: assert property (
        @(posedge clk) min <= a
    );

    // min is less than or equal to b.
    check_min_le_b: assert property (
        @(posedge clk) min <= b
    );

    // min is less than or equal to c.
    check_min_le_c: assert property (
        @(posedge clk) min <= c
    );

    // min is less than or equal to d.
    check_min_le_d: assert property (
        @(posedge clk) min <= d
    );

    // min equals one of the inputs a/b/c/d.
    check_min_is_input: assert property (
        @(posedge clk) (min == a) || (min == b) || (min == c) || (min == d)
    );

    // If a is strictly less than b,c,d then min equals a.
    check_unique_min_a: assert property (
        @(posedge clk) (a < b) && (a < c) && (a < d) |-> (min == a)
    );

    // If b is strictly less than a,c,d then min equals b.
    check_unique_min_b: assert property (
        @(posedge clk) (b < a) && (b < c) && (b < d) |-> (min == b)
    );

    // If c is strictly less than a,b,d then min equals c.
    check_unique_min_c: assert property (
        @(posedge clk) (c < a) && (c < b) && (c < d) |-> (min == c)
    );

    // If d is strictly less than a,b,c then min equals d.
    check_unique_min_d: assert property (
        @(posedge clk) (d < a) && (d < b) && (d < c) |-> (min == d)
    );

    // min matches the exact pairwise comparator/mux structure.
    check_min_structural_equivalence: assert property (
        @(posedge clk)
            min == ( (((a < b) ? a : b) < ((c < d) ? c : d))
                     ? ((a < b) ? a : b)
                     : ((c < d) ? c : d) )
    );

endmodule

