sva_code:
module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic VPWR,
    input logic VGND,
    input logic Y
);
    // X implements NOR of A1 and A2 (sampled after inputs settle).
    check_x_is_nor_a1a2: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge B1 or negedge B1 or
          posedge B2 or negedge B2 or
          posedge C1 or negedge C1 or
          posedge VPWR or negedge VPWR or
          posedge VGND or negedge VGND)
        (!$isunknown({A1, A2})) |-> ##0 (X === ~(A1 | A2))
    );

    // Y buffers X (sampled after drivers settle).
    check_y_buffers_x: assert property (
        @(posedge A1 or negedge A1 or
          posedge A2 or negedge A2 or
          posedge X  or negedge X  or
          posedge B1 or negedge B1 or
          posedge B2 or negedge B2 or
          posedge C1 or negedge C1 or
          posedge VPWR or negedge VPWR or
          posedge VGND or negedge VGND)
        (!$isunknown(X)) |-> ##0 (Y === X)
    );

    // When X rises, Y must be HIGH after propagation.
    buf_y_high_on_x_rise: assert property (
        @(posedge X) ##0 (Y === 1'b1)
    );

    // When X falls, Y must be LOW after propagation.
    buf_y_low_on_x_fall: assert property (
        @(negedge X) ##0 (Y === 1'b0)
    );

    // When Y rises, X must be HIGH (consistency with Y=X).
    buf_x_high_on_y_rise: assert property (
        @(posedge Y) ##0 (X === 1'b1)
    );

    // When Y falls, X must be LOW (consistency with Y=X).
    buf_x_low_on_y_fall: assert property (
        @(negedge Y) ##0 (X === 1'b0)
    );
endmodule

verilog_code:
module adder_4bit(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C_out
);

    wire [3:0] C;

    full_adder fa0(
        .A(A[0]),
        .B(B[0]),
        .C_in(1'b0),
        .S(S[0]),
        .C_out(C[0])
    );

    full_adder fa1(
        .A(A[1]),
        .B(B[1]),
        .C_in(C[0]),
        .S(S[1]),
        .C_out(C[1])
    );

    full_adder fa2(
        .A(A[2]),
        .B(B[2]),
        .C_in(C[1]),
        .S(S[2]),
        .C_out(C[2])
    );

    full_adder fa3(
        .A(A[3]),
        .B(B[3]),
        .C_in(C[2]),
        .S(S[3]),
        .C_out(C_out)
    );

endmodule

module full_adder(
    input A,
    input B,
    input C_in,
    output S,
    output C_out
);

    assign S = A ^ B ^ C_in;
    assign C_out = (A & B) | (C_in & (A ^ B));

endmodule

sva_code:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic C_out
);
    ///// Functional equivalence to addition /////
    // The 5-bit result equals zero-extended A + B.
    check_sum_matches_addition: assert property (
        @(posedge clk) {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    ///// Bit 0 (no carry-in) /////
    // LSB sum equals A0 XOR B0.
    check_s0_no_cin: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

    ///// Bit 1 with carry from bit 0 /////
    // Bit1 sum equals A1 XOR B1 XOR (A0 & B0).
    check_s1_with_c0: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );
    // If no carry from bit0, S1 is A1 XOR B1.
    check_s1_when_c0_zero: assert property (
        @(posedge clk) (~(A[0] & B[0])) |-> (S[1] == (A[1] ^ B[1]))
    );
    // If carry from bit0, S1 is inverted XOR of A1 and B1.
    check_s1_when_c0_one: assert property (
        @(posedge clk) (A[0] & B[0]) |-> (S[1] == ~(A[1] ^ B[1]))
    );

    ///// Bit 2 with ripple carry /////
    // Bit2 sum equals A2 XOR B2 XOR C1 (expanded C1).
    check_s2_with_c1: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))
    );
    // If C0==0 and A1==B1, then C1==A1&B1 so S2==A2 XOR B2 XOR (A1&B1).
    check_s2_c1_reduction: assert property (
        @(posedge clk) (~(A[0] & B[0]) && (A[1] == B[1])) |-> (S[2] == (A[2] ^ B[2] ^ (A[1] & B[1])))
    );
    // If C0==1 and (A1^B1)==1, then C1==1 so S2==~(A2^B2).
    check_s2_when_carry_generate: assert property (
        @(posedge clk) ((A[0] & B[0]) && (A[1] ^ B[1])) |-> (S[2] == ~(A[2] ^ B[2]))
    );

    ///// Bit 3 with ripple carry /////
    // Bit3 sum equals A3 XOR B3 XOR C2 (expanded C2).
    check_s3_with_c2: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0]))))))
    );

    ///// Final carry-out /////
    // C_out equals C3 (expanded from ripple logic).
    check_cout_with_c3: assert property (
        @(posedge clk) C_out == ((A[3] & B[3]) | ((A[3] ^ B[3]) & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & (A[0] & B[0])))))))
    );
    // If MSB inputs are both 1, C_out must be 1.
    check_cout_when_msb_both_one: assert property (
        @(posedge clk) (A[3] & B[3]) |-> (C_out == 1'b1)
    );
    // If MSB inputs are both 0, C_out must be 0.
    check_cout_when_msb_both_zero: assert property (
        @(posedge clk) (~A[3] & ~B[3]) |-> (C_out == 1'b0)
    );

    ///// Sanity and stability /////
    // Adding 0 + 0 yields 0 with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) ((A == 4'b0000) && (B == 4'b0000)) |-> ((S == 4'b0000) && (C_out == 1'b0))
    );
    // Adding 15 + 15 yields 30 => S=14 and C_out=1.
    check_max_plus_max: assert property (
        @(posedge clk) ((A == 4'b1111) && (B == 4'b1111)) |-> ((S == 4'b1110) && (C_out == 1'b1))
    );
    // If inputs are stable cycle-to-cycle, outputs are stable (pure combinational).
    check_outputs_stable_when_inputs_stable: assert property (
        @(posedge clk) ($stable(A) && $stable(B)) |-> ($stable(S) && $stable(C_out))
    );

endmodule

module sync_sva (
    input logic OutputClock,
    input logic reset_b,
    input logic InputData,
    input logic OutputData
);

    ///// Reset behavior /////
    // If reset was LOW in the previous cycle, OutputData must be 0 now.
    reset_prev_low_forces_zero_now: assert property (
        @(posedge OutputClock) $past(!reset_b) |-> (OutputData == 1'b0)
    );

    // If reset is LOW now, OutputData will be 0 on the next cycle.
    reset_low_forces_zero_next: assert property (
        @(posedge OutputClock) (!reset_b) |=> (OutputData == 1'b0)
    );

    // On the cycle reset_b rises, OutputData is 0.
    reset_release_cycle_zero: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> (OutputData == 1'b0)
    );

    // While reset is held LOW across consecutive cycles, OutputData stays 0.
    reset_held_low_keeps_zero: assert property (
        @(posedge OutputClock) (!reset_b && $past(!reset_b)) |-> (OutputData == 1'b0)
    );

    ///// Active behavior /////
    // When not in reset and the previous cycle was also not in reset, OutputData is either 0 (due to any async reset between clocks) or equals the previous InputData.
    active_out_is_zero_or_prev_in: assert property (
        @(posedge OutputClock) disable iff (!reset_b)
            $past(reset_b) |-> ((OutputData == 1'b0) || (OutputData == $past(InputData)))
    );

    // After a reset release, if reset remains HIGH next cycle, OutputData captures InputData from the release cycle.
    capture_after_reset_release: assert property (
        @(posedge OutputClock) $rose(reset_b) |-> ##1 (!reset_b || (OutputData == $past(InputData)))
    );

endmodule

verilog_code:
module parity_checker (
  input [7:0] data_in,
  input sel_b1,
  output reg parity
);

  wire xor_out;
  assign xor_out = data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7];

  always @(*) begin
    if(sel_b1) begin
      parity <= ~xor_out;
    end else begin
      parity <= xor_out;
    end
  end

endmodule

sva_code:
module parity_checker_sva (
    input logic CLK,          // external sampling clock for SVA (RTL has no clock)
    input logic [7:0] data_in,
    input logic sel_b1,
    input logic parity
);
    // Analysis: no clock/reset in RTL; purely combinational always @(*).
    // Behavior: xor_out = XOR of data_in[7:0]; parity = xor_out when sel_b1==0, else ~xor_out.

    // When sel_b1==0, parity equals XOR of data_in bits.
    check_parity_sel0: assert property (
        @(posedge CLK) (!sel_b1) |-> (parity == ^data_in)
    );

    // When sel_b1==1, parity equals inverted XOR of data_in bits.
    check_parity_sel1: assert property (
        @(posedge CLK) (sel_b1) |-> (parity == ~(^data_in))
    );

    // Parity matches the Boolean equation parity == (^data_in) ^ sel_b1.
    check_parity_equation: assert property (
        @(posedge CLK) 1'b1 |-> (parity == ((^data_in) ^ sel_b1))
    );

    // If inputs are stable, parity must be stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge CLK) ($stable(data_in) && $stable(sel_b1)) |-> $stable(parity)
    );

    // Output changes only if at least one input changes.
    check_output_change_requires_input_change: assert property (
        @(posedge CLK) $changed(parity) |-> (!$stable(data_in) || !$stable(sel_b1))
    );

    // If only sel_b1 toggles, parity toggles.
    check_toggle_when_only_sel_changes: assert property (
        @(posedge CLK) ($changed(sel_b1) && $stable(data_in)) |-> (parity == ~$past(parity))
    );

    // If sel_b1 is stable and an odd number of data bits toggle, parity toggles.
    check_toggle_on_odd_data_changes: assert property (
        @(posedge CLK) ($stable(sel_b1) && (^(data_in ^ $past(data_in)))) |-> (parity == ~$past(parity))
    );

    // If sel_b1 is stable and an even number of data bits toggle, parity does not toggle.
    check_no_toggle_on_even_data_changes: assert property (
        @(posedge CLK) ($stable(sel_b1) && !(^(data_in ^ $past(data_in)))) |-> (parity == $past(parity))
    );

    // If XOR of data_in is 0, parity equals sel_b1.
    check_xor_zero_parity_equals_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b0) |-> (parity == sel_b1)
    );

    // If XOR of data_in is 1, parity equals inverse of sel_b1.
    check_xor_one_parity_equals_not_sel: assert property (
        @(posedge CLK) ((^data_in) == 1'b1) |-> (parity == ~sel_b1)
    );
endmodule

