sva_code:
module three_to_one_sva (
    input logic CLK,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] X
);
    ///// Functional equivalence /////
    // X must equal (A & B) ^ (B | C).
    check_function_equivalence_main: assert property (
        @(posedge CLK) X == ((A & B) ^ (B | C))
    );
    // X must also equal ((~A) & B) | (C & ~B).
    check_equivalence_mux_form: assert property (
        @(posedge CLK) X == (((~A) & B) | (C & ~B))
    );

    ///// Bit-level masking behaviors /////
    // Bits where B is 0: X must match C on those bits.
    check_bits_where_B_zero_match_C: assert property (
        @(posedge CLK) (((X ^ C) & ~B) == 8'h00)
    );
    // Bits where B is 1: X must match ~A on those bits.
    check_bits_where_B_one_match_notA: assert property (
        @(posedge CLK) (((X ^ (~A)) & B) == 8'h00)
    );

    ///// Special cases /////
    // If all bits of B are 0, X equals C.
    check_all_B_zero_implies_X_eq_C: assert property (
        @(posedge CLK) (B == 8'h00) |-> (X == C)
    );
    // If all bits of B are 1, X equals ~A.
    check_all_B_ones_implies_X_eq_notA: assert property (
        @(posedge CLK) (B == 8'hFF) |-> (X == (~A))
    );
    // If A equals C, X reduces to A ^ B.
    check_when_A_equals_C_then_X_eq_A_xor_B: assert property (
        @(posedge CLK) (A == C) |-> (X == (A ^ B))
    );
    // If C equals ~A, X equals ~A regardless of B.
    check_when_C_equals_notA_then_X_eq_notA: assert property (
        @(posedge CLK) (C == (~A)) |-> (X == (~A))
    );
    // If B equals C, X equals B & ~A.
    check_when_B_equals_C_then_X_eq_B_and_notA: assert property (
        @(posedge CLK) (B == C) |-> (X == (B & (~A)))
    );
    // If B equals ~C, X equals ~(A & B).
    check_when_B_equals_notC_then_X_eq_not_AandB: assert property (
        @(posedge CLK) (B == (~C)) |-> (X == (~(A & B)))
    );
endmodule

verilog_code:
module binary_to_gray(
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];

endmodule

sva_code:
module binary_to_gray_sva (
    input logic clk,
    input logic [3:0] binary,
    input logic [3:0] gray
);
    ///// Bitwise mapping /////
    // MSB maps directly: gray[3] == binary[3].
    check_map_bit3: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] == binary[3]
    );
    // gray[2] == binary[3] ^ binary[2].
    check_map_bit2: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] == (binary[3] ^ binary[2])
    );
    // gray[1] == binary[2] ^ binary[1].
    check_map_bit1: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] == (binary[2] ^ binary[1])
    );
    // gray[0] == binary[1] ^ binary[0].
    check_map_bit0: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] == (binary[1] ^ binary[0])
    );

    ///// Vector mapping equivalence /////
    // gray == binary XOR (binary >> 1).
    check_map_vector: assert property (
        @(posedge clk) disable iff (1'b0) gray == (binary ^ {1'b0, binary[3:1]})
    );

    ///// Inverse relations derived from mapping /////
    // Recover binary[2] from gray: binary[2] == gray[2] ^ gray[3].
    check_inverse_b2: assert property (
        @(posedge clk) disable iff (1'b0) binary[2] == (gray[2] ^ gray[3])
    );
    // Recover binary[1] from gray: binary[1] == gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b1: assert property (
        @(posedge clk) disable iff (1'b0) binary[1] == (gray[1] ^ gray[2] ^ gray[3])
    );
    // Recover binary[0] from gray: binary[0] == gray[0] ^ gray[1] ^ gray[2] ^ gray[3].
    check_inverse_b0: assert property (
        @(posedge clk) disable iff (1'b0) binary[0] == (gray[0] ^ gray[1] ^ gray[2] ^ gray[3])
    );

    ///// Additional consistency checks /////
    // Parity of gray equals LSB of binary.
    check_parity_relation: assert property (
        @(posedge clk) disable iff (1'b0) (^gray) == binary[0]
    );
    // Upper pair mapping consistency: {gray[3],gray[2]}.
    check_upper_pair_map: assert property (
        @(posedge clk) disable iff (1'b0) {gray[3], gray[2]} == {binary[3], (binary[3] ^ binary[2])}
    );
endmodule

verilog_code:
module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input CI,
    output CO,
    output [3:0] S
);

wire [3:0] C; // intermediate carry values
wire [3:0] X; // intermediate sum values

// full adder for bit 0
full_adder FA0(A[0], B[0], CI, C[0], X[0]);

// full adder for bit 1
full_adder FA1(A[1], B[1], C[0], C[1], X[1]);

// full adder for bit 2
full_adder FA2(A[2], B[2], C[1], C[2], X[2]);

// full adder for bit 3
full_adder FA3(A[3], B[3], C[2], CO, X[3]);

assign S = X;

endmodule

module full_adder(
    input A,
    input B,
    input CI,
    output CO,
    output S
);

assign {CO, S} = A + B + CI;

endmodule

sva_code:
module four_bit_adder_sva (
    input logic CLK,          // sampling clock for SVA
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic CO,
    input logic [3:0] S
);
    // Sum and carry-out equal the 5-bit addition of inputs.
    sum_matches_addition: assert property (
        @(posedge CLK) {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

    // S equals lower 4 bits of the 5-bit sum.
    s_is_lower_nibble_of_sum: assert property (
        @(posedge CLK) S == (({1'b0, A} + {1'b0, B} + CI)[3:0])
    );

    // CO equals MSB of the 5-bit sum.
    co_is_msb_of_sum: assert property (
        @(posedge CLK) CO == (({1'b0, A} + {1'b0, B} + CI)[4])
    );

    // LSB sum equals XOR of inputs.
    lsb_xor_rule: assert property (
        @(posedge CLK) S[0] == (A[0] ^ B[0] ^ CI)
    );

    // Identity: when B==0 and CI==0, output equals A with no carry.
    identity_b_zero_ci_zero: assert property (
        @(posedge CLK) (B == 4'b0000) && (CI == 1'b0) |-> (S == A) && (CO == 1'b0)
    );

    // Identity: when A==0 and CI==0, output equals B with no carry.
    identity_a_zero_ci_zero: assert property (
        @(posedge CLK) (A == 4'b0000) && (CI == 1'b0) |-> (S == B) && (CO == 1'b0)
    );

    // Corner case: when A==0 and B==0, S echoes CI and CO is 0.
    zero_inputs_corner: assert property (
        @(posedge CLK) (A == 4'b0000) && (B == 4'b0000) |-> (S == {3'b000, CI}) && (CO == 1'b0)
    );

    // No carry-out when 5-bit sum is less than 16.
    no_carry_without_overflow: assert property (
        @(posedge CLK) (({1'b0, A} + {1'b0, B} + CI) < 5'd16) |-> (CO == 1'b0)
    );

    // Carry-out asserted when 5-bit sum is 16 or more.
    carry_with_overflow: assert property (
        @(posedge CLK) (({1'b0, A} + {1'b0, B} + CI) >= 5'd16) |-> (CO == 1'b1)
    );

    // Outputs remain stable when inputs are stable between samples.
    outputs_stable_when_inputs_stable: assert property (
        @(posedge CLK) $stable(A) && $stable(B) && $stable(CI) |-> $stable(S) && $stable(CO)
    );
endmodule

verilog_code:
module mux2to1 (out, in0, in1, sel);
	output out;
	input in0, in1;
	input sel;
	assign out = sel ? in1 : in0;
endmodule

module or2 (out, in0, in1);
	output out;
	input in0, in1;
	assign out = in0 | in1;
endmodule

module mux4to1 (out, in0, in1, in2, in3, sel);
