sva_code:
module mux4to1_sva (
    input logic CLK,
    input logic out,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic [1:0] sel
);
    // out equals the canonical 4:1 mux function of sel and inputs.
    check_mux_function: assert property (
        @(posedge CLK) out == (sel[1] ? (sel[0] ? in3 : in2) : (sel[0] ? in1 : in0))
    );

    // When sel==00, out must equal in0.
    check_sel00_maps_in0: assert property (
        @(posedge CLK) (sel == 2'b00) |-> (out == in0)
    );

    // When sel==01, out must equal in1.
    check_sel01_maps_in1: assert property (
        @(posedge CLK) (sel == 2'b01) |-> (out == in1)
    );

    // When sel==10, out must equal in2.
    check_sel10_maps_in2: assert property (
        @(posedge CLK) (sel == 2'b10) |-> (out == in2)
    );

    // When sel==11, out must equal in3.
    check_sel11_maps_in3: assert property (
        @(posedge CLK) (sel == 2'b11) |-> (out == in3)
    );

    // MSB of sel selects between lower pair (in0/in1) when 0.
    check_group_select_low: assert property (
        @(posedge CLK) (sel[1] == 1'b0) |-> (out == (sel[0] ? in1 : in0))
    );

    // MSB of sel selects between upper pair (in2/in3) when 1.
    check_group_select_high: assert property (
        @(posedge CLK) (sel[1] == 1'b1) |-> (out == (sel[0] ? in3 : in2))
    );

    // Purely combinational: if all inputs and sel are unchanged, out is unchanged.
    check_memoryless: assert property (
        @(posedge CLK) ({in3,in2,in1,in0,sel} == $past({in3,in2,in1,in0,sel})) |-> (out == $past(out))
    );

    // Isolation: with sel==00 stable, changes on in1/in2/in3 do not affect out.
    check_isolation_sel00: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b00 && sel == 2'b00 && in0 == $past(in0) &&
             ((in1 != $past(in1)) || (in2 != $past(in2)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==01 stable, changes on in0/in2/in3 do not affect out.
    check_isolation_sel01: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b01 && sel == 2'b01 && in1 == $past(in1) &&
             ((in0 != $past(in0)) || (in2 != $past(in2)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==10 stable, changes on in0/in1/in3 do not affect out.
    check_isolation_sel10: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b10 && sel == 2'b10 && in2 == $past(in2) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in3 != $past(in3))))
        |-> (out == $past(out))
    );

    // Isolation: with sel==11 stable, changes on in0/in1/in2 do not affect out.
    check_isolation_sel11: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b11 && sel == 2'b11 && in3 == $past(in3) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in2 != $past(in2))))
        |-> (out == $past(out))
    );
endmodule

verilog_code:
module mux_4to1 (
  input [3:0] data_in,
  input [1:0] sel,
  output reg out
);

always @(*)
begin
  case(sel)
    2'b00: out = sel[0] ? data_in[1] : data_in[0];
    2'b01: out = sel[0] ? data_in[3] : data_in[2];
    default: out = 1'b0;
  endcase
end

endmodule

sva_code:
module mux_4to1_sva (
    input logic [3:0] data_in,
    input logic [1:0] sel,
    input logic       out
);
    // Out matches truth table at sel[0] rising edges.
    check_truth_table_on_sel0: assert property (
        @(posedge sel[0]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

    // Out matches truth table at sel[1] rising edges.
    check_truth_table_on_sel1: assert property (
        @(posedge sel[1]) out == ((sel == 2'b00) ? data_in[0] :
                                   (sel == 2'b01) ? data_in[3] :
                                   1'b0)
    );

    // When sel==00, out equals data_in[0] at data_in[0] edges.
    check_sel00_data0_drives_out: assert property (
        @(posedge data_in[0]) (sel == 2'b00) |-> (out == data_in[0])
    );

    // When sel==01, out equals data_in[3] at data_in[3] edges.
    check_sel01_data3_drives_out: assert property (
        @(posedge data_in[3]) (sel == 2'b01) |-> (out == data_in[3])
    );

    // sel[1]==1 implies out is 0 at sel[1] rising edge (default case).
    check_default_zero_on_sel1_rise: assert property (
        @(posedge sel[1]) out == 1'b0
    );

    // Out cannot rise when sel[1]==1.
    check_no_out_rise_when_sel1_high: assert property (
        @(posedge out) sel[1] == 1'b0
    );
endmodule

verilog_code:
module r_COMMAND(output reg [7:0] reg_0x23, input wire reset, input wire wenb, input wire [7:0] in_data, input wire clk);
	always@(posedge clk)
	begin
		if(reset==0) begin
			if(wenb==0)
				reg_0x23<=in_data;
			else
				reg_0x23<=reg_0x23;
		end
		else
			reg_0x23<=8'h00;
	end
endmodule

sva_code:
module r_COMMAND_sva (
    input logic clk,
    input logic reset,       // active-high synchronous reset
    input logic wenb,        // active-low write enable
    input logic [7:0] in_data,
    input logic [7:0] reg_0x23
);
    // Reset drives reg_0x23 to 8'h00 on the next clock.
    check_reset_clears_reg_next: assert property (
        @(posedge clk) reset |-> (reg_0x23 == 8'h00)
    );

    // With wenb HIGH (no write), hold previous value to next cycle.
    check_hold_when_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |-> (reg_0x23 == $past(reg_0x23))
    );

    // With wenb LOW, load in_data on the next cycle.
    check_update_on_wenb_low: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |-> (reg_0x23 == $past(in_data))
    );

    // If the register changes and last cycle was not reset, last cycle must have had a write enable (wenb LOW).
    check_change_requires_prev_write_when_no_reset: assert property (
        @(posedge clk) disable iff (reset) ($changed(reg_0x23) && !$past(reset)) |-> ($past(wenb) == 1'b0)
    );

    // If last cycle was a write and in_data equaled the old value, the register must not change.
    check_write_same_value_no_change: assert property (
        @(posedge clk) disable iff (reset) ($past(wenb) == 1'b0 && ($past(in_data) == $past(reg_0x23))) |-> (reg_0x23 == $past(reg_0x23))
    );

    // If last cycle was a write and in_data differed from the old value, the register must change.
    check_write_diff_value_changes: assert property (
        @(posedge clk) disable iff (reset) ($past(wenb) == 1'b0 && ($past(in_data) != $past(reg_0x23))) |-> (reg_0x23 != $past(reg_0x23))
    );

    // Next-state relation when neither current nor previous cycle is in reset.
    check_next_state_definition: assert property (
        @(posedge clk) (!reset && !$past(reset)) |-> (reg_0x23 == (($past(wenb) == 1'b0) ? $past(in_data) : $past(reg_0x23)))
    );

    // Reset dominates write: if reset is asserted, next value is 0 regardless of wenb.
    check_reset_dominates_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |-> (reg_0x23 == 8'h00)
    );
endmodule

verilog_code:
module pipelined_or_gate(
    input a, 
    input b,
    input clk,  // Added clk as an input
    input reset,
    output reg out
);

reg stage1_out, stage2_out;

always @(posedge clk or posedge reset) begin  // Added reset to the sensitivity list
    if(reset) begin
        stage1_out <= 1'b0;
        stage2_out <= 1'b0;
        out <= 1'b0;
    end
    else begin
        stage1_out <= a | b;
        stage2_out <= stage1_out;
        out <= stage2_out;
    end
end

endmodule

sva_code:
module pipelined_or_gate_sva (
    input logic a,
    input logic b,
    input logic clk,
    input logic reset,
    input logic out,
    input logic stage1_out,
    input logic stage2_out
);
    // Clock: clk (posedge). Reset: reset (active-high, async in RTL). Logic: sequential 3-stage pipeline (stage1_out<=a|b, stage2_out<=stage1_out, out<=stage2_out).

    // On any clock where reset is HIGH, all pipeline registers are 0.
    check_reset_clears_pipeline: assert property (
        @(posedge clk) reset |-> (stage1_out == 1'b0) && (stage2_out == 1'b0) && (out == 1'b0)
    );

    // stage1_out equals OR of inputs from previous cycle when prior cycle wasn't in reset.
    check_stage1_captures_or_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage1_out == ($past(a) | $past(b)))
    );

    // stage2_out equals prior cycle's stage1_out when prior cycle wasn't in reset.
    check_stage2_captures_stage1_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage2_out == $past(stage1_out))
    );

    // out equals prior cycle's stage2_out when prior cycle wasn't in reset.
    check_out_captures_stage2_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (out == $past(stage2_out))
    );

    // stage2_out equals OR of inputs from previous cycle when prior cycle wasn't in reset.
    check_stage2_captures_or_prev: assert property (
        @(posedge clk) disable iff (reset) !$past(reset) |-> (stage2_out == ($past(a) | $past(b)))
    );

    // out equals OR of inputs from two cycles earlier when last two cycles weren't in reset.
    check_out_two_cycle_or: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset,1) && !$past(reset,2)) |-> (out == ($past(a,2) | $past(b,2)))
    );

    // One cycle after a reset cycle, all pipeline registers are still 0 before new updates.
    check_one_cycle_after_reset_holds_zero: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (stage1_out == 1'b0) && (stage2_out == 1'b0) && (out == 1'b0)
    );
endmodule

verilog_code:
module four_bit_adder(
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] SUM,
  output COUT,
  input VPWR,
  input VGND
);

  wire [3:0] C;
  wire [3:0] S;

  assign S[0] = A[0] ^ B[0] ^ CIN;
  assign C[0] = (A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN);

  assign S[1] = A[1] ^ B[1] ^ C[0];
  assign C[1] = (A[1] & B[1]) | (A[1] & C[0]) | (B[1] & C[0]);

  assign S[2] = A[2] ^ B[2] ^ C[1];
  assign C[2] = (A[2] & B[2]) | (A[2] & C[1]) | (B[2] & C[1]);

  assign S[3] = A[3] ^ B[3] ^ C[2];
  assign COUT = (A[3] & B[3]) | (A[3] & C[2]) | (B[3] & C[2]);

  assign SUM = {S[3], S[2], S[1], S[0]};

endmodule

sva_code:
module four_bit_adder_sva (
  input logic [3:0] A,
  input logic [3:0] B,
  input logic CIN,
  input logic [3:0] SUM,
  input logic COUT,
  input logic VPWR,
  input logic VGND
);
  // No clock or reset in RTL; combinational logic; assertions use posedge $global_clock with no reset disable.
  // Key behavior: 4-bit ripple-carry addition: {COUT,SUM} == A + B + CIN; VPWR/VGND are unused.

  // SUM and COUT must equal the 5-bit addition of A, B, and CIN.
  check_addition_packed: assert property (
    @(posedge $global_clock) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + CIN)
  );

  // SUM must match the low 4 bits of A + B + CIN.
  check_sum_lowbits: assert property (
    @(posedge $global_clock) SUM == (({1'b0, A} + {1'b0, B} + CIN)[3:0])
  );

  // COUT must match the carry-out bit (bit 4) of A + B + CIN.
  check_cout_bit: assert property (
    @(posedge $global_clock) COUT == (({1'b0, A} + {1'b0, B} + CIN)[4])
  );

  // LSB sum bit equals XOR of A[0], B[0], and CIN.
  check_sum_bit0_xor: assert property (
    @(posedge $global_clock) SUM[0] == (A[0] ^ B[0] ^ CIN)
  );

  // SUM[1] equals XOR of A[1], B[1], and carry from bit 0.
  check_sum_bit1_xor_with_c0: assert property (
    @(posedge $global_clock)
      SUM[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
  );

  // Outputs remain stable if A, B, and CIN are stable (no hidden state or VPWR/VGND dependence).
  check_outputs_stable_on_stable_inputs: assert property (
    @(posedge $global_clock) ($stable(A) && $stable(B) && $stable(CIN)) |-> ($stable(SUM) && $stable(COUT))
  );

  // Adding zeros yields zero result and no carry.
  check_zero_case: assert property (
    @(posedge $global_clock) (A == 4'd0 && B == 4'd0 && CIN == 1'b0) |-> (SUM == 4'd0 && COUT == 1'b0)
  );

  // 0xF + 0xF + 1 yields SUM=0xF and COUT=1.
  check_max_plus_one: assert property (
    @(posedge $global_clock) (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (SUM == 4'hF && COUT == 1'b1)
  );

endmodule

verilog_code:
module dffre (din, rst, en, clk, q, se, si, so);

parameter SIZE = 1;

input	[SIZE-1:0]	din ;	// data in
input			en ;	// functional enable
input			rst ;	// reset
input			clk ;	// clk or scan clk

output	[SIZE-1:0]	q ;	// output

input			se ;	// scan-enable
input	[SIZE-1:0]	si ;	// scan-input
output	[SIZE-1:0]	so ;	// scan-output

reg 	[SIZE-1:0]	q ;

always @ (posedge clk)
begin
    if (se == 1'b1) // if scan-enable is high, use scan-input
        q <= si;
    else if (rst == 1'b1) // if reset is high, reset output to 0
        q <= 1'b0;
    else if (en == 1'b1) // if enable is high, use data input
        q <= din;
end

assign so = q;

endmodule

sva_code:
module dffre_sva #(
    parameter SIZE = 1
) (
    input  logic [SIZE-1:0] din, // data in
    input  logic            rst, // active-high synchronous reset
    input  logic            en,  // functional enable
    input  logic            clk, // clock
    input  logic [SIZE-1:0] q,   // output
    input  logic            se,  // scan-enable
    input  logic [SIZE-1:0] si,  // scan-input
    input  logic [SIZE-1:0] so   // scan-output
);

    // so continuously mirrors q.
    check_so_equals_q: assert property (
        @(posedge clk) so == q
    );

    // When scan-enable is high, q loads si on next cycle.
    check_scan_loads_si: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b1) |=> (q == $past(si))
    );

    // When not in scan, reset high clears q to zero on next cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (q == {SIZE{1'b0}})
    );

    // When not in scan and not in reset, en high loads din on next cycle.
    check_en_loads_din: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b0) && (en == 1'b1) && (rst == 1'b0) |=> (q == $past(din))
    );

    // When not in scan and not in reset, en low holds q.
    check_hold_without_en: assert property (
        @(posedge clk) disable iff (rst) (se == 1'b0) && (rst == 1'b0) && (en == 1'b0) |=> (q == $past(q))
    );

    // When not in scan, reset high drives so to zero on next cycle (since so=q).
    check_reset_clears_so: assert property (
        @(posedge clk) (se == 1'b0) && (rst == 1'b1) |=> (so == {SIZE{1'b0}})
    );

endmodule

