module top_module (
    input clk,
    input reset,  // Synchronous active-high reset
    input [7:0] a,
    input [7:0] b,
    output [11:0] s
);

// Multiplication module
wire [15:0] mult_out;
multiplier multiplier_inst(.a(a), .b(b), .out(mult_out));

// Addition module
wire [7:0] add_out;
adder adder_inst(.a(a), .b(b), .out(add_out));

// Output register
