module mem_encryption (
  input clk,
  input reset,
  input [31:0] data_in,
  input [31:0] key,
  output reg [31:0] data_out
);

  reg [31:0] internal_state;

  always @(posedge clk) begin
    if (reset) begin
      internal_state <= 0;
      data_out <= 0;
    end else begin
      if (key == 0) begin
        data_out <= data_in;
      end else begin
        internal_state <= data_in ^ key;
        data_out <= internal_state ^ key;
      end
    end
  end

endmodule

sva_code:
module mem_encryption_sva (
    input logic         clk,
    input logic         reset,
    input logic [31:0]  data_in,
    input logic [31:0]  key,
    input logic [31:0]  data_out,
    input logic [31:0]  internal_state
);
    // Clock: clk (posedge). Reset: reset (active-high synchronous).
    // Sequential: registers internal_state and data_out update on posedge clk.
    // Function: reset clears regs; key==0 -> data_out=data_in, hold internal_state; else -> internal_state=data_in^key, data_out=$past(internal_state)^key.

    // On reset, both internal_state and data_out are driven to 0.
    reset_clears_regs: assert property (
        @(posedge clk) reset |-> (internal_state == 32'h0) && (data_out == 32'h0)
    );

    // When key is zero, data_out passes through data_in.
    key_zero_passthrough: assert property (
        @(posedge clk) disable iff (reset) (key == 32'h0) |-> (data_out == data_in)
    );

    // When key is zero, internal_state holds its previous value.
    hold_internal_state_when_key_zero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key == 32'h0)) |-> (internal_state == $past(internal_state))
    );

    // When key is nonzero, internal_state updates to data_in ^ key in the same cycle.
    update_internal_state_when_key_nonzero: assert property (
        @(posedge clk) disable iff (reset) (key != 32'h0) |-> (internal_state == (data_in ^ key))
    );

    // When key is nonzero, data_out uses previous internal_state XOR current key.
    data_out_uses_prev_internal_state_when_key_nonzero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key != 32'h0)) |-> (data_out == ($past(internal_state) ^ key))
    );

    // First cycle after reset with nonzero key: data_out equals key (prev internal_state was 0).
    first_nonzero_key_after_reset_outputs_key: assert property (
        @(posedge clk) disable iff (reset) ($past(reset) && (key != 32'h0)) |-> (data_out == key)
    );

    // If previous cycle had nonzero key and current key is zero, internal_state equals previous data_in ^ previous key.
    internal_state_matches_prev_calc_on_key_drop_to_zero: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && (key == 32'h0) && ($past(key) != 32'h0)) |-> (internal_state == ($past(data_in) ^ $past(key)))
    );

    // With nonzero keys in two consecutive cycles, data_out equals (prev data_in ^ prev key) ^ current key.
    data_out_two_cycle_relation_when_key_nonzero_consecutive: assert property (
        @(posedge clk) disable iff (reset) (!$past(reset) && !$past(reset,2) && (key != 32'h0) && ($past(key) != 32'h0)) |-> (data_out == (($past(data_in) ^ $past(key)) ^ key))
    );

endmodule

verilog_code:
module calculator(
    input [7:0] a, b,
    input [1:0] op,
    output reg [7:0] result
);

always @(*) begin
    case(op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: result = a / b;
    endcase
end

endmodule

sva_code:
module calculator_sva (
    // DUT ports
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result,
    // Checker clock (DUT is combinational; assertions are sampled on this clock)
    input logic clk
);
    // Analysis: No clock/reset in DUT; purely combinational; result selects a+b, a-b, a*b, a/b by op.

    // For op==00, result equals a+b truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (a + b)[7:0])
    );

    // For op==01, result equals a-b truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (a - b)[7:0])
    );

    // For op==10, result equals low 8 bits of a*b.
    check_mul_operation: assert property (
        @(posedge clk) (op == 2'b10) |-> (result == (a * b)[7:0])
    );

    // For op==11 with nonzero divisor, result equals a/b.
    check_div_operation_nonzero: assert property (
        @(posedge clk) (op == 2'b11 && b != 8'd0) |-> (result == (a / b)[7:0])
    );

    // If inputs a,b,op do not change, result must not change.
    check_pure_function_stability: assert property (
        @(posedge clk) ($stable(a) && $stable(b) && $stable(op)) |-> $stable(result)
    );

    // For add: adding zero from a side yields the other operand.
    check_add_zero_a: assert property (
        @(posedge clk) (op == 2'b00 && a == 8'd0) |-> (result == b)
    );

    // For add: adding zero from b side yields the other operand.
    check_add_zero_b: assert property (
        @(posedge clk) (op == 2'b00 && b == 8'd0) |-> (result == a)
    );

    // For sub: subtracting zero yields the minuend.
    check_sub_zero: assert property (
        @(posedge clk) (op == 2'b01 && b == 8'd0) |-> (result == a)
    );

    // For sub: subtracting equal operands yields zero.
    check_sub_equal_zero: assert property (
        @(posedge clk) (op == 2'b01 && a == b) |-> (result == 8'd0)
    );

    // For mul: multiplying by zero on a side yields zero.
    check_mul_zero_a: assert property (
        @(posedge clk) (op == 2'b10 && a == 8'd0) |-> (result == 8'd0)
    );

    // For mul: multiplying by zero on b side yields zero.
    check_mul_zero_b: assert property (
        @(posedge clk) (op == 2'b10 && b == 8'd0) |-> (result == 8'd0)
    );

    // For mul: multiplying by one on a side yields the other operand.
    check_mul_one_a: assert property (
        @(posedge clk) (op == 2'b10 && a == 8'd1) |-> (result == b)
    );

    // For mul: multiplying by one on b side yields the other operand.
    check_mul_one_b: assert property (
        @(posedge clk) (op == 2'b10 && b == 8'd1) |-> (result == a)
    );

    // For div: dividing by one yields the dividend.
    check_div_one: assert property (
        @(posedge clk) (op == 2'b11 && b == 8'd1) |-> (result == a)
    );
endmodule

