assign Y[0] = (~A) & (~B) & (~C);
assign Y[1] = (~A) & (~B) & C;
assign Y[2] = (~A) & B & (~C);
assign Y[3] = (~A) & B & C;
assign Y[4] = A & (~B) & (~C);
assign Y[5] = A & (~B) & C;
