        @(posedge CLK) disable iff (1'b0) (~(A1 & A2)) |-> (Y == 1'b1)
    );

    // If B-group is not both 1, Y must be 1.
    check_B_group_zero_y_one: assert property (
        @(posedge CLK) disable iff (1'b0) (~(B1 & B2)) |-> (Y == 1'b1)
    );

    // If not all inputs are 1, Y must be 1.
    check_not_all_ones_y_one: assert property (
        @(posedge CLK) disable iff (1'b0) !(A1 & A2 & B1 & B2) |-> (Y == 1'b1)
    );
endmodule

verilog_code:
module synchronous_counter(CLK, RST, LOAD, EN, DATA_IN, DATA_OUT);

input CLK, RST, LOAD, EN;
input [3:0] DATA_IN;
output reg [3:0] DATA_OUT;

always @(posedge CLK) begin
    if (RST) begin
        DATA_OUT <= 4'b0;
    end else if (LOAD) begin
        DATA_OUT <= DATA_IN;
    end else if (EN) begin
        if (DATA_OUT == 4'b1111) begin
            DATA_OUT <= 4'b0;
        end else begin
            DATA_OUT <= DATA_OUT + 1;
        end
    end
end

endmodule

sva_code:
module synchronous_counter_sva (
    input logic CLK,
    input logic RST,
    input logic LOAD,
    input logic EN,
    input logic [3:0] DATA_IN,
    input logic [3:0] DATA_OUT
);
    // Clock: CLK (posedge). Reset: RST active-high, synchronous. Logic: sequential.
    // Behavior: RST->0; LOAD->DATA_OUT:=DATA_IN; else if EN->count with wrap; else hold.

    // On RST high at a clock, DATA_OUT becomes 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (DATA_OUT == 4'b0000)
    );

    // LOAD updates DATA_OUT with DATA_IN on the next cycle.
    load_captures_data_in: assert property (
        @(posedge CLK) disable iff (RST) LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

    // LOAD has priority over EN when both are asserted.
    load_overrides_en: assert property (
        @(posedge CLK) disable iff (RST) (LOAD && EN) |=> (DATA_OUT == $past(DATA_IN))
    );

    // With EN and not LOAD, non-max value increments by 1 on the next cycle.
    en_increments_nonmax: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT != 4'hF)) |=> (DATA_OUT == $past(DATA_OUT) + 4'd1)
    );

    // With EN and not LOAD, 4'hF wraps to 0 on the next cycle.
    en_wraps_at_max_to_zero: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD && (DATA_OUT == 4'hF)) |=> (DATA_OUT == 4'h0)
    );

    // With neither EN nor LOAD, DATA_OUT holds its previous value.
    holds_when_idle: assert property (
        @(posedge CLK) disable iff (RST) (!EN && !LOAD) |=> (DATA_OUT == $past(DATA_OUT))
    );

    // With EN and not LOAD, DATA_OUT must change (either increment or wrap).
    en_causes_change: assert property (
        @(posedge CLK) disable iff (RST) (EN && !LOAD) |=> (DATA_OUT != $past(DATA_OUT))
    );

    // When not RESET and not LOAD, the only allowed transitions are hold, +1, or wrap.
    allowed_transitions_without_load: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !LOAD) |=> (
                // hold when EN==0
                (( !$past(EN) ) && (DATA_OUT == $past(DATA_OUT))) ||
                // +1 when EN==1 and not max
                (( $past(EN) && ($past(DATA_OUT) != 4'hF) ) && (DATA_OUT == $past(DATA_OUT) + 4'd1)) ||
                // wrap to 0 when EN==1 and max
                (( $past(EN) && ($past(DATA_OUT) == 4'hF) ) && (DATA_OUT == 4'h0))
            )
    );

endmodule

verilog_code:
module mux_encoder (
    input [15:0] in,
    input [3:0] sel,
    input [7:0] D,
    output [7:0] out,
    output [2:0] EN
);

    // 16-to-1 multiplexer
    wire [15:0] mux_out;
    assign mux_out = sel[3] ? in[15:8] : in[7:0];

    assign out = sel[2] ? mux_out[15:8] : mux_out[7:0];

    // 8-bit priority encoder
    wire [2:0] priority_out;
    assign priority_out = D[7] ? 3 : D[6] ? 2 : D[5] ? 1 : D[4] ? 0 : D[3] ? 3 : D[2] ? 2 : D[1] ? 1 : D[0] ? 0 : 3;

    assign EN = priority_out;

    // Bitwise OR module
    wire [7:0] or_out;
    assign or_out = mux_out[7:0] | priority_out;

endmodule

sva_code:
module mux_encoder_sva (
    input logic clk,
    input logic [15:0] in,
    input logic [3:0] sel,
    input logic [7:0] D,
    input logic [7:0] out,
    input logic [2:0] EN
);
    ///// Mux output rules /////
    // When sel[2]==1, out must be zero.
    check_out_zero_when_sel2: assert property (
        @(posedge clk) sel[2] |-> (out == 8'h00)
    );

    // When sel[2]==0 and sel[3]==1, out selects in[15:8].
    check_out_upper_when_sel3_and_sel2low: assert property (
        @(posedge clk) (!sel[2] && sel[3]) |-> (out == in[15+:8])
    );

    // When sel[2]==0 and sel[3]==0, out selects in[7:0].
    check_out_lower_when_sel3low_and_sel2low: assert property (
        @(posedge clk) (!sel[2] && !sel[3]) |-> (out == in[7:0])
    );

    // Out depends only on in and sel (stable in/sel implies stable out).
    check_out_function_of_in_sel_only: assert property (
        @(posedge clk) ($stable(in) && $stable(sel)) |-> (out == $past(out))
    );

    ///// Priority encoder rules (EN) /////
    // EN must equal the ternary priority chain defined on D.
    check_en_priority_chain: assert property (
        @(posedge clk)
        EN == ( D[7] ? 3'd3 :
                D[6] ? 3'd2 :
                D[5] ? 3'd1 :
                D[4] ? 3'd0 :
                D[3] ? 3'd3 :
                D[2] ? 3'd2 :
                D[1] ? 3'd1 :
                D[0] ? 3'd0 : 3'd3 )
    );

    // EN depends only on D (stable D implies stable EN).
    check_en_function_of_D_only: assert property (
        @(posedge clk) $stable(D) |-> (EN == $past(EN))
    );

    // If D[7] is set, EN must be 3 regardless of other bits.
    check_en_when_D7: assert property (
        @(posedge clk) D[7] |-> (EN == 3'd3)
    );

    // If only D[6] is the highest set bit, EN must be 2.
    check_en_when_D6_and_no_higher: assert property (
        @(posedge clk) (!D[7] && D[6]) |-> (EN == 3'd2)
    );

    // If only D[3] is the highest set bit, EN must be 3.
    check_en_when_D3_and_no_higher: assert property (
        @(posedge clk) (!D[7] && !D[6] && !D[5] && !D[4] && D[3]) |-> (EN == 3'd3)
    );

    // If all D bits are zero, EN must be 3 (default case).
    check_en_default_when_D_zero: assert property (
        @(posedge clk) (D == 8'h00) |-> (EN == 3'd3)
    );
endmodule

