module flip_flop(input D, SCD, SCE, RESET_B, VPWR, VGND, VPB, VNB, output Q, input CLK);

    // Instantiate the DFF module
    DFF dff(D, SCD, SCE, RESET_B, Q, CLK);

endmodule

module DFF(input D, SCD, SCE, RESET_B, output Q, input CLK);

    reg q;

    always @(posedge CLK or negedge RESET_B)
    begin
        if (!RESET_B)
            q <= 1'b0;
        else if (SCE)
            q <= D;
    end

    assign Q = q;

endmodule

sva_code:
module flip_flop_sva (
    input  logic D,
    input  logic SCD,
    input  logic SCE,
    input  logic RESET_B,  // Active-low async reset
    input  logic VPWR,
    input  logic VGND,
    input  logic VPB,
    input  logic VNB,
    input  logic Q,
    input  logic CLK
);
    // Reset low forces Q to 0 at every clock.
    reset_low_forces_zero: assert property (
        @(posedge CLK) (!RESET_B) |-> (Q == 1'b0)
    );

    // A falling edge on RESET_B clears Q to 0 by the next clock sample.
    reset_fall_clears_Q: assert property (
        @(posedge CLK) $fell(RESET_B) |-> (Q == 1'b0)
    );

    // With SCE HIGH, Q captures D on the next clock.
    capture_on_sce_high: assert property (
        @(posedge CLK) disable iff (!RESET_B) SCE |=> (Q == $past(D))
    );

    // With SCE LOW, Q holds its previous value.
    hold_on_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) !SCE |=> (Q == $past(Q))
    );

    // If SCE HIGH and D equals previous Q, Q does not change next cycle.
    sce_high_same_data_no_change: assert property (
        @(posedge CLK) disable iff (!RESET_B) (SCE && (D == $past(Q))) |=> (Q == $past(Q))
    );

    // If SCE HIGH and D differs from previous Q, Q must change next cycle.
    sce_high_diff_data_changes_q: assert property (
        @(posedge CLK) disable iff (!RESET_B) (SCE && (D != $past(Q))) |=> $changed(Q)
    );

    // Any Q change without a RESET_B fall implies prior SCE was HIGH.
    q_change_requires_sce_no_reset_edge: assert property (
        @(posedge CLK) disable iff (!RESET_B) ($changed(Q) && !$fell(RESET_B)) |-> $past(SCE)
    );

    // When SCE is LOW, SCD activity does not affect Q on the next clock.
    scd_change_no_effect_when_sce_low: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!SCE && $changed(SCD)) |=> (Q == $past(Q))
    );

    // Next-state equation when no reset fall occurred in the interval.
    next_state_equation_without_reset_edge: assert property (
        @(posedge CLK) disable iff (!RESET_B) (!$fell(RESET_B)) |-> (Q == ($past(SCE) ? $past(D) : $past(Q)))
    );

    // After reset deasserts and with SCE LOW, Q remains 0 on the next clock.
    post_reset_release_no_load_holds_zero: assert property (
        @(posedge CLK) ($rose(RESET_B) && !SCE) |=> (Q == 1'b0)
    );
endmodule

module mux_3to1_enable_sva (
    input logic [3:0] a,
    input logic [3:0] b,
    input logic [3:0] c,
    input logic       en,
    input logic [1:0] sel,
    input logic [3:0] out
);

    // Out matches the RTL's effective function (r folded into selection).
    check_function_equivalence: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        out == (en ? (sel[1] ? a : (sel[0] ? b : 4'b0)) : 4'b0)
    );

    // When disabled, output must be 0.
    check_out_zero_when_disabled: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (!en) |-> (out == 4'b0)
    );

    // When enabled and sel[1]=1, output selects a.
    check_select_a_when_sel1: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && sel[1]) |-> (out == a)
    );

    // When enabled and sel[1]=0, sel[0]=1, output selects b.
    check_select_b_when_sel0_only: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && !sel[1] && sel[0]) |-> (out == b)
    );

    // When enabled and sel==2'b00, output is 0.
    check_zero_when_enabled_sel00: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && !sel[1] && !sel[0]) |-> (out == 4'b0)
    );

    // When enabled and both sel bits are 1, a has priority over b.
    check_a_priority_when_both_sel_high: assert property (
        @(posedge en or posedge sel[0] or posedge sel[1] or
          posedge a[0] or posedge a[1] or posedge a[2] or posedge a[3] or
          posedge b[0] or posedge b[1] or posedge b[2] or posedge b[3] or
          posedge c[0] or posedge c[1] or posedge c[2] or posedge c[3] or
          posedge out[0] or posedge out[1] or posedge out[2] or posedge out[3])
        (en && sel[1] && sel[0]) |-> (out == a)
    );

endmodule

verilog_code:
module karnaugh_map(
  input wire A, B, C,
  output reg F
);

  always @*
  begin
    case ({A,B,C})
      3'b000: F = 0;
      3'b001: F = 1;
      3'b010: F = 0;
      3'b011: F = 1;
      3'b100: F = 0;
      3'b101: F = 1;
      3'b110: F = 1;
      3'b111: F = 0;
    endcase
  end

endmodule

sva_code:
module karnaugh_map_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic F
);
    // F must be 0 when A,B,C = 000.
    check_map_000: assert property (
        @(posedge CLK) ({A,B,C} === 3'b000) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 001.
    check_map_001: assert property (
        @(posedge CLK) ({A,B,C} === 3'b001) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 010.
    check_map_010: assert property (
        @(posedge CLK) ({A,B,C} === 3'b010) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 011.
    check_map_011: assert property (
        @(posedge CLK) ({A,B,C} === 3'b011) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 100.
    check_map_100: assert property (
        @(posedge CLK) ({A,B,C} === 3'b100) |-> (F == 1'b0)
    );

    // F must be 1 when A,B,C = 101.
    check_map_101: assert property (
        @(posedge CLK) ({A,B,C} === 3'b101) |-> (F == 1'b1)
    );

    // F must be 1 when A,B,C = 110.
    check_map_110: assert property (
        @(posedge CLK) ({A,B,C} === 3'b110) |-> (F == 1'b1)
    );

    // F must be 0 when A,B,C = 111.
    check_map_111: assert property (
        @(posedge CLK) ({A,B,C} === 3'b111) |-> (F == 1'b0)
    );

    // F equals C XOR (A AND B) for all known inputs.
    check_function_equivalence: assert property (
        @(posedge CLK) !($isunknown({A,B,C})) |-> (F == (C ^ (A & B)))
    );
endmodule

verilog_code:
module de_PLL (
    areset,
    inclk0,
    c0
);

    input areset;
    input inclk0;
    output c0;

    // Phase detector
    wire phase_error;
    reg phase_error_d1;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            phase_error_d1 <= 0;
        end else begin
            phase_error_d1 <= phase_error;
        end
    end

    assign phase_error = (c0 & ~inclk0) | (~c0 & inclk0);

    // Charge pump
    reg [7:0] charge_pump_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            charge_pump_out <= 0;
        end else begin
            charge_pump_out <= (phase_error & (charge_pump_out < 8'h7f)) ? charge_pump_out + 1 : 
                               (~phase_error & (charge_pump_out > 8'h80)) ? charge_pump_out - 1 : charge_pump_out;
        end
    end

    // Loop filter
    reg [15:0] loop_filter_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            loop_filter_out <= 16'h0000;
        end else begin
            loop_filter_out <= loop_filter_out + charge_pump_out;
        end
    end

    // Voltage-controlled oscillator (VCO)
    reg [31:0] vco_out;
    always @(posedge inclk0 or negedge areset) begin
        if (~areset) begin
            vco_out <= 32'h00000000;
        end else begin
            vco_out <= vco_out + loop_filter_out;
        end
    end

    // Divide-by-2
    reg [31:0] div_by_2_out;
    always @(posedge vco_out[31] or negedge areset) begin
        if (~areset) begin
            div_by_2_out <= 32'h00000000;
        end else begin
            div_by_2_out <= {vco_out[30:0], ~vco_out[31]};
        end
    end

    // Output clock signal
    assign c0 = div_by_2_out[31];

endmodule

sva_code:
module de_PLL_sva (
    input logic areset,
    input logic inclk0,
    input logic c0,

    // Internal signals from RTL (bind/connect hierarchically)
    input logic        phase_error,
    input logic        phase_error_d1,
    input logic [7:0]  charge_pump_out,
    input logic [15:0] loop_filter_out,
    input logic [31:0] vco_out,
    input logic [31:0] div_by_2_out
);

    ///// Reset behavior /////
    // During reset, c0 must be LOW.
    reset_c0_low: assert property (
        @(posedge inclk0) (!areset) |-> (c0 == 1'b0)
    );
    // During reset, phase_error_d1 must be 0.
    reset_phase_error_d1_zero: assert property (
        @(posedge inclk0) (!areset) |-> (phase_error_d1 == 1'b0)
    );
    // During reset, charge_pump_out must be 0.
    reset_charge_pump_zero: assert property (
        @(posedge inclk0) (!areset) |-> (charge_pump_out == 8'h00)
    );
    // During reset, loop_filter_out must be 0.
    reset_loop_filter_zero: assert property (
        @(posedge inclk0) (!areset) |-> (loop_filter_out == 16'h0000)
    );
    // During reset, vco_out must be 0.
    reset_vco_zero: assert property (
        @(posedge inclk0) (!areset) |-> (vco_out == 32'h00000000)
    );
    // During reset, div_by_2_out must be 0.
    reset_div2_zero: assert property (
        @(posedge inclk0) (!areset) |-> (div_by_2_out == 32'h00000000)
    );

    ///// Phase detector /////
    // phase_error is combinational: (c0 & ~inclk0) | (~c0 & inclk0).
    comb_phase_error_def: assert property (
        @(posedge inclk0) disable iff (!areset) phase_error == ((c0 & ~inclk0) | (~c0 & inclk0))
    );
    // phase_error_d1 is one-cycle delayed sample of phase_error.
    pipe_phase_error_d1: assert property (
        @(posedge inclk0) disable iff (!areset) $past(areset) |-> (phase_error_d1 == $past(phase_error))
    );

    ///// Charge pump /////
    // charge_pump_out next-state matches saturating up/down rules.
    cp_nextstate_match: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> charge_pump_out ==
                ((phase_error && ($past(charge_pump_out) < 8'h7F)) ? ($past(charge_pump_out) + 8'd1) :
                 ((!phase_error && ($past(charge_pump_out) > 8'h80)) ? ($past(charge_pump_out) - 8'd1) :
                  $past(charge_pump_out)))
    );
    // charge_pump_out step size is at most +/-1 per cycle.
    cp_step_bound: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (
                (charge_pump_out == $past(charge_pump_out)) ||
                (charge_pump_out == ($past(charge_pump_out) + 8'd1)) ||
                (charge_pump_out == ($past(charge_pump_out) - 8'd1))
            )
    );

    ///// Loop filter /////
    // loop_filter_out accumulates previous charge_pump_out.
    lf_accumulate: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (loop_filter_out == ($past(loop_filter_out) + $past(charge_pump_out)))
    );

    ///// VCO /////
    // vco_out accumulates previous loop_filter_out.
    vco_accumulate: assert property (
        @(posedge inclk0) disable iff (!areset)
            $past(areset) |-> (vco_out == ($past(vco_out) + $past(loop_filter_out)))
    );

    ///// Divide-by-2 and output /////
    // c0 is the MSB of div_by_2_out.
    c0_matches_div2_msb: assert property (
        @(posedge inclk0) disable iff (!areset) (c0 == div_by_2_out[31])
    );

endmodule

module Sprite_Controller_sva #(
    parameter int SizeX = 32,
    parameter int SizeY = 32
)(
    input logic [9:0] iColumnCount,
    input logic [9:0] iRowCount,
    input logic       imask,
    input logic       iEnable,
    input logic [9:0] iPosX,
    input logic [9:0] iPosY,
    input logic [2:0] iColorSprite,
    input logic [2:0] iColorBack,
    input logic [2:0] oRGB
);

    // No clock/reset in RTL; combinational logic. Sample assertions on posedge of iEnable.

    // When inside box with enable/mask high, drive sprite color.
    sprite_when_inside_and_enabled: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount <= (SizeX + iPosX)) && (iColumnCount >= iPosX) &&
        (iRowCount    <= (SizeY + iPosY)) && (iRowCount    >= iPosY)
        |-> (oRGB == iColorSprite)
    );

    // If mask is low, drive background color.
    background_when_mask_low: assert property (
        @(posedge iEnable)
        (imask == 1'b0) |-> (oRGB == iColorBack)
    );

    // If enable is low, drive background color.
    background_when_enable_low: assert property (
        @(posedge iEnable)
        (iEnable == 1'b0) |-> (oRGB == iColorBack)
    );

    // If column is left of sprite region, drive background color.
    background_when_left_of_box: assert property (
        @(posedge iEnable)
        (iColumnCount < iPosX) |-> (oRGB == iColorBack)
    );

    // If row is above sprite region, drive background color.
    background_when_above_box: assert property (
        @(posedge iEnable)
        (iRowCount < iPosY) |-> (oRGB == iColorBack)
    );

    // If column is right of sprite region, drive background color.
    background_when_right_of_box: assert property (
        @(posedge iEnable)
        (iColumnCount > (SizeX + iPosX)) |-> (oRGB == iColorBack)
    );

    // If row is below sprite region, drive background color.
    background_when_below_box: assert property (
        @(posedge iEnable)
        (iRowCount > (SizeY + iPosY)) |-> (oRGB == iColorBack)
    );

    // Output is always either sprite color or background color.
    output_is_sprite_or_background_only: assert property (
        @(posedge iEnable)
        (oRGB == iColorSprite) || (oRGB == iColorBack)
    );

    // Left edge inclusive: at left boundary with other coords in range and enables high, sprite color.
    sprite_on_left_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == iPosX) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount <= (SizeX + iPosX))
        |-> (oRGB == iColorSprite)
    );

    // Right edge inclusive: at right boundary with other coords in range and enables high, sprite color.
    sprite_on_right_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iColumnCount == (SizeX + iPosX)) &&
        (iRowCount    >= iPosY) && (iRowCount <= (SizeY + iPosY)) &&
        (iColumnCount >= iPosX)
        |-> (oRGB == iColorSprite)
    );

    // Top edge inclusive: at top boundary with other coords in range and enables high, sprite color.
    sprite_on_top_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == iPosY) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   <= (SizeY + iPosY))
        |-> (oRGB == iColorSprite)
    );

    // Bottom edge inclusive: at bottom boundary with other coords in range and enables high, sprite color.
    sprite_on_bottom_edge: assert property (
        @(posedge iEnable)
        (imask == 1'b1) && (iEnable == 1'b1) &&
        (iRowCount == (SizeY + iPosY)) &&
        (iColumnCount >= iPosX) && (iColumnCount <= (SizeX + iPosX)) &&
        (iRowCount   >= iPosY)
        |-> (oRGB == iColorSprite)
    );

endmodule

