    check_a_one_implies_x_one: assert property (
        @(posedge clk) (A === 1'b1) |-> (X === 1'b1)
    );

    // B=1 drives X=1.
    check_b_one_implies_x_one: assert property (
        @(posedge clk) (B === 1'b1) |-> (X === 1'b1)
    );

    // C=1 drives X=1.
    check_c_one_implies_x_one: assert property (
        @(posedge clk) (C === 1'b1) |-> (X === 1'b1)
