        @(posedge clk) (X === 1'b1) |-> (A === 1'b1 || B === 1'b1 || C === 1'b1 || D === 1'b1)
    );

    // If inputs are stable across a cycle, X is stable.
    check_stable_when_inputs_stable: assert property (
        @(posedge clk) $stable({A,B,C,D}) |-> $stable(X)
    );

endmodule

module mux4_sva (
