    // When !is_cx and cond==1110, jmp equals zf | (sf ^ of).
    check_no_cx_cond_1110: assert property (
        @(posedge $global_clock) (!is_cx && (cond == 4'b1110)) |=> (jmp == (zf | (sf ^ of)))
