module shift_register (
    input clk,
    input reset,
    input [7:0] data_in,
    input [1:0] shift_direction,
    input load,
    output reg [7:0] q
);

always @(posedge clk or negedge reset) begin
    if (!reset) begin
        q <= 8'd0;
    end else if (load) begin
        q <= data_in;
    end else begin
        if (shift_direction == 2'b00) begin
            q <= {q[6:0], q[7]};
        end else if (shift_direction == 2'b01) begin
            q <= {q[0], q[7:1]};
        end
    end
end

endmodule

