    check_B1n_high_forces_Y_zero: assert property (
        @(posedge CLK) disable iff (1'b0)
            (B1_N == 1'b1) |-> (Y == 1'b0)
    );

    // With B1_N=0 and A1=1, Y=1.
    check_B1n_low_A1_high_Y_one: assert property (
        @(posedge CLK) disable iff (1'b0)
            ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (Y == 1'b1)
