module mux_4_1_using_2_1_sva (
    // Sampling clock for assertions (RTL has no clock/reset)
    input logic CLK,

    // DUT ports
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y,

    // Internal RTL nets (present in mux_4_1_using_2_1)
    input logic m1_out,
    input logic m2_out
);
    // No clock or reset in RTL; purely combinational 4:1 mux built from 2:1 muxes.
    // Assertions sampled on CLK; no reset used in disable iff.

    // Y equals A when S1=0 and S0=0.
    select_00_y_eq_a: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1 && !S0) |-> (Y == A)
    );

    // Y equals B when S1=0 and S0=1.
    select_01_y_eq_b: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1 && S0) |-> (Y == B)
    );

    // Y equals C when S1=1 and S0=0.
    select_10_y_eq_c: assert property (
        @(posedge CLK) disable iff (1'b0) (S1 && !S0) |-> (Y == C)
    );

    // Y equals D when S1=1 and S0=1.
    select_11_y_eq_d: assert property (
        @(posedge CLK) disable iff (1'b0) (S1 && S0) |-> (Y == D)
    );

    // Y matches the full nested ternary of a 4:1 mux.
    y_matches_function: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == (S1 ? (S0 ? D : C) : (S0 ? B : A)))
    );

    // When S1=0, output selects m1_out.
    y_follows_m1_when_s1_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!S1) |-> (Y == m1_out)
    );

    // When S1=1, output selects m2_out.
    y_follows_m2_when_s1_high: assert property (
        @(posedge CLK) disable iff (1'b0) (S1) |-> (Y == m2_out)
    );

    // When S0=0, m1_out=A and m2_out=C.
    m1_m2_selects_when_s0_low: assert property (
        @(posedge CLK) disable iff (1'b0) (!S0) |-> ((m1_out == A) && (m2_out == C))
    );

    // When S0=1, m1_out=B and m2_out=D.
    m1_m2_selects_when_s0_high: assert property (
        @(posedge CLK) disable iff (1'b0) (S0) |-> ((m1_out == B) && (m2_out == D))
    );
endmodule

verilog_code:
module signal_modifier(
    input [15:0] in,
    input [1:0] ctrl,
    output [15:0] out
);

reg [15:0] temp;

always @*
begin
    case (ctrl)
        2'b00: temp = in;
        2'b01: temp = ~in;
        2'b10: temp = {in[13:0], 2'b00};
        2'b11: temp = {2'b00, in[15:2]};
    endcase
end

assign out = temp;

endmodule

sva_code:
module signal_modifier_sva (
    input  logic        CLK,   // verification clock (DUT has no clock/reset)
    input  logic [15:0] in,
    input  logic [1:0]  ctrl,
    input  logic [15:0] out
);

    ///// Functional correctness /////
    // When ctrl==00, out equals in.
    check_ctrl_00_passthrough: assert property (
        @(posedge CLK) (ctrl == 2'b00) |-> (out == in)
    );

    // When ctrl==01, out equals bitwise NOT of in.
    check_ctrl_01_invert: assert property (
        @(posedge CLK) (ctrl == 2'b01) |-> (out == ~in)
    );

    // When ctrl==10, out equals in shifted left by 2 with zeros in LSBs.
    check_ctrl_10_shift_left2: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out == {in[13:0], 2'b00})
    );

    // When ctrl==11, out equals in shifted right by 2 with zeros in MSBs.
    check_ctrl_11_shift_right2: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out == {2'b00, in[15:2]})
    );

    // Out matches the selected transformation for all ctrl values.
    check_functional_mapping: assert property (
        @(posedge CLK)
            out ==
                ((ctrl == 2'b00) ? in :
                 (ctrl == 2'b01) ? ~in :
                 (ctrl == 2'b10) ? {in[13:0], 2'b00} :
                                   {2'b00, in[15:2]})
    );

    ///// Bit-level implications /////
    // For shift-left (10), LSBs of out are zero.
    check_shift_left2_lsb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out[1:0] == 2'b00)
    );

    // For shift-right (11), MSBs of out are zero.
    check_shift_right2_msb_zero: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out[15:14] == 2'b00)
    );

    // For shift-left (10), out[15:2] equals in[13:0].
    check_shift_left2_upper_bits: assert property (
        @(posedge CLK) (ctrl == 2'b10) |-> (out[15:2] == in[13:0])
    );

    // For shift-right (11), out[13:0] equals in[15:2].
    check_shift_right2_lower_bits: assert property (
        @(posedge CLK) (ctrl == 2'b11) |-> (out[13:0] == in[15:2])
    );

    ///// Stability /////
    // If in and ctrl are stable across a cycle, out must be stable.
    check_stability: assert property (
        @(posedge CLK) $stable({in, ctrl}) |-> $stable(out)
    );

endmodule

module add_sub_sva (
  input logic clk,
  input logic reset,
  input logic operation,
  input logic [3:0] A,
  input logic [3:0] B,
  input logic [3:0] result
);

  // While reset is LOW, result must be zero.
  reset_level_forces_zero: assert property (
    @(posedge clk) (reset == 1'b0) |-> (result == 4'b0000)
  );

  // On the first clock after reset deasserts (LOW->HIGH), result is still zero.
  first_clk_after_reset_release_zero: assert property (
    @(posedge clk) (reset == 1'b1) && ($past(reset) == 1'b0) |-> (result == 4'b0000)
  );

  // With op=0, next result is (A+B) LSBs from the previous cycle.
  update_sum_when_op0: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b0)
      |-> (result == (($past(A) + $past(B)) & 4'hF))
  );

  // With op=1, next result is (A-B) LSBs from the previous cycle.
  update_diff_when_op1: assert property (
    @(posedge clk) disable iff (!reset)
      $past(reset) && ($past(operation) == 1'b1)
      |-> (result == (($past(A) - $past(B)) & 4'hF))
  );

endmodule

verilog_code:
module check_10us (
  input start,
  input stop,
  input clk,
  output reg [31:0] elapsed_time
);

  reg [31:0] counter = 0;
  reg counting = 0;

  always @(posedge clk) begin
    if (start) begin
      counter <= 0;
      counting <= 1;
    end else if (stop) begin
      counting <= 0;
      elapsed_time <= counter;
    end else if (counting) begin
      counter <= counter + 1;
    end
  end

endmodule

sva_code:
module check_10us_sva (
    input logic clk,
    input logic start,
    input logic stop,
    input logic [31:0] elapsed_time,
    input logic [31:0] counter,     // internal reg from DUT
    input logic counting            // internal reg from DUT
);
    // Start sets counter to 0 on the next cycle.
    start_clears_counter: assert property (
        @(posedge clk) start |=> (counter == 32'd0)
    );

    // Start sets counting to 1 on the next cycle.
    start_sets_counting: assert property (
        @(posedge clk) start |=> (counting == 1'b1)
    );

    // Start does not update elapsed_time.
    start_does_not_update_elapsed: assert property (
        @(posedge clk) start |=> (elapsed_time == $past(elapsed_time))
    );

    // Stop (when start is low) clears counting on the next cycle.
    stop_clears_counting: assert property (
        @(posedge clk) (!start && stop) |=> (counting == 1'b0)
    );

    // Stop (when start is low) captures current counter into elapsed_time.
    stop_captures_counter: assert property (
        @(posedge clk) (!start && stop) |=> (elapsed_time == $past(counter))
    );

    // Stop (when start is low) does not change counter.
    stop_does_not_update_counter: assert property (
        @(posedge clk) (!start && stop) |=> (counter == $past(counter))
    );

    // While counting (and no start/stop), counter increments by 1.
    increment_while_counting: assert property (
        @(posedge clk) (counting && !start && !stop) |=> (counter == $past(counter) + 32'd1)
    );

    // While counting (and no start/stop), counting remains asserted.
    counting_sticky_high: assert property (
        @(posedge clk) (counting && !start && !stop) |=> (counting == 1'b1)
    );

    // When idle (no start/stop and not counting), all state holds.
    idle_state_stable: assert property (
        @(posedge clk) (!counting && !start && !stop) |=> ($stable(counter) && $stable(counting) && $stable(elapsed_time))
    );

    // If start and stop are both high, start takes priority: reset counter, set counting, keep elapsed_time.
    start_priority_over_stop: assert property (
        @(posedge clk) (start && stop) |=> (counter == 32'd0) && (counting == 1'b1) && (elapsed_time == $past(elapsed_time))
    );
endmodule

verilog_code:
module hazard(
	input [2:0] reg_read_adr1_d,
	input [2:0] reg_read_adr2_d,
	input [2:0] reg_read_adr1_e,
	input [2:0] reg_read_adr2_e,
	input [2:0] reg_write_adr_e,
	input mem_to_reg_e,
	input reg_write_m,
	input [2:0] reg_write_adr_m,
	input reg_write_w,
	input [2:0] reg_write_adr_w,

	input PC_source,

	output reg stall_f,
	output reg stall_d,
	output reg flush_d,
	output reg  flush_e,

	output reg  [1:0] forward1_e,
	output reg  [1:0] forward2_e
	);

	always @(*) begin
		if ((reg_write_adr_m == reg_read_adr1_e) && reg_write_m)
			forward1_e = 2'h1;
		else if ((reg_write_adr_w == reg_read_adr1_e) && reg_write_w) 
			forward1_e = 2'h2;
		else
			forward1_e = 2'h0;

		if ((reg_write_adr_m == reg_read_adr2_e) && reg_write_m)
			forward2_e = 2'h1;
		else if ((reg_write_adr_w == reg_read_adr2_e) && reg_write_w)
			forward2_e = 2'h2;
		else
			forward2_e = 2'h0;	
	end

	reg stallCompare;

	always @(*) begin
		if ((reg_write_adr_e == reg_read_adr1_d) || (reg_write_adr_e == reg_read_adr2_d))
			stallCompare <= 1;
		else
			stallCompare <= 0;

		stall_f <= stallCompare && mem_to_reg_e;
		stall_d <= stallCompare && mem_to_reg_e;
		flush_e <= stallCompare && mem_to_reg_e;

		flush_d <= PC_source;
	end
endmodule

sva_code:
module hazard_sva (
    input logic CLK,

    input logic [2:0] reg_read_adr1_d,
    input logic [2:0] reg_read_adr2_d,
    input logic [2:0] reg_read_adr1_e,
    input logic [2:0] reg_read_adr2_e,
    input logic [2:0] reg_write_adr_e,
    input logic mem_to_reg_e,
    input logic reg_write_m,
    input logic [2:0] reg_write_adr_m,
    input logic reg_write_w,
    input logic [2:0] reg_write_adr_w,
    input logic PC_source,

    input logic stall_f,
    input logic stall_d,
    input logic flush_d,
    input logic flush_e,

    input logic [1:0] forward1_e,
    input logic [1:0] forward2_e
);
    // Forward1: M stage has priority when address matches
    fwd1_from_m_when_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) |-> (forward1_e == 2'h1)
    );

    // Forward1: W stage selected only if M does not match and W matches
    fwd1_from_w_when_no_m_but_w_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) &&
          (reg_write_w && (reg_write_adr_w == reg_read_adr1_e))) |-> (forward1_e == 2'h2)
    );

    // Forward1: No match in M or W yields no forwarding
    fwd1_none_when_no_matches: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr1_e)) &&
         ! (reg_write_w && (reg_write_adr_w == reg_read_adr1_e))) |-> (forward1_e == 2'h0)
    );

    // Forward1: Encoding is limited to 0/1/2
    fwd1_encoding_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (forward1_e != 2'h3)
    );

    // Forward2: M stage has priority when address matches
    fwd2_from_m_when_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) |-> (forward2_e == 2'h1)
    );

    // Forward2: W stage selected only if M does not match and W matches
    fwd2_from_w_when_no_m_but_w_match: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) &&
          (reg_write_w && (reg_write_adr_w == reg_read_adr2_e))) |-> (forward2_e == 2'h2)
    );

    // Forward2: No match in M or W yields no forwarding
    fwd2_none_when_no_matches: assert property (
        @(posedge CLK) disable iff (1'b0)
        (! (reg_write_m && (reg_write_adr_m == reg_read_adr2_e)) &&
         ! (reg_write_w && (reg_write_adr_w == reg_read_adr2_e))) |-> (forward2_e == 2'h0)
    );

    // Forward2: Encoding is limited to 0/1/2
    fwd2_encoding_valid: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (forward2_e != 2'h3)
    );

    // Stalls: stall_f equals stall_d
    stalls_equal: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (stall_f == stall_d)
    );

    // Stalls: stall_d equals flush_e
    stall_equals_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (stall_d == flush_e)
    );

    // Flush D: flush_d mirrors PC_source
    flush_d_equals_PC_source: assert property (
        @(posedge CLK) disable iff (1'b0)
        1'b1 |-> (flush_d == PC_source)
    );

    // No hazard on D sources -> no stall/flush_e regardless of mem_to_reg_e
    no_hazard_results_no_stall_or_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!((reg_write_adr_e == reg_read_adr1_d) || (reg_write_adr_e == reg_read_adr2_d))) |-> 
            (stall_f == 1'b0 && stall_d == 1'b0 && flush_e == 1'b0)
    );

    // Hazard on D sources with mem_to_reg_e -> assert stall_f/stall_d/flush_e
    hazard_and_memtoreg_cause_stall_and_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (mem_to_reg_e && ((reg_write_adr_e == reg_read_adr1_d) || (reg_write_adr_e == reg_read_adr2_d))) |-> 
            (stall_f == 1'b1 && stall_d == 1'b1 && flush_e == 1'b1)
    );

    // If mem_to_reg_e is 0 then stall_f/stall_d/flush_e must be 0
    memtoreg_low_clears_stall_and_flush_e: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!mem_to_reg_e) |-> (stall_f == 1'b0 && stall_d == 1'b0 && flush_e == 1'b0)
    );
endmodule

