module mux4to1(data0, data1, data2, data3, selectinput, out);

input [15:0] data0, data1, data2, data3;
input [1:0] selectinput;
output [15:0] out;

wire [15:0] mux0, mux1;

assign mux0 = (selectinput[0] == 0) ? data0 : data1;
assign mux1 = (selectinput[0] == 0) ? data2 : data3;

// Implementing the final 4-to-1 MUX using the outputs of the two 2-to-1 MUXes
assign out = (selectinput[1] == 0) ? mux0 : mux1;

endmodule

sva_code:
module mux4to1_sva (
    // DUT ports
    input logic [15:0] data0,
    input logic [15:0] data1,
    input logic [15:0] data2,
    input logic [15:0] data3,
    input logic [1:0]  selectinput,
    input logic [15:0] out,
    // External sampling clock for SVA (DUT has no clock/reset)
    input logic clk
);
    // Notes: DUT is pure combinational 4:1 MUX; no reset present. Assertions are sampled on external clk.

    // When select == 2'b00, out must equal data0.
    check_sel00_out_data0: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b00) |-> (out == data0)
    );

    // When select == 2'b01, out must equal data1.
    check_sel01_out_data1: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b01) |-> (out == data1)
    );

    // When select == 2'b10, out must equal data2.
    check_sel10_out_data2: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b10) |-> (out == data2)
    );

    // When select == 2'b11, out must equal data3.
    check_sel11_out_data3: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput === 2'b11) |-> (out == data3)
    );

    // With select[1]==0, out equals 2:1 mux of data0/data1 selected by select[0].
    check_lower_branch_mux: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput[1] === 1'b0) |-> (out == ((selectinput[0] == 1'b0) ? data0 : data1))
    );

    // With select[1]==1, out equals 2:1 mux of data2/data3 selected by select[0].
    check_upper_branch_mux: assert property (
        @(posedge clk) disable iff (1'b0) (selectinput[1] === 1'b1) |-> (out == ((selectinput[0] == 1'b0) ? data2 : data3))
    );

    // Out equals the exact nested conditional structure implemented in RTL.
    check_full_mux_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            out == ((selectinput[1] == 1'b0)
                      ? ((selectinput[0] == 1'b0) ? data0 : data1)
                      : ((selectinput[0] == 1'b0) ? data2 : data3))
    );

endmodule

verilog_code:
module SNPS_CLOCK_GATE_HIGH_ShiftRegister_W7_54 ( CLK, EN, ENCLK, TE );
  input CLK, EN, TE;
  output ENCLK;

  reg [6:0] shift_reg;
  wire [6:0] shifted_reg;
  wire latch_ECK;

  TLATNTSCAX2TS latch ( .E(EN & ENCLK), .SE(shift_reg[6]), .CK(CLK), .ECK(latch_ECK) );

  always @(posedge CLK) begin
    if (EN & ENCLK) begin
      shift_reg <= {shift_reg[5:0], TE};
    end
  end

  assign shifted_reg = {shift_reg[5:0], shift_reg[6]};
  assign ENCLK = latch_ECK;
endmodule
module TLATNTSCAX2TS (E, SE, CK, ECK);
  input E, SE, CK;
  output ECK;

  reg Q;

  always @(posedge CK) begin
    if (E) begin
      Q <= SE;
    end
  end

  assign ECK = Q;
endmodule

sva_code:
module SNPS_CLOCK_GATE_HIGH_ShiftRegister_W7_54_sva (
    input logic CLK,
    input logic EN,
    input logic ENCLK,
    input logic TE
);
    // Clock: CLK; no reset signal present in RTL.
    // Sequential design: ENCLK and internal shift_reg/Q update on posedge CLK; no combinational feedback to ENCLK.
    // Key behavior: Updates occur only when previous (EN & ENCLK) == 1; otherwise ENCLK holds. Once ENCLK is 0, it stays 0.

    // ENCLK holds its value when previous enable (EN & ENCLK) was low.
    enclk_holds_when_prev_enable_low: assert property (
        @(posedge CLK) (!$past(EN & ENCLK)) |-> (ENCLK == $past(ENCLK))
    );

    // Any ENCLK change requires previous (EN & ENCLK) to be high.
    enclk_change_requires_prev_enable: assert property (
        @(posedge CLK) (ENCLK != $past(ENCLK)) |-> $past(EN & ENCLK)
    );

    // Once ENCLK is low, it remains low forever.
    enclk_never_rises_from_zero: assert property (
        @(posedge CLK) ($past(ENCLK) == 1'b0) |-> (ENCLK == 1'b0)
    );

    // If previous EN was low, ENCLK must hold its value.
    enclk_holds_when_prev_en_low: assert property (
        @(posedge CLK) ($past(EN) == 1'b0) |-> (ENCLK == $past(ENCLK))
    );

    // A rising edge on ENCLK can only occur when previous (EN & ENCLK) was high.
    enclk_rise_requires_prev_enable: assert property (
        @(posedge CLK) $rose(ENCLK) |-> $past(EN & ENCLK)
    );

    // A falling edge on ENCLK can only occur when previous (EN & ENCLK) was high.
    enclk_fall_requires_prev_enable: assert property (
        @(posedge CLK) $fell(ENCLK) |-> $past(EN & ENCLK)
    );

    // TE changes cannot affect ENCLK when previous enable was low.
    te_change_no_effect_when_prev_disabled: assert property (
        @(posedge CLK) ($changed(TE) && !$past(EN & ENCLK)) |-> (ENCLK == $past(ENCLK))
    );

    // TE changes cannot affect ENCLK when previous EN was low.
    te_change_no_effect_when_prev_en_low: assert property (
        @(posedge CLK) ($changed(TE) && ($past(EN) == 1'b0)) |-> (ENCLK == $past(ENCLK))
    );

    // EN changes cannot affect ENCLK when previous ENCLK was low (it must stay 0).
    en_change_no_effect_when_prev_enclk_low: assert property (
        @(posedge CLK) ($changed(EN) && ($past(ENCLK) == 1'b0)) |-> (ENCLK == 1'b0)
    );

    // If previous (EN & ENCLK) was low, ENCLK must be stable this cycle.
    enclk_stable_when_prev_not_enabled: assert property (
        @(posedge CLK) (!$past(EN & ENCLK)) |-> $stable(ENCLK)
    );
endmodule

