module my_module_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);
    // Pure combinational logic; no clock/reset in RTL; sample on input edges.

    // X must equal (A1 & A2) | ~B1_N on any input edge.
    check_functional_equivalence: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            X == ((A1 & A2) | ~B1_N)
    );

    // When B1_N is LOW, X must be HIGH.
    check_low_B1N_forces_X_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            (!B1_N) |-> (X == 1'b1)
    );

    // When B1_N is HIGH, X equals A1 & A2.
    check_high_B1N_equals_and: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            (B1_N) |-> (X == (A1 & A2))
    );

    // If both A1 and A2 are HIGH, X must be HIGH.
    check_both_A_high_implies_X_high: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            (A1 && A2) |-> (X == 1'b1)
    );

    // With B1_N HIGH and A1 LOW, X must be LOW.
    check_high_B1N_A1_low_implies_X_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            (B1_N && !A1) |-> (X == 1'b0)
    );

    // With B1_N HIGH and A2 LOW, X must be LOW.
    check_high_B1N_A2_low_implies_X_low: assert property (
        @(posedge A1 or negedge A1 or posedge A2 or negedge A2 or posedge B1_N or negedge B1_N)
            (B1_N && !A2) |-> (X == 1'b0)
    );

    // On B1_N falling edge, X must be HIGH due to ~B1_N term.
    check_B1N_fall_sets_X_high: assert property (
        @(negedge B1_N) X == 1'b1
    );

    // On B1_N rising edge, X equals A1 & A2.
    check_B1N_rise_sets_X_to_and: assert property (
        @(posedge B1_N) X == (A1 & A2)
    );

    // On A1 rising edge with B1_N HIGH and A2 HIGH, X must be HIGH.
    check_A1_rise_when_enabled_sets_X_high: assert property (
        @(posedge A1) (B1_N && A2) |-> (X == 1'b1)
    );

    // On A2 rising edge with B1_N HIGH and A1 HIGH, X must be HIGH.
    check_A2_rise_when_enabled_sets_X_high: assert property (
        @(posedge A2) (B1_N && A1) |-> (X == 1'b1)
    );

endmodule

module calculator_sva (
  input  logic signed [7:0] a,
  input  logic signed [7:0] b,
  input  logic              op,
  input  logic              clk,
  input  logic signed [7:0] result,
  input  logic              overflow
);
  // Clock: clk (posedge). No reset present in RTL.
  // Logic: mixed — result is combinational; overflow is registered each clk.

  ///// Result computation /////
  // When op==0, result equals a + b (combinational).
  result_add_correct: assert property (
    @(posedge clk) (op == 1'b0) |-> (result == (a + b))
  );

  // When op==1, result equals a - b (combinational).
  result_sub_correct: assert property (
    @(posedge clk) (op == 1'b1) |-> (result == (a - b))
  );

  // If inputs are unchanged across a cycle, result must be unchanged.
  stable_result_when_inputs_stable: assert property (
    @(posedge clk) ((a == $past(a)) && (b == $past(b)) && (op == $past(op))) |-> (result == $past(result))
  );

  // If op rises (a,b stable), previous result was a+b and current result is a-b.
  result_switch_on_op_rise: assert property (
    @(posedge clk) ($past(op) == 1'b0 && op == 1'b1 && a == $past(a) && b == $past(b)) |-> ((result == (a - b)) && ($past(result) == ($past(a) + $past(b))))
  );

  // If op falls (a,b stable), previous result was a-b and current result is a+b.
  result_switch_on_op_fall: assert property (
    @(posedge clk) ($past(op) == 1'b1 && op == 1'b0 && a == $past(a) && b == $past(b)) |-> ((result == (a + b)) && ($past(result) == ($past(a) - $past(b))))
  );

  ///// Overflow computation (registered) /////
  // On the next cycle, overflow must be 1 when the RTL's overflow condition holds.
  overflow_set_when_condition: assert property (
    @(posedge clk)
      (
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b1)
  );

  // On the next cycle, overflow must be 0 when the RTL's overflow condition does not hold.
  overflow_clear_when_not_condition: assert property (
    @(posedge clk)
      !(
        ((result[7] == 1'b1) && (op == 1'b0) && (a[7] == 1'b1) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b1) && (op == 1'b1) && (a[7] == 1'b0) && (b[7] == 1'b1)) ||
        ((result[7] == 1'b0) && (op == 1'b1) && (a[7] == 1'b1) && (b[7] == 1'b0))
      ) |=> (overflow == 1'b0)
  );

  // After the first cycle, overflow is always a known 0/1 (registered each clk).
  overflow_binary_after_first_cycle: assert property (
    @(posedge clk) $past(1'b1) |-> (overflow inside {1'b0, 1'b1})
  );

  // If op and MSBs used by the RTL overflow logic are unchanged across a cycle, overflow holds its value on the next cycle.
  overflow_stable_when_signs_stable: assert property (
    @(posedge clk)
      ((a[7] == $past(a[7])) && (b[7] == $past(b[7])) && (result[7] == $past(result[7])) && (op == $past(op)))
      |=> (overflow == $past(overflow))
  );

endmodule

module RegisterAdd_4_sva (
    input logic CLK,
    input logic reset,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out
);
    // If reset is 1 on this edge, out must be 0 on the next edge.
    check_reset_clears_out_next: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

    // If reset was 1 in the previous cycle, out must be 0 now.
    check_prev_reset_out_zero_now: assert property (
        @(posedge CLK) $past(reset) |-> (out == 4'd0)
    );

    // If not in reset for two consecutive cycles, out equals in1+in2 from the prior cycle.
    check_sum_update_two_cycle_nonreset: assert property (
        @(posedge CLK) disable iff (reset) (!reset ##1 !reset) |-> (out == $past(in1 + in2))
    );

    // On the cycle reset deasserts, out must be 0 (was cleared by prior reset cycle).
    check_out_zero_on_reset_deassert: assert property (
        @(posedge CLK) $fell(reset) |-> (out == 4'd0)
    );

    // In normal operation (previous cycle not reset), out equals previous cycle's in1+in2.
    check_sum_update_prev_not_reset: assert property (
        @(posedge CLK) disable iff (reset) $past(!reset) |-> (out == $past(in1 + in2))
    );
endmodule

